  ('bebes_001', 'Puré de calabacín con pollo y cuscús', 'bebes', 'pollo', 'cuscús', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 18, 'facil', 'all', 175, 12, 17, 6, 1, true, true, '{"gluten"}', '[{"name":"Calabacín","amount":80,"unit":"g"},{"name":"Pechuga de pollo","amount":30,"unit":"g"},{"name":"Cuscús","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":5,"unit":"ml"},{"name":"Caldo casero sin sal","amount":200,"unit":"ml"}]'::jsonb, '{"Cortar calabacín en trozos pequeños.","Cortar pechuga de pollo en trozos pequeños.","Llevar caldo casero sin sal a ebullición en un cazo a fuego fuerte.","Añadir el calabacín y la pechuga de pollo al caldo cuando rompa a hervir.","Cocer a fuego medio hasta que el calabacín y la pechuga de pollo estén tiernos.","Retirar el calabacín y la pechuga de pollo cocidos con una espumadera y reservar en un bol.","Apartar 60 ml del caldo de cocción caliente y reservar en un bol pequeño.","Añadir cuscús al bol con el caldo de cocción reservado y tapar.","Esperar hasta que el cuscús absorba todo el caldo y esté hidratado.","Añadir el calabacín cocido, la pechuga de pollo cocida y el cuscús hidratado al vaso de la batidora.","Añadir aceite de oliva al vaso de la batidora.","Triturar todo hasta obtener una textura suave y homogénea, añadiendo caldo restante si fuera necesario.","Comprobar la temperatura del puré antes de servir y servir templado."}', 'Puré suave de calabacín con pollo y cuscús, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Calabacín}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pechuga de pollo}} en trozos pequeños.","minutes":1,"kind":"prep"},{"text":"Llevar {{Caldo casero sin sal}} a ebullición en un cazo a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Añadir el calabacín y la pechuga de pollo al caldo cuando rompa a hervir.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego medio hasta que el calabacín y la pechuga de pollo estén tiernos.","minutes":10,"kind":"pasivo"},{"text":"Retirar el calabacín y la pechuga de pollo cocidos con una espumadera y reservar en un bol.","minutes":1,"kind":"activo"},{"text":"Apartar 60 ml del caldo de cocción caliente y reservar en un bol pequeño.","minutes":1,"kind":"activo"},{"text":"Añadir {{Cuscús}} al bol con el caldo de cocción reservado y tapar.","minutes":1,"kind":"activo"},{"text":"Esperar hasta que el cuscús absorba todo el caldo y esté hidratado.","minutes":5,"kind":"espera"},{"text":"Añadir el calabacín cocido, la pechuga de pollo cocida y el cuscús hidratado al vaso de la batidora.","minutes":1,"kind":"prep"},{"text":"Añadir {{Aceite de oliva|chorrito}} al vaso de la batidora.","minutes":1,"kind":"prep"},{"text":"Triturar todo hasta obtener una textura suave y homogénea, añadiendo caldo restante si fuera necesario.","minutes":2,"kind":"activo"},{"text":"Comprobar la temperatura del puré antes de servir y servir templado.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('bebes_002', 'Puré de zanahoria con merluza y patata', 'bebes', 'pescado_blanco', 'patata', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 155, 9, 18, 5, 1, true, true, '{"pescado"}', '[{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Merluza","amount":40,"unit":"g"},{"name":"Patata","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":5,"unit":"ml"}]'::jsonb, '{"Pelar zanahoria y patata y cortar en trozos pequeños.","Llevar a ebullición agua en un cazo a fuego fuerte.","Cocer los trozos de zanahoria y patata en el cazo a fuego medio hasta que estén tiernos.","Limpiar merluza retirando espinas y piel, y cortar en trozos.","Añadir los trozos de merluza al cazo y cocer hasta que esté hecha.","Escurrir las verduras y la merluza, revisando que no quede ninguna espina.","Triturar la zanahoria, la patata y la merluza escurridas hasta obtener un puré fino y homogéneo.","Añadir aceite de oliva al puré y mezclar hasta integrar. Servir templado."}', 'Puré de zanahoria y patata con merluza, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Zanahoria}} y {{Patata}} y cortar en trozos pequeños.","minutes":3,"kind":"prep"},{"text":"Llevar a ebullición agua en un cazo a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Cocer los trozos de zanahoria y patata en el cazo a fuego medio hasta que estén tiernos.","minutes":12,"kind":"pasivo"},{"text":"Limpiar {{Merluza}} retirando espinas y piel, y cortar en trozos.","minutes":2,"kind":"prep"},{"text":"Añadir los trozos de merluza al cazo y cocer hasta que esté hecha.","minutes":5,"kind":"activo"},{"text":"Escurrir las verduras y la merluza, revisando que no quede ninguna espina.","minutes":1,"kind":"prep"},{"text":"Triturar la zanahoria, la patata y la merluza escurridas hasta obtener un puré fino y homogéneo.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} al puré y mezclar hasta integrar. Servir templado.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('bebes_003', 'Puré de calabaza con pavo y boniato', 'bebes', 'pavo', 'boniato', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 18, 'facil', 'all', 165, 11, 18, 6, 1, true, true, '{}', '[{"name":"Calabaza","amount":80,"unit":"g"},{"name":"Pechuga de pavo","amount":30,"unit":"g"},{"name":"Boniato","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":5,"unit":"ml"}]'::jsonb, '{"Pelar calabaza y boniato.","Cortar la calabaza y el boniato en trozos pequeños de tamaño similar.","Cortar pechuga de pavo en trozos pequeños.","Llevar a ebullición agua en un cazo a fuego fuerte.","Añadir la calabaza, el boniato y el pavo al cazo cuando rompa a hervir.","Cocer a fuego medio hasta que la calabaza y el boniato estén tiernos y el pavo cocido, unos 12 min.","Escurrir el contenido del cazo con un colador, reservando un poco del agua de cocción en un bol.","Triturar la calabaza, el boniato y el pavo junto con aceite de oliva hasta obtener una textura suave.","Añadir agua de cocción reservada poco a poco si la textura es demasiado espesa, y triturar hasta homogeneizar.","Servir el puré templado, comprobando la temperatura antes de ofrecer al bebé."}', 'Puré dulce de calabaza y boniato con pavo cocido, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Calabaza}} y {{Boniato}}.","minutes":2,"kind":"prep"},{"text":"Cortar la calabaza y el boniato en trozos pequeños de tamaño similar.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pechuga de pavo}} en trozos pequeños.","minutes":1,"kind":"prep"},{"text":"Llevar a ebullición agua en un cazo a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Añadir la calabaza, el boniato y el pavo al cazo cuando rompa a hervir.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la calabaza y el boniato estén tiernos y el pavo cocido, unos 12 min.","minutes":12,"kind":"pasivo"},{"text":"Escurrir el contenido del cazo con un colador, reservando un poco del agua de cocción en un bol.","minutes":1,"kind":"activo"},{"text":"Triturar la calabaza, el boniato y el pavo junto con {{Aceite de oliva|chorrito}} hasta obtener una textura suave.","minutes":1,"kind":"activo"},{"text":"Añadir agua de cocción reservada poco a poco si la textura es demasiado espesa, y triturar hasta homogeneizar.","minutes":1,"kind":"activo"},{"text":"Servir el puré templado, comprobando la temperatura antes de ofrecer al bebé.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('bebes_004', 'Puré de judías verdes con ternera y patata', 'bebes', 'ternera', 'patata', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 170, 10, 16, 7, 1, true, true, '{}', '[{"name":"Judías verdes","amount":60,"unit":"g"},{"name":"Ternera magra","amount":30,"unit":"g"},{"name":"Patata","amount":70,"unit":"g"},{"name":"Aceite de oliva","amount":5,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en trozos pequeños de tamaño similar.","Cortar judías verdes en trozos de unos 2 cm, retirando los extremos.","Cortar ternera magra en dados pequeños.","Llevar a ebullición agua en un cazo a fuego fuerte. Añadir la patata, las judías verdes y la ternera.","Cocer a fuego medio hasta que la patata y la ternera estén tiernas, unos 18 min. Reservar 3-4 cucharadas del caldo de cocción.","Escurrir las verduras y la ternera cocidas y trasladar al vaso de la batidora.","Añadir aceite de oliva y 2-3 cucharadas del caldo reservado. Triturar hasta obtener un puré liso y sin grumos.","Comprobar la textura y añadir más caldo si fuera necesario hasta lograr la consistencia deseada. Servir templado."}', 'Puré de judías verdes y patata con ternera, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Patata}} y cortar en trozos pequeños de tamaño similar.","minutes":2,"kind":"prep"},{"text":"Cortar {{Judías verdes}} en trozos de unos 2 cm, retirando los extremos.","minutes":2,"kind":"prep"},{"text":"Cortar {{Ternera magra}} en dados pequeños.","minutes":1,"kind":"prep"},{"text":"Llevar a ebullición agua en un cazo a fuego fuerte. Añadir la patata, las judías verdes y la ternera.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la patata y la ternera estén tiernas, unos 18 min. Reservar 3-4 cucharadas del caldo de cocción.","minutes":18,"kind":"pasivo"},{"text":"Escurrir las verduras y la ternera cocidas y trasladar al vaso de la batidora.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} y 2-3 cucharadas del caldo reservado. Triturar hasta obtener un puré liso y sin grumos.","minutes":2,"kind":"activo"},{"text":"Comprobar la textura y añadir más caldo si fuera necesario hasta lograr la consistencia deseada. Servir templado.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('bebes_005', 'Puré de guisantes con pollo y arroz', 'bebes', 'pollo', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 18, 'facil', 'all', 180, 13, 20, 6, 1, true, true, '{}', '[{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Pechuga de pollo","amount":30,"unit":"g"},{"name":"Arroz","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":5,"unit":"ml"}]'::jsonb, '{"Cortar pechuga de pollo en trozos pequeños.","Llevar a ebullición un cazo con agua a fuego fuerte.","Añadir arroz al agua hirviendo y cocer a fuego medio durante 10 min.","Añadir guisantes y la pechuga de pollo troceada al cazo y cocer 8 min más hasta que el pollo esté tierno.","Escurrir el conjunto reservando un poco del agua de cocción.","Triturar el arroz, los guisantes y el pollo con aceite de oliva hasta obtener una textura suave y homogénea.","Servir el puré templado en el plato o bol del bebé."}', 'Puré de guisantes y arroz con pollo cocido, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Pechuga de pollo}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición un cazo con agua a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Añadir {{Arroz}} al agua hirviendo y cocer a fuego medio durante 10 min.","minutes":10,"kind":"pasivo"},{"text":"Añadir {{Guisantes}} y la pechuga de pollo troceada al cazo y cocer 8 min más hasta que el pollo esté tierno.","minutes":8,"kind":"pasivo"},{"text":"Escurrir el conjunto reservando un poco del agua de cocción.","minutes":1,"kind":"activo"},{"text":"Triturar el arroz, los guisantes y el pollo con {{Aceite de oliva}} hasta obtener una textura suave y homogénea.","minutes":2,"kind":"activo"},{"text":"Servir el puré templado en el plato o bol del bebé.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('bebes_006', 'Puré de brócoli con merluza y arroz', 'bebes', 'pescado_blanco', 'arroz', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 18, 'facil', 'all', 160, 10, 19, 5, 1, true, true, '{"pescado"}', '[{"name":"Brócoli","amount":70,"unit":"g"},{"name":"Merluza","amount":40,"unit":"g"},{"name":"Arroz","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":5,"unit":"ml"}]'::jsonb, '{"Llevar a ebullición agua en un cazo pequeño a fuego fuerte.","Añadir arroz al agua hirviendo y cocer a fuego medio.","Separar brócoli en ramilletes pequeños.","Cortar merluza en trozos.","Incorporar el brócoli y la merluza al cazo y cocer a fuego medio hasta que el brócoli esté tierno.","Escurrir el contenido del cazo, reservando un poco del agua de cocción en un bol pequeño.","Revisar la merluza con los dedos y retirar con cuidado todas las espinas.","Añadir aceite de oliva al vaso de la trituradora junto con el brócoli, la merluza y el arroz.","Triturar hasta obtener un puré homogéneo, añadiendo agua de cocción reservada poco a poco hasta alcanzar la textura deseada.","Servir el puré templado, comprobando la temperatura antes de ofrecer al bebé."}', 'Puré de brócoli y arroz con merluza, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Llevar a ebullición agua en un cazo pequeño a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Añadir {{Arroz}} al agua hirviendo y cocer a fuego medio.","minutes":1,"kind":"activo"},{"text":"Separar {{Brócoli}} en ramilletes pequeños.","minutes":2,"kind":"prep"},{"text":"Cortar {{Merluza}} en trozos.","minutes":1,"kind":"prep"},{"text":"Incorporar el brócoli y la merluza al cazo y cocer a fuego medio hasta que el brócoli esté tierno.","minutes":7,"kind":"pasivo"},{"text":"Escurrir el contenido del cazo, reservando un poco del agua de cocción en un bol pequeño.","minutes":1,"kind":"activo"},{"text":"Revisar la merluza con los dedos y retirar con cuidado todas las espinas.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} al vaso de la trituradora junto con el brócoli, la merluza y el arroz.","minutes":1,"kind":"prep"},{"text":"Triturar hasta obtener un puré homogéneo, añadiendo agua de cocción reservada poco a poco hasta alcanzar la textura deseada.","minutes":1,"kind":"activo"},{"text":"Servir el puré templado, comprobando la temperatura antes de ofrecer al bebé.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('bebes_007', 'Papilla de arroz con pollo y zanahoria', 'bebes', 'pollo', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 175, 11, 22, 4, 1, true, true, '{}', '[{"name":"Arroz","amount":25,"unit":"g"},{"name":"Pechuga de pollo","amount":30,"unit":"g"},{"name":"Zanahoria","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":3,"unit":"ml"}]'::jsonb, '{"Rallar zanahoria con un rallador fino y reservar.","Cortar pechuga de pollo en trozos pequeños de aproximadamente 1 cm.","Llevar a ebullición 250 ml de agua en un cazo a fuego fuerte.","Añadir arroz, la zanahoria rallada y el pollo troceado al agua hirviendo.","Cocer a fuego suave durante 12 min, hasta que el arroz esté tierno y el pollo bien cocido.","Retirar del fuego y volcar el contenido del cazo en el vaso de la batidora, conservando el caldo de cocción.","Añadir aceite de oliva y triturar hasta obtener una textura de papilla fina y homogénea.","Servir la papilla templada, comprobando la temperatura antes de ofrecérsela al bebé."}', 'Papilla suave de arroz cocido con pollo y zanahoria', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Rallar {{Zanahoria}} con un rallador fino y reservar.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pechuga de pollo}} en trozos pequeños de aproximadamente 1 cm.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición 250 ml de agua en un cazo a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Añadir {{Arroz}}, la zanahoria rallada y el pollo troceado al agua hirviendo.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave durante 12 min, hasta que el arroz esté tierno y el pollo bien cocido.","minutes":12,"kind":"pasivo"},{"text":"Retirar del fuego y volcar el contenido del cazo en el vaso de la batidora, conservando el caldo de cocción.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} y triturar hasta obtener una textura de papilla fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Servir la papilla templada, comprobando la temperatura antes de ofrecérsela al bebé.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('bebes_008', 'Puré de lentejas rojas con zanahoria y calabacín', 'bebes', 'legumbre', 'lentejas', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 165, 9, 24, 5, 1, true, true, '{}', '[{"name":"Lentejas rojas","amount":30,"unit":"g"},{"name":"Zanahoria","amount":50,"unit":"g"},{"name":"Calabacín","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":5,"unit":"ml"}]'::jsonb, '{"Pelar zanahoria y cortar en trozos pequeños.","Cortar calabacín en trozos pequeños.","Poner lentejas rojas, la zanahoria y el calabacín en un cazo con agua suficiente para cubrirlos.","Llevar a ebullición a fuego fuerte y, cuando rompa a hervir, bajar a fuego suave.","Cocer a fuego suave hasta que las lentejas y las verduras estén muy tiernas.","Escurrir reservando un poco del agua de cocción. Triturar todo con una batidora hasta obtener una textura completamente fina.","Añadir aceite de oliva al puré y remover hasta integrarlo. Ajustar la textura con el agua de cocción reservada si es necesario.","Servir el puré templado, comprobando la temperatura antes de dárselo al bebé."}', 'Puré de lentejas rojas con zanahoria y calabacín, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Zanahoria}} y cortar en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Cortar {{Calabacín}} en trozos pequeños.","minutes":1,"kind":"prep"},{"text":"Poner {{Lentejas rojas}}, la zanahoria y el calabacín en un cazo con agua suficiente para cubrirlos.","minutes":1,"kind":"activo"},{"text":"Llevar a ebullición a fuego fuerte y, cuando rompa a hervir, bajar a fuego suave.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego suave hasta que las lentejas y las verduras estén muy tiernas.","minutes":15,"kind":"pasivo"},{"text":"Escurrir reservando un poco del agua de cocción. Triturar todo con una batidora hasta obtener una textura completamente fina.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} al puré y remover hasta integrarlo. Ajustar la textura con el agua de cocción reservada si es necesario.","minutes":1,"kind":"activo"},{"text":"Servir el puré templado, comprobando la temperatura antes de dárselo al bebé.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('bebes_009', 'Puré de boniato con pavo y calabacín', 'bebes', 'pavo', 'boniato', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 18, 'facil', 'all', 168, 11, 18, 6, 1, true, true, '{}', '[{"name":"Boniato","amount":80,"unit":"g"},{"name":"Pechuga de pavo","amount":30,"unit":"g"},{"name":"Calabacín","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":5,"unit":"ml"}]'::jsonb, '{"Pelar boniato y cortar en trozos de unos 2 cm.","Cortar calabacín en trozos de tamaño similar al boniato.","Cortar pechuga de pavo en trozos pequeños de unos 2 cm.","Llevar a ebullición agua en un cazo pequeño a fuego fuerte.","Añadir el boniato, el calabacín y el pavo al cazo cuando rompa a hervir.","Cocer a fuego medio hasta que el boniato y el pavo estén tiernos, unos 12 min.","Escurrir el boniato, el calabacín y el pavo, reservando un poco del caldo de cocción.","Triturar los ingredientes escurridos junto con aceite de oliva hasta obtener una textura suave.","Añadir caldo de cocción reservado poco a poco si la textura está demasiado espesa y triturar de nuevo.","Servir el puré templado, comprobando que no haya grumos ni temperatura excesiva."}', 'Puré de boniato y calabacín con pavo cocido, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Boniato}} y cortar en trozos de unos 2 cm.","minutes":2,"kind":"prep"},{"text":"Cortar {{Calabacín}} en trozos de tamaño similar al boniato.","minutes":1,"kind":"prep"},{"text":"Cortar {{Pechuga de pavo}} en trozos pequeños de unos 2 cm.","minutes":1,"kind":"prep"},{"text":"Llevar a ebullición agua en un cazo pequeño a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Añadir el boniato, el calabacín y el pavo al cazo cuando rompa a hervir.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego medio hasta que el boniato y el pavo estén tiernos, unos 12 min.","minutes":12,"kind":"pasivo"},{"text":"Escurrir el boniato, el calabacín y el pavo, reservando un poco del caldo de cocción.","minutes":1,"kind":"activo"},{"text":"Triturar los ingredientes escurridos junto con {{Aceite de oliva|chorrito}} hasta obtener una textura suave.","minutes":1,"kind":"activo"},{"text":"Añadir caldo de cocción reservado poco a poco si la textura está demasiado espesa y triturar de nuevo.","minutes":1,"kind":"activo"},{"text":"Servir el puré templado, comprobando que no haya grumos ni temperatura excesiva.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('bebes_010', 'Puré de puerro con salmón y arroz', 'bebes', 'pescado_azul', 'arroz', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 18, 'facil', 'all', 180, 8, 21, 7, 1, true, true, '{"pescado"}', '[{"name":"Puerro","amount":50,"unit":"g"},{"name":"Salmón fresco","amount":30,"unit":"g"},{"name":"Arroz","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":3,"unit":"ml"}]'::jsonb, '{"Limpiar puerro: retirar la parte verde oscura y las raíces.","Cortar el puerro limpio en rodajas finas.","Retirar la piel y las espinas de salmón fresco.","Cortar el salmón limpio en trozos pequeños.","Llevar agua a ebullición en un cazo pequeño a fuego fuerte.","Añadir arroz y las rodajas de puerro al cazo cuando el agua rompa a hervir.","Cocer a fuego medio durante 10 min, hasta que el arroz esté casi tierno.","Añadir los trozos de salmón al cazo y cocer 5 min más, hasta que el salmón esté opaco.","Retirar el cazo del fuego y escurrir el exceso de líquido, reservando un poco en un bol aparte.","Triturar el contenido del cazo junto con aceite de oliva hasta obtener una textura suave.","Añadir el líquido reservado poco a poco si el puré queda demasiado espeso, y triturar de nuevo.","Comprobar que no quedan grumos ni espinas antes de servir.","Servir el puré templado."}', 'Puré de puerro y arroz con salmón, rico en omega-3, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Limpiar {{Puerro}}: retirar la parte verde oscura y las raíces.","minutes":1,"kind":"prep"},{"text":"Cortar el puerro limpio en rodajas finas.","minutes":1,"kind":"prep"},{"text":"Retirar la piel y las espinas de {{Salmón fresco}}.","minutes":2,"kind":"prep"},{"text":"Cortar el salmón limpio en trozos pequeños.","minutes":1,"kind":"prep"},{"text":"Llevar agua a ebullición en un cazo pequeño a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Añadir {{Arroz}} y las rodajas de puerro al cazo cuando el agua rompa a hervir.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego medio durante 10 min, hasta que el arroz esté casi tierno.","minutes":10,"kind":"pasivo"},{"text":"Añadir los trozos de salmón al cazo y cocer 5 min más, hasta que el salmón esté opaco.","minutes":5,"kind":"pasivo"},{"text":"Retirar el cazo del fuego y escurrir el exceso de líquido, reservando un poco en un bol aparte.","minutes":1,"kind":"activo"},{"text":"Triturar el contenido del cazo junto con {{Aceite de oliva|chorrito}} hasta obtener una textura suave.","minutes":1,"kind":"activo"},{"text":"Añadir el líquido reservado poco a poco si el puré queda demasiado espeso, y triturar de nuevo.","minutes":1,"kind":"activo"},{"text":"Comprobar que no quedan grumos ni espinas antes de servir.","minutes":1,"kind":"activo"},{"text":"Servir el puré templado.","kind":"emplatado"}]'::jsonb, true)
