  steps_rich = excluded.steps_rich,
  estrella = excluded.estrella;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('bebes_012', 'Puré de garbanzos con calabaza', 'bebes', 'legumbre', 'garbanzos', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 18, 'facil', 'all', 160, 8, 22, 5, 1, true, true, '{}', '[{"name":"Garbanzos cocidos","amount":60,"unit":"g"},{"name":"Calabaza","amount":60,"unit":"g"},{"name":"Zanahoria","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":5,"unit":"ml"}]'::jsonb, '{"Cortar calabaza en trozos de unos 2 cm.","Cortar zanahoria en trozos de unos 2 cm.","Llevar a ebullición agua en un cazo a fuego fuerte.","Añadir la calabaza y la zanahoria al cazo y cocer 12 min a fuego medio, hasta que estén tiernas.","Añadir garbanzos cocidos al cazo y cocer 3 min más a fuego medio.","Escurrir el contenido del cazo reservando un poco del agua de cocción en un vaso.","Triturar la calabaza, la zanahoria y los garbanzos junto con aceite de oliva hasta obtener una textura fina.","Añadir agua de cocción reservada poco a poco si el puré está demasiado espeso, hasta que esté homogéneo.","Servir el puré templado, comprobando que la textura sea suave y sin grumos."}', 'Puré de garbanzos con calabaza y zanahoria, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Calabaza}} en trozos de unos 2 cm.","minutes":2,"kind":"prep"},{"text":"Cortar {{Zanahoria}} en trozos de unos 2 cm.","minutes":1,"kind":"prep"},{"text":"Llevar a ebullición agua en un cazo a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Añadir la calabaza y la zanahoria al cazo y cocer 12 min a fuego medio, hasta que estén tiernas.","minutes":12,"kind":"pasivo"},{"text":"Añadir {{Garbanzos cocidos}} al cazo y cocer 3 min más a fuego medio.","minutes":3,"kind":"pasivo"},{"text":"Escurrir el contenido del cazo reservando un poco del agua de cocción en un vaso.","minutes":1,"kind":"activo"},{"text":"Triturar la calabaza, la zanahoria y los garbanzos junto con {{Aceite de oliva|chorrito}} hasta obtener una textura fina.","minutes":2,"kind":"activo"},{"text":"Añadir agua de cocción reservada poco a poco si el puré está demasiado espeso, hasta que esté homogéneo.","minutes":1,"kind":"activo"},{"text":"Servir el puré templado, comprobando que la textura sea suave y sin grumos.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('bebes_013', 'Revuelto de huevo con boniato y tomate', 'bebes', 'huevo', 'boniato', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 12, 'facil', 'all', 165, 9, 15, 8, 1, true, true, '{"huevo"}', '[{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Boniato","amount":60,"unit":"g"},{"name":"Tomate natural","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":3,"unit":"ml"}]'::jsonb, '{"Pelar boniato y cortar en trozos pequeños.","Llevar a ebullición agua en un cazo y cocer el boniato durante 10 min, hasta que esté tierno.","Rallar tomate natural sobre un bol pequeño y reservar.","Batir huevo en un bol hasta obtener una mezcla homogénea y reservar.","Escurrir el boniato cocido y chafar con un tenedor hasta obtener un puré liso.","Calentar aceite de oliva en sartén a fuego medio.","Añadir el tomate rallado a la sartén y sofreír 1 min, hasta que pierda el agua.","Bajar a fuego suave, añadir el huevo batido y remover sin parar hasta que cuaje en cremoso.","Retirar la sartén del fuego y añadir el puré de boniato al revuelto.","Mezclar bien y chafar o triturar hasta obtener una textura homogénea y segura para la edad del bebé."}', 'Revuelto de huevo bien cuajado con puré de boniato y tomate, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Boniato}} y cortar en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición agua en un cazo y cocer el boniato durante 10 min, hasta que esté tierno.","minutes":10,"kind":"pasivo"},{"text":"Rallar {{Tomate natural}} sobre un bol pequeño y reservar.","minutes":1,"kind":"paralelo","during":1},{"text":"Batir {{Huevo}} en un bol hasta obtener una mezcla homogénea y reservar.","minutes":1,"kind":"paralelo","during":1},{"text":"Escurrir el boniato cocido y chafar con un tenedor hasta obtener un puré liso.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Añadir el tomate rallado a la sartén y sofreír 1 min, hasta que pierda el agua.","minutes":1,"kind":"activo"},{"text":"Bajar a fuego suave, añadir el huevo batido y remover sin parar hasta que cuaje en cremoso.","minutes":2,"kind":"activo"},{"text":"Retirar la sartén del fuego y añadir el puré de boniato al revuelto.","minutes":1,"kind":"activo"},{"text":"Mezclar bien y chafar o triturar hasta obtener una textura homogénea y segura para la edad del bebé.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('bebes_014', 'Papilla de avena con ternera y espinacas', 'bebes', 'ternera', 'avena', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 175, 12, 17, 7, 1, true, true, '{"gluten"}', '[{"name":"Copos de avena","amount":20,"unit":"g"},{"name":"Ternera magra","amount":30,"unit":"g"},{"name":"Espinacas frescas","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":5,"unit":"ml"},{"name":"Caldo casero sin sal","amount":200,"unit":"ml"}]'::jsonb, '{"Cortar ternera magra en trozos pequeños con un cuchillo afilado.","Llevar caldo casero sin sal a ebullición en un cazo a fuego medio.","Añadir copos de avena y la ternera picada al caldo cuando rompa a hervir.","Cocer a fuego suave durante 7 min, removiendo de vez en cuando, hasta que la avena esté tierna.","Añadir espinacas frescas al cazo y cocer 2 min más hasta que estén tiernas.","Retirar el cazo del fuego y añadir aceite de oliva.","Triturar todo con una batidora de mano hasta obtener una textura suave y homogénea, apta para bebé.","Servir la papilla templada, comprobando la temperatura antes de dársela al bebé."}', 'Papilla de avena con ternera y espinacas, rica en hierro, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Ternera magra}} en trozos pequeños con un cuchillo afilado.","minutes":2,"kind":"prep"},{"text":"Llevar {{Caldo casero sin sal}} a ebullición en un cazo a fuego medio.","minutes":3,"kind":"activo"},{"text":"Añadir {{Copos de avena}} y la ternera picada al caldo cuando rompa a hervir.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave durante 7 min, removiendo de vez en cuando, hasta que la avena esté tierna.","minutes":7,"kind":"pasivo"},{"text":"Añadir {{Espinacas frescas}} al cazo y cocer 2 min más hasta que estén tiernas.","minutes":2,"kind":"activo"},{"text":"Retirar el cazo del fuego y añadir {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"prep"},{"text":"Triturar todo con una batidora de mano hasta obtener una textura suave y homogénea, apta para bebé.","minutes":2,"kind":"activo"},{"text":"Servir la papilla templada, comprobando la temperatura antes de dársela al bebé.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('bebes_015', 'Crema de calabacín con huevo y sémola', 'bebes', 'huevo', 'sémola', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 155, 8, 16, 7, 1, true, true, '{"huevo","gluten"}', '[{"name":"Calabacín","amount":100,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Sémola de trigo","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":3,"unit":"ml"}]'::jsonb, '{"Cortar calabacín en trozos pequeños y reservar.","Llevar a ebullición agua en un cazo pequeño a fuego fuerte.","Introducir huevo en un cazo con agua fría y llevar a ebullición; cocer 10 min a fuego medio hasta que esté bien cuajado.","Cocer el calabacín en el cazo con agua hirviendo a fuego medio durante 10 min hasta que esté tierno.","Añadir sémola de trigo al cazo con el calabacín y cocer 3 min a fuego medio, removiendo, hasta que esté hidratada.","Retirar el huevo del cazo, enfriarlo bajo el chorro de agua fría, pelar y picar fino; reservar.","Triturar el calabacín con la sémola y el agua de cocción necesaria hasta obtener una crema lisa y sin grumos.","Añadir el huevo picado y aceite de oliva a la crema; mezclar hasta integrar.","Servir la crema templada, comprobando que la temperatura sea adecuada para el bebé."}', 'Crema de calabacín con sémola y huevo cocido, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Calabacín}} en trozos pequeños y reservar.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición agua en un cazo pequeño a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Introducir {{Huevo}} en un cazo con agua fría y llevar a ebullición; cocer 10 min a fuego medio hasta que esté bien cuajado.","minutes":12,"kind":"pasivo"},{"text":"Cocer el calabacín en el cazo con agua hirviendo a fuego medio durante 10 min hasta que esté tierno.","minutes":10,"kind":"pasivo"},{"text":"Añadir {{Sémola de trigo}} al cazo con el calabacín y cocer 3 min a fuego medio, removiendo, hasta que esté hidratada.","minutes":3,"kind":"activo"},{"text":"Retirar el huevo del cazo, enfriarlo bajo el chorro de agua fría, pelar y picar fino; reservar.","minutes":2,"kind":"prep"},{"text":"Triturar el calabacín con la sémola y el agua de cocción necesaria hasta obtener una crema lisa y sin grumos.","minutes":1,"kind":"activo"},{"text":"Añadir el huevo picado y {{Aceite de oliva|chorrito}} a la crema; mezclar hasta integrar.","minutes":1,"kind":"activo"},{"text":"Servir la crema templada, comprobando que la temperatura sea adecuada para el bebé.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('bebes_016', 'Puré de coliflor con pollo y patata', 'bebes', 'pollo', 'patata', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 18, 'facil', 'all', 165, 12, 14, 6, 1, true, true, '{}', '[{"name":"Coliflor","amount":70,"unit":"g"},{"name":"Pechuga de pollo","amount":30,"unit":"g"},{"name":"Patata","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":5,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en trozos de unos 2 cm.","Cortar coliflor en ramilletes pequeños.","Cortar pechuga de pollo en trozos pequeños.","Llevar a ebullición agua en un cazo a fuego fuerte y añadir la patata troceada.","Cocer la patata a fuego medio durante 8 min.","Añadir los ramilletes de coliflor y la pechuga troceada al cazo.","Cocer a fuego medio durante 10 min, hasta que todo esté tierno.","Escurrir el agua del cazo reservando un poco del caldo de cocción.","Triturar la patata, la coliflor y la pechuga con aceite de oliva y un chorrito del caldo reservado.","Comprobar la textura; si fuera necesario, añadir más caldo y triturar de nuevo hasta obtener una textura suave y homogénea.","Servir el puré templado."}', 'Puré de coliflor y patata con pollo cocido, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Patata}} y cortar en trozos de unos 2 cm.","minutes":2,"kind":"prep"},{"text":"Cortar {{Coliflor}} en ramilletes pequeños.","minutes":1,"kind":"prep"},{"text":"Cortar {{Pechuga de pollo}} en trozos pequeños.","minutes":1,"kind":"prep"},{"text":"Llevar a ebullición agua en un cazo a fuego fuerte y añadir la patata troceada.","minutes":2,"kind":"activo"},{"text":"Cocer la patata a fuego medio durante 8 min.","minutes":8,"kind":"pasivo"},{"text":"Añadir los ramilletes de coliflor y la pechuga troceada al cazo.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego medio durante 10 min, hasta que todo esté tierno.","minutes":10,"kind":"pasivo"},{"text":"Escurrir el agua del cazo reservando un poco del caldo de cocción.","minutes":1,"kind":"activo"},{"text":"Triturar la patata, la coliflor y la pechuga con {{Aceite de oliva|chorrito}} y un chorrito del caldo reservado.","minutes":1,"kind":"activo"},{"text":"Comprobar la textura; si fuera necesario, añadir más caldo y triturar de nuevo hasta obtener una textura suave y homogénea.","minutes":1,"kind":"activo"},{"text":"Servir el puré templado.","kind":"emplatado"}]'::jsonb, true),
  ('bebes_018', 'Puré de remolacha con pavo y patata', 'bebes', 'pavo', 'patata', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 170, 11, 19, 6, 1, true, true, '{}', '[{"name":"Remolacha cocida","amount":60,"unit":"g"},{"name":"Pechuga de pavo","amount":30,"unit":"g"},{"name":"Patata","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":5,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en trozos pequeños de aproximadamente 1 cm.","Cortar pechuga de pavo en trozos pequeños.","Cortar remolacha cocida en trozos pequeños.","Llevar a ebullición agua en un cazo pequeño a fuego fuerte.","Añadir la patata troceada y el pavo troceado al agua hirviendo; cocer a fuego medio durante 15 min, hasta que la patata esté tierna.","Añadir la remolacha troceada al cazo y calentar a fuego medio durante 3 min.","Escurrir el contenido del cazo y volcar en un vaso triturador.","Añadir aceite de oliva y triturar hasta obtener una textura suave y homogénea.","Servir el puré templado, comprobando la temperatura antes de ofrecérselo al bebé."}', 'Puré de remolacha y patata con pavo, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Patata}} y cortar en trozos pequeños de aproximadamente 1 cm.","minutes":3,"kind":"prep"},{"text":"Cortar {{Pechuga de pavo}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Cortar {{Remolacha cocida}} en trozos pequeños.","minutes":1,"kind":"prep"},{"text":"Llevar a ebullición agua en un cazo pequeño a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Añadir la patata troceada y el pavo troceado al agua hirviendo; cocer a fuego medio durante 15 min, hasta que la patata esté tierna.","minutes":15,"kind":"pasivo"},{"text":"Añadir la remolacha troceada al cazo y calentar a fuego medio durante 3 min.","minutes":3,"kind":"activo"},{"text":"Escurrir el contenido del cazo y volcar en un vaso triturador.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} y triturar hasta obtener una textura suave y homogénea.","minutes":2,"kind":"activo"},{"text":"Servir el puré templado, comprobando la temperatura antes de ofrecérselo al bebé.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('bebes_019', 'Puré de espinacas con salmón y boniato', 'bebes', 'pescado_azul', 'boniato', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 18, 'facil', 'all', 175, 9, 17, 8, 1, true, true, '{"pescado"}', '[{"name":"Espinacas frescas","amount":50,"unit":"g"},{"name":"Salmón fresco","amount":30,"unit":"g"},{"name":"Boniato","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":3,"unit":"ml"}]'::jsonb, '{"Pelar boniato y cortar en dados de unos 2 cm.","Retirar la piel y las espinas de salmón fresco y cortar en trozos pequeños.","Llevar un cazo con agua a ebullición a fuego fuerte.","Añadir los dados de boniato al cazo cuando rompa a hervir y cocer a fuego medio hasta que estén tiernos.","Añadir espinacas frescas y los trozos de salmón al cazo y cocer a fuego medio hasta que el salmón esté opaco y las espinacas mustias.","Escurrir el contenido del cazo reservando un poco del agua de cocción en un vaso.","Triturar el boniato, las espinacas y el salmón con aceite de oliva hasta obtener una textura suave.","Añadir agua de cocción reservada poco a poco si el puré resulta demasiado espeso y triturar de nuevo hasta que esté homogéneo.","Comprobar que el puré no tenga grumos ni espinas antes de servir templado."}', 'Puré de espinacas y boniato con salmón, rico en omega-3, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Boniato}} y cortar en dados de unos 2 cm.","minutes":2,"kind":"prep"},{"text":"Retirar la piel y las espinas de {{Salmón fresco}} y cortar en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Llevar un cazo con agua a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Añadir los dados de boniato al cazo cuando rompa a hervir y cocer a fuego medio hasta que estén tiernos.","minutes":10,"kind":"pasivo"},{"text":"Añadir {{Espinacas frescas}} y los trozos de salmón al cazo y cocer a fuego medio hasta que el salmón esté opaco y las espinacas mustias.","minutes":3,"kind":"activo"},{"text":"Escurrir el contenido del cazo reservando un poco del agua de cocción en un vaso.","minutes":1,"kind":"prep"},{"text":"Triturar el boniato, las espinacas y el salmón con {{Aceite de oliva|chorrito}} hasta obtener una textura suave.","minutes":1,"kind":"activo"},{"text":"Añadir agua de cocción reservada poco a poco si el puré resulta demasiado espeso y triturar de nuevo hasta que esté homogéneo.","minutes":1,"kind":"activo"},{"text":"Comprobar que el puré no tenga grumos ni espinas antes de servir templado.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('bebes_021', 'Puré de garbanzos con pollo y espinacas', 'bebes', 'pollo', 'garbanzos', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 185, 12, 20, 6, 1, true, true, '{}', '[{"name":"Garbanzos cocidos","amount":60,"unit":"g"},{"name":"Pechuga de pollo","amount":30,"unit":"g"},{"name":"Espinacas frescas","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":5,"unit":"ml"}]'::jsonb, '{"Cortar pechuga de pollo en trozos pequeños.","Llevar a ebullición agua en un cazo a fuego fuerte y añadir los trozos de pechuga de pollo.","Cocer la pechuga de pollo a fuego medio durante 10 min, hasta que esté bien cocida y sin color rosado en el interior.","Añadir garbanzos cocidos y espinacas frescas al cazo y calentar a fuego medio durante 5 min, hasta que las espinacas estén tiernas.","Escurrir el contenido del cazo y trasladar a un vaso de batidora.","Añadir aceite de oliva y triturar todo con la batidora hasta obtener una textura suave y homogénea, sin grumos.","Servir el puré templado, comprobando la temperatura antes de ofrecer al bebé."}', 'Puré de garbanzos con pollo y espinacas, rico en hierro, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Pechuga de pollo}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición agua en un cazo a fuego fuerte y añadir los trozos de pechuga de pollo.","minutes":1,"kind":"activo"},{"text":"Cocer la pechuga de pollo a fuego medio durante 10 min, hasta que esté bien cocida y sin color rosado en el interior.","minutes":10,"kind":"pasivo"},{"text":"Añadir {{Garbanzos cocidos}} y {{Espinacas frescas}} al cazo y calentar a fuego medio durante 5 min, hasta que las espinacas estén tiernas.","minutes":5,"kind":"activo"},{"text":"Escurrir el contenido del cazo y trasladar a un vaso de batidora.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} y triturar todo con la batidora hasta obtener una textura suave y homogénea, sin grumos.","minutes":2,"kind":"activo"},{"text":"Servir el puré templado, comprobando la temperatura antes de ofrecer al bebé.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('bebes_022', 'Puré de lentejas con ternera y zanahoria', 'bebes', 'ternera', 'lentejas', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 175, 12, 22, 5, 1, true, true, '{}', '[{"name":"Lentejas rojas","amount":30,"unit":"g"},{"name":"Ternera magra","amount":30,"unit":"g"},{"name":"Zanahoria","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":5,"unit":"ml"}]'::jsonb, '{"Pelar zanahoria y cortar en trozos pequeños.","Cortar ternera magra en trozos pequeños.","Poner lentejas rojas, la zanahoria troceada y la ternera en un cazo. Cubrir con agua fría.","Llevar a ebullición a fuego fuerte, luego bajar a fuego suave y cocer hasta que las lentejas y la zanahoria estén tiernas.","Escurrir el contenido del cazo reservando un poco del caldo de cocción.","Triturar las lentejas, la zanahoria y la ternera añadiendo caldo reservado hasta obtener una textura fina y homogénea.","Añadir aceite de oliva al puré y mezclar bien antes de servir."}', 'Puré de lentejas rojas con ternera y zanahoria, rico en hierro, sin sal', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Zanahoria}} y cortar en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Cortar {{Ternera magra}} en trozos pequeños.","minutes":1,"kind":"prep"},{"text":"Poner {{Lentejas rojas}}, la zanahoria troceada y la ternera en un cazo. Cubrir con agua fría.","minutes":1,"kind":"prep"},{"text":"Llevar a ebullición a fuego fuerte, luego bajar a fuego suave y cocer hasta que las lentejas y la zanahoria estén tiernas.","minutes":18,"kind":"pasivo"},{"text":"Escurrir el contenido del cazo reservando un poco del caldo de cocción.","minutes":1,"kind":"activo"},{"text":"Triturar las lentejas, la zanahoria y la ternera añadiendo caldo reservado hasta obtener una textura fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} al puré y mezclar bien antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_001', 'Pollo al horno con patatas', 'carnes', 'pollo', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 60, 'facil', 'all', 486, 38, 28, 24, 2, true, true, '{}', '[{"name":"Contramuslos de pollo","amount":400,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Romero","amount":3,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en gajos gruesos de unos 3 cm.","Pelar cebolla y cortar en gajos gruesos.","Pelar ajo y laminar.","Cortar limón por la mitad y exprimir el zumo. Reservar.","Precalentar el horno a 200 °C con calor arriba y abajo.","Disponer los gajos de patata y de cebolla en una bandeja de horno.","Añadir el ajo laminado y romero sobre las patatas y la cebolla.","Verter aceite de oliva sobre la bandeja y mezclar bien para que todo quede impregnado.","Colocar contramuslos de pollo sobre las verduras de la bandeja.","Rociar el pollo con el zumo de limón reservado.","Hornear la bandeja a 200 °C durante 45 min, hasta que el pollo esté dorado y las patatas tiernas.","Retirar la bandeja del horno y servir el pollo junto con las patatas y la cebolla."}', 'Contramuslos de pollo asados al horno sobre cama de patatas', '[{"appliance":"horno","time":60,"difficulty":"facil","prepSummary":"Marinar el pollo y las patatas con el resto de ingredientes. Hornear a 190-200°C durante 60 minutos, volteando el pollo y las patatas a mitad de cocción para asegurar un dorado uniforme y una cocción perfecta."},{"appliance":"airfryer","time":30,"difficulty":"facil","prepSummary":"Cortar las patatas en cubos pequeños y marinar junto al pollo. Cocinar en la airfryer a 190°C durante 25-30 minutos, agitando la cesta o volteando los ingredientes a mitad para un acabado crujiente y bien cocido."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Patata}} y cortar en gajos gruesos de unos 3 cm.","minutes":3,"kind":"prep"},{"text":"Pelar {{Cebolla}} y cortar en gajos gruesos.","minutes":2,"kind":"prep"},{"text":"Pelar {{Ajo}} y laminar.","minutes":2,"kind":"prep"},{"text":"Cortar {{Limón}} por la mitad y exprimir el zumo. Reservar.","minutes":1,"kind":"prep"},{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Disponer los gajos de patata y de cebolla en una bandeja de horno.","minutes":1,"kind":"prep"},{"text":"Añadir el ajo laminado y {{Romero|pizca}} sobre las patatas y la cebolla.","minutes":1,"kind":"prep"},{"text":"Verter {{Aceite de oliva|chorrito}} sobre la bandeja y mezclar bien para que todo quede impregnado.","minutes":1,"kind":"prep"},{"text":"Colocar {{Contramuslos de pollo}} sobre las verduras de la bandeja.","minutes":1,"kind":"prep"},{"text":"Rociar el pollo con el zumo de limón reservado.","minutes":1,"kind":"prep"},{"text":"Hornear la bandeja a 200 °C durante 45 min, hasta que el pollo esté dorado y las patatas tiernas.","minutes":45,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y servir el pollo junto con las patatas y la cebolla.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  main_protein = excluded.main_protein,
  main_base = excluded.main_base,
  meal_roles = excluded.meal_roles,
  type = excluded.type,
  base_dish_id = excluded.base_dish_id,
  required_appliance = excluded.required_appliance,
  time_minutes = excluded.time_minutes,
  difficulty = excluded.difficulty,
  season = excluded.season,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  base_servings = excluded.base_servings,
  kid_friendly = excluded.kid_friendly,
  tupper_friendly = excluded.tupper_friendly,
  allergens = excluded.allergens,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  description = excluded.description,
  methods = excluded.methods,
  product_aliases = excluded.product_aliases,
  apetecible = excluded.apetecible,
  montaje = excluded.montaje,
  can_be_garnish = excluded.can_be_garnish,
  main_ingredients = excluded.main_ingredients,
  sauce_id = excluded.sauce_id,
  extra_proteins = excluded.extra_proteins,
  freezable = excluded.freezable,
  steps_rich = excluded.steps_rich,
  estrella = excluded.estrella;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('carnes_002', 'Pechugas de pollo a la plancha', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 312, 42, 2, 14, 2, true, true, '{}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo en polvo","amount":3,"unit":"g"},{"name":"Orégano","amount":2,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Aplanar pechuga de pollo con la palma de la mano o un mazo hasta conseguir un grosor uniforme de unos 2 cm.","Cortar limón por la mitad y reservar para el emplatado.","Espolvorear ajo en polvo y orégano por ambas caras de las pechugas, presionando ligeramente para que se adhieran.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Añadir aceite de oliva sobre la plancha y extender con movimiento suave.","Colocar las pechugas sazonadas sobre la plancha y cocinar a fuego medio-fuerte sin moverlas durante 5 min, hasta que se doren por la base.","Dar la vuelta a las pechugas y cocinar 4 min más por el otro lado, hasta que estén doradas y jugosas en el interior.","Retirar las pechugas de la plancha y exprimir el limón reservado por encima antes de servir."}', 'Pechugas de pollo a la plancha con ajo y orégano', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Marina las pechugas con aceite, ajo y orégano. Cocínalas en la airfryer precalentada a 200°C durante 15-18 minutos, volteándolas a mitad del tiempo para un dorado uniforme y que queden jugosas."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Tras marinar las pechugas, hornéalas a 200-220°C durante unos 20 minutos. Para un acabado más ''a la plancha'', puedes usar la función grill los últimos 5 minutos y conseguir un exterior dorado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Aplanar {{Pechuga de pollo}} con la palma de la mano o un mazo hasta conseguir un grosor uniforme de unos 2 cm.","minutes":2,"kind":"prep"},{"text":"Cortar {{Limón}} por la mitad y reservar para el emplatado.","minutes":1,"kind":"prep"},{"text":"Espolvorear {{Ajo en polvo}} y {{Orégano}} por ambas caras de las pechugas, presionando ligeramente para que se adhieran.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} sobre la plancha y extender con movimiento suave.","minutes":1,"kind":"activo"},{"text":"Colocar las pechugas sazonadas sobre la plancha y cocinar a fuego medio-fuerte sin moverlas durante 5 min, hasta que se doren por la base.","minutes":5,"kind":"pasivo"},{"text":"Dar la vuelta a las pechugas y cocinar 4 min más por el otro lado, hasta que estén doradas y jugosas en el interior.","minutes":4,"kind":"pasivo"},{"text":"Retirar las pechugas de la plancha y exprimir el limón reservado por encima antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_003', 'Albóndigas en salsa de tomate', 'carnes', 'cerdo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', NULL, NULL, 40, 'normal', 'all', 438, 28, 18, 28, 2, true, true, '{"gluten","huevo"}', '[{"name":"Carne picada de cerdo","amount":300,"unit":"g"},{"name":"Pan rallado","amount":30,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Tomate triturado","amount":300,"unit":"ml"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Harina","amount":15,"unit":"g"}]'::jsonb, '{"Picar ajo muy fino y reservar.","Picar cebolla en trozos pequeños y reservar.","Mezclar en un bol carne picada de cerdo, pan rallado, huevo y la mitad del ajo picado hasta obtener una masa homogénea.","Formar albóndigas del tamaño de una nuez con la masa anterior.","Pasar cada albóndiga por harina hasta cubrirla ligeramente y sacudir el exceso.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Freír las albóndigas enharinadas hasta que se doren por todos los lados; retirar y reservar.","Sofreír la cebolla picada en la misma sartén a fuego medio hasta que esté tierna y transparente.","Añadir el resto del ajo picado y sofreír 1 min más hasta que desprenda aroma.","Añadir tomate triturado, remover y llevar a ebullición a fuego medio.","Incorporar las albóndigas reservadas a la salsa, tapar y cocer a fuego suave hasta que estén bien cocidas y la salsa espese.","Servir las albóndigas con la salsa de tomate por encima."}', 'Albóndigas caseras de cerdo en salsa de tomate', '[{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Hornea las albóndigas en una bandeja a 200°C durante 15-20 minutos hasta que doren. Prepara el sofrito y la salsa en una cazuela apta para horno, añade las albóndigas y termina de cocinar a 180°C durante 20-25 minutos."},{"appliance":"thermomix","time":55,"difficulty":"normal","prepSummary":"Prepara el sofrito de cebolla y ajo, luego la salsa de tomate. Incorpora las albóndigas y cocínalas directamente en la salsa a 100°C, velocidad cuchara invertida, durante 20-25 minutos para que se integren bien los sabores."},{"appliance":"olla_express","time":45,"difficulty":"normal","prepSummary":"Dora las albóndigas en la olla abierta, retira. Haz el sofrito y la salsa en la misma olla, reincorpora las albóndigas y cocina a presión durante 10-12 minutos para un resultado tierno y rápido."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Picar {{Ajo}} muy fino y reservar.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolla}} en trozos pequeños y reservar.","minutes":3,"kind":"prep"},{"text":"Mezclar en un bol {{Carne picada de cerdo}}, {{Pan rallado}}, {{Huevo}} y la mitad del ajo picado hasta obtener una masa homogénea.","minutes":3,"kind":"prep"},{"text":"Formar albóndigas del tamaño de una nuez con la masa anterior.","minutes":3,"kind":"prep"},{"text":"Pasar cada albóndiga por {{Harina}} hasta cubrirla ligeramente y sacudir el exceso.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego fuerte hasta que esté bien caliente.","minutes":1,"kind":"activo"},{"text":"Freír las albóndigas enharinadas hasta que se doren por todos los lados; retirar y reservar.","minutes":5,"kind":"activo"},{"text":"Sofreír la cebolla picada en la misma {{@Sartén}} a fuego medio hasta que esté tierna y transparente.","minutes":5,"kind":"activo"},{"text":"Añadir el resto del ajo picado y sofreír 1 min más hasta que desprenda aroma.","minutes":1,"kind":"activo"},{"text":"Añadir {{Tomate triturado}}, remover y llevar a ebullición a fuego medio.","minutes":3,"kind":"activo"},{"text":"Incorporar las albóndigas reservadas a la salsa, tapar y cocer a fuego suave hasta que estén bien cocidas y la salsa espese.","minutes":20,"kind":"pasivo"},{"text":"Servir las albóndigas con la salsa de tomate por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_004', 'Filetes de lomo empanados', 'carnes', 'cerdo', 'pan', ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 462, 34, 22, 26, 2, true, true, '{"gluten","huevo"}', '[{"name":"Lomo de cerdo en filetes","amount":300,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":60,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Salpimentar lomo de cerdo en filetes por ambas caras y reservar.","Cascar huevo en un plato hondo y batir hasta obtener una mezcla homogénea.","Extender harina en un plato llano y pan rallado en otro plato llano.","Pasar cada filete por la harina, sacudir el exceso, sumergir en el huevo batido y cubrir bien con el pan rallado.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Freír los filetes empanados hasta que estén dorados por ambas caras, aproximadamente 2 min por cada lado.","Retirar los filetes de la sartén y escurrir sobre papel absorbente para eliminar el exceso de aceite.","Servir los filetes empanados inmediatamente."}', 'Filetes de lomo de cerdo empanados y fritos', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Para unos filetes crujientes y con menos aceite, precalienta la airfryer a 190-200°C. Rocía los filetes empanados con un poco de aceite y cocina durante 12-15 minutos, dándoles la vuelta a mitad de cocción para un dorado uniforme."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Hornea los filetes para una versión más ligera. Precalienta el horno a 200°C con calor arriba y abajo. Coloca los filetes sobre una rejilla en una bandeja y hornea durante 20-25 minutos, volteándolos a mitad para que queden dorados por ambos lados."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Salpimentar {{Lomo de cerdo en filetes}} por ambas caras y reservar.","minutes":2,"kind":"prep"},{"text":"Cascar {{Huevo}} en un plato hondo y batir hasta obtener una mezcla homogénea.","minutes":1,"kind":"prep"},{"text":"Extender {{Harina}} en un plato llano y {{Pan rallado}} en otro plato llano.","minutes":1,"kind":"prep"},{"text":"Pasar cada filete por la harina, sacudir el exceso, sumergir en el huevo batido y cubrir bien con el pan rallado.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Freír los filetes empanados hasta que estén dorados por ambas caras, aproximadamente 2 min por cada lado.","minutes":4,"kind":"activo"},{"text":"Retirar los filetes de la sartén y escurrir sobre papel absorbente para eliminar el exceso de aceite.","minutes":1,"kind":"activo"},{"text":"Servir los filetes empanados inmediatamente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_005', 'Estofado de ternera', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 90, 'normal', 'invierno', 468, 36, 22, 26, 2, true, true, '{}', '[{"name":"Carne de ternera para guisar","amount":350,"unit":"g"},{"name":"Patata","amount":200,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Vino tinto","amount":80,"unit":"ml"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Pelar patata y cortar en trozos de unos 3 cm.","Pelar zanahoria y cortar en rodajas de 1 cm.","Pelar cebolla y picar fino.","Cortar carne de ternera para guisar en dados de unos 4 cm.","Calentar aceite de oliva en una olla a fuego fuerte hasta que humee.","Dorar la carne de ternera en tandas hasta que esté sellada por todos los lados; reservar.","Bajar a fuego medio y sofreír la cebolla picada en la misma olla hasta que esté transparente.","Añadir la zanahoria y sofreír 2 min hasta que empiece a ablandarse.","Añadir tomate triturado y remover hasta que se integre con el sofrito, unos 2 min.","Incorporar la carne reservada, vino tinto y laurel; cubrir con agua hasta sobrepasar los ingredientes.","Llevar a ebullición a fuego fuerte; cuando rompa a hervir, bajar a fuego suave y tapar.","Cocer tapado a fuego suave durante 40 min hasta que la carne empiece a estar tierna.","Añadir la patata cortada y cocer tapado a fuego suave durante 20 min hasta que esté tierna.","Retirar el laurel y servir el estofado bien caliente en platos hondos."}', 'Ternera guisada a fuego lento con patata, zanahoria y vino tinto', '[{"appliance":"horno","time":110,"difficulty":"normal","prepSummary":"Tras dorar la carne y pochar las verduras en una olla apta para horno, añade el resto de ingredientes y cocina tapado en el horno precalentado a 160°C durante 90-100 minutos hasta que la carne esté muy tierna."},{"appliance":"thermomix","time":85,"difficulty":"normal","prepSummary":"Sofríe las verduras y dora la carne (con mariposa o giro inverso). Añade el resto de ingredientes y cocina a 90-100°C, velocidad cuchara y giro inverso, durante 60-70 minutos hasta que la carne esté tierna y la salsa ligada."},{"appliance":"olla_express","time":45,"difficulty":"facil","prepSummary":"Dora la carne y sofríe las verduras en la olla. Incorpora los líquidos y el laurel, cierra la olla y cocina a presión (nivel 2) durante 25-30 minutos. Deja despresurizar naturalmente para una carne más tierna y jugosa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Patata}} y cortar en trozos de unos 3 cm.","minutes":3,"kind":"prep"},{"text":"Pelar {{Zanahoria}} y cortar en rodajas de 1 cm.","minutes":2,"kind":"prep"},{"text":"Pelar {{Cebolla}} y picar fino.","minutes":2,"kind":"prep"},{"text":"Cortar {{Carne de ternera para guisar}} en dados de unos 4 cm.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una olla a fuego fuerte hasta que humee.","minutes":2,"kind":"activo"},{"text":"Dorar la carne de ternera en tandas hasta que esté sellada por todos los lados; reservar.","minutes":6,"kind":"activo"},{"text":"Bajar a fuego medio y sofreír la cebolla picada en la misma olla hasta que esté transparente.","minutes":4,"kind":"activo"},{"text":"Añadir la zanahoria y sofreír 2 min hasta que empiece a ablandarse.","minutes":2,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y remover hasta que se integre con el sofrito, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Incorporar la carne reservada, {{Vino tinto}} y {{Laurel}}; cubrir con agua hasta sobrepasar los ingredientes.","minutes":2,"kind":"activo"},{"text":"Llevar a ebullición a fuego fuerte; cuando rompa a hervir, bajar a fuego suave y tapar.","minutes":3,"kind":"activo"},{"text":"Cocer tapado a fuego suave durante 40 min hasta que la carne empiece a estar tierna.","minutes":40,"kind":"pasivo"},{"text":"Añadir la patata cortada y cocer tapado a fuego suave durante 20 min hasta que esté tierna.","minutes":20,"kind":"pasivo"},{"text":"Retirar el laurel y servir el estofado bien caliente en platos hondos.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_006', 'Pollo al ajillo', 'carnes', 'pollo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'all', 398, 36, 4, 26, 2, true, true, '{}', '[{"name":"Pollo troceado","amount":500,"unit":"g"},{"name":"Ajo","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Guindilla","amount":1,"unit":"ud"}]'::jsonb, '{"Salpimentar pollo troceado por todos los lados.","Laminar ajo en láminas finas.","Calentar aceite de oliva en una sartén amplia a fuego fuerte hasta que esté bien caliente.","Dorar el pollo salpimentado en la sartén a fuego fuerte hasta que esté dorado por todas las caras, unos 6 min.","Añadir el ajo laminado, guindilla y laurel a la sartén y sofreír a fuego medio hasta que el ajo esté ligeramente dorado.","Verter vino blanco y remover para despegar los jugos del fondo hasta que el alcohol se evapore, unos 2 min.","Tapar la sartén y cocer a fuego medio hasta que el pollo esté tierno y la salsa haya reducido, unos 14 min.","Retirar el laurel y la guindilla, y servir el pollo con la salsa de ajo por encima."}', 'Pollo troceado frito con abundante ajo y vino blanco', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Dora el pollo y el ajo en una sartén apta para horno o cazuela. Añade el vino y el laurel, luego hornea a 180°C durante 20-25 minutos hasta que el pollo esté tierno y la salsa reducida."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Dora el pollo y el ajo en la olla express abierta con un poco de aceite. Incorpora el vino y el laurel, cierra la olla y cocina a presión durante 10-12 minutos. Despresuriza y sirve."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Sofríe el ajo y luego el pollo en el vaso a temperatura Varoma con giro inverso. Añade el vino y el laurel, y cocina 15-20 minutos a 100°C, velocidad cuchara, giro inverso, hasta que el pollo esté tierno."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Salpimentar {{Pollo troceado}} por todos los lados.","minutes":2,"kind":"prep"},{"text":"Laminar {{Ajo}} en láminas finas.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una {{@Sartén}} amplia a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Dorar el pollo salpimentado en la {{@Sartén}} a fuego fuerte hasta que esté dorado por todas las caras, unos 6 min.","minutes":6,"kind":"activo"},{"text":"Añadir el ajo laminado, {{Guindilla}} y {{Laurel}} a la {{@Sartén}} y sofreír a fuego medio hasta que el ajo esté ligeramente dorado.","minutes":2,"kind":"activo"},{"text":"Verter {{Vino blanco}} y remover para despegar los jugos del fondo hasta que el alcohol se evapore, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Tapar la {{@Sartén}} y cocer a fuego medio hasta que el pollo esté tierno y la salsa haya reducido, unos 14 min.","minutes":14,"kind":"pasivo"},{"text":"Retirar el laurel y la guindilla, y servir el pollo con la salsa de ajo por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_007', 'Cinta de lomo adobada', 'carnes', 'cerdo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 346, 34, 3, 22, 2, true, true, '{}', '[{"name":"Cinta de lomo","amount":300,"unit":"g"},{"name":"Pimentón","amount":6,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Orégano","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre","amount":15,"unit":"ml"}]'::jsonb, '{"Picar ajo muy fino y reservar.","Mezclar en un bol el ajo picado, pimentón, orégano, vinagre y aceite de oliva hasta obtener una pasta homogénea.","Cubrir cinta de lomo con la pasta del adobo por ambas caras hasta que quede bien impregnada.","Calentar plancha a fuego fuerte hasta que esté muy caliente.","Colocar los filetes de cinta de lomo en plancha y dorar 2 min por cada cara hasta que estén bien marcados.","Retirar los filetes de la plancha y servir con el jugo que hayan soltado."}', 'Filetes de cinta de lomo adobados con pimentón y ajo', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Marinar la cinta de lomo. Precalienta la airfryer a 190-200°C y cocina durante 15-20 minutos, dándole la vuelta a mitad para un dorado uniforme y una textura jugosa."},{"appliance":"horno","time":22,"difficulty":"facil","prepSummary":"Tras marinar, hornea la cinta de lomo a 190-200°C (con ventilador si es posible) durante 20-25 minutos. Voltéala una vez para asegurar una cocción pareja y un exterior ligeramente dorado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Ajo}} muy fino y reservar.","minutes":2,"kind":"prep"},{"text":"Mezclar en un bol el ajo picado, {{Pimentón}}, {{Orégano}}, {{Vinagre}} y {{Aceite de oliva}} hasta obtener una pasta homogénea.","minutes":2,"kind":"prep"},{"text":"Cubrir {{Cinta de lomo}} con la pasta del adobo por ambas caras hasta que quede bien impregnada.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté muy caliente.","minutes":2,"kind":"activo"},{"text":"Colocar los filetes de cinta de lomo en {{@Plancha}} y dorar 2 min por cada cara hasta que estén bien marcados.","minutes":4,"kind":"activo"},{"text":"Retirar los filetes de la plancha y servir con el jugo que hayan soltado.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_009', 'Hamburguesas caseras', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 448, 30, 24, 26, 2, true, false, '{"gluten","huevo"}', '[{"name":"Carne picada de ternera","amount":300,"unit":"g"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":20,"unit":"g"},{"name":"Pan de hamburguesa","amount":2,"unit":"ud"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Lechuga","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Rallar cebolla con un rallador fino y reservar.","Cortar tomate en rodajas finas y reservar.","Separar las hojas de lechuga y reservar.","Mezclar en un bol carne picada de ternera, la cebolla rallada, huevo y pan rallado hasta obtener una masa homogénea.","Dividir la masa en 2 porciones iguales y dar forma redonda y plana a cada una.","Salpimentar cada hamburguesa por ambas caras.","Calentar plancha a fuego fuerte con aceite de oliva hasta que humee ligeramente.","Colocar las hamburguesas en la plancha y dorar 4 min por el primer lado sin moverlas.","Dar la vuelta a las hamburguesas y dorar 4 min por el segundo lado hasta que estén cocinadas en el centro.","Retirar las hamburguesas y tostar pan de hamburguesa partido por la mitad en la plancha hasta que se dore ligeramente.","Colocar la base de cada pan, disponer las hojas de lechuga y la hamburguesa encima.","Añadir las rodajas de tomate sobre la hamburguesa y tapar con la parte superior del pan."}', 'Hamburguesas de ternera caseras con pan, tomate y lechuga', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Forma las hamburguesas y cocínalas en la airfryer precalentada a 190°C durante 12-15 minutos, volteándolas a mitad de cocción para un dorado uniforme. Quedan jugosas por dentro y con una capa exterior ligeramente crujiente."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Prepara las hamburguesas y hornéalas en una bandeja con papel de horno a 200°C durante 15-20 minutos, volteándolas una vez. Es una opción práctica para cocinar varias a la vez, manteniendo la carne tierna y jugosa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Rallar {{Cebolla}} con un rallador fino y reservar.","minutes":2,"kind":"prep"},{"text":"Cortar {{Tomate}} en rodajas finas y reservar.","minutes":1,"kind":"prep"},{"text":"Separar las hojas de {{Lechuga}} y reservar.","minutes":1,"kind":"prep"},{"text":"Mezclar en un bol {{Carne picada de ternera}}, la cebolla rallada, {{Huevo}} y {{Pan rallado}} hasta obtener una masa homogénea.","minutes":2,"kind":"activo"},{"text":"Dividir la masa en 2 porciones iguales y dar forma redonda y plana a cada una.","minutes":1,"kind":"prep"},{"text":"Salpimentar cada hamburguesa por ambas caras.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte con {{Aceite de oliva|chorrito}} hasta que humee ligeramente.","minutes":2,"kind":"activo"},{"text":"Colocar las hamburguesas en la plancha y dorar 4 min por el primer lado sin moverlas.","minutes":4,"kind":"pasivo"},{"text":"Dar la vuelta a las hamburguesas y dorar 4 min por el segundo lado hasta que estén cocinadas en el centro.","minutes":4,"kind":"pasivo"},{"text":"Retirar las hamburguesas y tostar {{Pan de hamburguesa}} partido por la mitad en la plancha hasta que se dore ligeramente.","minutes":1,"kind":"activo"},{"text":"Colocar la base de cada pan, disponer las hojas de lechuga y la hamburguesa encima.","minutes":1,"kind":"emplatado"},{"text":"Añadir las rodajas de tomate sobre la hamburguesa y tapar con la parte superior del pan.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_010', 'Pollo con pimientos', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', NULL, NULL, 40, 'facil', 'all', 382, 34, 12, 22, 2, true, true, '{}', '[{"name":"Pollo troceado","amount":500,"unit":"g"},{"name":"Pimiento rojo","amount":120,"unit":"g"},{"name":"Pimiento verde","amount":120,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Salpimentar pollo troceado por todos los lados y reservar.","Cortar pimiento rojo y pimiento verde en tiras de 1 cm de ancho.","Cortar cebolla en juliana fina.","Picar ajo fino.","Calentar aceite de oliva en sartén a fuego fuerte hasta que brille.","Dorar el pollo troceado en la sartén caliente, 3 min por cada lado, hasta que esté dorado. Retirar y reservar.","Reducir el fuego a medio y sofreír la cebolla y el ajo en la misma sartén hasta que estén blandos, unos 3 min.","Añadir las tiras de pimiento rojo y pimiento verde y saltear hasta que estén ligeramente tiernos, unos 4 min.","Añadir tomate triturado y remover para integrar con las verduras. Cocer 2 min a fuego medio.","Incorporar el pollo reservado a la sartén, remover y tapar.","Cocer tapado a fuego suave durante 20 min, hasta que el pollo esté tierno y la salsa haya espesado.","Servir el pollo con los pimientos y la salsa por encima."}', 'Pollo guisado con pimientos rojos y verdes en salsa de tomate', '[{"appliance":"horno","time":50,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo, dora el pollo en una sartén. Coloca todo en una fuente de horno con los pimientos y el tomate triturado. Hornea a 180°C durante unos 45-50 minutos, removiendo a mitad para una cocción uniforme."},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas en el vaso. Añade el pollo y sofríe brevemente. Incorpora el tomate y cocina todo a temperatura Varoma, giro inverso, velocidad cuchara durante unos 30-35 minutos hasta que el pollo esté tierno."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla abierta, dora el pollo y añade los pimientos y el tomate. Cierra la olla y cocina a presión durante 10-12 minutos desde que sube la válvula, luego despresuriza y sirve."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Salpimentar {{Pollo troceado}} por todos los lados y reservar.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pimiento rojo}} y {{Pimiento verde}} en tiras de 1 cm de ancho.","minutes":3,"kind":"prep"},{"text":"Cortar {{Cebolla}} en juliana fina.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego fuerte hasta que brille.","minutes":1,"kind":"activo"},{"text":"Dorar el pollo troceado en la sartén caliente, 3 min por cada lado, hasta que esté dorado. Retirar y reservar.","minutes":6,"kind":"activo"},{"text":"Reducir el fuego a medio y sofreír la cebolla y el ajo en la misma sartén hasta que estén blandos, unos 3 min.","minutes":3,"kind":"activo"},{"text":"Añadir las tiras de pimiento rojo y pimiento verde y saltear hasta que estén ligeramente tiernos, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y remover para integrar con las verduras. Cocer 2 min a fuego medio.","minutes":2,"kind":"activo"},{"text":"Incorporar el pollo reservado a la sartén, remover y tapar.","minutes":1,"kind":"activo"},{"text":"Cocer tapado a fuego suave durante 20 min, hasta que el pollo esté tierno y la salsa haya espesado.","minutes":20,"kind":"pasivo"},{"text":"Servir el pollo con los pimientos y la salsa por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_011', 'Costillas de cerdo al horno', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 75, 'facil', 'all', 528, 32, 8, 42, 2, true, true, '{}', '[{"name":"Costillas de cerdo","amount":500,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Miel","amount":20,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":5,"unit":"g"},{"name":"Romero","amount":3,"unit":"g"}]'::jsonb, '{"Pelar ajo y picar muy fino.","Exprimir limón y reservar el zumo.","Mezclar en un bol el ajo picado, el zumo de limón, miel, pimentón, romero y aceite de oliva.","Remover hasta que la marinada sea homogénea.","Cubrir costillas de cerdo con la marinada, frotando bien por todos los lados.","Tapar el bol con film y dejar reposar en la nevera hasta que la carne absorba los aromas.","Precalentar el horno a 180 °C con calor arriba y abajo.","Colocar las costillas marinadas en una bandeja de horno y verter el resto de la marinada por encima.","Cubrir la bandeja herméticamente con papel de aluminio.","Hornear a 180 °C hasta que la carne esté tierna.","Retirar el papel de aluminio y subir el horno a 220 °C.","Hornear hasta que las costillas se doren y caramelicen.","Retirar la bandeja del horno y dejar reposar las costillas.","Servir las costillas con los jugos de la bandeja por encima."}', 'Costillas de cerdo al horno con miel, limón y pimentón', '[{"appliance":"horno","time":75,"difficulty":"facil","prepSummary":"Marinar las costillas con ajo, miel, limón, aceite, pimentón y romero. Hornear a 180°C durante 75 minutos, volteando a mitad para asegurar un glaseado uniforme y una cocción perfecta."},{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Marinar las costillas con la mezcla de especias y miel. Cocinar en la airfryer a 190°C durante 35 minutos, volteando y pincelando con la marinada a mitad para un acabado dorado y jugoso."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Ajo}} y picar muy fino.","minutes":3,"kind":"prep"},{"text":"Exprimir {{Limón}} y reservar el zumo.","minutes":1,"kind":"prep"},{"text":"Mezclar en un bol el ajo picado, el zumo de limón, {{Miel}}, {{Pimentón}}, {{Romero|pizca}} y {{Aceite de oliva|chorrito}}.","minutes":2,"kind":"prep"},{"text":"Remover hasta que la marinada sea homogénea.","minutes":1,"kind":"prep"},{"text":"Cubrir {{Costillas de cerdo}} con la marinada, frotando bien por todos los lados.","minutes":3,"kind":"prep"},{"text":"Tapar el bol con film y dejar reposar en la nevera hasta que la carne absorba los aromas.","minutes":30,"kind":"espera"},{"text":"Precalentar el horno a 180 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Colocar las costillas marinadas en una bandeja de horno y verter el resto de la marinada por encima.","minutes":2,"kind":"prep"},{"text":"Cubrir la bandeja herméticamente con papel de aluminio.","minutes":1,"kind":"prep"},{"text":"Hornear a 180 °C hasta que la carne esté tierna.","minutes":40,"kind":"pasivo"},{"text":"Retirar el papel de aluminio y subir el horno a 220 °C.","minutes":1,"kind":"activo"},{"text":"Hornear hasta que las costillas se doren y caramelicen.","minutes":15,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y dejar reposar las costillas.","minutes":5,"kind":"espera"},{"text":"Servir las costillas con los jugos de la bandeja por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_012', 'San Jacobos caseros', 'carnes', 'cerdo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 498, 36, 20, 30, 2, true, true, '{"gluten","huevo","lactosa"}', '[{"name":"Lomo de cerdo en filetes","amount":250,"unit":"g"},{"name":"Jamón cocido","amount":60,"unit":"g"},{"name":"Queso en lonchas","amount":60,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":50,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Aplanar lomo de cerdo en filetes sobre la tabla con la mano hasta obtener un grosor uniforme.","Colocar jamón cocido sobre la mitad de cada filete.","Cubrir el jamón cocido con queso en lonchas.","Doblar cada filete por la mitad para encerrar el relleno.","Presionar los bordes de cada san jacobo con los dedos hasta que queden bien sellados.","Extender harina en un plato llano.","Batir huevo en un bol hasta que esté homogéneo.","Extender pan rallado en otro plato llano.","Pasar cada san jacobo por la harina y sacudir el exceso.","Pasar cada san jacobo por el huevo batido, cubriendo toda la superficie.","Pasar cada san jacobo por el pan rallado, cubriendo bien toda la superficie.","Calentar aceite de oliva en sartén a fuego medio hasta que esté bien caliente.","Freír los san jacobos hasta que estén dorados por un lado.","Girar los san jacobos con cuidado y dorar el otro lado hasta que el rebozado esté crujiente y uniforme.","Retirar los san jacobos de la sartén y escurrir sobre papel absorbente.","Servir inmediatamente para que el queso permanezca fundido en el interior."}', 'Filetes de lomo rellenos de jamón y queso, empanados y fritos', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Rocía ligeramente los San Jacobos empanados con aceite y cocínalos durante 15-18 minutos, dándoles la vuelta a mitad del tiempo, hasta que estén dorados y crujientes."},{"appliance":"horno","time":22,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Coloca los San Jacobos empanados en una bandeja con papel de horno, rociándolos con un poco de aceite. Hornea durante 20-25 minutos, volteándolos a mitad, hasta que estén dorados y bien cocidos."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Aplanar {{Lomo de cerdo en filetes}} sobre la tabla con la mano hasta obtener un grosor uniforme.","minutes":2,"kind":"prep"},{"text":"Colocar {{Jamón cocido}} sobre la mitad de cada filete.","minutes":1,"kind":"prep"},{"text":"Cubrir el jamón cocido con {{Queso en lonchas}}.","minutes":1,"kind":"prep"},{"text":"Doblar cada filete por la mitad para encerrar el relleno.","minutes":1,"kind":"prep"},{"text":"Presionar los bordes de cada san jacobo con los dedos hasta que queden bien sellados.","minutes":1,"kind":"prep"},{"text":"Extender {{Harina}} en un plato llano.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol hasta que esté homogéneo.","minutes":1,"kind":"prep"},{"text":"Extender {{Pan rallado}} en otro plato llano.","minutes":1,"kind":"prep"},{"text":"Pasar cada san jacobo por la harina y sacudir el exceso.","minutes":1,"kind":"prep"},{"text":"Pasar cada san jacobo por el huevo batido, cubriendo toda la superficie.","minutes":1,"kind":"prep"},{"text":"Pasar cada san jacobo por el pan rallado, cubriendo bien toda la superficie.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} a fuego medio hasta que esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Freír los san jacobos hasta que estén dorados por un lado.","minutes":3,"kind":"activo"},{"text":"Girar los san jacobos con cuidado y dorar el otro lado hasta que el rebozado esté crujiente y uniforme.","minutes":3,"kind":"activo"},{"text":"Retirar los san jacobos de la sartén y escurrir sobre papel absorbente.","minutes":1,"kind":"espera"},{"text":"Servir inmediatamente para que el queso permanezca fundido en el interior.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL)
