insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('carnes_013', 'Muslos de pollo al horno', 'carnes', 'pollo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 50, 'facil', 'all', 418, 34, 6, 28, 2, true, true, '{}', '[{"name":"Muslos de pollo","amount":500,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Tomillo","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Cortar cebolla en gajos de tamaño mediano.","Aplastar ajo con la hoja del cuchillo, sin pelar.","Salpimentar muslos de pollo por ambas caras y disponerlos en una bandeja de horno.","Colocar los gajos de cebolla y el ajo aplastado alrededor de los muslos en la bandeja.","Regar los muslos con aceite de oliva y vino blanco.","Espolvorear tomillo de manera uniforme sobre los muslos y las verduras.","Hornear a 200 °C durante 35 min hasta que la piel esté dorada y los jugos salgan claros.","Retirar la bandeja del horno y servir los muslos con la cebolla y el jugo de cocción."}', 'Muslos de pollo asados al horno con cebolla y tomillo', '[{"appliance":"horno","time":60,"difficulty":"facil","prepSummary":"Precalentar el horno a 190°C. Dorar los muslos en una fuente apta, añadir la cebolla, ajo, vino blanco y tomillo. Hornear durante 40-50 minutos, volteando a mitad, hasta que estén tiernos, dorados y la salsa ligeramente reducida."},{"appliance":"airfryer","time":40,"difficulty":"normal","prepSummary":"Precalentar la airfryer a 180°C. Cocinar los muslos con aceite, sal y tomillo durante 20 minutos. Luego, añadir la cebolla, ajo y vino blanco en la cesta o en un recipiente apto, y cocinar 10-15 minutos más hasta que el pollo esté crujiente y las verduras tiernas."},{"appliance":"olla_express","time":35,"difficulty":"normal","prepSummary":"Dorar los muslos en la olla express con aceite. Añadir la cebolla, ajo, vino blanco y tomillo. Cerrar la olla y cocinar a presión durante 12-15 minutos. Dejar despresurizar, obteniendo un pollo muy tierno con una salsa concentrada."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Cebolla}} en gajos de tamaño mediano.","minutes":2,"kind":"prep"},{"text":"Aplastar {{Ajo}} con la hoja del cuchillo, sin pelar.","minutes":1,"kind":"prep"},{"text":"Salpimentar {{Muslos de pollo}} por ambas caras y disponerlos en una bandeja de horno.","minutes":2,"kind":"prep"},{"text":"Colocar los gajos de cebolla y el ajo aplastado alrededor de los muslos en la bandeja.","minutes":1,"kind":"prep"},{"text":"Regar los muslos con {{Aceite de oliva|chorrito}} y {{Vino blanco}}.","minutes":1,"kind":"prep"},{"text":"Espolvorear {{Tomillo|pizca}} de manera uniforme sobre los muslos y las verduras.","minutes":1,"kind":"prep"},{"text":"Hornear a 200 °C durante 35 min hasta que la piel esté dorada y los jugos salgan claros.","minutes":35,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y servir los muslos con la cebolla y el jugo de cocción.","minutes":2,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_014', 'Filetes rusos', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 392, 28, 14, 24, 2, true, true, '{"gluten","huevo"}', '[{"name":"Carne picada de ternera","amount":300,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Pan rallado","amount":25,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Pelar cebolla y rallar con un rallador fino. Reservar.","Pelar ajo y picar muy fino.","Picar perejil fino.","Poner carne picada de ternera en un bol grande.","Añadir la cebolla rallada, el ajo picado, el perejil picado, huevo y pan rallado.","Salpimentar la mezcla del bol al gusto.","Mezclar todos los ingredientes del bol con las manos hasta obtener una masa homogénea.","Dividir la masa en 4 porciones iguales.","Dar a cada porción forma ovalada y aplanada de unos 2 cm de grosor.","Calentar plancha a fuego fuerte con aceite de oliva hasta que empiece a humear.","Colocar los filetes rusos sobre la plancha caliente y dorar 4 min sin moverlos, hasta que se doren por la base.","Dar la vuelta a los filetes y dorar otros 4 min, hasta que estén cocidos por dentro.","Retirar los filetes de la plancha y servir de inmediato."}', 'Filetes rusos de ternera con cebolla y perejil a la plancha', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Mezcla los ingredientes, forma los filetes y rocíalos ligeramente con aceite. Cocina en la airfryer precalentada a 190°C durante 18-20 minutos, dándoles la vuelta a mitad de cocción para un dorado uniforme y una textura jugosa."},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Prepara la mezcla y forma los filetes. Colócalos en una bandeja de horno con papel de hornear y un chorrito de aceite. Hornea a 200°C durante 25-30 minutos, hasta que estén dorados por fuera y bien cocidos por dentro."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Cebolla}} y rallar con un rallador fino. Reservar.","minutes":2,"kind":"prep"},{"text":"Pelar {{Ajo}} y picar muy fino.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil}} fino.","minutes":1,"kind":"prep"},{"text":"Poner {{Carne picada de ternera}} en un bol grande.","minutes":1,"kind":"prep"},{"text":"Añadir la cebolla rallada, el ajo picado, el perejil picado, {{Huevo}} y {{Pan rallado}}.","minutes":1,"kind":"prep"},{"text":"Salpimentar la mezcla del bol al gusto.","minutes":1,"kind":"prep"},{"text":"Mezclar todos los ingredientes del bol con las manos hasta obtener una masa homogénea.","minutes":2,"kind":"activo"},{"text":"Dividir la masa en 4 porciones iguales.","minutes":1,"kind":"prep"},{"text":"Dar a cada porción forma ovalada y aplanada de unos 2 cm de grosor.","minutes":2,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte con {{Aceite de oliva}} hasta que empiece a humear.","minutes":2,"kind":"activo"},{"text":"Colocar los filetes rusos sobre la plancha caliente y dorar 4 min sin moverlos, hasta que se doren por la base.","minutes":4,"kind":"pasivo"},{"text":"Dar la vuelta a los filetes y dorar otros 4 min, hasta que estén cocidos por dentro.","minutes":4,"kind":"pasivo"},{"text":"Retirar los filetes de la plancha y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_016', 'Pollo en pepitoria', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', NULL, NULL, 50, 'normal', 'all', 466, 36, 8, 32, 2, true, true, '{"huevo","frutos_secos"}', '[{"name":"Pollo troceado","amount":500,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Almendras","amount":30,"unit":"g"},{"name":"Huevo cocido","amount":1,"unit":"ud"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Azafrán","amount":1,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en brunoise fina.","Pelar y picar ajo fino.","Separar la yema de huevo cocido y reservar la clara por separado.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Salpimentar pollo troceado y dorar en la sartén por todos los lados hasta que esté dorado; retirar y reservar.","Bajar a fuego medio y sofreír la cebolla picada en el mismo aceite hasta que esté transparente y blanda.","Añadir el ajo picado y sofreír 1 min más hasta que empiece a dorarse.","Tostar almendras en la sartén a fuego suave, removiendo, hasta que estén doradas; retirar.","Majar en un mortero las almendras tostadas, la yema de huevo cocido y azafrán hasta obtener una pasta homogénea.","Devolver el pollo reservado a la sartén y añadir vino blanco; llevar a ebullición a fuego fuerte 1 min para evaporar el alcohol.","Añadir 150 ml de agua, tapar y cocer a fuego suave hasta que el pollo esté tierno.","Incorporar la majada al guiso, remover bien y cocer a fuego suave 3 min hasta que la salsa espese.","Laminar la clara de huevo cocido y dispersar por encima; servir en la misma sartén o en plato hondo."}', 'Pollo guisado en salsa de almendras, azafrán y huevo cocido', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Dora el pollo y sofríe la cebolla y el ajo en una cazuela apta para horno. Añade el vino, azafrán y líquido, luego cocina tapado en el horno a 170°C durante 45-50 min. Prepara la picada de almendras y huevo cocido aparte y añádela al final para espesar la salsa."},{"appliance":"thermomix","time":50,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo, luego dora el pollo en el vaso. Incorpora el vino, azafrán y líquido, y cocina a temperatura Varoma, giro inverso, velocidad cuchara durante 30-35 min. Tritura las almendras y el huevo cocido con parte de la salsa y reincorpora para espesar."},{"appliance":"olla_express","time":40,"difficulty":"normal","prepSummary":"Dora el pollo y sofríe la cebolla y el ajo en la olla abierta. Añade el vino, azafrán y líquido, cierra y cocina a presión durante 15-20 min. Libera la presión, prepara la picada de almendras y huevo cocido aparte y mézclala con la salsa para espesarla."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar y picar {{Cebolla}} en brunoise fina.","minutes":3,"kind":"prep"},{"text":"Pelar y picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Separar la yema de {{Huevo cocido}} y reservar la clara por separado.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego fuerte hasta que humee ligeramente.","minutes":2,"kind":"activo"},{"text":"Salpimentar {{Pollo troceado}} y dorar en la sartén por todos los lados hasta que esté dorado; retirar y reservar.","minutes":7,"kind":"activo"},{"text":"Bajar a fuego medio y sofreír la cebolla picada en el mismo aceite hasta que esté transparente y blanda.","minutes":5,"kind":"activo"},{"text":"Añadir el ajo picado y sofreír 1 min más hasta que empiece a dorarse.","minutes":1,"kind":"activo"},{"text":"Tostar {{Almendras}} en la sartén a fuego suave, removiendo, hasta que estén doradas; retirar.","minutes":2,"kind":"activo"},{"text":"Majar en un mortero las almendras tostadas, la yema de huevo cocido y {{Azafrán|pizca}} hasta obtener una pasta homogénea.","minutes":3,"kind":"prep"},{"text":"Devolver el pollo reservado a la sartén y añadir {{Vino blanco}}; llevar a ebullición a fuego fuerte 1 min para evaporar el alcohol.","minutes":2,"kind":"activo"},{"text":"Añadir 150 ml de agua, tapar y cocer a fuego suave hasta que el pollo esté tierno.","minutes":25,"kind":"pasivo"},{"text":"Incorporar la majada al guiso, remover bien y cocer a fuego suave 3 min hasta que la salsa espese.","minutes":3,"kind":"activo"},{"text":"Laminar la clara de huevo cocido y dispersar por encima; servir en la misma sartén o en plato hondo.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_017', 'Magro con tomate', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'all', 368, 32, 10, 22, 2, true, true, '{}', '[{"name":"Magro de cerdo","amount":300,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Cortar cebolla en brunoise fina y pimiento verde en trozos pequeños.","Picar ajo muy fino.","Cortar magro de cerdo en taquitos de unos 2 cm.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Dorar el magro en la sartén a fuego fuerte hasta que esté sellado por todos los lados; reservar en un plato.","Bajar a fuego medio y sofreír la cebolla, el ajo y el pimiento verde en la misma sartén hasta que estén tiernos.","Añadir tomate triturado y remover para integrar con las verduras.","Incorporar el magro reservado, bajar a fuego suave, tapar y cocer hasta que la salsa espese y la carne esté tierna.","Servir el magro con tomate bien caliente, repartido entre 2 platos."}', 'Taquitos de magro de cerdo guisados en salsa de tomate', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Sofríe la cebolla, pimiento y ajo en una cazuela apta para horno. Añade el magro y dora. Incorpora el tomate triturado, tapa y hornea a 180°C durante 30 minutos hasta que la carne esté tierna y la salsa reducida."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas. Añade el magro y dora. Incorpora el tomate triturado y cocina a fuego lento (Varoma, giro inverso, velocidad cuchara) durante 20 minutos hasta que la carne esté tierna y la salsa ligada."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Dora el magro en la olla express. Retira y sofríe las verduras. Vuelve a añadir el magro con el tomate triturado, cierra la olla y cocina 10-12 minutos desde que sube la válvula. Despresuriza y sirve."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Cebolla}} en brunoise fina y {{Pimiento verde}} en trozos pequeños.","minutes":4,"kind":"prep"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep"},{"text":"Cortar {{Magro de cerdo}} en taquitos de unos 2 cm.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte hasta que humee ligeramente.","minutes":1,"kind":"activo"},{"text":"Dorar el magro en la {{@Sartén}} a fuego fuerte hasta que esté sellado por todos los lados; reservar en un plato.","minutes":4,"kind":"activo"},{"text":"Bajar a fuego medio y sofreír la cebolla, el ajo y el pimiento verde en la misma {{@Sartén}} hasta que estén tiernos.","minutes":5,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y remover para integrar con las verduras.","minutes":1,"kind":"activo"},{"text":"Incorporar el magro reservado, bajar a fuego suave, tapar y cocer hasta que la salsa espese y la carne esté tierna.","minutes":15,"kind":"pasivo"},{"text":"Servir el magro con tomate bien caliente, repartido entre 2 platos.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_018', 'Secreto ibérico a la plancha', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 412, 28, 1, 32, 2, true, false, '{}', '[{"name":"Secreto ibérico","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Romero","amount":2,"unit":"g"}]'::jsonb, '{"Retirar secreto ibérico de la nevera y dejarlo reposar a temperatura ambiente hasta que esté atemperado.","Pelar y picar ajo muy fino.","Mezclar el ajo picado con romero y aceite de oliva en un bol pequeño hasta obtener una mezcla homogénea.","Pincelar el secreto ibérico por ambas caras con la mezcla de ajo, romero y aceite de oliva.","Calentar plancha a fuego fuerte hasta que esté muy caliente y empiece a humear ligeramente.","Colocar el secreto ibérico sobre la plancha y cocinar a fuego fuerte durante 3 min sin moverlo, hasta que se dore por la cara inferior.","Dar la vuelta al secreto ibérico y cocinar 3 min más por el otro lado, hasta que se dore y esté jugoso en el interior.","Retirar el secreto ibérico de la plancha, tapar con papel de aluminio y dejar reposar hasta que los jugos se redistribuyan.","Cortar el secreto ibérico en lonchas al bies y servir inmediatamente."}', 'Secreto ibérico a la plancha, jugoso y rosado por dentro', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Marina el secreto con aceite, ajo y romero. Precalienta la airfryer a 190-200°C y cocina durante 16-18 minutos, dándole la vuelta a mitad para un dorado uniforme y jugosidad."},{"appliance":"horno","time":22,"difficulty":"facil","prepSummary":"Precalienta el horno a 200-220°C. Marina el secreto y colócalo en una bandeja. Hornea durante 20-25 minutos, girándolo a mitad de cocción para un resultado tierno y ligeramente dorado."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Retirar {{Secreto ibérico}} de la nevera y dejarlo reposar a temperatura ambiente hasta que esté atemperado.","minutes":30,"kind":"espera"},{"text":"Pelar y picar {{Ajo}} muy fino.","minutes":2,"kind":"prep"},{"text":"Mezclar el ajo picado con {{Romero|pizca}} y {{Aceite de oliva|chorrito}} en un bol pequeño hasta obtener una mezcla homogénea.","minutes":1,"kind":"prep"},{"text":"Pincelar el secreto ibérico por ambas caras con la mezcla de ajo, romero y aceite de oliva.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté muy caliente y empiece a humear ligeramente.","minutes":2,"kind":"activo"},{"text":"Colocar el secreto ibérico sobre la plancha y cocinar a fuego fuerte durante 3 min sin moverlo, hasta que se dore por la cara inferior.","minutes":3,"kind":"activo"},{"text":"Dar la vuelta al secreto ibérico y cocinar 3 min más por el otro lado, hasta que se dore y esté jugoso en el interior.","minutes":3,"kind":"activo"},{"text":"Retirar el secreto ibérico de la plancha, tapar con papel de aluminio y dejar reposar hasta que los jugos se redistribuyan.","minutes":3,"kind":"espera"},{"text":"Cortar el secreto ibérico en lonchas al bies y servir inmediatamente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_019', 'Alitas de pollo al horno', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, 'horno', 45, 'facil', 'all', 386, 28, 6, 28, 2, true, true, '{}', '[{"name":"Alitas de pollo","amount":500,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pimentón","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Miel","amount":15,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Pelar ajo y picarlo fino.","Cortar limón por la mitad y exprimirlo para obtener el zumo.","Verter en un bol aceite de oliva, miel, pimentón, el ajo picado y el zumo de limón.","Mezclar hasta obtener una marinada homogénea.","Añadir alitas de pollo al bol y remover hasta que queden bien cubiertas con la marinada.","Tapar el bol y dejar reposar en frío durante 15 min hasta que la marinada penetre en la carne.","Precalentar el horno a 200 °C con calor arriba y abajo.","Disponer las alitas en una bandeja en una sola capa y verter el resto de la marinada por encima.","Hornear a 200 °C durante 18 min hasta que las alitas empiecen a dorarse.","Retirar la bandeja del horno y dar la vuelta a las alitas.","Hornear otros 15 min a 200 °C hasta que estén doradas y crujientes.","Retirar la bandeja del horno y servir las alitas con el jugo de la cocción por encima."}', 'Alitas de pollo al horno con miel, limón y pimentón', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Marinar las alitas con los ingredientes. Hornear a 200°C durante 45 minutos, dándoles la vuelta a mitad de cocción para un dorado uniforme y una piel crujiente."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Tras marinar, cocinar las alitas en la airfryer a 190-200°C durante 20-25 minutos, agitándolas o dándoles la vuelta varias veces para una cocción y dorado homogéneos."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Ajo}} y picarlo fino.","minutes":2,"kind":"prep"},{"text":"Cortar {{Limón}} por la mitad y exprimirlo para obtener el zumo.","minutes":1,"kind":"prep"},{"text":"Verter en un bol {{Aceite de oliva}}, {{Miel}}, {{Pimentón}}, el ajo picado y el zumo de limón.","minutes":1,"kind":"prep"},{"text":"Mezclar hasta obtener una marinada homogénea.","minutes":1,"kind":"prep"},{"text":"Añadir {{Alitas de pollo}} al bol y remover hasta que queden bien cubiertas con la marinada.","minutes":2,"kind":"activo"},{"text":"Tapar el bol y dejar reposar en frío durante 15 min hasta que la marinada penetre en la carne.","minutes":15,"kind":"espera"},{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Disponer las alitas en una bandeja en una sola capa y verter el resto de la marinada por encima.","minutes":2,"kind":"prep"},{"text":"Hornear a 200 °C durante 18 min hasta que las alitas empiecen a dorarse.","minutes":18,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y dar la vuelta a las alitas.","minutes":1,"kind":"activo"},{"text":"Hornear otros 15 min a 200 °C hasta que estén doradas y crujientes.","minutes":15,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y servir las alitas con el jugo de la cocción por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_020', 'Solomillo de cerdo al Pedro Ximénez', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'normal', 'all', 388, 34, 12, 18, 2, true, true, '{"lactosa"}', '[{"name":"Solomillo de cerdo","amount":350,"unit":"g"},{"name":"Pedro Ximénez","amount":80,"unit":"ml"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Champiñones","amount":100,"unit":"g"},{"name":"Nata","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar solomillo de cerdo en medallones de unos 3 cm de grosor.","Cortar cebolla en juliana fina.","Laminar champiñones en láminas de medio centímetro.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Dorar los medallones de solomillo 2 min por cada cara hasta que estén sellados y dorados; retirar y reservar.","Bajar a fuego medio y sofreír la cebolla en la misma sartén hasta que esté transparente y blanda.","Añadir los champiñones laminados y saltear hasta que pierdan el agua y se doren ligeramente.","Verter pedro ximénez y remover; dejar reducir a fuego medio hasta que la salsa espese y quede a la mitad.","Añadir nata y remover hasta que se integre con la salsa.","Incorporar los medallones reservados a la sartén y cocer a fuego suave hasta que estén bien calientes y la salsa los nape.","Servir los medallones con la salsa de champiñones y Pedro Ximénez por encima."}', 'Solomillo de cerdo en salsa de Pedro Ximénez con champiñones', '[{"appliance":"airfryer","time":30,"difficulty":"normal","prepSummary":"Sella el solomillo en la airfryer a 190°C durante 15-20 minutos, dándole la vuelta a mitad. Mientras, sofríe la cebolla y los champiñones en una sartén, añade el Pedro Ximénez y la nata, y reduce la salsa hasta que espese."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Sella el solomillo en una sartén apta para horno, luego añade la cebolla y champiñones y hornea a 180°C durante 25-30 minutos. Retira el solomillo, deglasea la bandeja con Pedro Ximénez y nata para la salsa."},{"appliance":"thermomix","time":35,"difficulty":"normal","prepSummary":"Sofríe la cebolla y champiñones en el vaso, luego añade el solomillo troceado y el Pedro Ximénez, cocinando a temperatura Varoma o 100°C. Incorpora la nata al final y programa unos minutos más para espesar la salsa."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Sella el solomillo en la olla abierta, retira y sofríe la cebolla y champiñones. Vuelve a añadir el solomillo, el Pedro Ximénez, cierra la olla y cocina a presión 5-7 minutos. Abre, añade la nata y reduce la salsa a fuego vivo."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Solomillo de cerdo}} en medallones de unos 3 cm de grosor.","minutes":3,"kind":"prep"},{"text":"Cortar {{Cebolla}} en juliana fina.","minutes":2,"kind":"prep"},{"text":"Laminar {{Champiñones}} en láminas de medio centímetro.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte hasta que humee ligeramente.","minutes":1,"kind":"activo"},{"text":"Dorar los medallones de solomillo 2 min por cada cara hasta que estén sellados y dorados; retirar y reservar.","minutes":4,"kind":"activo"},{"text":"Bajar a fuego medio y sofreír la cebolla en la misma sartén hasta que esté transparente y blanda.","minutes":4,"kind":"activo"},{"text":"Añadir los champiñones laminados y saltear hasta que pierdan el agua y se doren ligeramente.","minutes":3,"kind":"activo"},{"text":"Verter {{Pedro Ximénez}} y remover; dejar reducir a fuego medio hasta que la salsa espese y quede a la mitad.","minutes":4,"kind":"activo"},{"text":"Añadir {{Nata}} y remover hasta que se integre con la salsa.","minutes":1,"kind":"activo"},{"text":"Incorporar los medallones reservados a la sartén y cocer a fuego suave hasta que estén bien calientes y la salsa los nape.","minutes":5,"kind":"pasivo"},{"text":"Servir los medallones con la salsa de champiñones y Pedro Ximénez por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_022', 'Lomo de cerdo en salsa', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 35, 'facil', 'all', 374, 32, 10, 22, 2, true, true, '{}', '[{"name":"Lomo de cerdo en filetes","amount":300,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar cebolla en juliana fina.","Picar ajo muy fino.","Salpimentar lomo de cerdo en filetes por ambas caras.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Dorar el lomo de cerdo en filetes en la sartén, 2 min por cada cara, hasta que estén sellados y dorados.","Retirar los filetes dorados de la sartén y reservar.","Bajar el fuego a medio. Sofreír la cebolla en la misma sartén hasta que esté blanda y transparente.","Añadir el ajo picado y sofreír hasta que desprenda aroma sin llegar a dorarse.","Añadir tomate triturado y remover para integrar con la cebolla y el ajo.","Cocer a fuego medio hasta que el tomate pierda el exceso de líquido.","Verter vino blanco y añadir laurel. Remover y llevar a ebullición a fuego fuerte.","Bajar el fuego a suave y cocer la salsa hasta que el alcohol evapore y reduzca ligeramente.","Devolver los filetes reservados a la sartén y cubrir bien con la salsa.","Tapar y cocer a fuego suave hasta que la carne esté tierna y jugosa.","Retirar el laurel. Servir los filetes de lomo con la salsa por encima."}', 'Filetes de lomo de cerdo en salsa de tomate y vino blanco', '[{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Sella el lomo en una sartén y sofríe la cebolla y el ajo. Mezcla con el resto de ingredientes en una fuente apta para horno y hornea a 180°C durante 25-30 minutos, hasta que la carne esté tierna y la salsa reducida."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Trocea la cebolla y el ajo, sofríe con aceite. Sella el lomo, añade el resto de ingredientes y cocina a temperatura Varoma, velocidad cuchara, giro inverso durante 25-30 minutos, hasta que la carne esté hecha y la salsa ligada."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sella el lomo y sofríe la cebolla y el ajo en la olla. Añade el resto de ingredientes, cierra la olla y cocina a presión durante 8-10 minutos. Despresuriza y si es necesario, reduce la salsa sin tapa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Cebolla}} en juliana fina.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep"},{"text":"Salpimentar {{Lomo de cerdo en filetes}} por ambas caras.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte hasta que humee ligeramente.","minutes":1,"kind":"activo"},{"text":"Dorar el lomo de cerdo en filetes en la sartén, 2 min por cada cara, hasta que estén sellados y dorados.","minutes":4,"kind":"activo"},{"text":"Retirar los filetes dorados de la sartén y reservar.","minutes":1,"kind":"prep"},{"text":"Bajar el fuego a medio. Sofreír la cebolla en la misma sartén hasta que esté blanda y transparente.","minutes":4,"kind":"activo"},{"text":"Añadir el ajo picado y sofreír hasta que desprenda aroma sin llegar a dorarse.","minutes":1,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y remover para integrar con la cebolla y el ajo.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego medio hasta que el tomate pierda el exceso de líquido.","minutes":3,"kind":"pasivo"},{"text":"Verter {{Vino blanco}} y añadir {{Laurel}}. Remover y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Bajar el fuego a suave y cocer la salsa hasta que el alcohol evapore y reduzca ligeramente.","minutes":5,"kind":"pasivo"},{"text":"Devolver los filetes reservados a la sartén y cubrir bien con la salsa.","minutes":1,"kind":"activo"},{"text":"Tapar y cocer a fuego suave hasta que la carne esté tierna y jugosa.","minutes":10,"kind":"pasivo"},{"text":"Retirar el laurel. Servir los filetes de lomo con la salsa por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_023', 'Escalopines de ternera al limón', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 338, 32, 6, 20, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Escalopines de ternera","amount":300,"unit":"g"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Exprimir limón y reservar el zumo.","Picar perejil finamente y reservar.","Extender harina en un plato y enharinar escalopines de ternera por ambas caras, sacudiendo el exceso.","Calentar aceite de oliva en sartén a fuego fuerte hasta que empiece a humear.","Añadir mantequilla y esperar hasta que se derrita y empiece a burbujear.","Dorar los escalopines enharinadosa fuego fuerte, 2 min por cada lado, hasta que estén dorados.","Retirar los escalopines de la sartén y reservar en un plato templado.","Verter el zumo de limón en la misma sartén a fuego medio y remover hasta que reduzca ligeramente, 1 min.","Verter la salsa de limón sobre los escalopines reservados, espolvorear el perejil picado y servir."}', 'Escalopines finos de ternera en salsa de limón y mantequilla', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Enharina los escalopines y rocíalos ligeramente con aceite de oliva. Cocina durante 10-12 minutos, dándoles la vuelta a mitad de cocción, hasta que estén dorados y tiernos. La salsa de limón y mantequilla se prepara aparte en una sartén."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Enharina los escalopines y colócalos en una bandeja de horno ligeramente engrasada. Hornea durante 15-20 minutos, volteándolos una vez, hasta que estén dorados y cocidos. Prepara la salsa de limón y mantequilla en una sartén y viértela sobre los escalopines justo antes de servir."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Exprimir {{Limón}} y reservar el zumo.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil|pizca}} finamente y reservar.","minutes":1,"kind":"prep"},{"text":"Extender {{Harina}} en un plato y enharinar {{Escalopines de ternera}} por ambas caras, sacudiendo el exceso.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte hasta que empiece a humear.","minutes":1,"kind":"activo"},{"text":"Añadir {{Mantequilla}} y esperar hasta que se derrita y empiece a burbujear.","minutes":1,"kind":"activo"},{"text":"Dorar los escalopines enharinadosa fuego fuerte, 2 min por cada lado, hasta que estén dorados.","minutes":4,"kind":"activo"},{"text":"Retirar los escalopines de la sartén y reservar en un plato templado.","minutes":1,"kind":"activo"},{"text":"Verter el zumo de limón en la misma sartén a fuego medio y remover hasta que reduzca ligeramente, 1 min.","minutes":1,"kind":"activo"},{"text":"Verter la salsa de limón sobre los escalopines reservados, espolvorear el perejil picado y servir.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_024', 'Pavo a la plancha', 'carnes', 'pavo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 278, 38, 2, 12, 2, true, true, '{}', '[{"name":"Pechuga de pavo","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo en polvo","amount":3,"unit":"g"},{"name":"Orégano","amount":2,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar pechuga de pavo en filetes de unos 8 mm de grosor.","Exprimir limón y reservar el zumo en un bol pequeño.","Pincelar los filetes de pavo por ambas caras con aceite de oliva.","Espolvorear ajo en polvo y orégano por ambas caras de los filetes.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Colocar los filetes en la plancha y dorar 3 min por cada cara hasta que estén dorados y sin rosa interior.","Retirar los filetes y regar con el zumo de limón reservado antes de servir."}', 'Filetes de pechuga de pavo a la plancha con hierbas', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Marinar el pavo con aceite y especias. Cocinar en la airfryer precalentada a 190-200°C durante 15-18 minutos, dándole la vuelta a mitad para un dorado uniforme y un interior jugoso."},{"appliance":"horno","time":22,"difficulty":"facil","prepSummary":"Precalentar el horno a 200°C. Colocar el pavo marinado en una bandeja y hornear durante 20-25 minutos, hasta que esté cocido y ligeramente dorado. Se puede usar la función grill al final para un mejor acabado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pechuga de pavo}} en filetes de unos 8 mm de grosor.","minutes":3,"kind":"prep"},{"text":"Exprimir {{Limón}} y reservar el zumo en un bol pequeño.","minutes":1,"kind":"prep"},{"text":"Pincelar los filetes de pavo por ambas caras con {{Aceite de oliva}}.","minutes":1,"kind":"prep"},{"text":"Espolvorear {{Ajo en polvo|pizca}} y {{Orégano|pizca}} por ambas caras de los filetes.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Colocar los filetes en la plancha y dorar 3 min por cada cara hasta que estén dorados y sin rosa interior.","minutes":6,"kind":"activo"},{"text":"Retirar los filetes y regar con el zumo de limón reservado antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  main_protein = excluded.main_protein,
  main_base = excluded.main_base,
  meal_roles = excluded.meal_roles,
  type = excluded.type,
  base_dish_id = excluded.base_dish_id,
  required_appliance = excluded.required_appliance,
  time_minutes = excluded.time_minutes,
  difficulty = excluded.difficulty,
  season = excluded.season,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  base_servings = excluded.base_servings,
  kid_friendly = excluded.kid_friendly,
  tupper_friendly = excluded.tupper_friendly,
  allergens = excluded.allergens,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  description = excluded.description,
  methods = excluded.methods,
  product_aliases = excluded.product_aliases,
  apetecible = excluded.apetecible,
  montaje = excluded.montaje,
  can_be_garnish = excluded.can_be_garnish,
  main_ingredients = excluded.main_ingredients,
  sauce_id = excluded.sauce_id,
  extra_proteins = excluded.extra_proteins,
  freezable = excluded.freezable,
  steps_rich = excluded.steps_rich,
  estrella = excluded.estrella;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('carnes_025', 'Pollo al curry', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', NULL, NULL, 35, 'facil', 'all', 396, 34, 14, 22, 2, false, true, '{"lactosa"}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Nata","amount":60,"unit":"ml"},{"name":"Curry en polvo","amount":8,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar pechuga de pollo en dados de unos 3 cm.","Picar cebolla en trozos finos y picar ajo.","Calentar aceite de oliva en una sartén grande a fuego fuerte hasta que esté caliente.","Dorar los dados de pechuga de pollo en la sartén a fuego fuerte hasta que estén dorados por todos los lados.","Retirar el pollo dorado a un plato y reservar.","Sofreír la cebolla picada y el ajo picado en la misma sartén a fuego medio hasta que estén tiernos.","Añadir curry en polvo sobre la cebolla y el ajo y remover durante 1 min hasta que el curry libere su aroma.","Incorporar tomate triturado y remover para integrar; cocer a fuego medio hasta que la salsa espese.","Añadir nata y los dados de pollo reservados; remover para integrar bien.","Cocer a fuego suave, tapado, hasta que el pollo esté tierno y la salsa cremosa.","Servir el pollo al curry directamente desde la sartén."}', 'Pollo en salsa de curry suave con tomate y nata', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en una olla apta para horno. Incorpora el pollo y dora ligeramente. Añade el tomate triturado y el curry, y hornea a 180°C durante 25-30 minutos. Termina con la nata fuera del horno para una salsa cremosa."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríe. Añade el pollo troceado y dora. Incorpora el tomate triturado y el curry, y cocina a 100°C, giro inverso, velocidad cuchara durante 20-25 minutos. Añade la nata al final y mezcla suavemente."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo, dora el pollo en la olla. Añade el tomate triturado y el curry, cierra la olla y cocina a presión durante 8-10 minutos. Despresuriza, incorpora la nata y cocina unos minutos más sin tapa para espesar la salsa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Pechuga de pollo}} en dados de unos 3 cm.","minutes":3,"kind":"prep"},{"text":"Picar {{Cebolla}} en trozos finos y picar {{Ajo}}.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una sartén grande a fuego fuerte hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Dorar los dados de pechuga de pollo en la {{@Sartén}} a fuego fuerte hasta que estén dorados por todos los lados.","minutes":5,"kind":"activo"},{"text":"Retirar el pollo dorado a un plato y reservar.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada y el ajo picado en la misma {{@Sartén}} a fuego medio hasta que estén tiernos.","minutes":4,"kind":"activo"},{"text":"Añadir {{Curry en polvo|pizca}} sobre la cebolla y el ajo y remover durante 1 min hasta que el curry libere su aroma.","minutes":1,"kind":"activo"},{"text":"Incorporar {{Tomate triturado}} y remover para integrar; cocer a fuego medio hasta que la salsa espese.","minutes":10,"kind":"pasivo"},{"text":"Añadir {{Nata}} y los dados de pollo reservados; remover para integrar bien.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave, tapado, hasta que el pollo esté tierno y la salsa cremosa.","minutes":10,"kind":"pasivo"},{"text":"Servir el pollo al curry directamente desde la sartén.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_026', 'Albóndigas de pollo', 'carnes', 'pollo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 35, 'normal', 'all', 378, 32, 16, 20, 2, true, true, '{"gluten","huevo"}', '[{"name":"Carne picada de pollo","amount":300,"unit":"g"},{"name":"Pan rallado","amount":25,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla muy fina. Reservar.","Pelar y rallar zanahoria. Reservar.","Pelar y picar ajo muy fino. Reservar.","Mezclar en un bol carne picada de pollo, huevo, pan rallado y el ajo picado hasta obtener una masa homogénea.","Formar albóndigas del tamaño de una nuez con la masa anterior. Reservar en un plato.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada en el aceite caliente hasta que esté transparente, unos 3 min a fuego medio.","Añadir la zanahoria rallada y sofreír junto a la cebolla 2 min más a fuego medio, removiendo.","Añadir tomate triturado, remover y llevar a ebullición a fuego fuerte.","Incorporar las albóndigas a la salsa, tapar y cocer a fuego suave hasta que estén cocidas por dentro, unos 20 min.","Retirar la tapa, comprobar el punto de la salsa y servir las albóndigas con la salsa por encima."}', 'Albóndigas de pollo en salsa de tomate con zanahoria', '[{"appliance":"airfryer","time":35,"difficulty":"normal","prepSummary":"Forma las albóndigas y cocínalas en la airfryer a 190°C durante 15-20 minutos, girándolas a mitad, hasta que estén doradas. Mientras, prepara la salsa en una sartén y luego incorpora las albóndigas para que se impregnen bien."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Hornea las albóndigas a 180°C durante 15 minutos para dorarlas. Luego, transfiérelas a una fuente con la salsa ya preparada (o con los ingredientes de la salsa) y hornea todo junto 20-25 minutos más a 170°C para que los sabores se integren."},{"appliance":"thermomix","time":45,"difficulty":"normal","prepSummary":"Pica las verduras en el vaso. Prepara la salsa sofriendo las verduras y añadiendo el tomate. Luego, incorpora las albóndigas (previamente formadas) al vaso y cocina a temperatura Varoma, velocidad cuchara, giro inverso, durante 20-25 minutos para que se hagan en la salsa."},{"appliance":"olla_express","time":35,"difficulty":"normal","prepSummary":"Dora las albóndigas en la olla express con un poco de aceite. Retira, sofríe la cebolla, zanahoria y ajo. Añade el tomate, reincorpora las albóndigas y un poco de agua si es necesario. Cierra la olla y cocina 10-12 minutos desde que sube la válvula."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar y picar {{Cebolla}} muy fina. Reservar.","minutes":3,"kind":"prep"},{"text":"Pelar y rallar {{Zanahoria}}. Reservar.","minutes":2,"kind":"prep"},{"text":"Pelar y picar {{Ajo}} muy fino. Reservar.","minutes":1,"kind":"prep"},{"text":"Mezclar en un bol {{Carne picada de pollo}}, {{Huevo}}, {{Pan rallado}} y el ajo picado hasta obtener una masa homogénea.","minutes":2,"kind":"prep"},{"text":"Formar albóndigas del tamaño de una nuez con la masa anterior. Reservar en un plato.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada en el aceite caliente hasta que esté transparente, unos 3 min a fuego medio.","minutes":3,"kind":"activo"},{"text":"Añadir la zanahoria rallada y sofreír junto a la cebolla 2 min más a fuego medio, removiendo.","minutes":2,"kind":"activo"},{"text":"Añadir {{Tomate triturado}}, remover y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Incorporar las albóndigas a la salsa, tapar y cocer a fuego suave hasta que estén cocidas por dentro, unos 20 min.","minutes":20,"kind":"pasivo"},{"text":"Retirar la tapa, comprobar el punto de la salsa y servir las albóndigas con la salsa por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_027', 'Chuletas de cerdo a la plancha', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 402, 30, 1, 30, 2, true, false, '{}', '[{"name":"Chuletas de cerdo","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Romero","amount":2,"unit":"g"}]'::jsonb, '{"Picar ajo muy fino y reservar.","Salpimentar chuletas de cerdo por ambas caras.","Frotar las chuletas con el ajo picado y romero por ambas caras.","Calentar plancha a fuego fuerte hasta que humee ligeramente.","Pincelar plancha con aceite de oliva y colocar las chuletas.","Dorar las chuletas 4 min por el primer lado sin moverlas, hasta que se forme costra dorada.","Girar las chuletas y cocinar 4 min más por el segundo lado hasta que estén doradas.","Retirar las chuletas de plancha y dejar reposar 2 min antes de servir.","Servir las chuletas en el plato con los jugos del reposo por encima."}', 'Chuletas de cerdo a la plancha con ajo y romero', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Marinar las chuletas con aceite, ajo y romero. Precalentar la airfryer a 190-200°C y cocinar durante 15-18 minutos, dándoles la vuelta a mitad para un dorado uniforme y jugosidad."},{"appliance":"horno","time":22,"difficulty":"facil","prepSummary":"Marinar las chuletas. Precalentar el horno a 200-220°C con función grill si es posible. Colocar en una bandeja con rejilla y cocinar unos 20-25 minutos, volteándolas a mitad para que se doren por ambos lados."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Ajo}} muy fino y reservar.","minutes":2,"kind":"prep"},{"text":"Salpimentar {{Chuletas de cerdo}} por ambas caras.","minutes":1,"kind":"prep"},{"text":"Frotar las chuletas con el ajo picado y {{Romero|pizca}} por ambas caras.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que humee ligeramente.","minutes":2,"kind":"activo"},{"text":"Pincelar {{@Plancha}} con {{Aceite de oliva|chorrito}} y colocar las chuletas.","minutes":1,"kind":"activo"},{"text":"Dorar las chuletas 4 min por el primer lado sin moverlas, hasta que se forme costra dorada.","minutes":4,"kind":"activo"},{"text":"Girar las chuletas y cocinar 4 min más por el segundo lado hasta que estén doradas.","minutes":4,"kind":"activo"},{"text":"Retirar las chuletas de {{@Plancha}} y dejar reposar 2 min antes de servir.","minutes":2,"kind":"espera"},{"text":"Servir las chuletas en el plato con los jugos del reposo por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_028', 'Pollo con champiñones', 'carnes', 'pollo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'all', 362, 36, 8, 20, 2, true, true, '{}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Champiñones","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Cortar pechuga de pollo en filetes de unos 2 cm de grosor.","Salpimentar los filetes de pechuga de pollo al gusto por ambas caras.","Limpiar champiñones con un paño húmedo y laminar.","Picar cebolla en daditos finos.","Picar ajo fino.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Dorar los filetes de pechuga de pollo en la sartén, 2 min por cada lado, hasta que estén dorados.","Retirar los filetes de pechuga de pollo de la sartén y reservar en un plato.","Bajar el fuego a medio y sofreír la cebolla picada y el ajo picado en la misma sartén hasta que estén transparentes.","Subir el fuego a fuerte, añadir los champiñones laminados y saltear, removiendo, hasta que suelten el agua y se doren.","Añadir vino blanco y remover para desglasar el fondo de la sartén.","Reducir a fuego medio hasta que el alcohol se evapore.","Picar perejil fino.","Devolver los filetes de pechuga de pollo reservados a la sartén y tapar.","Cocer a fuego suave hasta que el pollo esté bien cocido en el centro.","Retirar del fuego, espolvorear el perejil picado por encima y servir de inmediato."}', 'Pechugas de pollo con champiñones salteados al vino blanco', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Cocina el pollo y los champiñones en la airfryer a 190°C por 15-20 minutos, dándoles la vuelta. Prepara la cebolla, ajo y vino en una sartén aparte y mezcla todo al final para integrar los sabores."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Combina el pollo, champiñones, cebolla, ajo y aceite en una fuente apta para horno. Hornea a 180°C durante 25-30 minutos, añadiendo el vino blanco a mitad de cocción para que los sabores se integren."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Trocea la cebolla y el ajo, sofríelos. Añade el pollo y los champiñones, cocina con el vino blanco a temperatura Varoma/100°C hasta que el pollo esté tierno y la salsa reducida."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla. Incorpora el pollo y los champiñones, añade el vino y cocina a presión durante 8-10 minutos. Deja despresurizar y sirve."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Pechuga de pollo}} en filetes de unos 2 cm de grosor.","minutes":3,"kind":"prep"},{"text":"Salpimentar los filetes de pechuga de pollo al gusto por ambas caras.","minutes":1,"kind":"prep"},{"text":"Limpiar {{Champiñones}} con un paño húmedo y laminar.","minutes":3,"kind":"prep"},{"text":"Picar {{Cebolla}} en daditos finos.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte hasta que humee ligeramente.","minutes":1,"kind":"activo"},{"text":"Dorar los filetes de pechuga de pollo en la sartén, 2 min por cada lado, hasta que estén dorados.","minutes":4,"kind":"activo"},{"text":"Retirar los filetes de pechuga de pollo de la sartén y reservar en un plato.","minutes":1,"kind":"activo"},{"text":"Bajar el fuego a medio y sofreír la cebolla picada y el ajo picado en la misma sartén hasta que estén transparentes.","minutes":3,"kind":"activo"},{"text":"Subir el fuego a fuerte, añadir los champiñones laminados y saltear, removiendo, hasta que suelten el agua y se doren.","minutes":4,"kind":"activo"},{"text":"Añadir {{Vino blanco}} y remover para desglasar el fondo de la sartén.","minutes":1,"kind":"activo"},{"text":"Reducir a fuego medio hasta que el alcohol se evapore.","minutes":2,"kind":"pasivo"},{"text":"Picar {{Perejil}} fino.","minutes":1,"kind":"paralelo","during":11},{"text":"Devolver los filetes de pechuga de pollo reservados a la sartén y tapar.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave hasta que el pollo esté bien cocido en el centro.","minutes":4,"kind":"pasivo"},{"text":"Retirar del fuego, espolvorear el perejil picado por encima y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_029', 'Redondo de ternera', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', NULL, NULL, 90, 'normal', 'all', 412, 38, 14, 22, 2, true, true, '{}', '[{"name":"Redondo de ternera","amount":400,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Vino tinto","amount":100,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Tomate triturado","amount":80,"unit":"ml"}]'::jsonb, '{"Pelar y cortar zanahoria en rodajas gruesas y cebolla en cuartos.","Pelar y laminar ajo.","Calentar aceite de oliva en una olla a fuego fuerte hasta que humee ligeramente.","Añadir redondo de ternera entero y dorar por todos sus lados hasta que tenga costra uniforme, unos 8 min en total.","Retirar el redondo y reservar en un plato.","Sofreír la zanahoria, la cebolla y el ajo en el mismo aceite a fuego medio hasta que estén ligeramente dorados.","Añadir tomate triturado y remover hasta que se integre con las verduras, unos 2 min.","Verter vino tinto y llevar a ebullición hasta que el alcohol se evapore, unos 2 min.","Colocar el redondo reservado sobre las verduras y añadir laurel y 150 ml de agua hasta cubrir a media altura.","Tapar la olla y cocer a fuego suave hasta que el redondo esté tierno al pinchar con una brocheta.","Retirar el redondo de la olla y reposar 5 min antes de cortar.","Triturar la salsa de las verduras en un vaso batidor hasta obtener una crema lisa y volver a calentar a fuego suave si es necesario.","Cortar el redondo en rodajas de 1 cm y servir con la salsa por encima."}', 'Redondo de ternera guisado entero con verduras y vino tinto', '[{"appliance":"horno","time":100,"difficulty":"normal","prepSummary":"Sella la ternera en una cazuela apta para horno. Rehoga las verduras, añade el vino, tomate y laurel. Tapa y hornea a 160-170°C durante 80-90 minutos hasta que la carne esté tierna y la salsa reducida."},{"appliance":"thermomix","time":75,"difficulty":"normal","prepSummary":"Sella la ternera (en Thermomix o aparte). Sofreír las verduras. Incorpora la carne, el vino, tomate y laurel. Cocina a 100°C, giro inverso, velocidad cuchara, durante 60-70 minutos hasta que la carne esté tierna."},{"appliance":"olla_express","time":55,"difficulty":"normal","prepSummary":"Sella la ternera en la olla express. Sofreír las verduras. Añade el vino, tomate y laurel. Cierra y cocina a presión durante 35-40 minutos. Deja despresurizar naturalmente para una carne más jugosa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar y cortar {{Zanahoria}} en rodajas gruesas y {{Cebolla}} en cuartos.","minutes":4,"kind":"prep"},{"text":"Pelar y laminar {{Ajo}}.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una olla a fuego fuerte hasta que humee ligeramente.","minutes":2,"kind":"activo"},{"text":"Añadir {{Redondo de ternera}} entero y dorar por todos sus lados hasta que tenga costra uniforme, unos 8 min en total.","minutes":8,"kind":"activo"},{"text":"Retirar el redondo y reservar en un plato.","minutes":1,"kind":"activo"},{"text":"Sofreír la zanahoria, la cebolla y el ajo en el mismo aceite a fuego medio hasta que estén ligeramente dorados.","minutes":6,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y remover hasta que se integre con las verduras, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Verter {{Vino tinto}} y llevar a ebullición hasta que el alcohol se evapore, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Colocar el redondo reservado sobre las verduras y añadir {{Laurel}} y 150 ml de agua hasta cubrir a media altura.","minutes":1,"kind":"activo"},{"text":"Tapar la olla y cocer a fuego suave hasta que el redondo esté tierno al pinchar con una brocheta.","minutes":60,"kind":"pasivo"},{"text":"Retirar el redondo de la olla y reposar 5 min antes de cortar.","minutes":5,"kind":"espera"},{"text":"Triturar la salsa de las verduras en un vaso batidor hasta obtener una crema lisa y volver a calentar a fuego suave si es necesario.","minutes":3,"kind":"activo"},{"text":"Cortar el redondo en rodajas de 1 cm y servir con la salsa por encima.","minutes":2,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_030', 'Brochetas de pollo', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'verano', 342, 36, 10, 16, 2, true, false, '{}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Orégano","amount":3,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar pechuga de pollo en dados de 3 cm, procurando que sean de tamaño uniforme.","Cortar pimiento rojo en cuadrados de 3 cm.","Cortar pimiento verde en cuadrados de 3 cm.","Cortar cebolla en trozos de 3 cm, separando las capas para que encajen bien en el pincho.","Exprimir limón y reservar el zumo en un bol pequeño.","Ensartar en cada brocheta alternando: dado de pollo, pimiento rojo, cebolla y pimiento verde.","Repetir la secuencia hasta completar cada brocheta.","Pincelar las brochetas con aceite de oliva.","Espolvorear orégano sobre las brochetas y regar con el zumo de limón reservado.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Colocar las brochetas sobre la plancha caliente y asarlas durante 10 min, girándolas cada 2-3 min.","Retirar las brochetas de la plancha cuando el pollo esté dorado y cocido por completo, y servir inmediatamente."}', 'Brochetas de pollo con pimientos y cebolla a la plancha', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cocina las brochetas durante 18-22 minutos, volteándolas a mitad de cocción, hasta que el pollo esté dorado y las verduras tiernas y ligeramente caramelizadas."},{"appliance":"horno","time":28,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Coloca las brochetas en una bandeja con papel de horno y ásalas durante 25-30 minutos, dándoles la vuelta una vez para una cocción uniforme y un buen dorado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pechuga de pollo}} en dados de 3 cm, procurando que sean de tamaño uniforme.","minutes":3,"kind":"prep"},{"text":"Cortar {{Pimiento rojo}} en cuadrados de 3 cm.","minutes":1,"kind":"prep"},{"text":"Cortar {{Pimiento verde}} en cuadrados de 3 cm.","minutes":1,"kind":"prep"},{"text":"Cortar {{Cebolla}} en trozos de 3 cm, separando las capas para que encajen bien en el pincho.","minutes":1,"kind":"prep"},{"text":"Exprimir {{Limón}} y reservar el zumo en un bol pequeño.","minutes":1,"kind":"prep"},{"text":"Ensartar en cada brocheta alternando: dado de pollo, pimiento rojo, cebolla y pimiento verde.","minutes":3,"kind":"prep"},{"text":"Repetir la secuencia hasta completar cada brocheta.","minutes":2,"kind":"prep"},{"text":"Pincelar las brochetas con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"prep"},{"text":"Espolvorear {{Orégano|pizca}} sobre las brochetas y regar con el zumo de limón reservado.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Colocar las brochetas sobre la plancha caliente y asarlas durante 10 min, girándolas cada 2-3 min.","minutes":10,"kind":"activo"},{"text":"Retirar las brochetas de la plancha cuando el pollo esté dorado y cocido por completo, y servir inmediatamente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_031', 'Fricandó de ternera', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 70, 'normal', 'invierno', 398, 34, 12, 22, 2, true, true, '{"gluten"}', '[{"name":"Filetes finos de ternera","amount":300,"unit":"g"},{"name":"Setas","amount":150,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Vino rancio","amount":60,"unit":"ml"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar cebolla en brunoise fina.","Limpiar setas y cortar en láminas gruesas.","Enharinar filetes finos de ternera con harina, sacudiendo el exceso.","Calentar aceite de oliva en una sartén grande a fuego fuerte hasta que humee ligeramente.","Dorar los filetes 1 min por cada lado hasta que estén sellados; retirar y reservar.","Bajar a fuego medio y sofreír la cebolla en la misma sartén, removiendo, hasta que esté transparente.","Añadir tomate triturado y sofreír, removiendo, hasta que reduzca y pierda el agua, unos 5 min.","Incorporar las setas laminadas y saltear a fuego medio hasta que suelten el agua y empiecen a dorarse.","Verter vino rancio y añadir laurel; remover y llevar a ebullición hasta que se evapore el alcohol.","Devolver los filetes reservados a la sartén, tapar y cocer a fuego suave hasta que la carne esté tierna.","Retirar el laurel, comprobar el punto de sal y servir los filetes cubiertos con la salsa y las setas."}', 'Filetes finos de ternera guisados con setas al estilo catalán', '[{"appliance":"horno","time":80,"difficulty":"normal","prepSummary":"Dora los filetes y sofríe la cebolla y setas en una olla apta para horno. Añade el vino, tomate, harina y laurel. Cubre y hornea a 160°C durante 60-70 minutos hasta que la ternera esté muy tierna y la salsa ligada."},{"appliance":"thermomix","time":65,"difficulty":"normal","prepSummary":"Sofríe la cebolla y setas. Incorpora la ternera en trozos para dorar ligeramente. Añade el vino, tomate, harina y laurel. Cocina a 100°C, velocidad cuchara, giro inverso, durante 50-60 minutos hasta que la carne esté tierna y la salsa espesa."},{"appliance":"olla_express","time":45,"difficulty":"normal","prepSummary":"Dora la ternera y sofríe la cebolla y setas en la olla. Añade el vino, tomate, harina y laurel. Cierra la olla y cocina a presión durante 20-25 minutos. Despresuriza y si es necesario, reduce la salsa a fuego vivo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Cebolla}} en brunoise fina.","minutes":3,"kind":"prep"},{"text":"Limpiar {{Setas}} y cortar en láminas gruesas.","minutes":3,"kind":"prep"},{"text":"Enharinar {{Filetes finos de ternera}} con {{Harina}}, sacudiendo el exceso.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una sartén grande a fuego fuerte hasta que humee ligeramente.","minutes":1,"kind":"activo"},{"text":"Dorar los filetes 1 min por cada lado hasta que estén sellados; retirar y reservar.","minutes":3,"kind":"activo"},{"text":"Bajar a fuego medio y sofreír la cebolla en la misma sartén, removiendo, hasta que esté transparente.","minutes":6,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y sofreír, removiendo, hasta que reduzca y pierda el agua, unos 5 min.","minutes":5,"kind":"activo"},{"text":"Incorporar las setas laminadas y saltear a fuego medio hasta que suelten el agua y empiecen a dorarse.","minutes":4,"kind":"activo"},{"text":"Verter {{Vino rancio}} y añadir {{Laurel|gusto}}; remover y llevar a ebullición hasta que se evapore el alcohol.","minutes":2,"kind":"activo"},{"text":"Devolver los filetes reservados a la sartén, tapar y cocer a fuego suave hasta que la carne esté tierna.","minutes":40,"kind":"pasivo"},{"text":"Retirar el laurel, comprobar el punto de sal y servir los filetes cubiertos con la salsa y las setas.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_032', 'Escalope de pollo', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 424, 36, 22, 22, 2, true, true, '{"gluten","huevo"}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":50,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Aplanar las pechugas con film hasta dejarlas finas y uniformes","Batir el huevo en un bol y disponer harina y pan rallado en dos platos aparte","Cortar el limón en gajos y reservar para servir","Salpimentar las pechugas por ambos lados","Pasar cada pechuga por harina, luego por huevo y por último por pan rallado, presionando bien","Calentar abundante aceite en sartén a fuego medio-alto","Cocinar los escalopes 3 min por lado en aceite caliente hasta dorar","Escurrir sobre papel y servir con los gajos de limón"}', 'Pechuga de pollo aplastada, empanada y frita', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Rocía los escalopes empanados con un poco de aceite en spray y cocina durante 12-15 minutos, volteando a mitad, hasta que estén dorados y crujientes."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Coloca los escalopes empanados en una bandeja con papel de horno, rocía con un poco de aceite y hornea 20-25 minutos, volteando una vez, hasta que estén cocidos y ligeramente dorados."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Aplanar las {{Pechuga de pollo}} con film hasta dejarlas finas y uniformes.","minutes":3,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol y disponer {{Harina}} y {{Pan rallado}} en dos platos aparte.","minutes":2,"kind":"prep"},{"text":"Cortar {{Limón}} en gajos y reservar para servir.","minutes":1,"kind":"prep"},{"text":"Salpimentar las pechugas por ambos lados.","minutes":1,"kind":"activo"},{"text":"Pasar cada pechuga por harina, luego por huevo batido y por último por pan rallado, presionando para que se adhiera.","minutes":4,"kind":"activo"},{"text":"Calentar {{@Sartén}} con {{Aceite de oliva|abundante}} a fuego medio-alto hasta que el aceite esté caliente.","minutes":2,"kind":"activo"},{"text":"Cocinar los escalopes 3 min por lado en el aceite caliente hasta que estén dorados y hechos por dentro.","minutes":6,"kind":"activo"},{"text":"Escurrir sobre papel absorbente y servir con los gajos de limón.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_033', 'Ragú de ternera', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 90, 'normal', 'invierno', 436, 34, 16, 26, 2, true, true, '{"apio"}', '[{"name":"Carne de ternera para guisar","amount":350,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Apio","amount":50,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Vino tinto","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar carne de ternera para guisar en dados de unos 3 cm.","Pelar y picar cebolla en brunoise fina.","Pelar y cortar zanahoria en dados pequeños.","Cortar apio en trozos pequeños.","Calentar aceite de oliva en una olla a fuego fuerte hasta que humee ligeramente.","Dorar los dados de carne de ternera en la olla por todos los lados hasta que estén bien sellados; retirar y reservar.","Bajar el fuego a medio y sofreír la cebolla picada en la misma olla hasta que esté translúcida.","Añadir la zanahoria y el apio cortados; sofreír hasta que estén ligeramente tiernos.","Añadir vino tinto y remover hasta que el alcohol se evapore casi por completo.","Añadir tomate triturado y laurel; remover para integrar todos los ingredientes.","Incorporar la carne reservada, tapar la olla y cocer a fuego suave hasta que la carne esté muy tierna.","Retirar la hoja de laurel y servir el ragú bien caliente."}', 'Ragú espeso de ternera con sofrito de verduras y vino tinto', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Primero, sella la carne y sofríe las verduras en una olla apta para horno. Luego, añade el resto de ingredientes, cubre y hornea a 160°C durante 1 hora y 45 minutos, removiendo ocasionalmente, para un ragú tierno y lleno de sabor."},{"appliance":"thermomix","time":80,"difficulty":"normal","prepSummary":"Pica las verduras y sofríelas en el vaso con aceite. Añade la carne (previamente sellada para mejor resultado), el vino y el resto de ingredientes. Cocina 70 minutos a 95°C, giro inverso, velocidad cuchara, para un ragú meloso y bien integrado."},{"appliance":"olla_express","time":50,"difficulty":"normal","prepSummary":"Sella la carne y sofríe las verduras en la olla. Incorpora el resto de ingredientes, cierra la olla y cocina a presión (segundo anillo) durante 35 minutos desde que sube la válvula, para un ragú con carne muy tierna en tiempo récord."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Carne de ternera para guisar}} en dados de unos 3 cm.","minutes":5,"kind":"prep"},{"text":"Pelar y picar {{Cebolla}} en brunoise fina.","minutes":3,"kind":"prep"},{"text":"Pelar y cortar {{Zanahoria}} en dados pequeños.","minutes":3,"kind":"prep"},{"text":"Cortar {{Apio}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una olla a fuego fuerte hasta que humee ligeramente.","minutes":2,"kind":"activo"},{"text":"Dorar los dados de carne de ternera en la olla por todos los lados hasta que estén bien sellados; retirar y reservar.","minutes":6,"kind":"activo"},{"text":"Bajar el fuego a medio y sofreír la cebolla picada en la misma olla hasta que esté translúcida.","minutes":4,"kind":"activo"},{"text":"Añadir la zanahoria y el apio cortados; sofreír hasta que estén ligeramente tiernos.","minutes":4,"kind":"activo"},{"text":"Añadir {{Vino tinto}} y remover hasta que el alcohol se evapore casi por completo.","minutes":3,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y {{Laurel}}; remover para integrar todos los ingredientes.","minutes":2,"kind":"activo"},{"text":"Incorporar la carne reservada, tapar la olla y cocer a fuego suave hasta que la carne esté muy tierna.","minutes":75,"kind":"pasivo"},{"text":"Retirar la hoja de laurel y servir el ragú bien caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_034', 'Pollo a la cerveza', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', NULL, NULL, 45, 'facil', 'all', 408, 34, 10, 24, 2, true, true, '{"gluten"}', '[{"name":"Pollo troceado","amount":500,"unit":"g"},{"name":"Cerveza","amount":200,"unit":"ml"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Pelar y cortar cebolla en juliana fina.","Pelar y picar ajo fino.","Salpimentar pollo troceado por todos los lados.","Calentar aceite de oliva en una cazuela amplia a fuego fuerte hasta que humee ligeramente.","Dorar el pollo troceado en la cazuela hasta que tenga color dorado por todos los lados; retirar y reservar.","Bajar a fuego medio y sofreír la cebolla en juliana en la misma cazuela hasta que esté transparente.","Añadir el ajo picado y sofreír 1 min más hasta que desprenda aroma.","Incorporar el pollo reservado a la cazuela y verter cerveza removiendo para integrar los jugos del fondo.","Añadir laurel y llevar a ebullición a fuego fuerte.","Tapar la cazuela, bajar a fuego suave y cocer hasta que el pollo esté tierno y la salsa haya reducido ligeramente.","Retirar el laurel y servir el pollo con la salsa de cerveza por encima."}', 'Pollo troceado guisado en salsa de cerveza con cebolla', '[{"appliance":"horno","time":55,"difficulty":"facil","prepSummary":"Dora el pollo y las verduras en una cazuela apta para horno. Añade la cerveza y el laurel, tapa y cocina a 180°C durante 40-45 minutos. Destapa los últimos 10 minutos para que la salsa espese."},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo, luego dora ligeramente el pollo en el vaso. Incorpora la cerveza y el laurel, y cocina a 100°C, giro inverso, velocidad cuchara, durante 35-40 minutos hasta que el pollo esté tierno."},{"appliance":"olla_express","time":30,"difficulty":"facil","prepSummary":"Dora el pollo y sofríe la cebolla y el ajo en la olla. Vierte la cerveza y el laurel, cierra la olla y cocina a presión durante 15-20 minutos. Si la salsa está muy líquida, redúcela unos minutos sin tapa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar y cortar {{Cebolla}} en juliana fina.","minutes":3,"kind":"prep"},{"text":"Pelar y picar {{Ajo}} fino.","minutes":2,"kind":"prep"},{"text":"Salpimentar {{Pollo troceado}} por todos los lados.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela amplia a fuego fuerte hasta que humee ligeramente.","minutes":2,"kind":"activo"},{"text":"Dorar el pollo troceado en la cazuela hasta que tenga color dorado por todos los lados; retirar y reservar.","minutes":6,"kind":"activo"},{"text":"Bajar a fuego medio y sofreír la cebolla en juliana en la misma cazuela hasta que esté transparente.","minutes":4,"kind":"activo"},{"text":"Añadir el ajo picado y sofreír 1 min más hasta que desprenda aroma.","minutes":1,"kind":"activo"},{"text":"Incorporar el pollo reservado a la cazuela y verter {{Cerveza}} removiendo para integrar los jugos del fondo.","minutes":1,"kind":"activo"},{"text":"Añadir {{Laurel|pizca}} y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Tapar la cazuela, bajar a fuego suave y cocer hasta que el pollo esté tierno y la salsa haya reducido ligeramente.","minutes":28,"kind":"pasivo"},{"text":"Retirar el laurel y servir el pollo con la salsa de cerveza por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  main_protein = excluded.main_protein,
  main_base = excluded.main_base,
  meal_roles = excluded.meal_roles,
  type = excluded.type,
  base_dish_id = excluded.base_dish_id,
  required_appliance = excluded.required_appliance,
  time_minutes = excluded.time_minutes,
  difficulty = excluded.difficulty,
  season = excluded.season,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  base_servings = excluded.base_servings,
  kid_friendly = excluded.kid_friendly,
  tupper_friendly = excluded.tupper_friendly,
  allergens = excluded.allergens,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  description = excluded.description,
  methods = excluded.methods,
  product_aliases = excluded.product_aliases,
  apetecible = excluded.apetecible,
  montaje = excluded.montaje,
  can_be_garnish = excluded.can_be_garnish,
  main_ingredients = excluded.main_ingredients,
  sauce_id = excluded.sauce_id,
  extra_proteins = excluded.extra_proteins,
  freezable = excluded.freezable,
  steps_rich = excluded.steps_rich,
  estrella = excluded.estrella;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('carnes_035', 'Flamenquines cordobeses', 'carnes', 'cerdo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 512, 34, 22, 32, 2, true, true, '{"gluten","huevo"}', '[{"name":"Lomo de cerdo en filetes","amount":250,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":50,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"}]'::jsonb, '{"Aplanar lomo de cerdo en filetes sobre la tabla con la palma de la mano hasta que queden uniformes.","Colocar jamón serrano sobre cada filete en una sola capa, sin que sobresalga por los bordes.","Enrollar cada filete sobre sí mismo apretando bien para que el jamón quede dentro y no se abra al freír.","Sujetar cada rollo con 1 o 2 palillos para que mantenga la forma durante el rebozado y la fritura.","Disponer 3 platos: uno con harina, uno con huevo batido y uno con pan rallado.","Batir el huevo en su plato hasta que esté homogéneo.","Pasar cada flamenquín por la harina y sacudir el exceso.","Pasar cada flamenquín enharinado por el huevo batido, cubriéndolo bien.","Pasar cada flamenquín por el pan rallado, presionando para que se adhiera por todos los lados.","Calentar aceite de oliva en sartén a fuego fuerte hasta que alcance 180 °C.","Freír los flamenquines en el aceite caliente, girándolos, hasta que estén dorados y crujientes por todos los lados.","Retirar los flamenquines y escurrir sobre papel absorbente hasta que suelten el exceso de aceite.","Retirar los palillos y servir los flamenquines en caliente."}', 'Rollitos de lomo rellenos de jamón serrano, empanados y fritos', '[{"appliance":"airfryer","time":20,"difficulty":"normal","prepSummary":"Precalienta la airfryer a 190-200°C. Rocía ligeramente los flamenquines con aceite de oliva y cocina durante unos 15-20 minutos, dándoles la vuelta a mitad de cocción, hasta que estén dorados y crujientes."},{"appliance":"horno","time":30,"difficulty":"normal","prepSummary":"Precalienta el horno a 200°C con calor arriba y abajo. Coloca los flamenquines en una bandeja con papel de horno, rocíalos con un poco de aceite y hornea durante 25-30 minutos, volteándolos a mitad de cocción, hasta que estén dorados."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Aplanar {{Lomo de cerdo en filetes}} sobre la tabla con la palma de la mano hasta que queden uniformes.","minutes":2,"kind":"prep"},{"text":"Colocar {{Jamón serrano}} sobre cada filete en una sola capa, sin que sobresalga por los bordes.","minutes":1,"kind":"prep"},{"text":"Enrollar cada filete sobre sí mismo apretando bien para que el jamón quede dentro y no se abra al freír.","minutes":2,"kind":"prep"},{"text":"Sujetar cada rollo con 1 o 2 palillos para que mantenga la forma durante el rebozado y la fritura.","minutes":1,"kind":"prep"},{"text":"Disponer 3 platos: uno con {{Harina}}, uno con {{Huevo}} batido y uno con {{Pan rallado}}.","minutes":1,"kind":"prep"},{"text":"Batir el huevo en su plato hasta que esté homogéneo.","minutes":1,"kind":"prep"},{"text":"Pasar cada flamenquín por la harina y sacudir el exceso.","minutes":1,"kind":"prep"},{"text":"Pasar cada flamenquín enharinado por el huevo batido, cubriéndolo bien.","minutes":1,"kind":"prep"},{"text":"Pasar cada flamenquín por el pan rallado, presionando para que se adhiera por todos los lados.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} a fuego fuerte hasta que alcance 180 °C.","minutes":2,"kind":"activo"},{"text":"Freír los flamenquines en el aceite caliente, girándolos, hasta que estén dorados y crujientes por todos los lados.","minutes":6,"kind":"activo"},{"text":"Retirar los flamenquines y escurrir sobre papel absorbente hasta que suelten el exceso de aceite.","minutes":1,"kind":"espera"},{"text":"Retirar los palillos y servir los flamenquines en caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_036', 'Nuggets de pollo caseros', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 420, 32, 22, 22, 2, true, true, '{"gluten","huevo"}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":60,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Cortar pechuga de pollo en trozos de unos 3-4 cm, del tamaño de un bocado.","Batir huevo en un bol hasta homogeneizar.","Disponer harina en un plato y pan rallado en otro plato separado.","Pasar cada trozo de pechuga primero por la harina, sacudiendo el exceso.","Bañar cada trozo enharinado en el huevo batido, escurriendo el sobrante.","Rebozar cada trozo en el pan rallado, presionando para que quede bien adherido.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Freír los nuggets en tandas hasta que estén dorados por todos los lados, unos 4-5 min.","Escurrir los nuggets sobre papel absorbente para eliminar el exceso de aceite.","Servir inmediatamente."}', 'Trozos de pechuga de pollo empanados y fritos, crujientes y jugosos', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Rocía los nuggets empanados con un poco de aceite y cocina durante 12-15 minutos, dándoles la vuelta a mitad de cocción, hasta que estén dorados y crujientes."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Coloca los nuggets empanados en una bandeja con papel de horno, rocía con un poco de aceite y hornea 18-22 minutos, volteándolos una vez, hasta que estén dorados."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Pechuga de pollo}} en trozos de unos 3-4 cm, del tamaño de un bocado.","minutes":4,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol hasta homogeneizar.","minutes":1,"kind":"prep"},{"text":"Disponer {{Harina}} en un plato y {{Pan rallado}} en otro plato separado.","minutes":1,"kind":"prep"},{"text":"Pasar cada trozo de pechuga primero por la harina, sacudiendo el exceso.","minutes":2,"kind":"prep"},{"text":"Bañar cada trozo enharinado en el huevo batido, escurriendo el sobrante.","minutes":2,"kind":"prep"},{"text":"Rebozar cada trozo en el pan rallado, presionando para que quede bien adherido.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Freír los nuggets en tandas hasta que estén dorados por todos los lados, unos 4-5 min.","minutes":5,"kind":"activo"},{"text":"Escurrir los nuggets sobre papel absorbente para eliminar el exceso de aceite.","minutes":1,"kind":"prep"},{"text":"Servir inmediatamente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('carnes_037', 'Carrilleras de ternera al vino tinto', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 210, 'elaborada', 'all', 540, 44, 22, 27, 4, true, true, '{"gluten","lactosa","sulfitos"}', '[{"name":"Carrillera de ternera","amount":900,"unit":"g"},{"name":"Vino tinto","amount":500,"unit":"ml"},{"name":"Apionabo","amount":600,"unit":"g"},{"name":"Zanahoria","amount":150,"unit":"g"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Puerro","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Caldo de carne","amount":300,"unit":"ml"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Tomillo","amount":3,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Cortar apionabo en trozos de tamaño similar para que cuezan de manera uniforme.","Llevar a ebullición una olla con agua abundante y sal.","Cocer el apionabo troceado hasta que esté muy tierno.","Escurrir el apionabo cocido y triturarlo con mantequilla y nata para cocinar hasta obtener un puré sedoso.","Salpimentar el puré con sal y pimienta negra. Reservar en caliente.","Picar cebolla, zanahoria, puerro y ajo en trozos finos.","Salpimentar carrillera de ternera por ambas caras con sal y pimienta negra.","Enharinar las carrilleras con harina, sacudiendo el exceso.","Calentar aceite de oliva en una cazuela grande a fuego fuerte.","Dorar las carrilleras por todos los lados hasta que estén bien selladas. Reservar.","Sofreír la cebolla, la zanahoria, el puerro y el ajo picados en el mismo aceite a fuego medio hasta que ablanden.","Añadir laurel y tomillo al sofrito y remover para integrar.","Devolver las carrilleras a la cazuela y regar con vino tinto.","Dejar reducir el vino a fuego fuerte hasta que el alcohol se evapore.","Añadir caldo de carne, tapar la cazuela y cocer a fuego suave hasta que la carne se deshaga con el tenedor.","Retirar las carrilleras de la cazuela con cuidado y reservarlas tapadas.","Triturar la salsa con una batidora hasta que esté completamente lisa.","Colar la salsa triturada para que quede fina y sin restos de verdura.","Devolver las carrilleras a la cazuela con la salsa colada y calentar a fuego suave hasta que todo esté bien caliente.","Servir una base generosa de puré de apionabo en cada plato, colocar las carrilleras encima y salsear al gusto."}', 'Carrilleras de ternera braseadas lentamente en vino tinto hasta quedar gelatinosas, servidas sobre un puré sedoso de apionabo.', '[{"appliance":"horno","time":210,"difficulty":"elaborada","prepSummary":"Tras sellar la carne y pochar las verduras en una cazuela apta, desglasa con el vino, añade el caldo y especias. Tapa y cocina en el horno precalentado a 150-160°C durante 2.5 a 3 horas, hasta que las carrilleras estén muy tiernas. Finaliza reduciendo la salsa en la encimera."},{"appliance":"thermomix","time":180,"difficulty":"elaborada","prepSummary":"Sella las carrilleras en la Thermomix y reserva. Pocha las verduras, luego incorpora la carne, el vino, caldo y especias. Cocina a temperatura Varoma o 98-100°C con giro inverso y velocidad cuchara durante 2.5 a 3 horas, hasta que la carne se deshaga. La salsa se puede triturar y"},{"appliance":"olla_express","time":90,"difficulty":"normal","prepSummary":"Sella las carrilleras en la olla express y retira. Pocha las verduras, reincorpora la carne, vierte el vino, caldo y especias. Cierra y cocina a presión alta durante 60-75 minutos. Una vez despresurizada, retira la carne y reduce la salsa a fuego vivo para espesar y concentrar sa"}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Apionabo}} en trozos de tamaño similar para que cuezan de manera uniforme.","minutes":5,"kind":"prep","part":"guarnicion"},{"text":"Llevar a ebullición una olla con agua abundante y {{Sal|gusto}}.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Cocer el apionabo troceado hasta que esté muy tierno.","minutes":20,"kind":"pasivo","part":"guarnicion"},{"text":"Escurrir el apionabo cocido y triturarlo con {{Mantequilla}} y {{Nata para cocinar}} hasta obtener un puré sedoso.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Salpimentar el puré con {{Sal|gusto}} y {{Pimienta negra|pizca}}. Reservar en caliente.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Picar {{Cebolla}}, {{Zanahoria}}, {{Puerro}} y {{Ajo}} en trozos finos.","minutes":6,"kind":"prep","part":"principal"},{"text":"Salpimentar {{Carrillera de ternera}} por ambas caras con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep","part":"principal"},{"text":"Enharinar las carrilleras con {{Harina}}, sacudiendo el exceso.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela grande a fuego fuerte.","minutes":1,"kind":"activo","part":"principal"},{"text":"Dorar las carrilleras por todos los lados hasta que estén bien selladas. Reservar.","minutes":6,"kind":"activo","part":"principal"},{"text":"Sofreír la cebolla, la zanahoria, el puerro y el ajo picados en el mismo aceite a fuego medio hasta que ablanden.","minutes":10,"kind":"activo","part":"principal"},{"text":"Añadir {{Laurel}} y {{Tomillo|pizca}} al sofrito y remover para integrar.","minutes":1,"kind":"activo","part":"principal"},{"text":"Devolver las carrilleras a la cazuela y regar con {{Vino tinto}}.","minutes":1,"kind":"activo","part":"principal"},{"text":"Dejar reducir el vino a fuego fuerte hasta que el alcohol se evapore.","minutes":5,"kind":"activo","part":"principal"},{"text":"Añadir {{Caldo de carne}}, tapar la cazuela y cocer a fuego suave hasta que la carne se deshaga con el tenedor.","minutes":150,"kind":"pasivo","part":"principal"},{"text":"Retirar las carrilleras de la cazuela con cuidado y reservarlas tapadas.","minutes":2,"kind":"activo","part":"principal"},{"text":"Triturar la salsa con una batidora hasta que esté completamente lisa.","minutes":2,"kind":"activo","part":"principal"},{"text":"Colar la salsa triturada para que quede fina y sin restos de verdura.","minutes":2,"kind":"activo","part":"principal"},{"text":"Devolver las carrilleras a la cazuela con la salsa colada y calentar a fuego suave hasta que todo esté bien caliente.","minutes":3,"kind":"activo","part":"principal"},{"text":"Servir una base generosa de puré de apionabo en cada plato, colocar las carrilleras encima y salsear al gusto.","minutes":3,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_038', 'Solomillo Wellington', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 90, 'elaborada', 'all', 660, 40, 28, 42, 6, true, false, '{"gluten","lactosa","mostaza","huevo"}', '[{"name":"Solomillo de ternera","amount":900,"unit":"g"},{"name":"Foie mi-cuit","amount":150,"unit":"g"},{"name":"Champiñones","amount":400,"unit":"g"},{"name":"Jamón serrano en lonchas finas","amount":100,"unit":"g"},{"name":"Hojaldre","amount":400,"unit":"g"},{"name":"Mostaza de Dijon","amount":30,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":3,"unit":"g"},{"name":"Tomillo","amount":2,"unit":"g"}]'::jsonb, '{"Calentar sartén a fuego fuerte con aceite de oliva.","Salpimentar solomillo de ternera con sal y pimienta negra.","Sellar el solomillo en la sartén muy caliente por todos los lados hasta que esté dorado, 1-2 min por cara.","Retirar el solomillo de la sartén y dejar enfriar sobre una rejilla o plato.","Picar champiñones muy finos.","Saltear los champiñones picados en la misma sartén a fuego fuerte hasta que suelten toda el agua y quede una duxelle seca.","Añadir tomillo y salpimentar la duxelle al gusto.","Retirar la duxelle de la sartén y dejar enfriar por completo.","Untar el solomillo frío con mostaza de dijon por toda la superficie.","Extender film transparente sobre la encimera y colocar jamón serrano en lonchas finas solapado formando un rectángulo.","Extender la duxelle fría de manera uniforme sobre las lonchas de jamón.","Cortar foie mi-cuit en trozos y repartirlos por encima de la duxelle.","Colocar el solomillo untado en el centro del rectángulo de jamón.","Envolver el solomillo con el film, apretando bien para formar un cilindro compacto y firme.","Refrigerar el cilindro envuelto en film durante 20 min para que mantenga la forma.","Precalentar el horno a 200 °C.","Batir huevo en un bol pequeño.","Extender hojaldre sobre la encimera ligeramente enharinada formando un rectángulo suficiente para envolver el cilindro.","Retirar el film del cilindro y colocarlo en el centro del hojaldre extendido.","Pintar los bordes del hojaldre con huevo batido y envolver el solomillo, sellando bien los extremos.","Colocar el Wellington con el cierre hacia abajo en una bandeja de horno.","Pintar toda la superficie del hojaldre con el huevo batido restante.","Marcar cortes decorativos superficiales en el hojaldre con la punta de un cuchillo sin atravesarlo.","Hornear a 200 °C durante 25-30 min hasta que el hojaldre esté dorado y crujiente.","Retirar el Wellington del horno y dejar reposar 10 min antes de cortar.","Cortar en raciones gruesas y servir de inmediato."}', 'Solomillo de ternera envuelto en jamón, duxelles de champiñones y foie, horneado en hojaldre dorado y crujiente.', '[{"appliance":"horno","time":90,"difficulty":"elaborada","prepSummary":"Sella el solomillo previamente, envuélvelo con la duxelles de champiñones y jamón, y el hojaldre, pintándolo con huevo. Hornea a 200-220°C durante 30-50 minutos, hasta que el hojaldre esté dorado y crujiente y la carne en su punto deseado."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Calentar {{@Sartén}} a fuego fuerte con {{Aceite de oliva|chorrito}}.","minutes":2,"kind":"activo"},{"text":"Salpimentar {{Solomillo de ternera}} con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":2,"kind":"prep"},{"text":"Sellar el solomillo en la sartén muy caliente por todos los lados hasta que esté dorado, 1-2 min por cara.","minutes":6,"kind":"activo"},{"text":"Retirar el solomillo de la sartén y dejar enfriar sobre una rejilla o plato.","minutes":10,"kind":"espera"},{"text":"Picar {{Champiñones}} muy finos.","minutes":5,"kind":"paralelo","during":3},{"text":"Saltear los champiñones picados en la misma sartén a fuego fuerte hasta que suelten toda el agua y quede una duxelle seca.","minutes":10,"kind":"activo"},{"text":"Añadir {{Tomillo|pizca}} y salpimentar la duxelle al gusto.","minutes":1,"kind":"activo"},{"text":"Retirar la duxelle de la sartén y dejar enfriar por completo.","minutes":10,"kind":"espera"},{"text":"Untar el solomillo frío con {{Mostaza de Dijon}} por toda la superficie.","minutes":2,"kind":"prep"},{"text":"Extender film transparente sobre la encimera y colocar {{Jamón serrano en lonchas finas}} solapado formando un rectángulo.","minutes":3,"kind":"prep"},{"text":"Extender la duxelle fría de manera uniforme sobre las lonchas de jamón.","minutes":2,"kind":"prep"},{"text":"Cortar {{Foie mi-cuit}} en trozos y repartirlos por encima de la duxelle.","minutes":2,"kind":"prep"},{"text":"Colocar el solomillo untado en el centro del rectángulo de jamón.","minutes":1,"kind":"prep"},{"text":"Envolver el solomillo con el film, apretando bien para formar un cilindro compacto y firme.","minutes":3,"kind":"prep"},{"text":"Refrigerar el cilindro envuelto en film durante 20 min para que mantenga la forma.","minutes":20,"kind":"espera"},{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Batir {{Huevo}} en un bol pequeño.","minutes":1,"kind":"paralelo","during":15},{"text":"Extender {{Hojaldre}} sobre la encimera ligeramente enharinada formando un rectángulo suficiente para envolver el cilindro.","minutes":3,"kind":"paralelo","during":15},{"text":"Retirar el film del cilindro y colocarlo en el centro del hojaldre extendido.","minutes":1,"kind":"prep"},{"text":"Pintar los bordes del hojaldre con huevo batido y envolver el solomillo, sellando bien los extremos.","minutes":3,"kind":"prep"},{"text":"Colocar el Wellington con el cierre hacia abajo en una bandeja de horno.","minutes":1,"kind":"prep"},{"text":"Pintar toda la superficie del hojaldre con el huevo batido restante.","minutes":1,"kind":"prep"},{"text":"Marcar cortes decorativos superficiales en el hojaldre con la punta de un cuchillo sin atravesarlo.","minutes":2,"kind":"prep"},{"text":"Hornear a 200 °C durante 25-30 min hasta que el hojaldre esté dorado y crujiente.","minutes":28,"kind":"pasivo"},{"text":"Retirar el Wellington del horno y dejar reposar 10 min antes de cortar.","minutes":10,"kind":"espera"},{"text":"Cortar en raciones gruesas y servir de inmediato.","minutes":3,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_039', 'Costillar de cerdo glaseado a baja temperatura', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 260, 'elaborada', 'all', 620, 46, 24, 34, 4, true, true, '{"soja"}', '[{"name":"Costillar de cerdo","amount":1400,"unit":"g"},{"name":"Salsa de soja","amount":60,"unit":"ml"},{"name":"Miel","amount":80,"unit":"g"},{"name":"Ketchup","amount":60,"unit":"g"},{"name":"Vinagre de manzana","amount":30,"unit":"ml"},{"name":"Ajo","amount":20,"unit":"g"},{"name":"Pimentón dulce","amount":6,"unit":"g"},{"name":"Pimentón picante","amount":3,"unit":"g"},{"name":"Comino","amount":3,"unit":"g"},{"name":"Sal","amount":8,"unit":"g"},{"name":"Pimienta negra","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Picar ajo muy fino y reservar.","Mezclar pimentón dulce, pimentón picante, comino, sal y pimienta negra en un bol hasta obtener un adobo seco homogéneo.","Frotar costillar de cerdo con aceite de oliva por ambas caras.","Aplicar el adobo seco sobre el costillar, cubriendo bien toda la superficie por ambas caras.","Envolver el costillar en papel de aluminio y refrigerar en la nevera.","Precalentar el horno a 130 °C.","Colocar el costillar envuelto en papel de aluminio sobre una bandeja y hornear a 130 °C.","Calentar un cazo a fuego suave y añadir salsa de soja, miel, ketchup, vinagre de manzana y el ajo picado.","Remover la mezcla y cocer a fuego suave hasta que el glaseado espese ligeramente.","Retirar el glaseado del fuego y reservar a temperatura ambiente.","Retirar el costillar del horno y desenvolver el papel de aluminio con cuidado del vapor.","Subir la temperatura del horno a 220 °C.","Pincelar el costillar generosamente con el glaseado por ambas caras.","Hornear el costillar destapado a 220 °C, pincelando con más glaseado cada 5 min.","Retirar del horno cuando el costillar esté oscuro y brillante, y dejar reposar fuera del horno.","Cortar el costillar entre los huesos y servir con el resto del glaseado aparte."}', 'Costillar de cerdo cocinado muy lentamente hasta quedar tierno y glaseado con una laca oscura y brillante.', '[{"appliance":"horno","time":260,"difficulty":"elaborada","prepSummary":"Marinar las costillas y cocinarlas lentamente en el horno a baja temperatura (aprox. 130-140°C) durante unas 4 horas para que queden extremadamente tiernas. Finalmente, subir la temperatura o usar el grill para glasear y caramelizar la superficie con la salsa."},{"appliance":"olla_express","time":80,"difficulty":"normal","prepSummary":"Cocinar las costillas en la olla express con parte de la salsa durante unos 45-60 minutos para ablandarlas rápidamente. Después, transferir al horno o airfryer a alta temperatura (200-220°C) durante 20-30 minutos, pincelando con la salsa restante para un glaseado perfecto."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Picar {{Ajo}} muy fino y reservar.","minutes":2,"kind":"prep"},{"text":"Mezclar {{Pimentón dulce}}, {{Pimentón picante}}, {{Comino}}, {{Sal|gusto}} y {{Pimienta negra|pizca}} en un bol hasta obtener un adobo seco homogéneo.","minutes":2,"kind":"prep"},{"text":"Frotar {{Costillar de cerdo}} con {{Aceite de oliva|chorrito}} por ambas caras.","minutes":2,"kind":"prep"},{"text":"Aplicar el adobo seco sobre el costillar, cubriendo bien toda la superficie por ambas caras.","minutes":3,"kind":"prep"},{"text":"Envolver el costillar en papel de aluminio y refrigerar en la nevera.","minutes":60,"kind":"espera"},{"text":"Precalentar el horno a 130 °C.","minutes":15,"kind":"pasivo"},{"text":"Colocar el costillar envuelto en papel de aluminio sobre una bandeja y hornear a 130 °C.","minutes":180,"kind":"pasivo"},{"text":"Calentar un cazo a fuego suave y añadir {{Salsa de soja}}, {{Miel}}, {{Ketchup}}, {{Vinagre de manzana}} y el ajo picado.","minutes":2,"kind":"paralelo","during":6},{"text":"Remover la mezcla y cocer a fuego suave hasta que el glaseado espese ligeramente.","minutes":10,"kind":"paralelo","during":6},{"text":"Retirar el glaseado del fuego y reservar a temperatura ambiente.","minutes":1,"kind":"paralelo","during":6},{"text":"Retirar el costillar del horno y desenvolver el papel de aluminio con cuidado del vapor.","minutes":2,"kind":"activo"},{"text":"Subir la temperatura del horno a 220 °C.","minutes":10,"kind":"pasivo"},{"text":"Pincelar el costillar generosamente con el glaseado por ambas caras.","minutes":2,"kind":"activo"},{"text":"Hornear el costillar destapado a 220 °C, pincelando con más glaseado cada 5 min.","minutes":15,"kind":"activo"},{"text":"Retirar del horno cuando el costillar esté oscuro y brillante, y dejar reposar fuera del horno.","minutes":5,"kind":"espera"},{"text":"Cortar el costillar entre los huesos y servir con el resto del glaseado aparte.","minutes":3,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_040', 'Pato a la naranja con reducción de Cointreau', 'carnes', 'pollo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 70, 'normal', 'all', 520, 32, 26, 30, 2, true, true, '{"lactosa","sulfitos"}', '[{"name":"Pechuga de pato","amount":400,"unit":"g"},{"name":"Naranja","amount":2,"unit":"ud"},{"name":"Zumo de naranja","amount":150,"unit":"ml"},{"name":"Azúcar","amount":40,"unit":"g"},{"name":"Cointreau","amount":50,"unit":"ml"},{"name":"Vinagre de vino blanco","amount":15,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Caldo de pollo","amount":100,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Marcar la piel de pechuga de pato con cortes en rombo sin llegar a la carne.","Salpimentar las pechugas con sal y pimienta negra por ambos lados.","Rallar la piel de 1 naranja y reservar. Pelar en vivo la otra naranja y sacar los gajos; reservar.","Colocar las pechugas en sartén fría con la piel hacia abajo y calentar a fuego medio.","Cocinar a fuego medio hasta que la piel esté dorada y crujiente y la grasa se derrita.","Dar la vuelta a las pechugas y cocinar a fuego medio hasta que estén rosadas por dentro.","Retirar las pechugas de la sartén y tapar con papel de aluminio para que reposen.","Retirar el exceso de grasa de la sartén dejando solo una cucharada.","Añadir azúcar a la sartén y calentar a fuego medio hasta que se caramelice ligeramente.","Añadir vinagre de vino blanco y raspar el fondo de la sartén para desglasar.","Añadir zumo de naranja y la ralladura de naranja reservada; remover para integrar.","Añadir caldo de pollo y reducir a fuego medio hasta que la salsa espese ligeramente.","Retirar la sartén del fuego y añadir cointreau; flambear con cuidado hasta que se apague la llama.","Añadir mantequilla fría y remover hasta que la salsa quede brillante y ligada.","Cortar las pechugas en lonchas y disponerlas en el plato.","Napar las lonchas con la salsa de naranja y decorar con los gajos de naranja reservados."}', 'Pechuga de pato con la piel dorada y crujiente, napada en una salsa espejo de naranja y Cointreau flambeado.', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Sella la pechuga de pato en una sartén apta para horno hasta dorar la piel, luego termina la cocción en el horno a 180-200°C para una carne jugosa. Prepara la salsa de naranja y Cointreau en la misma sartén sobre el fuego, aprovechando los jugos del pato."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Cocina la pechuga de pato en la airfryer a 180-200°C durante 20-25 minutos, volteándola a mitad, para lograr una piel muy crujiente. La reducción de Cointreau y naranja se elabora simultáneamente en una sartén aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Marcar la piel de {{Pechuga de pato}} con cortes en rombo sin llegar a la carne.","minutes":2,"kind":"prep"},{"text":"Salpimentar las pechugas con {{Sal|gusto}} y {{Pimienta negra|pizca}} por ambos lados.","minutes":1,"kind":"prep"},{"text":"Rallar la piel de 1 {{Naranja}} y reservar. Pelar en vivo la otra naranja y sacar los gajos; reservar.","minutes":4,"kind":"prep"},{"text":"Colocar las pechugas en {{@Sartén}} fría con la piel hacia abajo y calentar a fuego medio.","minutes":1,"kind":"activo"},{"text":"Cocinar a fuego medio hasta que la piel esté dorada y crujiente y la grasa se derrita.","minutes":8,"kind":"pasivo"},{"text":"Dar la vuelta a las pechugas y cocinar a fuego medio hasta que estén rosadas por dentro.","minutes":4,"kind":"activo"},{"text":"Retirar las pechugas de la sartén y tapar con papel de aluminio para que reposen.","minutes":8,"kind":"espera"},{"text":"Retirar el exceso de grasa de la sartén dejando solo una cucharada.","minutes":1,"kind":"activo"},{"text":"Añadir {{Azúcar}} a la sartén y calentar a fuego medio hasta que se caramelice ligeramente.","minutes":2,"kind":"activo"},{"text":"Añadir {{Vinagre de vino blanco}} y raspar el fondo de la sartén para desglasar.","minutes":1,"kind":"activo"},{"text":"Añadir {{Zumo de naranja}} y la ralladura de naranja reservada; remover para integrar.","minutes":1,"kind":"activo"},{"text":"Añadir {{Caldo de pollo}} y reducir a fuego medio hasta que la salsa espese ligeramente.","minutes":5,"kind":"pasivo"},{"text":"Retirar la sartén del fuego y añadir {{Cointreau}}; flambear con cuidado hasta que se apague la llama.","minutes":2,"kind":"activo"},{"text":"Añadir {{Mantequilla}} fría y remover hasta que la salsa quede brillante y ligada.","minutes":2,"kind":"activo"},{"text":"Cortar las pechugas en lonchas y disponerlas en el plato.","minutes":2,"kind":"emplatado"},{"text":"Napar las lonchas con la salsa de naranja y decorar con los gajos de naranja reservados.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_041', 'Magret de pato con salsa de frutos rojos', 'carnes', 'pollo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 35, 'normal', 'all', 500, 30, 22, 30, 2, true, true, '{"lactosa","sulfitos"}', '[{"name":"Magret de pato","amount":400,"unit":"g"},{"name":"Frutos rojos (frambuesa, mora, arándano)","amount":200,"unit":"g"},{"name":"Vino tinto","amount":100,"unit":"ml"},{"name":"Azúcar moreno","amount":30,"unit":"g"},{"name":"Vinagre balsámico","amount":15,"unit":"ml"},{"name":"Chalota","amount":40,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Laminar la piel de magret de pato con cortes en rombo sin llegar a la carne.","Salpimentar el magret por ambas caras con sal y pimienta negra.","Picar chalota en brunoise fina.","Colocar el magret en sartén fría con la piel hacia abajo a fuego medio.","Cocinar hasta que la piel esté dorada y crujiente y la grasa haya fundido, sin mover.","Voltear el magret y cocinar por el lado de la carne hasta que esté rosado en el centro.","Retirar el magret de la sartén y tapar con papel de aluminio para que repose.","Retirar casi toda la grasa de la sartén, dejando solo una cucharada.","Sofreír la chalota picada en la misma sartén a fuego medio hasta que esté transparente.","Añadir frutos rojos (frambuesa, mora, arándano) y azúcar moreno y remover para integrar.","Añadir vino tinto y vinagre balsámico y remover.","Cocer a fuego medio hasta que la salsa haya reducido y tenga consistencia densa.","Triturar la salsa ligeramente con un tenedor, dejando algo de textura.","Retirar la sartén del fuego y añadir mantequilla, removiendo hasta que la salsa brille.","Laminar el magret en lonchas finas en diagonal.","Servir las lonchas napadas con la salsa de frutos rojos."}', 'Magret de pato con la piel crujiente y una salsa granate de frutos rojos reducida al vino tinto.', '[{"appliance":"horno","time":35,"difficulty":"normal","prepSummary":"Sella el magret en una sartén apta para horno por el lado de la piel hasta dorar y renderizar la grasa. Luego, termina la cocción en el horno precalentado a 180°C durante 10-15 minutos para el punto deseado. La salsa de frutos rojos se prepara simultáneamente en la encimera, redu"}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Laminar la piel de {{Magret de pato}} con cortes en rombo sin llegar a la carne.","minutes":2,"kind":"prep"},{"text":"Salpimentar el magret por ambas caras con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep"},{"text":"Picar {{Chalota}} en brunoise fina.","minutes":2,"kind":"prep"},{"text":"Colocar el magret en {{@Sartén}} fría con la piel hacia abajo a fuego medio.","minutes":1,"kind":"activo","part":"principal"},{"text":"Cocinar hasta que la piel esté dorada y crujiente y la grasa haya fundido, sin mover.","minutes":8,"kind":"pasivo","part":"principal"},{"text":"Voltear el magret y cocinar por el lado de la carne hasta que esté rosado en el centro.","minutes":3,"kind":"activo","part":"principal"},{"text":"Retirar el magret de la sartén y tapar con papel de aluminio para que repose.","minutes":5,"kind":"espera","part":"principal"},{"text":"Retirar casi toda la grasa de la sartén, dejando solo una cucharada.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Sofreír la chalota picada en la misma sartén a fuego medio hasta que esté transparente.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Añadir {{Frutos rojos (frambuesa, mora, arándano)}} y {{Azúcar moreno}} y remover para integrar.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Añadir {{Vino tinto}} y {{Vinagre balsámico}} y remover.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Cocer a fuego medio hasta que la salsa haya reducido y tenga consistencia densa.","minutes":9,"kind":"pasivo","part":"salsa"},{"text":"Triturar la salsa ligeramente con un tenedor, dejando algo de textura.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Retirar la sartén del fuego y añadir {{Mantequilla}}, removiendo hasta que la salsa brille.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Laminar el magret en lonchas finas en diagonal.","minutes":2,"kind":"prep","part":"combinado"},{"text":"Servir las lonchas napadas con la salsa de frutos rojos.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_042', 'Rabo de toro al vino de Jerez', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 240, 'elaborada', 'invierno', 580, 46, 28, 30, 4, true, true, '{"gluten","sulfitos","lactosa"}', '[{"name":"Rabo de toro troceado","amount":1400,"unit":"g"},{"name":"Vino de Jerez","amount":300,"unit":"ml"},{"name":"Cebolla","amount":250,"unit":"g"},{"name":"Zanahoria","amount":200,"unit":"g"},{"name":"Puerro","amount":100,"unit":"g"},{"name":"Ajo","amount":20,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"g"},{"name":"Caldo de carne","amount":400,"unit":"ml"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Laurel","amount":2,"unit":"ud"},{"name":"Pimienta negra","amount":3,"unit":"g"},{"name":"Sal","amount":8,"unit":"g"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Leche","amount":80,"unit":"ml"}]'::jsonb, '{"Salpimentar rabo de toro troceado por todos los lados.","Enharinar el rabo de toro con harina, sacudiendo el exceso.","Calentar aceite de oliva en una cazuela a fuego fuerte hasta que humee.","Dorar el rabo de toro por todos los lados hasta que esté bien sellado y con color.","Retirar el rabo de toro de la cazuela y reservar.","Pelar y picar cebolla en trozos finos.","Pelar y picar zanahoria en trozos finos.","Limpiar y picar puerro en trozos finos.","Pelar y picar ajo fino.","Sofreír la cebolla, la zanahoria, el puerro y el ajo en la misma cazuela a fuego medio hasta que estén blandos.","Añadir tomate triturado y sofreír hasta que pierda el agua y se concentre.","Devolver el rabo de toro a la cazuela y añadir laurel y pimienta negra.","Añadir vino de jerez y llevar a ebullición hasta que el alcohol se evapore.","Añadir caldo de carne, tapar la cazuela y cocer a fuego suave hasta que la carne se separe del hueso.","Pelar patata y cortar en trozos.","Cocer la patata en agua con sal hasta que esté tierna.","Retirar el rabo de toro de la cazuela y reservar.","Retirar el laurel y triturar la salsa con la batidora hasta que esté fina.","Colar la salsa triturada de vuelta a la cazuela.","Devolver el rabo de toro a la cazuela con la salsa colada y cocer a fuego medio sin tapar hasta que la salsa reduzca.","Calentar leche en un cazo a fuego suave hasta que esté caliente.","Escurrir la patata cocida y triturar con mantequilla y la leche caliente hasta obtener un puré fino.","Rectificar el punto de sal del puré.","Servir el rabo de toro con su salsa sobre una base de puré de patata."}', 'Rabo de toro guisado despacio en vino de Jerez hasta que la carne se deshace, servido sobre puré de patata.', '[{"appliance":"horno","time":240,"difficulty":"elaborada","prepSummary":"Tras sellar el rabo y pochar las verduras en una cazuela apta, añade el resto de ingredientes y brasea a fuego lento en el horno a 150-160°C durante 3-4 horas hasta que la carne se desprenda del hueso."},{"appliance":"thermomix","time":210,"difficulty":"elaborada","prepSummary":"Sofríe las verduras y sella el rabo por tandas en el vaso. Incorpora el resto de líquidos y cocina a 95°C, giro inverso, velocidad cuchara, durante 3-3.5 horas, asegurando una cocción uniforme y tierna."},{"appliance":"olla_express","time":120,"difficulty":"normal","prepSummary":"Sella el rabo y sofríe las verduras en la olla. Añade el vino, tomate y caldo, cierra la olla y cocina a presión alta durante 60-90 minutos. Despresuriza y deja reposar para una carne melosa."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Salpimentar {{Rabo de toro troceado}} por todos los lados.","minutes":2,"kind":"prep","part":"principal"},{"text":"Enharinar el rabo de toro con {{Harina}}, sacudiendo el exceso.","minutes":2,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de oliva}} en una cazuela a fuego fuerte hasta que humee.","minutes":2,"kind":"activo","part":"principal"},{"text":"Dorar el rabo de toro por todos los lados hasta que esté bien sellado y con color.","minutes":8,"kind":"activo","part":"principal"},{"text":"Retirar el rabo de toro de la cazuela y reservar.","minutes":1,"kind":"prep","part":"principal"},{"text":"Pelar y picar {{Cebolla}} en trozos finos.","minutes":3,"kind":"prep","part":"principal"},{"text":"Pelar y picar {{Zanahoria}} en trozos finos.","minutes":2,"kind":"prep","part":"principal"},{"text":"Limpiar y picar {{Puerro}} en trozos finos.","minutes":2,"kind":"prep","part":"principal"},{"text":"Pelar y picar {{Ajo}} fino.","minutes":1,"kind":"prep","part":"principal"},{"text":"Sofreír la cebolla, la zanahoria, el puerro y el ajo en la misma cazuela a fuego medio hasta que estén blandos.","minutes":12,"kind":"activo","part":"principal"},{"text":"Añadir {{Tomate triturado}} y sofreír hasta que pierda el agua y se concentre.","minutes":5,"kind":"activo","part":"principal"},{"text":"Devolver el rabo de toro a la cazuela y añadir {{Laurel}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"activo","part":"principal"},{"text":"Añadir {{Vino de Jerez}} y llevar a ebullición hasta que el alcohol se evapore.","minutes":5,"kind":"activo","part":"principal"},{"text":"Añadir {{Caldo de carne}}, tapar la cazuela y cocer a fuego suave hasta que la carne se separe del hueso.","minutes":150,"kind":"pasivo","part":"principal"},{"text":"Pelar {{Patata}} y cortar en trozos.","minutes":4,"kind":"paralelo","part":"guarnicion","during":13},{"text":"Cocer la patata en agua con {{Sal|gusto}} hasta que esté tierna.","minutes":20,"kind":"pasivo","part":"guarnicion"},{"text":"Retirar el rabo de toro de la cazuela y reservar.","minutes":2,"kind":"prep","part":"principal"},{"text":"Retirar el laurel y triturar la salsa con la batidora hasta que esté fina.","minutes":3,"kind":"activo","part":"principal"},{"text":"Colar la salsa triturada de vuelta a la cazuela.","minutes":2,"kind":"activo","part":"principal"},{"text":"Devolver el rabo de toro a la cazuela con la salsa colada y cocer a fuego medio sin tapar hasta que la salsa reduzca.","minutes":10,"kind":"pasivo","part":"principal"},{"text":"Calentar {{Leche}} en un cazo a fuego suave hasta que esté caliente.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Escurrir la patata cocida y triturar con {{Mantequilla}} y la leche caliente hasta obtener un puré fino.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Rectificar el punto de sal del puré.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Servir el rabo de toro con su salsa sobre una base de puré de patata.","minutes":2,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_043', 'Medio cochinillo confitado con piel crujiente', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 320, 'elaborada', 'all', 650, 48, 2, 48, 6, true, true, '{"sulfitos"}', '[{"name":"Medio cochinillo","amount":2500,"unit":"g"},{"name":"Manteca de cerdo","amount":300,"unit":"g"},{"name":"Ajo","amount":40,"unit":"g"},{"name":"Laurel","amount":4,"unit":"ud"},{"name":"Tomillo","amount":6,"unit":"g"},{"name":"Sal gorda","amount":30,"unit":"g"},{"name":"Pimienta negra","amount":6,"unit":"g"},{"name":"Vino blanco","amount":100,"unit":"ml"}]'::jsonb, '{"Salar medio cochinillo por ambos lados con sal gorda.","Reposar el cochinillo a temperatura ambiente hasta que la sal penetre.","Precalentar el horno a 120 °C.","Machacar ajo hasta obtener un majado grueso.","Fundir manteca de cerdo en un cazo a fuego suave hasta que esté líquida.","Colocar el cochinillo en una bandeja honda con la piel hacia arriba.","Repartir el ajo majado, laurel y tomillo alrededor del cochinillo.","Verter la manteca de cerdo fundida y vino blanco sobre la bandeja.","Cubrir la bandeja con papel de aluminio, sellando bien los bordes.","Hornear a 120 °C durante 3 h, hasta que la carne esté muy tierna y se separe del hueso.","Retirar la bandeja del horno y quitar el papel de aluminio con cuidado del vapor.","Secar bien la piel del cochinillo con papel de cocina hasta que no quede humedad.","Pintar la piel con la grasa recogida en la bandeja usando un pincel o cuchara.","Espolvorear la piel con pimienta negra y un poco más de sal gorda.","Subir la temperatura del horno a 220 °C.","Hornear destapado a 220 °C hasta que la piel esté dorada y crujiente, vigilando que no se queme.","Retirar el cochinillo del horno y dejar reposar antes de trocear.","Trocear el cochinillo y servir bien caliente con la piel hacia arriba."}', 'Medio cochinillo confitado a baja temperatura hasta quedar tierno por dentro y con la piel crujiente por fuera.', '[{"appliance":"horno","time":320,"difficulty":"elaborada","prepSummary":"Cocina el cochinillo sumergido en manteca a baja temperatura (aprox. 130-150°C) durante varias horas hasta que esté muy tierno. Para la piel crujiente, sube la temperatura del horno a 200-220°C durante los últimos 20-30 minutos."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Salar {{Medio cochinillo}} por ambos lados con {{Sal gorda|gusto}}.","minutes":5,"kind":"prep"},{"text":"Reposar el cochinillo a temperatura ambiente hasta que la sal penetre.","minutes":30,"kind":"espera"},{"text":"Precalentar el horno a 120 °C.","minutes":15,"kind":"pasivo"},{"text":"Machacar {{Ajo}} hasta obtener un majado grueso.","minutes":3,"kind":"paralelo","during":2},{"text":"Fundir {{Manteca de cerdo}} en un cazo a fuego suave hasta que esté líquida.","minutes":3,"kind":"paralelo","during":2},{"text":"Colocar el cochinillo en una bandeja honda con la piel hacia arriba.","minutes":2,"kind":"prep"},{"text":"Repartir el ajo majado, {{Laurel}} y {{Tomillo}} alrededor del cochinillo.","minutes":2,"kind":"prep"},{"text":"Verter la manteca de cerdo fundida y {{Vino blanco}} sobre la bandeja.","minutes":1,"kind":"prep"},{"text":"Cubrir la bandeja con papel de aluminio, sellando bien los bordes.","minutes":2,"kind":"prep"},{"text":"Hornear a 120 °C durante 3 h, hasta que la carne esté muy tierna y se separe del hueso.","minutes":180,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y quitar el papel de aluminio con cuidado del vapor.","minutes":2,"kind":"activo"},{"text":"Secar bien la piel del cochinillo con papel de cocina hasta que no quede humedad.","minutes":3,"kind":"activo"},{"text":"Pintar la piel con la grasa recogida en la bandeja usando un pincel o cuchara.","minutes":2,"kind":"activo"},{"text":"Espolvorear la piel con {{Pimienta negra|pizca}} y un poco más de sal gorda.","minutes":1,"kind":"activo"},{"text":"Subir la temperatura del horno a 220 °C.","minutes":10,"kind":"pasivo"},{"text":"Hornear destapado a 220 °C hasta que la piel esté dorada y crujiente, vigilando que no se queme.","minutes":25,"kind":"activo"},{"text":"Retirar el cochinillo del horno y dejar reposar antes de trocear.","minutes":10,"kind":"espera"},{"text":"Trocear el cochinillo y servir bien caliente con la piel hacia arriba.","minutes":5,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_044', 'Solomillo al whisky flambeado con patatas panadera', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 680, 40, 34, 40, 2, true, true, '{"lactosa"}', '[{"name":"Solomillo de ternera","amount":400,"unit":"g"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Whisky","amount":60,"unit":"ml"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":3,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en rodajas finas de unos 3 mm.","Cortar cebolla en juliana fina.","Calentar aceite de oliva en sartén amplia a fuego medio.","Añadir las patatas y la cebolla, tapar y cocer a fuego suave hasta que estén tiernas y doradas.","Picar ajo fino.","Cortar solomillo de ternera en medallones de unos 3 cm de grosor.","Salpimentar los medallones con sal y pimienta negra por ambas caras.","Picar perejil fresco fino y reservar.","Añadir sal a las patatas y remover para distribuir.","Calentar mantequilla en sartén limpia a fuego fuerte hasta que espume.","Añadir el ajo picado y sofreír 30 segundos hasta que empiece a dorarse.","Añadir los medallones y dorar 2 min por cada cara hasta que estén sellados y rosados por dentro.","Retirar la sartén del fuego y añadir whisky con cuidado.","Flambear acercando una llama al borde de la sartén hasta que el fuego se apague solo.","Volver a poner la sartén al fuego suave y añadir nata para cocinar.","Reducir la salsa a fuego suave, removiendo, hasta que espese ligeramente.","Servir los medallones sobre las patatas panadera, napar con la salsa y espolvorear el perejil picado."}', 'Medallones de solomillo flambeados al whisky con una salsa cremosa, acompañados de patatas panadera.', '[{"appliance":"airfryer","time":45,"difficulty":"normal","prepSummary":"Para el solomillo, séllalo a 200°C por 15-20 min, volteando a mitad, para un exterior dorado. Las patatas panadera se cortan finas con cebolla, se rocían con aceite y se cocinan a 180°C por 25-30 min, removiendo hasta que estén tiernas y doradas. La salsa de whisky se prepara apa"},{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Las patatas panadera se hornean a 180°C con cebolla, aceite y un poco de caldo por 40-50 min. El solomillo se sella en una fuente de horno muy caliente a 220°C por 10 min, luego se baja a 180°C para terminar la cocción. La salsa de whisky se prepara aparte en un cazo."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en rodajas finas de unos 3 mm.","minutes":5,"kind":"prep","part":"guarnicion"},{"text":"Cortar {{Cebolla}} en juliana fina.","minutes":3,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} amplia a fuego medio.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Añadir las patatas y la cebolla, tapar y cocer a fuego suave hasta que estén tiernas y doradas.","minutes":20,"kind":"pasivo","part":"guarnicion"},{"text":"Picar {{Ajo}} fino.","minutes":2,"kind":"paralelo","part":"principal","during":3},{"text":"Cortar {{Solomillo de ternera}} en medallones de unos 3 cm de grosor.","minutes":2,"kind":"paralelo","part":"principal","during":3},{"text":"Salpimentar los medallones con {{Sal|gusto}} y {{Pimienta negra|gusto}} por ambas caras.","minutes":1,"kind":"paralelo","part":"principal","during":3},{"text":"Picar {{Perejil fresco}} fino y reservar.","minutes":1,"kind":"paralelo","part":"principal","during":3},{"text":"Añadir {{Sal|gusto}} a las patatas y remover para distribuir.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Calentar {{Mantequilla}} en {{@Sartén}} limpia a fuego fuerte hasta que espume.","minutes":1,"kind":"activo","part":"principal"},{"text":"Añadir el ajo picado y sofreír 30 segundos hasta que empiece a dorarse.","minutes":1,"kind":"activo","part":"principal"},{"text":"Añadir los medallones y dorar 2 min por cada cara hasta que estén sellados y rosados por dentro.","minutes":4,"kind":"activo","part":"principal"},{"text":"Retirar la sartén del fuego y añadir {{Whisky}} con cuidado.","minutes":1,"kind":"activo","part":"principal"},{"text":"Flambear acercando una llama al borde de la sartén hasta que el fuego se apague solo.","minutes":1,"kind":"activo","part":"principal"},{"text":"Volver a poner la sartén al fuego suave y añadir {{Nata para cocinar}}.","minutes":1,"kind":"activo","part":"principal"},{"text":"Reducir la salsa a fuego suave, removiendo, hasta que espese ligeramente.","minutes":4,"kind":"activo","part":"principal"},{"text":"Servir los medallones sobre las patatas panadera, napar con la salsa y espolvorear el perejil picado.","minutes":2,"kind":"emplatado","part":"combinado"}]'::jsonb, true)
