insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('carnes_045', 'Entraña a la brasa con chimichurri', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 480, 38, 3, 34, 2, true, true, '{"sulfitos"}', '[{"name":"Entraña de ternera","amount":400,"unit":"g"},{"name":"Perejil fresco","amount":20,"unit":"g"},{"name":"Orégano seco","amount":3,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"},{"name":"Vinagre de vino tinto","amount":20,"unit":"ml"},{"name":"Guindilla en copos","amount":1,"unit":"g"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Retirar entraña de ternera de la nevera y dejar atemperar a temperatura ambiente.","Picar perejil fresco muy fino.","Picar ajo muy fino.","Mezclar en un bol el perejil picado y el ajo picado con orégano seco, guindilla en copos, vinagre de vino tinto y aceite de oliva.","Reservar el chimichurri y dejar reposar para que se integren los sabores.","Salpimentar la entraña por ambos lados con sal y pimienta negra.","Calentar plancha a fuego fuerte hasta que esté muy caliente.","Asar la entraña 3 min por el primer lado, hasta que esté bien marcada.","Dar la vuelta a la entraña y asar 3 min por el otro lado, hasta que esté marcada y jugosa por dentro.","Retirar la entraña de la plancha y dejar reposar en una tabla.","Cortar la entraña en tiras en contra de la fibra.","Servir las tiras de entraña con el chimichurri por encima."}', 'Entraña a la brasa bien marcada por fuera y jugosa por dentro, con un chimichurri verde recién picado.', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 200°C. Cocina la entraña salpimentada durante 20-25 minutos, volteándola a mitad, hasta que esté dorada y jugosa. Un truco clave es no sobrecargar la cesta para asegurar un buen sellado y dorado uniforme."},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Precalienta el horno a 220°C con función grill si es posible. Cocina la entraña en una bandeja caliente durante 10-15 minutos por cada lado, hasta conseguir un buen dorado. El truco es sellarla primero a alta temperatura para mantenerla jugosa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Retirar {{Entraña de ternera}} de la nevera y dejar atemperar a temperatura ambiente.","minutes":20,"kind":"espera","part":"principal"},{"text":"Picar {{Perejil fresco}} muy fino.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Mezclar en un bol el perejil picado y el ajo picado con {{Orégano seco}}, {{Guindilla en copos}}, {{Vinagre de vino tinto}} y {{Aceite de oliva|chorrito}}.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Reservar el chimichurri y dejar reposar para que se integren los sabores.","minutes":10,"kind":"espera","part":"salsa"},{"text":"Salpimentar la entraña por ambos lados con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté muy caliente.","minutes":2,"kind":"activo","part":"principal"},{"text":"Asar la entraña 3 min por el primer lado, hasta que esté bien marcada.","minutes":3,"kind":"pasivo","part":"principal"},{"text":"Dar la vuelta a la entraña y asar 3 min por el otro lado, hasta que esté marcada y jugosa por dentro.","minutes":3,"kind":"activo","part":"principal"},{"text":"Retirar la entraña de la plancha y dejar reposar en una tabla.","minutes":5,"kind":"espera","part":"principal"},{"text":"Cortar la entraña en tiras en contra de la fibra.","minutes":1,"kind":"prep","part":"principal"},{"text":"Servir las tiras de entraña con el chimichurri por encima.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_046', 'Steak tartare de ternera', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'normal', 'all', 380, 28, 18, 22, 2, false, false, '{"huevo","mostaza","gluten","pescado","sulfitos"}', '[{"name":"Solomillo de ternera muy fresco","amount":300,"unit":"g"},{"name":"Yema de huevo","amount":2,"unit":"ud"},{"name":"Alcaparras","amount":20,"unit":"g"},{"name":"Pepinillos en vinagre","amount":30,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Mostaza de Dijon","amount":15,"unit":"g"},{"name":"Salsa Worcestershire","amount":10,"unit":"ml"},{"name":"Tabasco","amount":2,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"},{"name":"Pan tostado","amount":100,"unit":"g"}]'::jsonb, '{"Picar solomillo de ternera muy fresco a cuchillo en dados muy finos; nunca usar picadora para preservar la textura.","Reservar la carne picada en un bol sobre hielo hasta el momento de mezclar.","Picar alcaparras muy finas.","Picar pepinillos en vinagre muy finos.","Picar cebolla morada muy fina.","Añadir al bol con la carne las alcaparras picadas, los pepinillos picados y la cebolla morada picada.","Añadir mostaza de dijon, salsa worcestershire, tabasco y aceite de oliva.","Salpimentar con sal y pimienta negra.","Mezclar con suavidad hasta integrar todo sin machacar la carne.","Formar 2 montículos con ayuda de un aro de emplatar en el centro de cada plato.","Hacer un hueco en el centro de cada montículo y colocar yema de huevo cruda en cada uno.","Servir de inmediato con pan tostado aparte."}', 'Steak tartare de ternera picado a cuchillo, aliñado y coronado con una yema de huevo cruda.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"La Thermomix es ideal para picar finamente el solomillo de ternera y el resto de ingredientes (alcaparras, pepinillos, cebolla morada) en pocos segundos, usando golpes de turbo o velocidad 5-7. Luego, mezcla todos los componentes a velocidad cuchara para integrar la preparación d"}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Solomillo de ternera muy fresco}} a cuchillo en dados muy finos; nunca usar picadora para preservar la textura.","minutes":8,"kind":"prep"},{"text":"Reservar la carne picada en un bol sobre hielo hasta el momento de mezclar.","minutes":1,"kind":"prep"},{"text":"Picar {{Alcaparras}} muy finas.","minutes":1,"kind":"prep"},{"text":"Picar {{Pepinillos en vinagre}} muy finos.","minutes":1,"kind":"prep"},{"text":"Picar {{Cebolla morada}} muy fina.","minutes":1,"kind":"prep"},{"text":"Añadir al bol con la carne las alcaparras picadas, los pepinillos picados y la cebolla morada picada.","minutes":1,"kind":"activo"},{"text":"Añadir {{Mostaza de Dijon}}, {{Salsa Worcestershire}}, {{Tabasco}} y {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"activo"},{"text":"Salpimentar con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"activo"},{"text":"Mezclar con suavidad hasta integrar todo sin machacar la carne.","minutes":1,"kind":"activo"},{"text":"Formar 2 montículos con ayuda de un aro de emplatar en el centro de cada plato.","minutes":1,"kind":"emplatado"},{"text":"Hacer un hueco en el centro de cada montículo y colocar {{Yema de huevo}} cruda en cada uno.","minutes":1,"kind":"emplatado"},{"text":"Servir de inmediato con {{Pan tostado}} aparte.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_047', 'Presa ibérica a la brasa con mojo', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 520, 34, 8, 40, 2, true, true, '{"sulfitos","gluten"}', '[{"name":"Presa ibérica","amount":400,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Comino","amount":2,"unit":"g"},{"name":"Pimentón dulce","amount":4,"unit":"g"},{"name":"Pimentón picante","amount":2,"unit":"g"},{"name":"Vinagre de vino","amount":15,"unit":"ml"},{"name":"Aceite de oliva","amount":60,"unit":"ml"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pan duro","amount":20,"unit":"g"}]'::jsonb, '{"Asar pimiento rojo entero sobre la llama directamente hasta que la piel esté completamente negra.","Envolver el pimiento asado en papel de cocina y dejar reposar hasta que enfríe lo suficiente para manejarlo.","Sacar presa ibérica de la nevera para que atempere mientras el pimiento reposa.","Pelar y despepitar el pimiento asado, retirando bien la piel quemada.","Triturar el pimiento pelado con ajo, comino, pimentón dulce, pimentón picante, pan duro, vinagre de vino y aceite de oliva hasta obtener una salsa fina.","Añadir sal al mojo, mezclar y reservar.","Calentar plancha a fuego fuerte hasta que humee.","Salar la presa ibérica por ambas caras.","Asar la presa en la plancha caliente 4 min por el primer lado, sin moverla, hasta que esté bien dorada.","Dar la vuelta y asar 4 min más por el otro lado hasta que esté dorada y jugosa por dentro.","Retirar la presa de la plancha y dejar reposar en una tabla 5 min para que los jugos se asienten.","Cortar la presa en lonchas gruesas en diagonal.","Servir las lonchas con el mojo rojo aparte o napado por encima."}', 'Presa ibérica asada a la brasa, jugosa y veteada, acompañada de un mojo rojo canario.', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 200°C. Cocina la presa ibérica durante 15-18 minutos, dándole la vuelta a mitad, para un exterior sellado y un interior jugoso. El mojo se prepara aparte triturando los ingredientes."},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Precalienta el horno a 220-230°C con función grill. Cocina la presa ibérica directamente en la rejilla o en una fuente apta para grill durante 15-20 minutos, volteándola, para lograr un exterior dorado y un interior jugoso. El mojo se prepara aparte."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Asar {{Pimiento rojo}} entero sobre la llama directamente hasta que la piel esté completamente negra.","minutes":10,"kind":"activo","part":"salsa"},{"text":"Envolver el pimiento asado en papel de cocina y dejar reposar hasta que enfríe lo suficiente para manejarlo.","minutes":10,"kind":"espera","part":"salsa"},{"text":"Sacar {{Presa ibérica}} de la nevera para que atempere mientras el pimiento reposa.","minutes":10,"kind":"paralelo","part":"principal","during":1},{"text":"Pelar y despepitar el pimiento asado, retirando bien la piel quemada.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Triturar el pimiento pelado con {{Ajo}}, {{Comino|pizca}}, {{Pimentón dulce|pizca}}, {{Pimentón picante|pizca}}, {{Pan duro}}, {{Vinagre de vino}} y {{Aceite de oliva|chorrito}} hasta obtener una salsa fina.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Añadir {{Sal|gusto}} al mojo, mezclar y reservar.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que humee.","minutes":2,"kind":"activo","part":"principal"},{"text":"Salar la presa ibérica por ambas caras.","minutes":1,"kind":"prep","part":"principal"},{"text":"Asar la presa en la plancha caliente 4 min por el primer lado, sin moverla, hasta que esté bien dorada.","minutes":4,"kind":"activo","part":"principal"},{"text":"Dar la vuelta y asar 4 min más por el otro lado hasta que esté dorada y jugosa por dentro.","minutes":4,"kind":"activo","part":"principal"},{"text":"Retirar la presa de la plancha y dejar reposar en una tabla 5 min para que los jugos se asienten.","minutes":5,"kind":"espera","part":"principal"},{"text":"Cortar la presa en lonchas gruesas en diagonal.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Servir las lonchas con el mojo rojo aparte o napado por encima.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_048', 'Ossobuco a la milanesa con gremolata', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 150, 'elaborada', 'all', 560, 44, 30, 26, 4, true, true, '{"gluten","sulfitos","apio","lactosa"}', '[{"name":"Jarrete de ternera con hueso (ossobuco)","amount":1200,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Zanahoria","amount":150,"unit":"g"},{"name":"Apio","amount":100,"unit":"g"},{"name":"Vino blanco","amount":150,"unit":"ml"},{"name":"Tomate triturado","amount":300,"unit":"g"},{"name":"Caldo de carne","amount":300,"unit":"ml"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Perejil fresco","amount":15,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Leche","amount":60,"unit":"ml"},{"name":"Sal","amount":8,"unit":"g"},{"name":"Pimienta negra","amount":3,"unit":"g"}]'::jsonb, '{"Picar cebolla, zanahoria y apio en dados pequeños y reservar.","Salpimentar jarrete de ternera con hueso (ossobuco) por ambas caras con sal y pimienta negra.","Enharinar el ossobuco por ambas caras con harina, sacudiendo el exceso.","Calentar aceite de oliva en una cazuela amplia a fuego fuerte hasta que humee.","Dorar el ossobuco 3-4 min por cada cara hasta que esté bien sellado. Reservar en un plato.","Sofreír la cebolla, la zanahoria y el apio picados en la misma cazuela a fuego medio, removiendo, hasta que se ablanden.","Devolver el ossobuco a la cazuela y añadir vino blanco. Dejar reducir hasta que el alcohol se evapore.","Añadir tomate triturado y caldo de carne. Remover para integrar y llevar a ebullición.","Tapar la cazuela, bajar a fuego suave y cocer hasta que la carne se separe fácilmente del hueso.","Pelar y cortar patata en trozos medianos.","Cocer la patata en una olla con agua y sal al gusto. Hervir hasta que esté tierna.","Calentar leche en un cazo a fuego suave hasta que esté caliente. Reservar.","Escurrir la patata cocida y triturar en la misma olla con mantequilla y la leche caliente hasta obtener un puré liso.","Salpimentar el puré al gusto. Reservar tapado para mantener el calor.","Picar perejil fresco muy fino.","Picar ajo muy fino.","Rallar la piel de limón con un rallador fino para obtener la ralladura.","Mezclar el perejil picado, el ajo picado y la ralladura de limón en un bol pequeño para formar la gremolata.","Disponer una base de puré de patata en cada plato y colocar encima un trozo de ossobuco con su salsa.","Espolvorear la gremolata sobre el ossobuco justo antes de servir."}', 'Ossobuco de ternera braseado hasta que la carne se separa del hueso, con gremolata fresca y puré de patata.', '[{"appliance":"horno","time":210,"difficulty":"elaborada","prepSummary":"Tras sellar la carne y sofreír las verduras en una olla apta para horno, se cocina tapado a 160-170°C durante 2.5-3 horas hasta que la carne esté muy tierna. El calor envolvente del horno asegura una cocción uniforme y un estofado perfecto."},{"appliance":"thermomix","time":180,"difficulty":"normal","prepSummary":"Pica las verduras y sofríelas en el vaso. Tras sellar el ossobuco (en sartén aparte para un mejor dorado), añade el resto de ingredientes y cocina en función ''cocción lenta'' o ''estofado'' a 90-95°C durante 2-2.5 horas, logrando una carne tierna y una salsa ligada. La gremolata y e"},{"appliance":"olla_express","time":80,"difficulty":"normal","prepSummary":"Sella el ossobuco y sofríe las verduras en la propia olla. Añade el resto de ingredientes líquidos, cierra y cocina a presión alta durante 45-60 minutos. La olla express reduce drásticamente el tiempo de cocción, obteniendo una carne muy tierna y una salsa concentrada."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Picar {{Cebolla}}, {{Zanahoria}} y {{Apio}} en dados pequeños y reservar.","minutes":5,"kind":"prep","part":"principal"},{"text":"Salpimentar {{Jarrete de ternera con hueso (ossobuco)}} por ambas caras con {{Sal|gusto}} y {{Pimienta negra|gusto}}.","minutes":2,"kind":"prep","part":"principal"},{"text":"Enharinar el ossobuco por ambas caras con {{Harina}}, sacudiendo el exceso.","minutes":2,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de oliva}} en una cazuela amplia a fuego fuerte hasta que humee.","minutes":2,"kind":"activo","part":"principal"},{"text":"Dorar el ossobuco 3-4 min por cada cara hasta que esté bien sellado. Reservar en un plato.","minutes":8,"kind":"activo","part":"principal"},{"text":"Sofreír la cebolla, la zanahoria y el apio picados en la misma cazuela a fuego medio, removiendo, hasta que se ablanden.","minutes":10,"kind":"activo","part":"principal"},{"text":"Devolver el ossobuco a la cazuela y añadir {{Vino blanco}}. Dejar reducir hasta que el alcohol se evapore.","minutes":5,"kind":"activo","part":"principal"},{"text":"Añadir {{Tomate triturado}} y {{Caldo de carne}}. Remover para integrar y llevar a ebullición.","minutes":3,"kind":"activo","part":"principal"},{"text":"Tapar la cazuela, bajar a fuego suave y cocer hasta que la carne se separe fácilmente del hueso.","minutes":90,"kind":"pasivo","part":"principal"},{"text":"Pelar y cortar {{Patata}} en trozos medianos.","minutes":5,"kind":"paralelo","part":"guarnicion","during":8},{"text":"Cocer la patata en una olla con agua y sal al gusto. Hervir hasta que esté tierna.","minutes":20,"kind":"pasivo","part":"guarnicion"},{"text":"Calentar {{Leche}} en un cazo a fuego suave hasta que esté caliente. Reservar.","minutes":3,"kind":"paralelo","part":"guarnicion","during":10},{"text":"Escurrir la patata cocida y triturar en la misma olla con {{Mantequilla}} y la leche caliente hasta obtener un puré liso.","minutes":4,"kind":"activo","part":"guarnicion"},{"text":"Salpimentar el puré al gusto. Reservar tapado para mantener el calor.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Picar {{Perejil fresco}} muy fino.","minutes":2,"kind":"paralelo","part":"principal","during":8},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"paralelo","part":"principal","during":8},{"text":"Rallar la piel de {{Limón}} con un rallador fino para obtener la ralladura.","minutes":1,"kind":"paralelo","part":"principal","during":8},{"text":"Mezclar el perejil picado, el ajo picado y la ralladura de limón en un bol pequeño para formar la gremolata.","minutes":1,"kind":"prep","part":"principal"},{"text":"Disponer una base de puré de patata en cada plato y colocar encima un trozo de ossobuco con su salsa.","minutes":3,"kind":"emplatado","part":"combinado"},{"text":"Espolvorear la gremolata sobre el ossobuco justo antes de servir.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_049', 'Pluma ibérica al Pedro Ximénez con pera', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 35, 'normal', 'all', 540, 34, 24, 32, 2, true, true, '{"sulfitos","lactosa"}', '[{"name":"Pluma ibérica","amount":400,"unit":"g"},{"name":"Pera","amount":2,"unit":"ud"},{"name":"Vino Pedro Ximénez","amount":150,"unit":"ml"},{"name":"Chalota","amount":40,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Caldo de carne","amount":80,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar pera y cortar cada una en cuartos.","Retirar el corazón de cada cuarto de pera.","Picar chalota finamente.","Salpimentar pluma ibérica por ambas caras con sal y pimienta negra.","Fundir la mitad de mantequilla en sartén a fuego medio.","Añadir los cuartos de pera y dorar a fuego medio hasta que estén dorados y tiernos.","Retirar la pera caramelizada y reservar en un plato.","Calentar aceite de oliva en la misma sartén a fuego fuerte.","Sellar la pluma ibérica 3 min por cada lado hasta que esté dorada.","Retirar la pluma ibérica, tapar y dejar reposar fuera del fuego.","Sofreír la chalota picada en la misma sartén a fuego medio hasta que esté transparente.","Añadir vino pedro ximénez y reducir a fuego medio hasta que espese como un almíbar.","Añadir caldo de carne y cocer a fuego medio hasta que la salsa ligue.","Retirar la sartén del fuego e incorporar el resto de la mantequilla, removiendo hasta que brille.","Cortar la pluma ibérica en lonchas.","Disponer las lonchas en el plato, napar con la salsa y servir con la pera caramelizada."}', 'Pluma ibérica con una salsa dulzona de Pedro Ximénez y peras caramelizadas.', '[]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Pera}} y cortar cada una en cuartos.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Retirar el corazón de cada cuarto de pera.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Picar {{Chalota}} finamente.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Salpimentar {{Pluma ibérica}} por ambas caras con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep","part":"principal"},{"text":"Fundir la mitad de {{Mantequilla}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Añadir los cuartos de pera y dorar a fuego medio hasta que estén dorados y tiernos.","minutes":7,"kind":"activo","part":"guarnicion"},{"text":"Retirar la pera caramelizada y reservar en un plato.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva|chorrito}} en la misma {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo","part":"principal"},{"text":"Sellar la pluma ibérica 3 min por cada lado hasta que esté dorada.","minutes":6,"kind":"activo","part":"principal"},{"text":"Retirar la pluma ibérica, tapar y dejar reposar fuera del fuego.","minutes":5,"kind":"espera","part":"principal"},{"text":"Sofreír la chalota picada en la misma sartén a fuego medio hasta que esté transparente.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Añadir {{Vino Pedro Ximénez}} y reducir a fuego medio hasta que espese como un almíbar.","minutes":6,"kind":"pasivo","part":"salsa"},{"text":"Añadir {{Caldo de carne}} y cocer a fuego medio hasta que la salsa ligue.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Retirar la sartén del fuego e incorporar el resto de la mantequilla, removiendo hasta que brille.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Cortar la pluma ibérica en lonchas.","minutes":1,"kind":"prep","part":"combinado"},{"text":"Disponer las lonchas en el plato, napar con la salsa y servir con la pera caramelizada.","minutes":2,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_050', 'Codornices escabechadas', 'carnes', 'pollo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 60, 'normal', 'all', 520, 38, 12, 36, 4, false, true, '{"gluten","sulfitos"}', '[{"name":"Codorniz limpia entera","amount":8,"unit":"ud"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Zanahoria","amount":200,"unit":"g"},{"name":"Ajo","amount":30,"unit":"g"},{"name":"Vinagre de vino blanco","amount":200,"unit":"ml"},{"name":"Vino blanco","amount":150,"unit":"ml"},{"name":"Aceite de oliva","amount":200,"unit":"ml"},{"name":"Laurel","amount":4,"unit":"ud"},{"name":"Romero","amount":5,"unit":"g"},{"name":"Pimienta negra en grano","amount":3,"unit":"g"},{"name":"Sal","amount":8,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"}]'::jsonb, '{"Salpimentar codorniz limpia entera por dentro y por fuera con sal.","Enharinar las codornices con harina, sacudiendo el exceso.","Pelar y cortar cebolla en juliana fina.","Pelar y cortar zanahoria en rodajas de medio centímetro.","Pelar ajo y dejar los dientes enteros.","Calentar la mitad de aceite de oliva en una cazuela a fuego fuerte.","Dorar las codornices en la cazuela por todos los lados hasta que estén bien doradas.","Retirar las codornices y reservar en un plato.","Añadir el resto del aceite de oliva a la misma cazuela y bajar a fuego medio.","Sofreír la cebolla, la zanahoria y el ajo hasta que estén tiernos y ligeramente dorados.","Devolver las codornices a la cazuela sobre las verduras.","Añadir laurel, romero y pimienta negra en grano a la cazuela.","Verter vinagre de vino blanco y vino blanco sobre las codornices.","Tapar la cazuela y cocer a fuego suave hasta que las codornices estén tiernas.","Retirar la cazuela del fuego y dejar enfriar a temperatura ambiente.","Refrigerar las codornices en su escabeche en la nevera hasta que absorban todo el sabor.","Servir las codornices frías o atemperadas acompañadas de las verduras y el líquido del escabeche."}', 'Codornices escabechadas con verduras, romero y vinagre, para comer frías y con más sabor de un día para otro.', '[{"appliance":"horno","time":70,"difficulty":"normal","prepSummary":"Dorar las codornices y sofreír las verduras en una olla apta para horno. Añadir el resto de ingredientes y cocinar tapado en el horno a fuego lento (aprox. 160-170°C) durante unos 60-75 minutos hasta que las codornices estén tiernas y los sabores integrados."},{"appliance":"thermomix","time":75,"difficulty":"normal","prepSummary":"Dorar las codornices en el vaso (en dos tandas si es necesario). Retirar y sofreír las verduras. Añadir las codornices, líquidos y especias, y programar cocción lenta (unos 60-70 min a 90-100°C, giro inverso, velocidad cuchara) hasta que estén tiernas."},{"appliance":"olla_express","time":40,"difficulty":"normal","prepSummary":"Dorar las codornices y sofreír las verduras en la olla abierta. Añadir el resto de ingredientes, cerrar y cocinar a presión durante unos 15-20 minutos. Dejar despresurizar naturalmente para una carne más tierna y jugosa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Salpimentar {{Codorniz limpia entera}} por dentro y por fuera con {{Sal|gusto}}.","minutes":2,"kind":"prep"},{"text":"Enharinar las codornices con {{Harina}}, sacudiendo el exceso.","minutes":2,"kind":"prep"},{"text":"Pelar y cortar {{Cebolla}} en juliana fina.","minutes":3,"kind":"prep"},{"text":"Pelar y cortar {{Zanahoria}} en rodajas de medio centímetro.","minutes":2,"kind":"prep"},{"text":"Pelar {{Ajo}} y dejar los dientes enteros.","minutes":1,"kind":"prep"},{"text":"Calentar la mitad de {{Aceite de oliva}} en una cazuela a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Dorar las codornices en la cazuela por todos los lados hasta que estén bien doradas.","minutes":8,"kind":"activo"},{"text":"Retirar las codornices y reservar en un plato.","minutes":1,"kind":"activo"},{"text":"Añadir el resto del aceite de oliva a la misma cazuela y bajar a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla, la zanahoria y el ajo hasta que estén tiernos y ligeramente dorados.","minutes":10,"kind":"activo"},{"text":"Devolver las codornices a la cazuela sobre las verduras.","minutes":1,"kind":"activo"},{"text":"Añadir {{Laurel}}, {{Romero}} y {{Pimienta negra en grano}} a la cazuela.","minutes":1,"kind":"activo"},{"text":"Verter {{Vinagre de vino blanco}} y {{Vino blanco}} sobre las codornices.","minutes":1,"kind":"activo"},{"text":"Tapar la cazuela y cocer a fuego suave hasta que las codornices estén tiernas.","minutes":38,"kind":"pasivo"},{"text":"Retirar la cazuela del fuego y dejar enfriar a temperatura ambiente.","minutes":30,"kind":"espera"},{"text":"Refrigerar las codornices en su escabeche en la nevera hasta que absorban todo el sabor.","minutes":720,"kind":"espera"},{"text":"Servir las codornices frías o atemperadas acompañadas de las verduras y el líquido del escabeche.","minutes":2,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_051', 'Costillas glaseadas al horno', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 120, 'facil', 'all', 560, 40, 20, 34, 4, true, true, '{"soja"}', '[{"name":"Costillas de cerdo","amount":1200,"unit":"g"},{"name":"Salsa barbacoa","amount":150,"unit":"g"},{"name":"Miel","amount":40,"unit":"g"},{"name":"Salsa de soja","amount":30,"unit":"ml"},{"name":"Ajo en polvo","amount":5,"unit":"g"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 150 °C.","Salpimentar costillas de cerdo con sal y pimienta negra.","Frotar las costillas con ajo en polvo y pimentón dulce.","Añadir aceite de oliva sobre las costillas y repartir bien por toda la superficie.","Envolver las costillas en papel de aluminio y colocarlas en una bandeja de horno.","Hornear a 150 °C durante 90 min, hasta que la carne esté muy tierna.","Mezclar en un bol salsa barbacoa, miel y salsa de soja hasta obtener un glaseado homogéneo.","Retirar las costillas del horno y desenvolver con cuidado el papel de aluminio.","Subir la temperatura del horno a 220 °C.","Pincelar las costillas con el glaseado por ambos lados de forma generosa.","Hornear destapadas a 220 °C durante 7 min, hasta que el glaseado empiece a caramelizar.","Retirar las costillas, pincelar de nuevo con el glaseado y volver a introducir en el horno.","Hornear 6 min más, hasta que la superficie quede oscura y pegajosa.","Retirar del horno y dejar reposar 5 min antes de cortar.","Cortar entre los huesos y servir con el resto del glaseado."}', 'Costillas de cerdo horneadas a baja temperatura y glaseadas hasta quedar pegajosas y oscuras.', '[{"appliance":"horno","time":125,"difficulty":"facil","prepSummary":"Marinar las costillas y hornear a 150°C durante 90-100 minutos cubiertas con papel de aluminio. Luego, destapar, subir la temperatura a 190°C y glasear con la salsa cada 10-15 minutos durante 20-30 minutos más, hasta que estén tiernas y caramelizadas."},{"appliance":"airfryer","time":55,"difficulty":"facil","prepSummary":"Corta las costillas en porciones individuales y marínalas. Cocínalas en la airfryer a 170°C durante 35-40 minutos, dándoles la vuelta. Luego, pincela con la salsa glaseada y cocina a 190°C por 10-15 minutos más hasta que estén doradas y caramelizadas."},{"appliance":"olla_express","time":65,"difficulty":"normal","prepSummary":"Cocina las costillas marinadas en la olla express con un poco de líquido durante 35-40 minutos a alta presión para ablandarlas. Luego, pásalas a una bandeja de horno o airfryer, píntalas con la salsa y hornea/fríe a 200°C durante 15-20 minutos hasta que estén bien glaseadas y car"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 150 °C.","minutes":10,"kind":"activo"},{"text":"Salpimentar {{Costillas de cerdo}} con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":2,"kind":"prep"},{"text":"Frotar las costillas con {{Ajo en polvo}} y {{Pimentón dulce}}.","minutes":2,"kind":"prep"},{"text":"Añadir {{Aceite de oliva|chorrito}} sobre las costillas y repartir bien por toda la superficie.","minutes":1,"kind":"prep"},{"text":"Envolver las costillas en papel de aluminio y colocarlas en una bandeja de horno.","minutes":2,"kind":"prep"},{"text":"Hornear a 150 °C durante 90 min, hasta que la carne esté muy tierna.","minutes":90,"kind":"pasivo"},{"text":"Mezclar en un bol {{Salsa barbacoa}}, {{Miel}} y {{Salsa de soja}} hasta obtener un glaseado homogéneo.","minutes":3,"kind":"paralelo","during":5},{"text":"Retirar las costillas del horno y desenvolver con cuidado el papel de aluminio.","minutes":2,"kind":"activo"},{"text":"Subir la temperatura del horno a 220 °C.","minutes":5,"kind":"activo"},{"text":"Pincelar las costillas con el glaseado por ambos lados de forma generosa.","minutes":2,"kind":"activo"},{"text":"Hornear destapadas a 220 °C durante 7 min, hasta que el glaseado empiece a caramelizar.","minutes":7,"kind":"pasivo"},{"text":"Retirar las costillas, pincelar de nuevo con el glaseado y volver a introducir en el horno.","minutes":2,"kind":"activo"},{"text":"Hornear 6 min más, hasta que la superficie quede oscura y pegajosa.","minutes":6,"kind":"pasivo"},{"text":"Retirar del horno y dejar reposar 5 min antes de cortar.","minutes":5,"kind":"espera"},{"text":"Cortar entre los huesos y servir con el resto del glaseado.","minutes":3,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_052', 'Albóndigas en salsa de boletus', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', NULL, NULL, 45, 'normal', 'all', 560, 34, 26, 34, 2, true, true, '{"gluten","lactosa","huevo","sulfitos"}', '[{"name":"Carne picada de ternera y cerdo","amount":350,"unit":"g"},{"name":"Pan rallado","amount":30,"unit":"g"},{"name":"Leche","amount":40,"unit":"ml"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Perejil fresco","amount":8,"unit":"g"},{"name":"Boletus","amount":200,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Vino blanco","amount":80,"unit":"ml"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Caldo de carne","amount":150,"unit":"ml"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Remojar pan rallado en leche durante 5 min hasta que quede bien empapado.","Picar ajo muy fino y picar perejil fresco fino.","Mezclar carne picada de ternera y cerdo, el pan remojado escurrido, huevo, el ajo picado y el perejil picado en un bol.","Salpimentar la mezcla con sal y pimienta negra y amasar hasta obtener una pasta homogénea.","Formar albóndigas del tamaño de una nuez grande con la mezcla.","Enharinar cada albóndiga con harina hasta cubrirlas con una capa fina.","Calentar aceite de oliva en una cazuela a fuego medio hasta que esté caliente.","Dorar las albóndigas en la cazuela por todos los lados hasta que estén doradas, retirar y reservar.","Picar cebolla fina y cortar boletus en trozos.","Sofreír la cebolla picada en la misma cazuela a fuego medio hasta que esté blanda y transparente.","Añadir los boletus troceados y saltear a fuego medio hasta que suelten el agua y se doren.","Añadir vino blanco y remover hasta que reduzca casi por completo.","Añadir caldo de carne y nata para cocinar y remover para integrar.","Incorporar las albóndigas reservadas a la cazuela y tapar.","Cocer a fuego suave tapado hasta que la salsa espese y las albóndigas estén hechas por dentro.","Rectificar de sal al gusto y servir las albóndigas bien calientes con la salsa de boletus."}', 'Albóndigas caseras en una cremosa salsa de boletus.', '[{"appliance":"thermomix","time":50,"difficulty":"normal","prepSummary":"Prepara la masa de las albóndigas en el vaso. Sofríe la cebolla y los boletus, añade los líquidos y espesa la salsa. Cocina las albóndigas al vapor en el Varoma mientras la salsa se elabora en el vaso, logrando una cocción homogénea y una salsa integrada."},{"appliance":"olla_express","time":40,"difficulty":"normal","prepSummary":"Dora las albóndigas en la olla a presión. En el mismo recipiente, sofríe la cebolla y los boletus, desglasa con vino y añade el resto de ingredientes para la salsa. Incorpora las albóndigas y cocina a presión para una cocción rápida y sabores intensos."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Remojar {{Pan rallado}} en {{Leche}} durante 5 min hasta que quede bien empapado.","minutes":5,"kind":"espera"},{"text":"Picar {{Ajo}} muy fino y picar {{Perejil fresco}} fino.","minutes":3,"kind":"prep"},{"text":"Mezclar {{Carne picada de ternera y cerdo}}, el pan remojado escurrido, {{Huevo}}, el ajo picado y el perejil picado en un bol.","minutes":2,"kind":"activo"},{"text":"Salpimentar la mezcla con {{Sal|gusto}} y {{Pimienta negra|pizca}} y amasar hasta obtener una pasta homogénea.","minutes":2,"kind":"activo"},{"text":"Formar albóndigas del tamaño de una nuez grande con la mezcla.","minutes":3,"kind":"prep"},{"text":"Enharinar cada albóndiga con {{Harina}} hasta cubrirlas con una capa fina.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una cazuela a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Dorar las albóndigas en la cazuela por todos los lados hasta que estén doradas, retirar y reservar.","minutes":5,"kind":"activo"},{"text":"Picar {{Cebolla}} fina y cortar {{Boletus}} en trozos.","minutes":3,"kind":"prep"},{"text":"Sofreír la cebolla picada en la misma cazuela a fuego medio hasta que esté blanda y transparente.","minutes":5,"kind":"activo"},{"text":"Añadir los boletus troceados y saltear a fuego medio hasta que suelten el agua y se doren.","minutes":5,"kind":"activo"},{"text":"Añadir {{Vino blanco}} y remover hasta que reduzca casi por completo.","minutes":3,"kind":"activo"},{"text":"Añadir {{Caldo de carne}} y {{Nata para cocinar}} y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Incorporar las albóndigas reservadas a la cazuela y tapar.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave tapado hasta que la salsa espese y las albóndigas estén hechas por dentro.","minutes":18,"kind":"pasivo"},{"text":"Rectificar de sal al gusto y servir las albóndigas bien calientes con la salsa de boletus.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_053', 'Pechuga de pato con puré de boniato y naranja', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'normal', 'all', 560, 32, 40, 28, 2, true, true, '{"lactosa"}', '[{"name":"Pechuga de pato","amount":400,"unit":"g"},{"name":"Boniato","amount":500,"unit":"g"},{"name":"Naranja","amount":2,"unit":"ud"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Nata para cocinar","amount":40,"unit":"ml"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Pelar boniato y cortar en dados de unos 3 cm.","Llevar a ebullición agua con sal en un cazo y cocer los dados de boniato a fuego medio hasta que estén muy tiernos.","Rallar la piel de 1 naranja y reservar la ralladura.","Marcar la piel de pechuga de pato con cortes en rombo con un cuchillo.","Salpimentar sal y pimienta negra las pechugas de pato por ambas caras.","Escurrir el boniato cocido y triturarlo en un bol con mantequilla y nata para cocinar hasta obtener un puré fino.","Añadir la ralladura de naranja reservada al puré, mezclar y salpimentar al gusto. Reservar caliente tapado.","Calentar sartén a fuego medio sin aceite de oliva y colocar las pechugas con la piel hacia abajo.","Cocinar las pechugas a fuego medio hasta que la piel esté dorada y crujiente.","Dar la vuelta a las pechugas y cocinar por el otro lado hasta que estén al punto deseado.","Retirar las pechugas de la sartén y tapar con papel de aluminio para que reposen.","Exprimir el zumo de las 2 naranjas y verterlo en la misma sartén a fuego medio.","Reducir el zumo de naranja a fuego medio, removiendo, hasta que espese ligeramente.","Cortar las pechugas reposadas en lonchas de unos 5 mm.","Disponer una base generosa de puré de boniato en cada plato y colocar las lonchas de pato encima.","Rociar con la reducción de naranja y servir de inmediato."}', 'Pechuga de pato con la piel crujiente sobre un puré de boniato y naranja.', '[{"appliance":"airfryer","time":40,"difficulty":"normal","prepSummary":"Precalienta la airfryer a 190°C. Cocina la pechuga de pato con la piel hacia arriba unos 15-20 minutos, girándola a mitad para dorar ambos lados. Asa el boniato en trozos hasta que esté tierno para el puré."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Asa el boniato entero o en trozos en el horno a 200°C hasta que esté muy tierno. Sella la pechuga de pato en una sartén y termina su cocción en el horno durante 10-15 minutos para un punto perfecto."},{"appliance":"thermomix","time":40,"difficulty":"normal","prepSummary":"Prepara el puré de boniato y naranja cociendo el boniato al vapor en el Varoma y luego triturándolo en el vaso con el resto de ingredientes. La pechuga de pato se sellaría aparte en una sartén para lograr la piel crujiente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Boniato}} y cortar en dados de unos 3 cm.","minutes":4,"kind":"prep","part":"guarnicion"},{"text":"Llevar a ebullición agua con sal en un cazo y cocer los dados de boniato a fuego medio hasta que estén muy tiernos.","minutes":17,"kind":"pasivo","part":"guarnicion"},{"text":"Rallar la piel de 1 {{Naranja}} y reservar la ralladura.","minutes":2,"kind":"paralelo","part":"guarnicion","during":1},{"text":"Marcar la piel de {{Pechuga de pato}} con cortes en rombo con un cuchillo.","minutes":2,"kind":"paralelo","part":"principal","during":1},{"text":"Salpimentar {{Sal|gusto}} y {{Pimienta negra|gusto}} las pechugas de pato por ambas caras.","minutes":1,"kind":"paralelo","part":"principal","during":1},{"text":"Escurrir el boniato cocido y triturarlo en un bol con {{Mantequilla}} y {{Nata para cocinar}} hasta obtener un puré fino.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Añadir la ralladura de naranja reservada al puré, mezclar y salpimentar al gusto. Reservar caliente tapado.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Calentar {{@Sartén}} a fuego medio sin {{Aceite de oliva}} y colocar las pechugas con la piel hacia abajo.","minutes":1,"kind":"activo","part":"principal"},{"text":"Cocinar las pechugas a fuego medio hasta que la piel esté dorada y crujiente.","minutes":8,"kind":"pasivo","part":"principal"},{"text":"Dar la vuelta a las pechugas y cocinar por el otro lado hasta que estén al punto deseado.","minutes":4,"kind":"activo","part":"principal"},{"text":"Retirar las pechugas de la sartén y tapar con papel de aluminio para que reposen.","minutes":5,"kind":"espera","part":"principal"},{"text":"Exprimir el zumo de las 2 naranjas y verterlo en la misma sartén a fuego medio.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Reducir el zumo de naranja a fuego medio, removiendo, hasta que espese ligeramente.","minutes":5,"kind":"activo","part":"salsa"},{"text":"Cortar las pechugas reposadas en lonchas de unos 5 mm.","minutes":1,"kind":"prep","part":"combinado"},{"text":"Disponer una base generosa de puré de boniato en cada plato y colocar las lonchas de pato encima.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Rociar con la reducción de naranja y servir de inmediato.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_054', 'Chuletón madurado a la parrilla', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 620, 52, 0, 44, 2, true, false, '{}', '[{"name":"Chuletón de ternera madurada","amount":900,"unit":"g"},{"name":"Sal en escamas","amount":8,"unit":"g"},{"name":"Pimienta negra","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Retirar chuletón de ternera madurada de la nevera y dejar atemperar a temperatura ambiente durante 60 min.","Secar bien la superficie del chuletón con papel de cocina por ambas caras.","Untar el chuletón por ambas caras con aceite de oliva.","Calentar plancha a fuego fuerte hasta que humee ligeramente.","Colocar el chuletón en plancha y marcar 4 min sin moverlo, hasta que se forme una costra dorada.","Dar la vuelta al chuletón y cocinar 4 min más por el otro lado hasta lograr el punto deseado.","Poner el chuletón de pie, apoyado sobre el hueso, 2 min hasta que el borde graso esté cocinado.","Retirar el chuletón de la plancha y dejar reposar sobre una tabla durante 5 min.","Trinchar el chuletón en lonchas gruesas separando la carne del hueso.","Sazonar las lonchas con sal en escamas y pimienta negra y servir de inmediato."}', 'Chuletón de ternera madurada asado a la parrilla, con la costra dorada y el hueso en T bien visible.', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 200°C. Sella el chuletón durante 8-10 minutos por cada lado, dependiendo del punto deseado. Un truco clave es dejarlo reposar unos minutos antes de cortar para que los jugos se redistribuyan."},{"appliance":"horno","time":35,"difficulty":"normal","prepSummary":"Precalienta el horno a 220°C. Asa el chuletón directamente en una bandeja durante 25-30 minutos, volteándolo a mitad, para un punto medio. Para un mejor sellado, puedes usar la función grill del horno los últimos minutos y es fundamental dejar reposar la pieza 10 minutos antes de"}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Retirar {{Chuletón de ternera madurada}} de la nevera y dejar atemperar a temperatura ambiente durante 60 min.","minutes":60,"kind":"espera"},{"text":"Secar bien la superficie del chuletón con papel de cocina por ambas caras.","minutes":1,"kind":"prep"},{"text":"Untar el chuletón por ambas caras con {{Aceite de oliva}}.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que humee ligeramente.","minutes":3,"kind":"activo"},{"text":"Colocar el chuletón en {{@Plancha}} y marcar 4 min sin moverlo, hasta que se forme una costra dorada.","minutes":4,"kind":"activo"},{"text":"Dar la vuelta al chuletón y cocinar 4 min más por el otro lado hasta lograr el punto deseado.","minutes":4,"kind":"activo"},{"text":"Poner el chuletón de pie, apoyado sobre el hueso, 2 min hasta que el borde graso esté cocinado.","minutes":2,"kind":"activo"},{"text":"Retirar el chuletón de la plancha y dejar reposar sobre una tabla durante 5 min.","minutes":5,"kind":"espera"},{"text":"Trinchar el chuletón en lonchas gruesas separando la carne del hueso.","minutes":2,"kind":"emplatado"},{"text":"Sazonar las lonchas con {{Sal en escamas}} y {{Pimienta negra}} y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true)
