insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('carnes_055', 'Carrillada ibérica al oporto', 'carnes', 'cerdo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', NULL, NULL, 150, 'normal', 'all', 520, 40, 20, 28, 4, true, true, '{"gluten","sulfitos"}', '[{"name":"Carrillada ibérica","amount":1000,"unit":"g"},{"name":"Vino de Oporto","amount":250,"unit":"ml"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Zanahoria","amount":150,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Caldo de carne","amount":250,"unit":"ml"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Laurel","amount":2,"unit":"ud"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Cortar cebolla en brunoise fina y zanahoria en rodajas finas.","Picar ajo fino.","Salpimentar carrillada ibérica por ambas caras con sal y pimienta negra.","Enharinar la carrillada ibérica con harina, sacudiendo el exceso.","Calentar aceite de oliva en una cazuela a fuego fuerte hasta que humee.","Dorar la carrillada ibérica en la cazuela por todos los lados hasta que esté bien sellada.","Retirar la carrillada ibérica y reservar en un plato.","Sofreír la cebolla, la zanahoria y el ajo picados en la misma cazuela a fuego medio hasta que estén tiernos.","Devolver la carrillada ibérica a la cazuela junto con laurel.","Añadir vino de oporto y llevar a ebullición a fuego fuerte.","Reducir el vino de Oporto a fuego medio hasta que el alcohol evapore.","Añadir caldo de carne, tapar la cazuela y cocer a fuego suave hasta que la carne esté muy tierna.","Retirar la carrillada ibérica de la cazuela y reservar tapada.","Retirar el laurel de la salsa y triturar el resto con una batidora hasta obtener una salsa fina.","Colar la salsa triturada por un colador fino de vuelta a la cazuela.","Devolver la carrillada ibérica a la cazuela con la salsa colada.","Cocer a fuego medio destapado hasta que la salsa alcance la densidad deseada.","Servir la carrillada ibérica bien caliente con su salsa de Oporto por encima."}', 'Carrillada ibérica guisada lentamente al vino de Oporto hasta quedar melosa.', '[{"appliance":"horno","time":180,"difficulty":"normal","prepSummary":"Sella la carrillada y sofríe las verduras en una olla apta para horno. Incorpora el resto de ingredientes, tapa y brasea a 160°C durante 2.5-3 horas hasta que la carne esté muy tierna. La clave es la cocción lenta y constante para una textura melosa y una salsa profunda."},{"appliance":"thermomix","time":200,"difficulty":"normal","prepSummary":"Sofríe las verduras y sella la carrillada (si es posible en la máquina o fuera). Añade el resto de ingredientes y cocina a 90-100°C, velocidad cuchara y giro inverso durante 3-3.5 horas. El control de temperatura y el movimiento suave garantizan una carne tierna y una salsa emuls"},{"appliance":"olla_express","time":85,"difficulty":"normal","prepSummary":"Sella la carrillada y sofríe las verduras en la olla express. Incorpora el resto de ingredientes, cierra la olla y cocina a presión durante 45-60 minutos. La cocción a alta presión reduce drásticamente el tiempo, logrando una carne extremadamente tierna y una salsa concentrada."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Cebolla}} en brunoise fina y {{Zanahoria}} en rodajas finas.","minutes":5,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":2,"kind":"prep"},{"text":"Salpimentar {{Carrillada ibérica}} por ambas caras con {{Sal|gusto}} y {{Pimienta negra|gusto}}.","minutes":2,"kind":"prep"},{"text":"Enharinar la carrillada ibérica con {{Harina}}, sacudiendo el exceso.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela a fuego fuerte hasta que humee.","minutes":2,"kind":"activo"},{"text":"Dorar la carrillada ibérica en la cazuela por todos los lados hasta que esté bien sellada.","minutes":6,"kind":"activo"},{"text":"Retirar la carrillada ibérica y reservar en un plato.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla, la zanahoria y el ajo picados en la misma cazuela a fuego medio hasta que estén tiernos.","minutes":10,"kind":"activo"},{"text":"Devolver la carrillada ibérica a la cazuela junto con {{Laurel}}.","minutes":1,"kind":"activo"},{"text":"Añadir {{Vino de Oporto}} y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Reducir el vino de Oporto a fuego medio hasta que el alcohol evapore.","minutes":5,"kind":"activo"},{"text":"Añadir {{Caldo de carne}}, tapar la cazuela y cocer a fuego suave hasta que la carne esté muy tierna.","minutes":120,"kind":"pasivo"},{"text":"Retirar la carrillada ibérica de la cazuela y reservar tapada.","minutes":2,"kind":"activo"},{"text":"Retirar el laurel de la salsa y triturar el resto con una batidora hasta obtener una salsa fina.","minutes":3,"kind":"activo"},{"text":"Colar la salsa triturada por un colador fino de vuelta a la cazuela.","minutes":3,"kind":"activo"},{"text":"Devolver la carrillada ibérica a la cazuela con la salsa colada.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego medio destapado hasta que la salsa alcance la densidad deseada.","minutes":8,"kind":"activo"},{"text":"Servir la carrillada ibérica bien caliente con su salsa de Oporto por encima.","minutes":2,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_056', 'Tataki de solomillo con sésamo', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'normal', 'all', 340, 30, 6, 20, 2, false, false, '{"soja","sesamo"}', '[{"name":"Solomillo de ternera","amount":300,"unit":"g"},{"name":"Sésamo blanco y negro","amount":25,"unit":"g"},{"name":"Salsa de soja","amount":40,"unit":"ml"},{"name":"Mirin","amount":20,"unit":"ml"},{"name":"Vinagre de arroz","amount":15,"unit":"ml"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Cebollino","amount":5,"unit":"g"}]'::jsonb, '{"Rallar jengibre fresco y reservar.","Picar cebollino fino y reservar.","Mezclar salsa de soja, mirin, vinagre de arroz, el jengibre rallado y aceite de sésamo en un bol hasta integrar.","Salpimentar solomillo de ternera y untar su superficie con aceite de oliva.","Extender sésamo blanco y negro en un plato llano y rebozar el solomillo por todos los lados, presionando para que se adhiera bien.","Calentar plancha a fuego fuerte hasta que humee.","Sellar el solomillo por todos los lados, 30 segundos por cara, hasta que el sésamo esté tostado y el centro quede crudo.","Retirar el solomillo de la plancha y envolver en film transparente, apretando para compactar la pieza.","Introducir el solomillo envuelto en el congelador hasta que esté firme y se pueda laminar con facilidad.","Retirar el solomillo del congelador, desenvolver y laminar en lonchas muy finas con un cuchillo bien afilado.","Disponer las láminas de solomillo en el plato, rociar con parte de la salsa y espolvorear con el cebollino picado.","Servir el resto de la salsa en un bol aparte para mojar."}', 'Tataki de solomillo de ternera sellado por fuera, crudo en el centro y rebozado en sésamo tostado.', '[{"appliance":"airfryer","time":25,"difficulty":"normal","prepSummary":"Marinar el solomillo, cubrir con sésamo y cocinar en la airfryer precalentada a 200°C durante 6-8 minutos, volteando a mitad, para un exterior sellado y un interior poco hecho."},{"appliance":"horno","time":35,"difficulty":"normal","prepSummary":"Tras marinar y cubrir con sésamo, sella el solomillo en un horno muy caliente (220-250°C, preferiblemente con función grill o convección) durante 8-10 minutos, volteando a mitad, para un sellado rápido y un interior jugoso."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Rallar {{Jengibre fresco}} y reservar.","minutes":1,"kind":"prep"},{"text":"Picar {{Cebollino}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Mezclar {{Salsa de soja}}, {{Mirin}}, {{Vinagre de arroz}}, el jengibre rallado y {{Aceite de sésamo}} en un bol hasta integrar.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Salpimentar {{Solomillo de ternera}} y untar su superficie con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"prep","part":"principal"},{"text":"Extender {{Sésamo blanco y negro}} en un plato llano y rebozar el solomillo por todos los lados, presionando para que se adhiera bien.","minutes":2,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que humee.","minutes":2,"kind":"activo","part":"principal"},{"text":"Sellar el solomillo por todos los lados, 30 segundos por cara, hasta que el sésamo esté tostado y el centro quede crudo.","minutes":3,"kind":"activo","part":"principal"},{"text":"Retirar el solomillo de la plancha y envolver en film transparente, apretando para compactar la pieza.","minutes":1,"kind":"activo","part":"principal"},{"text":"Introducir el solomillo envuelto en el congelador hasta que esté firme y se pueda laminar con facilidad.","minutes":15,"kind":"espera","part":"principal"},{"text":"Retirar el solomillo del congelador, desenvolver y laminar en lonchas muy finas con un cuchillo bien afilado.","minutes":2,"kind":"prep","part":"principal"},{"text":"Disponer las láminas de solomillo en el plato, rociar con parte de la salsa y espolvorear con el cebollino picado.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Servir el resto de la salsa en un bol aparte para mojar.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_057', 'Filete de ternera a la plancha con gremolata', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 340, 38, 2, 18, 2, true, true, '{}', '[{"name":"Filete de ternera","amount":350,"unit":"g"},{"name":"Perejil fresco","amount":20,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Picar perejil fresco muy fino.","Picar ajo muy fino.","Rallar la piel de limón sobre un bol pequeño.","Mezclar el perejil picado y el ajo picado con la ralladura de limón hasta obtener la gremolata.","Salpimentar filete de ternera por ambos lados con sal y pimienta negra.","Calentar plancha con aceite de oliva a fuego fuerte hasta que humee ligeramente.","Colocar los filetes en plancha y cocinar 2 min sin moverlos, hasta que se despeguen solos.","Dar la vuelta a los filetes y cocinar 2 min más, hasta alcanzar el punto deseado.","Retirar los filetes de la plancha y dejar reposar 2 min en un plato para que los jugos se redistribuyan.","Exprimir un poco de zumo del limón ya rallado sobre los filetes.","Repartir la gremolata sobre los filetes y servir de inmediato."}', 'Filete de ternera a la plancha coronado con una gremolata fresca de perejil, ajo y limón.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Sazona el filete, úntalo ligeramente con aceite y cocínalo durante 8-12 minutos, volteándolo a mitad, para un punto medio-jugoso. La gremolata se prepara aparte picando perejil, ajo y ralladura de limón."},{"appliance":"horno","time":22,"difficulty":"normal","prepSummary":"Precalienta el horno a 200-220°C. Sella el filete en una sartén muy caliente con un poco de aceite durante 2 minutos por cada lado para crear una costra, luego termina de cocinarlo en el horno durante 8-12 minutos hasta el punto deseado. La gremolata se elabora por separado."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Perejil fresco}} muy fino.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep"},{"text":"Rallar la piel de {{Limón}} sobre un bol pequeño.","minutes":1,"kind":"prep"},{"text":"Mezclar el perejil picado y el ajo picado con la ralladura de limón hasta obtener la gremolata.","minutes":1,"kind":"prep"},{"text":"Salpimentar {{Filete de ternera}} por ambos lados con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} con {{Aceite de oliva|chorrito}} a fuego fuerte hasta que humee ligeramente.","minutes":2,"kind":"activo"},{"text":"Colocar los filetes en {{@Plancha}} y cocinar 2 min sin moverlos, hasta que se despeguen solos.","minutes":2,"kind":"activo"},{"text":"Dar la vuelta a los filetes y cocinar 2 min más, hasta alcanzar el punto deseado.","minutes":2,"kind":"activo"},{"text":"Retirar los filetes de la plancha y dejar reposar 2 min en un plato para que los jugos se redistribuyan.","minutes":2,"kind":"espera"},{"text":"Exprimir un poco de zumo del limón ya rallado sobre los filetes.","minutes":1,"kind":"emplatado"},{"text":"Repartir la gremolata sobre los filetes y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_058', 'Pechuga de pollo a la plancha con salsa rápida de yogur y limón', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 320, 40, 6, 14, 2, true, true, '{"lactosa"}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Yogur griego","amount":150,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Eneldo fresco","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Rallar ajo sobre un bol pequeño.","Rallar la piel de limón y exprimir la mitad de su zumo sobre el mismo bol.","Picar eneldo fresco fino.","Añadir yogur griego, el eneldo picado, sal y pimienta negra al bol con el ajo, la ralladura y el zumo.","Mezclar bien hasta obtener una salsa homogénea y reservar en frío.","Aplanar pechuga de pollo ligeramente con la mano o la palma hasta que tengan un grosor uniforme.","Salpimentar las pechugas por ambas caras.","Calentar plancha con aceite de oliva a fuego fuerte hasta que empiece a humear.","Colocar las pechugas en la plancha y cocinar 5 min por el primer lado, hasta que se doren.","Dar la vuelta a las pechugas y cocinar 5 min por el otro lado, hasta que estén bien hechas por dentro.","Retirar las pechugas de la plancha y dejar reposar 2 min sobre la tabla.","Cortar las pechugas en lonchas y servir con la salsa de yogur por encima."}', 'Pechuga de pollo a la plancha con una salsa rápida y fresca de yogur y limón.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Para el pollo, sazona y cocina en la airfryer a 190°C durante 15-18 minutos, volteando a mitad para un dorado uniforme. La salsa se prepara mezclando el yogur, zumo de limón, ajo picado y eneldo."},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Sazona la pechuga y ásala en el horno precalentado a 200°C durante 20-25 minutos hasta que esté dorada y cocida. La salsa se elabora mezclando el resto de ingredientes mientras el pollo se cocina."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Rallar {{Ajo}} sobre un bol pequeño.","minutes":1,"kind":"prep"},{"text":"Rallar la piel de {{Limón}} y exprimir la mitad de su zumo sobre el mismo bol.","minutes":1,"kind":"prep"},{"text":"Picar {{Eneldo fresco}} fino.","minutes":1,"kind":"prep"},{"text":"Añadir {{Yogur griego}}, el eneldo picado, {{Sal|gusto}} y {{Pimienta negra|pizca}} al bol con el ajo, la ralladura y el zumo.","minutes":1,"kind":"prep"},{"text":"Mezclar bien hasta obtener una salsa homogénea y reservar en frío.","minutes":1,"kind":"prep"},{"text":"Aplanar {{Pechuga de pollo}} ligeramente con la mano o la palma hasta que tengan un grosor uniforme.","minutes":1,"kind":"prep"},{"text":"Salpimentar las pechugas por ambas caras.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} con {{Aceite de oliva|chorrito}} a fuego fuerte hasta que empiece a humear.","minutes":2,"kind":"activo"},{"text":"Colocar las pechugas en la plancha y cocinar 5 min por el primer lado, hasta que se doren.","minutes":5,"kind":"activo"},{"text":"Dar la vuelta a las pechugas y cocinar 5 min por el otro lado, hasta que estén bien hechas por dentro.","minutes":5,"kind":"activo"},{"text":"Retirar las pechugas de la plancha y dejar reposar 2 min sobre la tabla.","minutes":2,"kind":"espera"},{"text":"Cortar las pechugas en lonchas y servir con la salsa de yogur por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_059', 'Lomo de cerdo a la plancha con ensalada de tomate y cebolla', 'carnes', 'cerdo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'verano', 380, 34, 10, 22, 2, true, true, '{"sulfitos"}', '[{"name":"Lomo de cerdo en filetes","amount":350,"unit":"g"},{"name":"Tomate","amount":300,"unit":"g"},{"name":"Cebolla dulce","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"},{"name":"Orégano seco","amount":2,"unit":"g"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Cortar tomate en gajos medianos.","Laminar cebolla dulce en juliana fina.","Mezclar el tomate y la cebolla en un bol con aceite de oliva, vinagre de vino, orégano seco y sal.","Reservar la ensalada y dejar reposar mientras se cocina la carne.","Salpimentar lomo de cerdo en filetes por ambas caras con sal y pimienta negra.","Calentar plancha con aceite de oliva a fuego fuerte hasta que humee ligeramente.","Colocar los filetes en la plancha y cocinar 2 min por cada lado hasta que estén dorados.","Retirar los filetes de la plancha y dejar reposar 2 min para que los jugos se redistribuyan.","Servir el lomo junto con la ensalada de tomate y cebolla."}', 'Lomo de cerdo a la plancha en finas lonchas doradas, junto a una ensalada fresca de tomate y cebolla.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 200°C. Cocina los filetes de lomo sazonados durante 12-15 minutos, dándoles la vuelta a mitad de cocción, para un resultado dorado y jugoso, similar a la plancha."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Tomate}} en gajos medianos.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Laminar {{Cebolla dulce}} en juliana fina.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Mezclar el tomate y la cebolla en un bol con {{Aceite de oliva|chorrito}}, {{Vinagre de vino}}, {{Orégano seco|pizca}} y {{Sal|gusto}}.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Reservar la ensalada y dejar reposar mientras se cocina la carne.","minutes":8,"kind":"espera","part":"guarnicion"},{"text":"Salpimentar {{Lomo de cerdo en filetes}} por ambas caras con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} con {{Aceite de oliva|chorrito}} a fuego fuerte hasta que humee ligeramente.","minutes":1,"kind":"activo","part":"principal"},{"text":"Colocar los filetes en la plancha y cocinar 2 min por cada lado hasta que estén dorados.","minutes":4,"kind":"activo","part":"principal"},{"text":"Retirar los filetes de la plancha y dejar reposar 2 min para que los jugos se redistribuyan.","minutes":2,"kind":"espera","part":"principal"},{"text":"Servir el lomo junto con la ensalada de tomate y cebolla.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_060', 'Filetes de pavo a la plancha con salsa rápida de mostaza y miel', 'carnes', 'pavo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 300, 38, 12, 10, 2, true, true, '{"mostaza"}', '[{"name":"Filetes de pavo","amount":350,"unit":"g"},{"name":"Mostaza de Dijon","amount":20,"unit":"g"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Mezclar mostaza de dijon y miel en un bol pequeño hasta obtener una salsa homogénea.","Salpimentar filetes de pavo por ambas caras con sal y pimienta negra.","Calentar plancha con aceite de oliva a fuego medio-fuerte hasta que humee ligeramente.","Colocar los filetes de pavo en la plancha y cocinar 3-4 min por cada lado hasta que estén dorados.","Bajar el fuego a suave y añadir la salsa de mostaza y miel sobre los filetes.","Remover suavemente para que la salsa cubra los filetes, hasta que esté caliente.","Servir los filetes de pavo con la salsa de mostaza y miel por encima."}', 'Filetes de pavo a la plancha con un chorrito agridulce de mostaza y miel.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Rocía los filetes con aceite de oliva, salpimenta y cocina durante 12-15 minutos, dándoles la vuelta a mitad para un dorado uniforme. La salsa se mezcla rápidamente aparte."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C (con función grill si es posible). Coloca los filetes de pavo salpimentados y ligeramente aceitados en una bandeja y hornea durante 15-20 minutos, volteándolos una vez, hasta que estén dorados y cocidos. La salsa se prepara aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Mezclar {{Mostaza de Dijon}} y {{Miel}} en un bol pequeño hasta obtener una salsa homogénea.","minutes":1,"kind":"prep"},{"text":"Salpimentar {{Filetes de pavo}} por ambas caras con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} con {{Aceite de oliva|chorrito}} a fuego medio-fuerte hasta que humee ligeramente.","minutes":2,"kind":"activo"},{"text":"Colocar los filetes de pavo en la plancha y cocinar 3-4 min por cada lado hasta que estén dorados.","minutes":7,"kind":"activo"},{"text":"Bajar el fuego a suave y añadir la salsa de mostaza y miel sobre los filetes.","minutes":1,"kind":"activo"},{"text":"Remover suavemente para que la salsa cubra los filetes, hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Servir los filetes de pavo con la salsa de mostaza y miel por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_061', 'Solomillo de cerdo a la plancha con chimichurri exprés', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 400, 36, 3, 26, 2, true, true, '{"sulfitos"}', '[{"name":"Solomillo de cerdo","amount":400,"unit":"g"},{"name":"Perejil fresco","amount":15,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Vinagre de vino tinto","amount":15,"unit":"ml"},{"name":"Orégano seco","amount":2,"unit":"g"},{"name":"Guindilla en copos","amount":1,"unit":"g"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Cortar solomillo de cerdo en medallones de 3 cm de grosor.","Picar finamente perejil fresco y ajo.","Mezclar el perejil y el ajo picados con orégano seco, guindilla en copos, vinagre de vino tinto y aceite de oliva.","Salpimentar los medallones con sal y pimienta negra por ambas caras.","Calentar plancha a fuego fuerte hasta que esté muy caliente.","Colocar los medallones en plancha y cocinar 3 min por el primer lado, hasta que se doren.","Dar la vuelta a los medallones y cocinar 3 min más por el otro lado, hasta que estén dorados y jugosos.","Retirar los medallones de la plancha y dejar reposar 2 min fuera del fuego.","Servir los medallones con el chimichurri exprés por encima."}', 'Medallones de solomillo de cerdo a la plancha con un chimichurri exprés recién picado.', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cocina el solomillo sazonado por 15-20 minutos, volteándolo a mitad, para un exterior dorado y jugoso. Prepara el chimichurri mientras tanto."},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Asa el solomillo sazonado por 20-25 minutos hasta el punto deseado. Para una costra perfecta, séllalo previamente en una sartén antes de hornear."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Solomillo de cerdo}} en medallones de 3 cm de grosor.","minutes":3,"kind":"prep","part":"principal"},{"text":"Picar finamente {{Perejil fresco}} y {{Ajo}}.","minutes":3,"kind":"prep","part":"salsa"},{"text":"Mezclar el perejil y el ajo picados con {{Orégano seco|pizca}}, {{Guindilla en copos|pizca}}, {{Vinagre de vino tinto}} y {{Aceite de oliva|chorrito}}.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Salpimentar los medallones con {{Sal|gusto}} y {{Pimienta negra|pizca}} por ambas caras.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté muy caliente.","minutes":2,"kind":"activo","part":"principal"},{"text":"Colocar los medallones en {{@Plancha}} y cocinar 3 min por el primer lado, hasta que se doren.","minutes":3,"kind":"activo","part":"principal"},{"text":"Dar la vuelta a los medallones y cocinar 3 min más por el otro lado, hasta que estén dorados y jugosos.","minutes":3,"kind":"activo","part":"principal"},{"text":"Retirar los medallones de la plancha y dejar reposar 2 min fuera del fuego.","minutes":2,"kind":"espera","part":"principal"},{"text":"Servir los medallones con el chimichurri exprés por encima.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_062', 'Entrecot con patatas fritas y salsa de queso azul', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 720, 46, 34, 44, 2, false, false, '{"lactosa"}', '[{"name":"Entrecot de ternera","amount":500,"unit":"g"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Aceite de girasol","amount":400,"unit":"ml"},{"name":"Queso azul","amount":80,"unit":"g"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":10,"unit":"g"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":3,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en bastones uniformes.","Secar los bastones de patata con un paño limpio para eliminar el exceso de humedad.","Calentar aceite de girasol en una sartén honda a 160 °C.","Freír los bastones de patata a 160 °C durante 6 min hasta que estén tiernos pero sin dorar.","Escurrir las patatas y reservar. Subir el aceite a 190 °C.","Freír de nuevo las patatas a 190 °C durante 3 min hasta que estén doradas y crujientes.","Escurrir las patatas sobre papel absorbente y salar con sal.","Calentar nata para cocinar en un cazo a fuego suave.","Añadir queso azul troceado y mantequilla al cazo.","Remover a fuego suave hasta que el queso y la mantequilla se fundan y la salsa sea homogénea.","Retirar la salsa del fuego y reservar caliente.","Salpimentar entrecot de ternera por ambos lados con sal al gusto y pimienta negra.","Calentar plancha a fuego fuerte hasta que humee.","Cocinar el entrecot 3 min por cada lado para un punto medio, ajustando según el punto deseado.","Retirar el entrecot de la plancha y dejar reposar 3 min para que los jugos se asienten.","Cortar el entrecot en lonchas.","Servir el entrecot en lonchas junto a las patatas fritas y la salsa de queso azul aparte o por encima."}', 'Entrecot con patatas fritas caseras y una cremosa salsa de queso azul.', '[{"appliance":"airfryer","time":40,"difficulty":"facil","prepSummary":"Cocina las patatas en la airfryer a 190°C por 20-25 min hasta que estén doradas y crujientes. Después, el entrecot a 200°C por 12-15 min, volteándolo a mitad para un sellado perfecto, mientras la salsa se prepara en un cazo aparte."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Precalienta el horno a 200°C y hornea las patatas con un poco de aceite durante 30-35 min, volteándolas a mitad. Mientras, sella el entrecot en una sartén y termínalo en el horno a 180°C por 10-15 min, preparando la salsa en un cazo aparte."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en bastones uniformes.","minutes":5,"kind":"prep","part":"guarnicion"},{"text":"Secar los bastones de patata con un paño limpio para eliminar el exceso de humedad.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de girasol}} en una sartén honda a 160 °C.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Freír los bastones de patata a 160 °C durante 6 min hasta que estén tiernos pero sin dorar.","minutes":6,"kind":"pasivo","part":"guarnicion"},{"text":"Escurrir las patatas y reservar. Subir el aceite a 190 °C.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Freír de nuevo las patatas a 190 °C durante 3 min hasta que estén doradas y crujientes.","minutes":3,"kind":"pasivo","part":"guarnicion"},{"text":"Escurrir las patatas sobre papel absorbente y salar con {{Sal|gusto}}.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Nata para cocinar}} en un cazo a fuego suave.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Añadir {{Queso azul}} troceado y {{Mantequilla}} al cazo.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Remover a fuego suave hasta que el queso y la mantequilla se fundan y la salsa sea homogénea.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Retirar la salsa del fuego y reservar caliente.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Salpimentar {{Entrecot de ternera}} por ambos lados con sal al gusto y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que humee.","minutes":2,"kind":"activo","part":"principal"},{"text":"Cocinar el entrecot 3 min por cada lado para un punto medio, ajustando según el punto deseado.","minutes":6,"kind":"activo","part":"principal"},{"text":"Retirar el entrecot de la plancha y dejar reposar 3 min para que los jugos se asienten.","minutes":3,"kind":"espera","part":"principal"},{"text":"Cortar el entrecot en lonchas.","minutes":1,"kind":"prep","part":"principal"},{"text":"Servir el entrecot en lonchas junto a las patatas fritas y la salsa de queso azul aparte o por encima.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_063', 'Steak frites con mantequilla de perejil', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 680, 40, 36, 40, 2, true, false, '{"lactosa"}', '[{"name":"Entrecot de ternera","amount":400,"unit":"g"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Aceite de girasol","amount":400,"unit":"ml"},{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Perejil fresco","amount":15,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":3,"unit":"g"}]'::jsonb, '{"Sacar mantequilla de la nevera y dejar atemperar hasta que esté blanda.","Picar perejil fresco muy fino.","Rallar ajo.","Mezclar la mantequilla blanda con el perejil picado y el ajo rallado hasta obtener una pasta homogénea.","Formar un cilindro con la pasta de mantequilla envuelto en film transparente.","Refrigerar el cilindro de mantequilla hasta que esté firme.","Pelar patata y cortarlas en bastones uniformes.","Secar bien los bastones de patata con un paño limpio.","Calentar aceite de girasol en una olla a 160 °C a fuego medio.","Freír los bastones de patata a 160 °C hasta que estén tiernos pero sin color, unos 6 min.","Escurrir los bastones de patata sobre papel absorbente y reservar.","Subir el aceite a 190 °C a fuego fuerte.","Salpimentar entrecot de ternera por ambas caras con sal y pimienta negra.","Calentar plancha a fuego fuerte hasta que humee.","Freír de nuevo los bastones de patata a 190 °C durante 2-3 min hasta que estén dorados y crujientes.","Cocinar los entrecots en la plancha 2-3 min por cada lado, según el punto deseado.","Escurrir las patatas fritas sobre papel absorbente y salar al gusto.","Retirar los entrecots de la plancha y reposar 2 min antes de emplatar.","Cortar unas rodajas del cilindro de mantequilla de perejil.","Colocar las rodajas de mantequilla de perejil sobre los entrecots calientes y dejar que se derritan.","Servir los entrecots junto a las patatas fritas."}', 'El clásico filete francés con patatas fritas y una mantequilla de perejil que se derrite encima.', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Prepara las patatas en la airfryer a 190°C durante 20-25 minutos, agitándolas. Luego, cocina el entrecot sazonado a 200°C por 10-15 minutos, volteándolo a mitad, para un resultado jugoso y con menos grasa."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Hornea las patatas cortadas en bastones con un poco de aceite a 200°C durante 35-40 minutos, dándoles la vuelta. El entrecot se puede sellar en sartén y terminar en el horno a 200°C por 10-15 minutos para un punto perfecto."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Sacar {{Mantequilla}} de la nevera y dejar atemperar hasta que esté blanda.","minutes":15,"kind":"espera","part":"salsa"},{"text":"Picar {{Perejil fresco}} muy fino.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Rallar {{Ajo}}.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Mezclar la mantequilla blanda con el perejil picado y el ajo rallado hasta obtener una pasta homogénea.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Formar un cilindro con la pasta de mantequilla envuelto en film transparente.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Refrigerar el cilindro de mantequilla hasta que esté firme.","minutes":20,"kind":"espera","part":"salsa"},{"text":"Pelar {{Patata}} y cortarlas en bastones uniformes.","minutes":5,"kind":"prep","part":"guarnicion"},{"text":"Secar bien los bastones de patata con un paño limpio.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de girasol}} en una olla a 160 °C a fuego medio.","minutes":4,"kind":"activo","part":"guarnicion"},{"text":"Freír los bastones de patata a 160 °C hasta que estén tiernos pero sin color, unos 6 min.","minutes":6,"kind":"pasivo","part":"guarnicion"},{"text":"Escurrir los bastones de patata sobre papel absorbente y reservar.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Subir el aceite a 190 °C a fuego fuerte.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Salpimentar {{Entrecot de ternera}} por ambas caras con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que humee.","minutes":2,"kind":"activo","part":"principal"},{"text":"Freír de nuevo los bastones de patata a 190 °C durante 2-3 min hasta que estén dorados y crujientes.","minutes":3,"kind":"pasivo","part":"guarnicion"},{"text":"Cocinar los entrecots en la plancha 2-3 min por cada lado, según el punto deseado.","minutes":5,"kind":"activo","part":"principal"},{"text":"Escurrir las patatas fritas sobre papel absorbente y salar al gusto.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Retirar los entrecots de la plancha y reposar 2 min antes de emplatar.","minutes":2,"kind":"espera","part":"principal"},{"text":"Cortar unas rodajas del cilindro de mantequilla de perejil.","minutes":1,"kind":"prep","part":"combinado"},{"text":"Colocar las rodajas de mantequilla de perejil sobre los entrecots calientes y dejar que se derritan.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Servir los entrecots junto a las patatas fritas.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_064', 'Hamburguesa gourmet con cheddar curado y bacon', 'carnes', 'ternera', 'pan', ARRAY['segundo','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 760, 42, 42, 46, 2, true, false, '{"gluten","lactosa","mostaza"}', '[{"name":"Carne picada de ternera","amount":350,"unit":"g"},{"name":"Pan de hamburguesa brioche","amount":2,"unit":"ud"},{"name":"Queso cheddar curado en lonchas","amount":60,"unit":"g"},{"name":"Bacon","amount":80,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Lechuga","amount":40,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Ketchup","amount":20,"unit":"g"},{"name":"Mostaza","amount":15,"unit":"g"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar cebolla en aros finos.","Cortar tomate en rodajas y separar hojas de lechuga. Reservar.","Dividir carne picada de ternera en 2 porciones iguales y formar 2 hamburguesas.","Presionar el centro de cada hamburguesa con el pulgar para que no se abombe al cocinarse.","Salpimentar las hamburguesas por ambas caras con sal y pimienta negra.","Calentar sartén con aceite de oliva a fuego medio.","Sofreír la cebolla en aros a fuego medio hasta que esté dorada y caramelizada.","Retirar la cebolla caramelizada y reservar. Subir el fuego a fuerte.","Dorar bacon en tiras en la misma sartén a fuego fuerte hasta que esté crujiente.","Retirar el bacon crujiente y reservar. Limpiar la sartén con papel de cocina.","Calentar plancha a fuego fuerte hasta que humee.","Cocinar las hamburguesas 3 min por el primer lado sin moverlas.","Dar la vuelta a las hamburguesas y colocar queso cheddar curado en lonchas encima de cada una.","Cocinar 2 min más hasta que el queso se funda y la carne esté al punto.","Retirar las hamburguesas y tostar pan de hamburguesa brioche por el interior en la misma plancha hasta que estén dorados.","Untar la base de cada pan con ketchup y mostaza.","Colocar la lechuga y las rodajas de tomate sobre la base untada.","Colocar la hamburguesa con el queso fundido, el bacon crujiente y la cebolla caramelizada. Cerrar con la tapa del pan."}', 'Hamburguesa gourmet de ternera con cheddar curado, bacon crujiente y cebolla caramelizada.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Cocina el bacon a 180°C durante 8-10 min hasta que esté crujiente. Luego, las hamburguesas a 190°C por 12-15 min, añadiendo el queso los últimos 2 min para que se funda, y tuesta el pan brevemente."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Cocina el bacon en una rejilla y las hamburguesas en una bandeja durante 15-20 min, añadiendo el queso sobre las hamburguesas los últimos 5 min para que se gratine y funda, y tuesta el pan."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Cebolla}} en aros finos.","minutes":2,"kind":"prep"},{"text":"Cortar {{Tomate}} en rodajas y separar hojas de {{Lechuga}}. Reservar.","minutes":2,"kind":"prep"},{"text":"Dividir {{Carne picada de ternera}} en 2 porciones iguales y formar 2 hamburguesas.","minutes":2,"kind":"prep"},{"text":"Presionar el centro de cada hamburguesa con el pulgar para que no se abombe al cocinarse.","minutes":1,"kind":"prep"},{"text":"Salpimentar las hamburguesas por ambas caras con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Sartén}} con {{Aceite de oliva|chorrito}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla en aros a fuego medio hasta que esté dorada y caramelizada.","minutes":9,"kind":"pasivo"},{"text":"Retirar la cebolla caramelizada y reservar. Subir el fuego a fuerte.","minutes":1,"kind":"activo"},{"text":"Dorar {{Bacon}} en tiras en la misma sartén a fuego fuerte hasta que esté crujiente.","minutes":4,"kind":"activo"},{"text":"Retirar el bacon crujiente y reservar. Limpiar la sartén con papel de cocina.","minutes":1,"kind":"activo"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que humee.","minutes":2,"kind":"activo"},{"text":"Cocinar las hamburguesas 3 min por el primer lado sin moverlas.","minutes":3,"kind":"pasivo"},{"text":"Dar la vuelta a las hamburguesas y colocar {{Queso cheddar curado en lonchas}} encima de cada una.","minutes":1,"kind":"activo"},{"text":"Cocinar 2 min más hasta que el queso se funda y la carne esté al punto.","minutes":2,"kind":"pasivo"},{"text":"Retirar las hamburguesas y tostar {{Pan de hamburguesa brioche}} por el interior en la misma plancha hasta que estén dorados.","minutes":1,"kind":"activo"},{"text":"Untar la base de cada pan con {{Ketchup}} y {{Mostaza}}.","minutes":1,"kind":"emplatado"},{"text":"Colocar la lechuga y las rodajas de tomate sobre la base untada.","minutes":1,"kind":"emplatado"},{"text":"Colocar la hamburguesa con el queso fundido, el bacon crujiente y la cebolla caramelizada. Cerrar con la tapa del pan.","minutes":1,"kind":"emplatado"}]'::jsonb, true)
