insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('carnes_065', 'Pollo frito crujiente con miel picante', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 40, 'normal', 'all', 570, 36, 38, 30, 2, false, false, '{"gluten","huevo","lactosa","soja"}', '[{"name":"Contramuslos de pollo deshuesados","amount":400,"unit":"g"},{"name":"Harina de trigo","amount":60,"unit":"g"},{"name":"Maicena","amount":30,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Leche","amount":50,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Ajo en polvo","amount":3,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Aceite de girasol","amount":300,"unit":"ml"},{"name":"Miel","amount":40,"unit":"g"},{"name":"Salsa de soja","amount":15,"unit":"ml"},{"name":"Copos de guindilla","amount":3,"unit":"g"},{"name":"Zumo de lima","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar contramuslos de pollo deshuesados en trozos de unos 4 cm.","Mezclar harina de trigo, maicena, pimentón dulce, ajo en polvo y sal en un bol hasta integrar.","Batir huevo con leche en otro bol hasta obtener una mezcla homogénea.","Pasar cada trozo de pollo por la mezcla de harina, luego por el huevo batido y de nuevo por la harina.","Presionar bien el rebozado sobre cada trozo para que se adhiera y reservar.","Calentar aceite de girasol en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","Freír el pollo rebozado por tandas a 180 °C durante 5 min, hasta que esté dorado y crujiente.","Escurrir el pollo frito sobre papel absorbente y reservar.","Calentar miel, salsa de soja, copos de guindilla y zumo de lima en un cazo a fuego suave.","Remover la salsa sin parar durante 2 min hasta que espese ligeramente y retirar del fuego.","Verter la salsa caliente sobre el pollo frito y remover para que quede bien cubierto.","Servir de inmediato para conservar el crujiente del rebozado."}', 'Trozos de pollo rebozados y fritos hasta quedar crujientes, bañados en una salsa de miel picante brillante.', '[{"appliance":"airfryer","time":35,"difficulty":"normal","prepSummary":"Prepara el pollo empanado y rocíalo ligeramente con aceite. Cocina en la airfryer a 190-200°C durante 20-25 minutos, volteando a mitad, hasta que esté dorado y crujiente. La salsa de miel picante se prepara aparte."},{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Empana el pollo y colócalo en una rejilla sobre una bandeja de horno. Hornea a 200-220°C durante 30-35 minutos, volteando una vez, hasta que esté bien dorado y crujiente. Prepara la salsa mientras el pollo se hornea."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Contramuslos de pollo deshuesados}} en trozos de unos 4 cm.","minutes":3,"kind":"prep"},{"text":"Mezclar {{Harina de trigo}}, {{Maicena}}, {{Pimentón dulce}}, {{Ajo en polvo}} y {{Sal}} en un bol hasta integrar.","minutes":2,"kind":"prep"},{"text":"Batir {{Huevo}} con {{Leche}} en otro bol hasta obtener una mezcla homogénea.","minutes":1,"kind":"prep"},{"text":"Pasar cada trozo de pollo por la mezcla de harina, luego por el huevo batido y de nuevo por la harina.","minutes":4,"kind":"prep"},{"text":"Presionar bien el rebozado sobre cada trozo para que se adhiera y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de girasol}} en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","minutes":3,"kind":"activo"},{"text":"Freír el pollo rebozado por tandas a 180 °C durante 5 min, hasta que esté dorado y crujiente.","minutes":10,"kind":"activo"},{"text":"Escurrir el pollo frito sobre papel absorbente y reservar.","minutes":1,"kind":"activo"},{"text":"Calentar {{Miel}}, {{Salsa de soja}}, {{Copos de guindilla}} y {{Zumo de lima}} en un cazo a fuego suave.","minutes":1,"kind":"activo"},{"text":"Remover la salsa sin parar durante 2 min hasta que espese ligeramente y retirar del fuego.","minutes":2,"kind":"activo"},{"text":"Verter la salsa caliente sobre el pollo frito y remover para que quede bien cubierto.","minutes":1,"kind":"emplatado"},{"text":"Servir de inmediato para conservar el crujiente del rebozado.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_066', 'Costillas BBQ con salsa casera ahumada', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 145, 'normal', 'all', 600, 42, 22, 38, 2, true, true, '{"mostaza","soja","sulfitos"}', '[{"name":"Costillar de cerdo","amount":600,"unit":"g"},{"name":"Pimentón ahumado","amount":5,"unit":"g"},{"name":"Ajo en polvo","amount":3,"unit":"g"},{"name":"Azúcar moreno","amount":15,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra molida","amount":2,"unit":"g"},{"name":"Tomate frito","amount":100,"unit":"g"},{"name":"Vinagre de manzana","amount":15,"unit":"ml"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Mostaza","amount":10,"unit":"g"},{"name":"Salsa de soja","amount":10,"unit":"ml"}]'::jsonb, '{"Retirar la membrana posterior de costillar de cerdo tirando de una esquina con ayuda de papel de cocina.","Mezclar pimentón ahumado, ajo en polvo, azúcar moreno, sal y pimienta negra molida en un bol hasta obtener un adobo seco homogéneo.","Frotar el costillar por ambos lados con el adobo seco.","Refrigerar el costillar adobado en la nevera durante 30 min.","Precalentar el horno a 150 °C.","Mezclar tomate frito, vinagre de manzana, miel, mostaza y salsa de soja en un cazo.","Cocer la salsa a fuego suave hasta que espese ligeramente, unos 8 min.","Retirar la salsa del fuego y reservar.","Envolver el costillar en papel de aluminio y colocarlo en una bandeja.","Hornear el costillar envuelto a 150 °C durante 120 min, hasta que la carne esté muy tierna.","Retirar el costillar del horno y subir la temperatura a 220 °C.","Quitar el papel de aluminio y pincelar el costillar generosamente con la salsa reservada.","Hornear a 220 °C durante 7 min, hasta que la salsa empiece a lacarse.","Pincelar de nuevo con más salsa y hornear 6 min más, hasta conseguir una laca oscura y pegajosa.","Retirar el costillar del horno y dejar reposar 5 min antes de cortar.","Cortar el costillar entre hueso y hueso y servir con el resto de la salsa aparte."}', 'Costillar de cerdo cocinado lento hasta quedar tierno y glaseado con una salsa BBQ casera ahumada.', '[{"appliance":"horno","time":145,"difficulty":"normal","prepSummary":"Sazonar las costillas y hornear cubiertas a 130-150°C por 2 horas para tiernizar. Luego, destapar, subir a 180-200°C, untar con la salsa casera y hornear 20-30 min más hasta caramelizar."},{"appliance":"airfryer","time":60,"difficulty":"normal","prepSummary":"Cortar las costillas en porciones, sazonar y cocinar en la airfryer a 160°C durante 40-50 minutos, volteando a mitad. Luego, untar con la salsa casera y cocinar a 180°C por 10-15 minutos más hasta dorar y caramelizar."},{"appliance":"olla_express","time":55,"difficulty":"normal","prepSummary":"Cocinar las costillas sazonadas en la olla express con un poco de líquido durante 25-30 minutos a presión para tiernizarlas. Finalizar en el horno o airfryer a 200°C, untando con la salsa casera, por 15-20 minutos hasta dorar y caramelizar."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Retirar la membrana posterior de {{Costillar de cerdo}} tirando de una esquina con ayuda de papel de cocina.","minutes":3,"kind":"prep","part":"principal"},{"text":"Mezclar {{Pimentón ahumado}}, {{Ajo en polvo}}, {{Azúcar moreno}}, {{Sal}} y {{Pimienta negra molida}} en un bol hasta obtener un adobo seco homogéneo.","minutes":2,"kind":"prep","part":"principal"},{"text":"Frotar el costillar por ambos lados con el adobo seco.","minutes":2,"kind":"prep","part":"principal"},{"text":"Refrigerar el costillar adobado en la nevera durante 30 min.","minutes":30,"kind":"espera","part":"principal"},{"text":"Precalentar el horno a 150 °C.","minutes":10,"kind":"pasivo","part":"principal"},{"text":"Mezclar {{Tomate frito}}, {{Vinagre de manzana}}, {{Miel}}, {{Mostaza}} y {{Salsa de soja}} en un cazo.","minutes":2,"kind":"paralelo","part":"salsa","during":4},{"text":"Cocer la salsa a fuego suave hasta que espese ligeramente, unos 8 min.","minutes":8,"kind":"pasivo","part":"salsa"},{"text":"Retirar la salsa del fuego y reservar.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Envolver el costillar en papel de aluminio y colocarlo en una bandeja.","minutes":2,"kind":"activo","part":"principal"},{"text":"Hornear el costillar envuelto a 150 °C durante 120 min, hasta que la carne esté muy tierna.","minutes":120,"kind":"pasivo","part":"principal"},{"text":"Retirar el costillar del horno y subir la temperatura a 220 °C.","minutes":2,"kind":"activo","part":"principal"},{"text":"Quitar el papel de aluminio y pincelar el costillar generosamente con la salsa reservada.","minutes":2,"kind":"activo","part":"principal"},{"text":"Hornear a 220 °C durante 7 min, hasta que la salsa empiece a lacarse.","minutes":7,"kind":"pasivo","part":"principal"},{"text":"Pincelar de nuevo con más salsa y hornear 6 min más, hasta conseguir una laca oscura y pegajosa.","minutes":6,"kind":"pasivo","part":"principal"},{"text":"Retirar el costillar del horno y dejar reposar 5 min antes de cortar.","minutes":5,"kind":"espera","part":"combinado"},{"text":"Cortar el costillar entre hueso y hueso y servir con el resto de la salsa aparte.","minutes":2,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_067', 'Milanesa de ternera con patatas fritas', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 720, 42, 55, 36, 2, true, false, '{"gluten","huevo"}', '[{"name":"Filete de ternera para milanesa","amount":350,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Pan rallado","amount":100,"unit":"g"},{"name":"Harina de trigo","amount":40,"unit":"g"},{"name":"Ajo en polvo","amount":3,"unit":"g"},{"name":"Perejil picado","amount":5,"unit":"g"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Aceite de oliva","amount":400,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en bastones de 0,5 cm.","Secar los bastones de patata con un paño limpio hasta eliminar la humedad.","Calentar aceite de oliva en una sartén grande a fuego fuerte.","Freír los bastones de patata a fuego medio hasta que estén dorados y crujientes.","Escurrir las patatas fritas sobre papel absorbente y reservar.","Mezclar pan rallado, ajo en polvo y perejil picado en un plato llano.","Batir huevo en un plato hondo hasta homogeneizar.","Poner harina de trigo en un tercer plato llano.","Salar filete de ternera para milanesa por ambos lados.","Pasar cada filete por harina, sacudiendo el exceso.","Sumergir cada filete enharinado en el huevo batido hasta cubrirlo bien.","Rebozar cada filete en la mezcla de pan rallado, presionando para que adhiera.","Calentar el aceite restante en sartén a fuego fuerte hasta que esté bien caliente.","Freír las milanesas a fuego medio-fuerte 3 min por el primer lado hasta que estén doradas.","Dar la vuelta a las milanesas y freír 3 min más hasta que estén doradas por el otro lado.","Escurrir las milanesas sobre papel absorbente.","Salar sal las patatas fritas reservadas.","Servir las milanesas calientes junto a las patatas fritas."}', 'Filete de ternera empanado y frito, crujiente por fuera y jugoso por dentro, con patatas fritas.', '[{"appliance":"airfryer","time":40,"difficulty":"facil","prepSummary":"Prepara las patatas con un poco de aceite y sal, cocínalas en la airfryer a 190°C durante 20-25 minutos, agitándolas a mitad. Luego, las milanesas, rociadas con aceite, a 190°C durante 15-18 minutos, volteándolas para un dorado uniforme y crujiente."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Dispón las patatas y las milanesas (ligeramente rociadas con aceite) en bandejas separadas. Hornea las patatas por 30-40 minutos y las milanesas por 20-25 minutos, volteando ambos a mitad de cocción para un resultado dorado y crujiente con menos gras"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en bastones de 0,5 cm.","minutes":5,"kind":"prep","part":"guarnicion"},{"text":"Secar los bastones de patata con un paño limpio hasta eliminar la humedad.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva|abundante}} en una sartén grande a fuego fuerte.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Freír los bastones de patata a fuego medio hasta que estén dorados y crujientes.","minutes":10,"kind":"pasivo","part":"guarnicion"},{"text":"Escurrir las patatas fritas sobre papel absorbente y reservar.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Mezclar {{Pan rallado}}, {{Ajo en polvo|pizca}} y {{Perejil picado|pizca}} en un plato llano.","minutes":1,"kind":"prep","part":"principal"},{"text":"Batir {{Huevo}} en un plato hondo hasta homogeneizar.","minutes":1,"kind":"prep","part":"principal"},{"text":"Poner {{Harina de trigo}} en un tercer plato llano.","minutes":1,"kind":"prep","part":"principal"},{"text":"Salar {{Filete de ternera para milanesa}} por ambos lados.","minutes":1,"kind":"prep","part":"principal"},{"text":"Pasar cada filete por harina, sacudiendo el exceso.","minutes":1,"kind":"prep","part":"principal"},{"text":"Sumergir cada filete enharinado en el huevo batido hasta cubrirlo bien.","minutes":1,"kind":"prep","part":"principal"},{"text":"Rebozar cada filete en la mezcla de pan rallado, presionando para que adhiera.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar el aceite restante en {{@Sartén}} a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo","part":"principal"},{"text":"Freír las milanesas a fuego medio-fuerte 3 min por el primer lado hasta que estén doradas.","minutes":3,"kind":"activo","part":"principal"},{"text":"Dar la vuelta a las milanesas y freír 3 min más hasta que estén doradas por el otro lado.","minutes":3,"kind":"activo","part":"principal"},{"text":"Escurrir las milanesas sobre papel absorbente.","minutes":1,"kind":"activo","part":"principal"},{"text":"Salar {{Sal|gusto}} las patatas fritas reservadas.","minutes":1,"kind":"activo","part":"combinado"},{"text":"Servir las milanesas calientes junto a las patatas fritas.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_068', 'Filete a la pimienta verde flambeado', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 460, 34, 4, 34, 2, false, true, '{"lactosa","sulfitos"}', '[{"name":"Filete de solomillo de ternera","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Pimienta verde en grano","amount":20,"unit":"g"},{"name":"Brandy","amount":40,"unit":"ml"},{"name":"Nata para cocinar","amount":150,"unit":"ml"},{"name":"Caldo de carne","amount":50,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Retirar filete de solomillo de ternera de la nevera y dejar atemperar 15 min antes de cocinar.","Escurrir pimienta verde en grano y machacar ligeramente la mitad con el dorso de un cuchillo.","Salpimentar los filetes con sal por ambas caras justo antes de cocinar.","Calentar aceite de oliva y la mitad de mantequilla en sartén a fuego fuerte.","Marcar los filetes 2 min por cada lado hasta que estén dorados por fuera y rosados por dentro.","Retirar los filetes a un plato y reservar los jugos que hayan quedado en la sartén.","Retirar la sartén del fuego y añadir brandy.","Flambear con cuidado acercando una llama hasta que el brandy arda y dejar que la llama se apague sola.","Volver a poner la sartén a fuego medio y añadir la pimienta verde machacada y el resto de la pimienta.","Añadir caldo de carne y dejar reducir 1 min hasta que el líquido se evapore ligeramente.","Incorporar nata para cocinar y la mantequilla restante, removiendo para integrar.","Cocer a fuego medio 3 min, removiendo de vez en cuando, hasta que la salsa espese y nape la cuchara.","Devolver los filetes a la sartén con los jugos reservados y napar con la salsa.","Calentar 1 min a fuego suave hasta que los filetes estén calientes sin sobrecocer.","Servir los filetes en el plato con la salsa de pimienta verde por encima."}', 'Filete de ternera flambeado con brandy y napado en una cremosa salsa de pimienta verde.', '[]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Retirar {{Filete de solomillo de ternera}} de la nevera y dejar atemperar 15 min antes de cocinar.","minutes":15,"kind":"espera"},{"text":"Escurrir {{Pimienta verde en grano}} y machacar ligeramente la mitad con el dorso de un cuchillo.","minutes":2,"kind":"prep"},{"text":"Salpimentar los filetes con {{Sal|gusto}} por ambas caras justo antes de cocinar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} y la mitad de {{Mantequilla}} en {{@Sartén}} a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Marcar los filetes 2 min por cada lado hasta que estén dorados por fuera y rosados por dentro.","minutes":4,"kind":"activo"},{"text":"Retirar los filetes a un plato y reservar los jugos que hayan quedado en la sartén.","minutes":1,"kind":"activo"},{"text":"Retirar la sartén del fuego y añadir {{Brandy}}.","minutes":1,"kind":"activo"},{"text":"Flambear con cuidado acercando una llama hasta que el brandy arda y dejar que la llama se apague sola.","minutes":1,"kind":"activo"},{"text":"Volver a poner la sartén a fuego medio y añadir la pimienta verde machacada y el resto de la pimienta.","minutes":1,"kind":"activo"},{"text":"Añadir {{Caldo de carne}} y dejar reducir 1 min hasta que el líquido se evapore ligeramente.","minutes":1,"kind":"activo"},{"text":"Incorporar {{Nata para cocinar}} y la mantequilla restante, removiendo para integrar.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego medio 3 min, removiendo de vez en cuando, hasta que la salsa espese y nape la cuchara.","minutes":3,"kind":"pasivo"},{"text":"Devolver los filetes a la sartén con los jugos reservados y napar con la salsa.","minutes":1,"kind":"activo"},{"text":"Calentar 1 min a fuego suave hasta que los filetes estén calientes sin sobrecocer.","minutes":1,"kind":"pasivo"},{"text":"Servir los filetes en el plato con la salsa de pimienta verde por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_069', 'Carpaccio de ternera con parmesano y rúcula', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 285, 26, 2, 19, 2, false, false, '{"lactosa"}', '[{"name":"Solomillo de ternera","amount":250,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Queso parmesano","amount":30,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":30,"unit":"ml"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Sal en escamas","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Envolver solomillo de ternera en film transparente bien prieto y congelar hasta que esté firme pero no duro.","Laminar el solomillo semicongelado en láminas lo más finas posible con un cuchillo bien afilado.","Disponer las láminas de carne en un plato grande, superponiéndolas ligeramente hasta cubrir toda la superficie.","Lavar y escurrir rúcula.","Rallar queso parmesano en virutas con un pelador.","Mezclar aceite de oliva virgen extra con zumo de limón en un bol pequeño hasta integrar.","Repartir la rúcula sobre la carne.","Distribuir las virutas de queso parmesano por encima.","Aliñar con la mezcla de aceite de oliva virgen extra y zumo de limón.","Terminar con sal en escamas y pimienta negra recién molida al gusto, y servir enseguida."}', 'Láminas finas de solomillo de ternera crudo con virutas de parmesano, rúcula y aceite de oliva.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Sella el solomillo entero en la airfryer a 200°C durante 6-8 minutos, girándolo a mitad, para crear una fina costra exterior. Enfríalo rápidamente en el congelador (15-20 min) para facilitar el laminado muy fino y luego monta el carpaccio."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a máxima potencia con la función grill. Sella el solomillo 3-4 minutos por cada lado hasta dorar ligeramente la superficie. Refrigera en el congelador (15-20 min) para un corte más fácil, luego lamina muy fino y emplata el carpaccio."}]'::jsonb, '{}', true, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Envolver {{Solomillo de ternera}} en film transparente bien prieto y congelar hasta que esté firme pero no duro.","minutes":60,"kind":"espera"},{"text":"Laminar el solomillo semicongelado en láminas lo más finas posible con un cuchillo bien afilado.","minutes":5,"kind":"prep"},{"text":"Disponer las láminas de carne en un plato grande, superponiéndolas ligeramente hasta cubrir toda la superficie.","minutes":2,"kind":"activo"},{"text":"Lavar y escurrir {{Rúcula}}.","minutes":1,"kind":"prep"},{"text":"Rallar {{Queso parmesano}} en virutas con un pelador.","minutes":1,"kind":"prep"},{"text":"Mezclar {{Aceite de oliva virgen extra}} con {{Zumo de limón}} en un bol pequeño hasta integrar.","minutes":1,"kind":"prep"},{"text":"Repartir la rúcula sobre la carne.","minutes":1,"kind":"emplatado"},{"text":"Distribuir las virutas de queso parmesano por encima.","minutes":1,"kind":"emplatado"},{"text":"Aliñar con la mezcla de aceite de oliva virgen extra y zumo de limón.","minutes":1,"kind":"emplatado"},{"text":"Terminar con {{Sal en escamas}} y {{Pimienta negra}} recién molida al gusto, y servir enseguida.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_070', 'Tartar de solomillo al cuchillo', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 360, 28, 3, 26, 2, false, false, '{"huevo","mostaza","pescado","sulfitos"}', '[{"name":"Solomillo de ternera","amount":300,"unit":"g"},{"name":"Yema de huevo","amount":2,"unit":"ud"},{"name":"Mostaza de Dijon","amount":15,"unit":"g"},{"name":"Alcaparras","amount":15,"unit":"g"},{"name":"Pepinillos en vinagre","amount":20,"unit":"g"},{"name":"Cebolleta","amount":20,"unit":"g"},{"name":"Salsa Perrins","amount":10,"unit":"ml"},{"name":"Tabasco","amount":2,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Cortar solomillo de ternera en dados muy pequeños a cuchillo, sin picadora, para conservar la textura.","Picar alcaparras finamente.","Picar pepinillos en vinagre finamente.","Picar cebolleta finamente.","Mezclar en un bol la carne picada con las alcaparras, los pepinillos y la cebolleta.","Añadir mostaza de dijon, salsa perrins y tabasco sobre la mezcla.","Añadir aceite de oliva virgen extra, sal y pimienta negra.","Remover bien hasta integrar todos los ingredientes de forma homogénea.","Rectificar el punto de sal, pimienta y tabasco al gusto.","Colocar un aro de emplatar sobre cada plato y rellenar con el tartar, compactando y alisando la superficie.","Retirar el aro con cuidado, hacer un hueco en el centro y disponer yema de huevo encima antes de servir."}', 'Solomillo de ternera picado a cuchillo y aliñado a mano, coronado con una yema de huevo cruda.', '[]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Solomillo de ternera}} en dados muy pequeños a cuchillo, sin picadora, para conservar la textura.","minutes":8,"kind":"prep"},{"text":"Picar {{Alcaparras}} finamente.","minutes":2,"kind":"prep"},{"text":"Picar {{Pepinillos en vinagre}} finamente.","minutes":1,"kind":"prep"},{"text":"Picar {{Cebolleta}} finamente.","minutes":1,"kind":"prep"},{"text":"Mezclar en un bol la carne picada con las alcaparras, los pepinillos y la cebolleta.","minutes":1,"kind":"activo"},{"text":"Añadir {{Mostaza de Dijon}}, {{Salsa Perrins}} y {{Tabasco}} sobre la mezcla.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva virgen extra|chorrito}}, {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"activo"},{"text":"Remover bien hasta integrar todos los ingredientes de forma homogénea.","minutes":1,"kind":"activo"},{"text":"Rectificar el punto de sal, pimienta y tabasco al gusto.","minutes":1,"kind":"activo"},{"text":"Colocar un aro de emplatar sobre cada plato y rellenar con el tartar, compactando y alisando la superficie.","minutes":2,"kind":"emplatado"},{"text":"Retirar el aro con cuidado, hacer un hueco en el centro y disponer {{Yema de huevo}} encima antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_071', 'Albóndigas en salsa de almendras y azafrán', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 50, 'normal', 'all', 410, 28, 20, 24, 2, true, true, '{"gluten","huevo","frutos_secos","sulfitos"}', '[{"name":"Carne picada de ternera","amount":300,"unit":"g"},{"name":"Pan rallado","amount":25,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Perejil picado","amount":3,"unit":"g"},{"name":"Harina de trigo","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Almendra molida","amount":30,"unit":"g"},{"name":"Hebras de azafrán","amount":1,"unit":"g"},{"name":"Caldo de carne","amount":250,"unit":"ml"},{"name":"Vino blanco","amount":30,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Picar ajo fino y dividirlo en dos mitades iguales.","Picar cebolla en brunoise fina.","Mezclar carne picada de ternera, pan rallado, huevo, la mitad del ajo picado, perejil picado y sal en un bol.","Amasar la mezcla con las manos hasta que todos los ingredientes queden bien integrados.","Formar albóndigas del tamaño de una nuez con las manos húmedas.","Pasar cada albóndiga por harina de trigo, sacudiendo el exceso.","Calentar aceite de oliva en una cazuela a fuego medio.","Dorar las albóndigas en tandas hasta que estén selladas por todos los lados.","Retirar las albóndigas de la cazuela y reservar en un plato.","Sofreír la cebolla picada y la mitad restante del ajo en el mismo aceite a fuego medio.","Añadir vino blanco y remover hasta que se evapore el alcohol.","Añadir caldo de carne, almendra molida y hebras de azafrán y remover bien para integrar.","Incorporar las albóndigas reservadas a la cazuela y tapar.","Cocer a fuego suave durante 20 min, hasta que la salsa espese y las albóndigas estén hechas por dentro.","Probar la salsa y rectificar de sal al gusto.","Servir las albóndigas bien calientes con la salsa de almendras y azafrán por encima."}', 'Albóndigas de ternera guisadas en una salsa dorada de almendra molida y azafrán.', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Las albóndigas se hornean primero a 200°C durante 15-20 minutos para dorarlas. Luego, se prepara la salsa en una cazuela apta para horno, se incorporan las albóndigas y se cocina a fuego lento en el horno a 180°C hasta que la salsa espese y los sabores se integren."},{"appliance":"thermomix","time":50,"difficulty":"facil","prepSummary":"La Thermomix mezcla los ingredientes de las albóndigas y prepara la salsa sofriendo la cebolla y cociendo a la perfección con las almendras y el azafrán. Las albóndigas se pueden cocinar en el Varoma al vapor mientras se hace la salsa o añadir directamente al vaso para el cocinad"},{"appliance":"olla_express","time":35,"difficulty":"normal","prepSummary":"Dora las albóndigas y sofríe la cebolla en la olla express. Luego, añade el resto de ingredientes de la salsa, incorpora las albóndigas y cocina a presión durante 10-15 minutos desde que sube la válvula para una cocción rápida y profunda de todos los sabores."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Picar {{Ajo}} fino y dividirlo en dos mitades iguales.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolla}} en brunoise fina.","minutes":3,"kind":"prep"},{"text":"Mezclar {{Carne picada de ternera}}, {{Pan rallado}}, {{Huevo}}, la mitad del ajo picado, {{Perejil picado}} y {{Sal|gusto}} en un bol.","minutes":2,"kind":"prep"},{"text":"Amasar la mezcla con las manos hasta que todos los ingredientes queden bien integrados.","minutes":2,"kind":"prep"},{"text":"Formar albóndigas del tamaño de una nuez con las manos húmedas.","minutes":3,"kind":"prep"},{"text":"Pasar cada albóndiga por {{Harina de trigo}}, sacudiendo el exceso.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela a fuego medio.","minutes":1,"kind":"activo"},{"text":"Dorar las albóndigas en tandas hasta que estén selladas por todos los lados.","minutes":5,"kind":"activo"},{"text":"Retirar las albóndigas de la cazuela y reservar en un plato.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada y la mitad restante del ajo en el mismo aceite a fuego medio.","minutes":8,"kind":"pasivo"},{"text":"Añadir {{Vino blanco}} y remover hasta que se evapore el alcohol.","minutes":2,"kind":"activo"},{"text":"Añadir {{Caldo de carne}}, {{Almendra molida}} y {{Hebras de azafrán}} y remover bien para integrar.","minutes":1,"kind":"activo"},{"text":"Incorporar las albóndigas reservadas a la cazuela y tapar.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave durante 20 min, hasta que la salsa espese y las albóndigas estén hechas por dentro.","minutes":20,"kind":"pasivo"},{"text":"Probar la salsa y rectificar de sal al gusto.","minutes":1,"kind":"activo"},{"text":"Servir las albóndigas bien calientes con la salsa de almendras y azafrán por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_072', 'Pollo asado entero con limón y hierbas', 'carnes', 'pollo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 90, 'facil', 'all', 465, 45, 3, 30, 2, true, true, '{"lactosa"}', '[{"name":"Pollo entero","amount":900,"unit":"g"},{"name":"Limón","amount":2,"unit":"ud"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Romero fresco","amount":3,"unit":"g"},{"name":"Tomillo fresco","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Secar pollo entero por dentro y por fuera con papel de cocina.","Picar ajo fino.","Cortar 1 ud de limón en cuartos.","Mezclar el ajo picado con aceite de oliva, mantequilla, sal y pimienta negra hasta obtener una pasta homogénea.","Untar el pollo seco por fuera con la pasta de ajo y mantequilla.","Introducir los dedos bajo la piel de la pechuga con cuidado y untar también por debajo con la pasta restante.","Meter los cuartos de limón, romero fresco y tomillo fresco dentro de la cavidad del pollo.","Colocar el pollo en una fuente de horno con la pechuga hacia arriba.","Exprimir el segundo limón por encima del pollo.","Hornear 80 min a 200 °C, regando el pollo con sus propios jugos cada 20 min, hasta que la piel esté dorada y el jugo salga claro al pinchar el muslo.","Retirar el pollo del horno y dejar reposar 10 min sobre la fuente antes de trinchar.","Trinchar el pollo y servir con los jugos de la fuente por encima."}', 'Pollo entero asado al horno con limón, ajo y hierbas aromáticas hasta quedar dorado y jugoso.', '[{"appliance":"horno","time":90,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Unta el pollo con la mezcla de mantequilla, hierbas, sal y pimienta, rellena con limón y ajo, y asa durante 90 minutos, regando ocasionalmente para una piel dorada y crujiente."},{"appliance":"airfryer","time":55,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 180°C. Unta el pollo y cocina durante 45-55 minutos, volteándolo a mitad de cocción y subiendo a 200°C los últimos 10 minutos para una piel extra crujiente y jugosidad interior."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Secar {{Pollo entero}} por dentro y por fuera con papel de cocina.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":2,"kind":"prep"},{"text":"Cortar 1 ud de {{Limón}} en cuartos.","minutes":1,"kind":"prep"},{"text":"Mezclar el ajo picado con {{Aceite de oliva}}, {{Mantequilla}}, {{Sal|gusto}} y {{Pimienta negra|pizca}} hasta obtener una pasta homogénea.","minutes":2,"kind":"prep"},{"text":"Untar el pollo seco por fuera con la pasta de ajo y mantequilla.","minutes":2,"kind":"activo"},{"text":"Introducir los dedos bajo la piel de la pechuga con cuidado y untar también por debajo con la pasta restante.","minutes":2,"kind":"activo"},{"text":"Meter los cuartos de limón, {{Romero fresco}} y {{Tomillo fresco}} dentro de la cavidad del pollo.","minutes":1,"kind":"activo"},{"text":"Colocar el pollo en una fuente de horno con la pechuga hacia arriba.","minutes":1,"kind":"activo"},{"text":"Exprimir el segundo {{Limón}} por encima del pollo.","minutes":1,"kind":"activo"},{"text":"Hornear 80 min a 200 °C, regando el pollo con sus propios jugos cada 20 min, hasta que la piel esté dorada y el jugo salga claro al pinchar el muslo.","minutes":80,"kind":"pasivo"},{"text":"Retirar el pollo del horno y dejar reposar 10 min sobre la fuente antes de trinchar.","minutes":10,"kind":"espera"},{"text":"Trinchar el pollo y servir con los jugos de la fuente por encima.","minutes":3,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_073', 'Muslos de pollo al horno con miel y mostaza', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, 'horno', 50, 'facil', 'all', 425, 34, 18, 24, 2, true, true, '{"mostaza"}', '[{"name":"Muslos de pollo","amount":500,"unit":"g"},{"name":"Miel","amount":40,"unit":"g"},{"name":"Mostaza de Dijon","amount":30,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Picar ajo muy fino.","Mezclar miel, mostaza de dijon, el ajo picado, aceite de oliva, pimentón dulce, sal y pimienta negra en un bol hasta obtener una salsa homogénea.","Colocar muslos de pollo en una bandeja de horno con la piel hacia arriba.","Untar los muslos de pollo con la salsa de miel y mostaza por todos los lados, cubriendo bien la piel.","Hornear a 200 °C durante 35 min.","Subir la temperatura del horno a 220 °C.","Pincelar los muslos con el jugo acumulado en la bandeja.","Hornear a 220 °C durante 10 min, hasta que la piel esté dorada, brillante y pegajosa.","Reposar los muslos en la bandeja durante 5 min antes de servir.","Servir los muslos de pollo con el jugo de la bandeja por encima."}', 'Muslos de pollo al horno glaseados con una mezcla de miel y mostaza hasta quedar pegajosos y dorados.', '[{"appliance":"horno","time":50,"difficulty":"facil","prepSummary":"Precalienta el horno a 190-200°C. Hornea los muslos marinados durante 45-50 minutos, dándoles la vuelta a mitad de cocción para un dorado uniforme y una salsa caramelizada."},{"appliance":"airfryer","time":28,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 180°C. Cocina los muslos marinados durante 25-30 minutos, volteándolos a mitad de cocción y pincelando con más salsa para asegurar un exterior crujiente y jugoso."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Picar {{Ajo}} muy fino.","minutes":2,"kind":"prep"},{"text":"Mezclar {{Miel}}, {{Mostaza de Dijon}}, el ajo picado, {{Aceite de oliva|chorrito}}, {{Pimentón dulce|pizca}}, {{Sal|gusto}} y {{Pimienta negra|pizca}} en un bol hasta obtener una salsa homogénea.","minutes":2,"kind":"prep"},{"text":"Colocar {{Muslos de pollo}} en una bandeja de horno con la piel hacia arriba.","minutes":1,"kind":"prep"},{"text":"Untar los muslos de pollo con la salsa de miel y mostaza por todos los lados, cubriendo bien la piel.","minutes":2,"kind":"prep"},{"text":"Hornear a 200 °C durante 35 min.","minutes":35,"kind":"pasivo"},{"text":"Subir la temperatura del horno a 220 °C.","minutes":1,"kind":"activo"},{"text":"Pincelar los muslos con el jugo acumulado en la bandeja.","minutes":1,"kind":"activo"},{"text":"Hornear a 220 °C durante 10 min, hasta que la piel esté dorada, brillante y pegajosa.","minutes":10,"kind":"pasivo"},{"text":"Reposar los muslos en la bandeja durante 5 min antes de servir.","minutes":5,"kind":"espera"},{"text":"Servir los muslos de pollo con el jugo de la bandeja por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_074', 'Secreto ibérico con patatas fritas y mojo picón', 'carnes', 'cerdo', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 700, 38, 42, 42, 2, false, false, '{"sulfitos"}', '[{"name":"Secreto ibérico","amount":400,"unit":"g"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Aceite de oliva","amount":400,"unit":"ml"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pimentón picante","amount":5,"unit":"g"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Vinagre de vino","amount":15,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":40,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en bastones uniformes.","Secar los bastones de patata con papel de cocina hasta que no quede humedad.","Calentar aceite de oliva en una sartén honda a fuego medio hasta que esté caliente.","Freír los bastones de patata hasta que estén dorados y tiernos, unos 10 min.","Cortar pimiento rojo en trozos grandes y pelar ajo.","Triturar el pimiento rojo y el ajo con pimentón picante, comino molido, vinagre de vino y sal hasta obtener una pasta.","Añadir aceite de oliva virgen extra en hilo fino mientras se tritura hasta obtener una salsa fina y homogénea.","Escurrir las patatas fritas sobre papel de cocina y salar al gusto.","Salar secreto ibérico y dejar atemperar fuera de la nevera.","Calentar plancha a fuego fuerte hasta que humee ligeramente.","Marcar el secreto ibérico por un lado hasta que esté dorado, unos 3 min.","Dar la vuelta al secreto ibérico y marcar por el otro lado hasta que esté dorado y jugoso por dentro, unos 3 min.","Retirar el secreto ibérico de la plancha y dejar reposar.","Cortar el secreto ibérico en lonchas en sentido transversal a la fibra.","Servir las lonchas de secreto ibérico con las patatas fritas y el mojo picón aparte."}', 'Secreto ibérico a la plancha servido con patatas fritas y un mojo picón intenso.', '[{"appliance":"airfryer","time":40,"difficulty":"facil","prepSummary":"Cocina el secreto y las patatas en la airfryer a 190°C. Las patatas tardarán unos 20-25 min y el secreto 15-20 min, dándoles la vuelta a mitad para un dorado uniforme. El mojo se prepara aparte en batidora."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Hornea las patatas en una bandeja con un poco de aceite durante 30-40 min. Añade el secreto a la misma bandeja o en otra para los últimos 20-25 min, hasta que esté dorado y jugoso. El mojo se prepara aparte."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en bastones uniformes.","minutes":5,"kind":"prep","part":"guarnicion"},{"text":"Secar los bastones de patata con papel de cocina hasta que no quede humedad.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva|abundante}} en una sartén honda a fuego medio hasta que esté caliente.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Freír los bastones de patata hasta que estén dorados y tiernos, unos 10 min.","minutes":10,"kind":"pasivo","part":"guarnicion"},{"text":"Cortar {{Pimiento rojo}} en trozos grandes y pelar {{Ajo}}.","minutes":3,"kind":"paralelo","part":"salsa","during":3},{"text":"Triturar el pimiento rojo y el ajo con {{Pimentón picante|pizca}}, {{Comino molido|pizca}}, {{Vinagre de vino}} y {{Sal|gusto}} hasta obtener una pasta.","minutes":2,"kind":"paralelo","part":"salsa","during":3},{"text":"Añadir {{Aceite de oliva virgen extra}} en hilo fino mientras se tritura hasta obtener una salsa fina y homogénea.","minutes":1,"kind":"paralelo","part":"salsa","during":3},{"text":"Escurrir las patatas fritas sobre papel de cocina y salar al gusto.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Salar {{Secreto ibérico}} y dejar atemperar fuera de la nevera.","minutes":10,"kind":"espera","part":"principal"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que humee ligeramente.","minutes":2,"kind":"activo","part":"principal"},{"text":"Marcar el secreto ibérico por un lado hasta que esté dorado, unos 3 min.","minutes":3,"kind":"activo","part":"principal"},{"text":"Dar la vuelta al secreto ibérico y marcar por el otro lado hasta que esté dorado y jugoso por dentro, unos 3 min.","minutes":3,"kind":"activo","part":"principal"},{"text":"Retirar el secreto ibérico de la plancha y dejar reposar.","minutes":3,"kind":"espera","part":"principal"},{"text":"Cortar el secreto ibérico en lonchas en sentido transversal a la fibra.","minutes":1,"kind":"prep","part":"principal"},{"text":"Servir las lonchas de secreto ibérico con las patatas fritas y el mojo picón aparte.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true)
