insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('carnes_075', 'Solomillo a la pimienta con patatas paja', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 720, 38, 38, 46, 2, false, false, '{"lactosa","sulfitos"}', '[{"name":"Solomillo de ternera","amount":350,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":400,"unit":"ml"},{"name":"Pimienta negra en grano","amount":15,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Brandy","amount":30,"unit":"ml"},{"name":"Nata para cocinar","amount":150,"unit":"ml"},{"name":"Caldo de carne","amount":40,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y cortarlas en juliana muy fina con mandolina.","Secar bien las patatas con un paño limpio para eliminar el exceso de humedad.","Calentar aceite de oliva en una olla a fuego fuerte hasta que esté bien caliente.","Freír las patatas en el aceite caliente hasta que estén doradas y crujientes.","Escurrir las patatas sobre papel absorbente y salpimentar con sal.","Machacar pimienta negra en grano ligeramente con el dorso de un cuchillo.","Salar solomillo de ternera y presionar la pimienta machacada por ambas caras.","Calentar mantequilla en sartén a fuego fuerte hasta que empiece a espumar.","Dorar los solomillos 2 min por cada cara hasta alcanzar el punto deseado.","Retirar los solomillos de la sartén y reservar en un plato.","Retirar la sartén del fuego y añadir brandy con cuidado; flamear inclinando la sartén.","Añadir caldo de carne cuando se apague la llama y remover a fuego medio.","Incorporar nata para cocinar y cocer a fuego medio hasta que la salsa espese.","Devolver los solomillos a la sartén y calentar 1 min hasta que estén bien integrados.","Servir los solomillos napados con la salsa de pimienta y acompañados de las patatas paja."}', 'Solomillo de ternera a la pimienta con una salsa cremosa de brandy y nata, acompañado de patatas paja crujientes.', '[{"appliance":"airfryer","time":45,"difficulty":"normal","prepSummary":"Prepara el solomillo sazonado y cocínalo en la airfryer a 190°C unos 12-15 minutos, volteando a mitad, para un punto jugoso. Las patatas paja se cortan muy finas, se rocían con poco aceite y se hacen en la airfryer a 180°C en tandas, removiendo frecuentemente, hasta que estén cru"}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortarlas en juliana muy fina con mandolina.","minutes":5,"kind":"prep","part":"guarnicion"},{"text":"Secar bien las patatas con un paño limpio para eliminar el exceso de humedad.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva|abundante}} en una olla a fuego fuerte hasta que esté bien caliente.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Freír las patatas en el aceite caliente hasta que estén doradas y crujientes.","minutes":5,"kind":"activo","part":"guarnicion"},{"text":"Escurrir las patatas sobre papel absorbente y salpimentar con {{Sal|gusto}}.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Machacar {{Pimienta negra en grano}} ligeramente con el dorso de un cuchillo.","minutes":2,"kind":"prep","part":"principal"},{"text":"Salar {{Solomillo de ternera}} y presionar la pimienta machacada por ambas caras.","minutes":2,"kind":"prep","part":"principal"},{"text":"Calentar {{Mantequilla}} en {{@Sartén}} a fuego fuerte hasta que empiece a espumar.","minutes":1,"kind":"activo","part":"principal"},{"text":"Dorar los solomillos 2 min por cada cara hasta alcanzar el punto deseado.","minutes":4,"kind":"activo","part":"principal"},{"text":"Retirar los solomillos de la sartén y reservar en un plato.","minutes":1,"kind":"activo","part":"principal"},{"text":"Retirar la sartén del fuego y añadir {{Brandy}} con cuidado; flamear inclinando la sartén.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Añadir {{Caldo de carne}} cuando se apague la llama y remover a fuego medio.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Incorporar {{Nata para cocinar}} y cocer a fuego medio hasta que la salsa espese.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Devolver los solomillos a la sartén y calentar 1 min hasta que estén bien integrados.","minutes":1,"kind":"activo","part":"combinado"},{"text":"Servir los solomillos napados con la salsa de pimienta y acompañados de las patatas paja.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_076', 'Redondo de ternera mechado', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 100, 'normal', 'all', 390, 44, 8, 20, 2, true, true, '{"huevo","sulfitos"}', '[{"name":"Redondo de ternera","amount":450,"unit":"g"},{"name":"Jamón cocido en lonchas","amount":50,"unit":"g"},{"name":"Huevo cocido","amount":1,"unit":"ud"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Caldo de carne","amount":150,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Pelar y picar fino cebolla y ajo.","Pelar y cortar zanahoria en rodajas finas.","Abrir redondo de ternera en forma de libro con un cuchillo, dejándolo plano.","Salpimentar la carne por dentro con sal y pimienta negra.","Cubrir la superficie interior con jamón cocido en lonchas extendiéndolas bien.","Colocar huevo cocido entero en el centro a lo largo.","Enrollar la carne sobre sí misma envolviendo el relleno y atar con hilo de cocina.","Calentar aceite de oliva en una cazuela a fuego fuerte.","Dorar el redondo por todos los lados hasta que esté sellado y con color uniforme.","Retirar el redondo y reservar. Bajar el fuego a medio.","Sofreír la cebolla, el ajo y la zanahoria en la misma cazuela hasta que estén tiernos.","Añadir vino blanco y remover hasta que evapore el alcohol.","Incorporar caldo de carne y volver a colocar el redondo en la cazuela.","Tapar y cocer a fuego suave hasta que la carne esté tierna, dando la vuelta a mitad.","Retirar el redondo de la cazuela y dejar reposar sobre una tabla.","Triturar la salsa de la cazuela hasta que quede fina y homogénea.","Retirar el hilo de cocina y cortar el redondo en lonchas de grosor uniforme.","Servir las lonchas en el plato napadas con la salsa triturada."}', 'Redondo de ternera relleno de jamón y huevo cocido, guisado y cortado en lonchas finas.', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Sella el redondo en una sartén y luego pásalo a una cazuela de horno con las verduras, el vino y el caldo. Cocina a 160-180°C durante 90-120 minutos hasta que esté muy tierno, logrando una carne jugosa y una salsa rica."},{"appliance":"olla_express","time":75,"difficulty":"normal","prepSummary":"Sella el redondo directamente en la olla express. Añade las verduras, el vino y el caldo, y cocina a alta presión durante 30-40 minutos. Obtendrás una carne extremadamente tierna y una salsa concentrada en mucho menos tiempo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Pelar y picar fino {{Cebolla}} y {{Ajo}}.","minutes":3,"kind":"prep"},{"text":"Pelar y cortar {{Zanahoria}} en rodajas finas.","minutes":2,"kind":"prep"},{"text":"Abrir {{Redondo de ternera}} en forma de libro con un cuchillo, dejándolo plano.","minutes":3,"kind":"prep"},{"text":"Salpimentar la carne por dentro con {{Sal|gusto}} y {{Pimienta negra|gusto}}.","minutes":1,"kind":"prep"},{"text":"Cubrir la superficie interior con {{Jamón cocido en lonchas}} extendiéndolas bien.","minutes":1,"kind":"prep"},{"text":"Colocar {{Huevo cocido}} entero en el centro a lo largo.","minutes":1,"kind":"prep"},{"text":"Enrollar la carne sobre sí misma envolviendo el relleno y atar con hilo de cocina.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Dorar el redondo por todos los lados hasta que esté sellado y con color uniforme.","minutes":6,"kind":"activo"},{"text":"Retirar el redondo y reservar. Bajar el fuego a medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla, el ajo y la zanahoria en la misma cazuela hasta que estén tiernos.","minutes":5,"kind":"activo"},{"text":"Añadir {{Vino blanco}} y remover hasta que evapore el alcohol.","minutes":2,"kind":"activo"},{"text":"Incorporar {{Caldo de carne}} y volver a colocar el redondo en la cazuela.","minutes":1,"kind":"activo"},{"text":"Tapar y cocer a fuego suave hasta que la carne esté tierna, dando la vuelta a mitad.","minutes":75,"kind":"pasivo"},{"text":"Retirar el redondo de la cazuela y dejar reposar sobre una tabla.","minutes":10,"kind":"espera"},{"text":"Triturar la salsa de la cazuela hasta que quede fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Retirar el hilo de cocina y cortar el redondo en lonchas de grosor uniforme.","minutes":2,"kind":"prep"},{"text":"Servir las lonchas en el plato napadas con la salsa triturada.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_077', 'Carne mechada con puré y salsa de su jugo', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 110, 'normal', 'all', 500, 38, 32, 24, 2, true, true, '{"lactosa","sulfitos"}', '[{"name":"Carne para mechar (morcillo de ternera)","amount":400,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino tinto","amount":75,"unit":"ml"},{"name":"Caldo de carne","amount":200,"unit":"ml"},{"name":"Tomate triturado","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Leche","amount":50,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en brunoise fina.","Pelar y picar zanahoria en trozos pequeños.","Pelar y picar ajo fino.","Salpimentar carne para mechar (morcillo de ternera) por todos los lados con sal y pimienta negra.","Calentar aceite de oliva en una cazuela a fuego fuerte.","Dorar la carne por todos los lados hasta que esté sellada y con color uniforme. Retirar y reservar.","Bajar el fuego a medio y sofreír la cebolla picada, la zanahoria picada y el ajo picado en la misma cazuela durante 8 min, hasta que estén tiernos.","Añadir tomate triturado y sofreír 3 min, removiendo hasta que pierda el agua.","Verter vino tinto y llevar a ebullición hasta que el alcohol evapore, unos 3 min.","Devolver la carne a la cazuela y añadir caldo de carne. Tapar y cocer a fuego suave 90 min, hasta que la carne esté muy tierna.","Pelar y cortar patata en trozos regulares.","Hervir agua con sal en un cazo y cocer las patatas troceadas 20 min, hasta que estén tiernas.","Calentar leche en un cazo pequeño a fuego suave hasta que esté caliente, sin que hierva.","Escurrir las patatas cocidas y triturarlas en el mismo cazo.","Añadir la leche caliente y mantequilla al puré y mezclar hasta obtener una textura fina y homogénea.","Retirar la carne de la cazuela y desmecharla con 2 tenedores en tiras finas.","Triturar la salsa de la cazuela con un batidor de mano hasta obtener una salsa lisa.","Devolver la carne desmechada a la cazuela con la salsa triturada y remover hasta integrar bien.","Servir una base de puré de patata en el plato y disponer la carne mechada con su salsa por encima."}', 'Carne de ternera mechada hasta deshacerse, servida sobre puré de patata con su propia salsa reducida.', '[{"appliance":"horno","time":150,"difficulty":"normal","prepSummary":"Sellaremos la carne y sofreiremos las verduras en una olla apta para horno en la encimera. Luego, añadiremos los líquidos y cocinaremos tapado en el horno a 160°C durante unas 2.5 horas hasta que la carne esté muy tierna. El puré se hará aparte."},{"appliance":"thermomix","time":160,"difficulty":"normal","prepSummary":"Dorar la carne en una sartén aparte. En la Thermomix, sofreír las verduras, añadir la carne y los líquidos, y cocinar a baja velocidad y temperatura (aprox. 100°C, giro inverso) durante 90-120 minutos hasta que la carne esté tierna. La salsa se triturará y el puré se preparará en"},{"appliance":"olla_express","time":90,"difficulty":"normal","prepSummary":"Dorar la carne y sofreír las verduras en la olla a presión abierta. Añadir los líquidos, cerrar y cocinar a presión durante 40-50 minutos. Tras liberar la presión, la carne estará muy tierna y la salsa lista, pudiendo reducirse si se desea. El puré se hará aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar y picar {{Cebolla}} en brunoise fina.","minutes":3,"kind":"prep","part":"principal"},{"text":"Pelar y picar {{Zanahoria}} en trozos pequeños.","minutes":2,"kind":"prep","part":"principal"},{"text":"Pelar y picar {{Ajo}} fino.","minutes":1,"kind":"prep","part":"principal"},{"text":"Salpimentar {{Carne para mechar (morcillo de ternera)}} por todos los lados con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela a fuego fuerte.","minutes":1,"kind":"activo","part":"principal"},{"text":"Dorar la carne por todos los lados hasta que esté sellada y con color uniforme. Retirar y reservar.","minutes":6,"kind":"activo","part":"principal"},{"text":"Bajar el fuego a medio y sofreír la cebolla picada, la zanahoria picada y el ajo picado en la misma cazuela durante 8 min, hasta que estén tiernos.","minutes":8,"kind":"activo","part":"principal"},{"text":"Añadir {{Tomate triturado}} y sofreír 3 min, removiendo hasta que pierda el agua.","minutes":3,"kind":"activo","part":"principal"},{"text":"Verter {{Vino tinto}} y llevar a ebullición hasta que el alcohol evapore, unos 3 min.","minutes":3,"kind":"activo","part":"principal"},{"text":"Devolver la carne a la cazuela y añadir {{Caldo de carne}}. Tapar y cocer a fuego suave 90 min, hasta que la carne esté muy tierna.","minutes":90,"kind":"pasivo","part":"principal"},{"text":"Pelar y cortar {{Patata}} en trozos regulares.","minutes":4,"kind":"paralelo","part":"guarnicion","during":9},{"text":"Hervir agua con sal en un cazo y cocer las patatas troceadas 20 min, hasta que estén tiernas.","minutes":20,"kind":"pasivo","part":"guarnicion"},{"text":"Calentar {{Leche}} en un cazo pequeño a fuego suave hasta que esté caliente, sin que hierva.","minutes":2,"kind":"paralelo","part":"guarnicion","during":11},{"text":"Escurrir las patatas cocidas y triturarlas en el mismo cazo.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Añadir la leche caliente y {{Mantequilla}} al puré y mezclar hasta obtener una textura fina y homogénea.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Retirar la carne de la cazuela y desmecharla con 2 tenedores en tiras finas.","minutes":4,"kind":"activo","part":"principal"},{"text":"Triturar la salsa de la cazuela con un batidor de mano hasta obtener una salsa lisa.","minutes":2,"kind":"activo","part":"principal"},{"text":"Devolver la carne desmechada a la cazuela con la salsa triturada y remover hasta integrar bien.","minutes":2,"kind":"activo","part":"combinado"},{"text":"Servir una base de puré de patata en el plato y disponer la carne mechada con su salsa por encima.","minutes":2,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_078', 'Estofado de carrilleras con boniato', 'carnes', 'cerdo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 120, 'normal', 'invierno', 440, 34, 30, 20, 2, true, true, '{"sulfitos"}', '[{"name":"Carrilleras de cerdo","amount":400,"unit":"g"},{"name":"Boniato","amount":250,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino tinto","amount":100,"unit":"ml"},{"name":"Caldo de carne","amount":150,"unit":"ml"},{"name":"Tomate triturado","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en brunoise fina.","Pelar y picar zanahoria en brunoise fina.","Picar ajo fino.","Pelar boniato y cortarlo en dados grandes.","Salpimentar carrilleras de cerdo por ambas caras con sal y pimienta negra.","Calentar aceite de oliva en una cazuela a fuego fuerte hasta que humee.","Dorar las carrilleras de cerdo en la cazuela hasta que estén selladas por todos los lados.","Retirar las carrilleras de cerdo de la cazuela y reservar en un plato.","Bajar el fuego a medio y sofreír la cebolla picada, la zanahoria picada y el ajo picado en la misma cazuela hasta que estén tiernos.","Añadir tomate triturado y sofreír hasta que pierda el agua y se concentre.","Verter vino tinto y subir el fuego hasta que se evapore el alcohol y el líquido reduzca a la mitad.","Devolver las carrilleras de cerdo reservadas a la cazuela.","Añadir caldo de carne y laurel.","Tapar la cazuela y cocer a fuego suave durante 60 min.","Añadir el boniato en dados a la cazuela y remover con suavidad para integrarlo.","Tapar de nuevo y cocer a fuego suave hasta que el boniato esté tierno y las carrilleras se deshagan.","Retirar el laurel de la cazuela.","Probar el estofado y rectificar de sal si fuera necesario.","Servir el estofado bien caliente en platos hondos con el boniato integrado en la salsa."}', 'Carrilleras de cerdo guisadas a fuego lento con boniato hasta quedar melosas.', '[{"appliance":"horno","time":180,"difficulty":"normal","prepSummary":"Sella las carrilleras en una olla apta para horno, sofríe las verduras, añade el resto de ingredientes y cocina tapado en el horno precalentado a 160°C durante 2.5-3 horas hasta que la carne se deshaga."},{"appliance":"thermomix","time":100,"difficulty":"normal","prepSummary":"Dora la carne en la Thermomix, sofríe las verduras, incorpora el resto de ingredientes y programa 90-100 minutos a 100°C o Varoma, giro inverso y velocidad cuchara, hasta obtener una carne muy tierna."},{"appliance":"olla_express","time":60,"difficulty":"normal","prepSummary":"Sella las carrilleras y sofríe las verduras en la olla a presión. Añade los líquidos y el resto de ingredientes, cierra la olla y cocina durante 45-50 minutos desde que sube la válvula para una carne increíblemente tierna."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar y picar {{Cebolla}} en brunoise fina.","minutes":3,"kind":"prep"},{"text":"Pelar y picar {{Zanahoria}} en brunoise fina.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Pelar {{Boniato}} y cortarlo en dados grandes.","minutes":3,"kind":"prep"},{"text":"Salpimentar {{Carrilleras de cerdo}} por ambas caras con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela a fuego fuerte hasta que humee.","minutes":2,"kind":"activo"},{"text":"Dorar las carrilleras de cerdo en la cazuela hasta que estén selladas por todos los lados.","minutes":6,"kind":"activo"},{"text":"Retirar las carrilleras de cerdo de la cazuela y reservar en un plato.","minutes":1,"kind":"activo"},{"text":"Bajar el fuego a medio y sofreír la cebolla picada, la zanahoria picada y el ajo picado en la misma cazuela hasta que estén tiernos.","minutes":8,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y sofreír hasta que pierda el agua y se concentre.","minutes":3,"kind":"activo"},{"text":"Verter {{Vino tinto}} y subir el fuego hasta que se evapore el alcohol y el líquido reduzca a la mitad.","minutes":4,"kind":"activo"},{"text":"Devolver las carrilleras de cerdo reservadas a la cazuela.","minutes":1,"kind":"activo"},{"text":"Añadir {{Caldo de carne}} y {{Laurel}}.","minutes":1,"kind":"activo"},{"text":"Tapar la cazuela y cocer a fuego suave durante 60 min.","minutes":60,"kind":"pasivo"},{"text":"Añadir el boniato en dados a la cazuela y remover con suavidad para integrarlo.","minutes":2,"kind":"activo"},{"text":"Tapar de nuevo y cocer a fuego suave hasta que el boniato esté tierno y las carrilleras se deshagan.","minutes":28,"kind":"pasivo"},{"text":"Retirar el laurel de la cazuela.","minutes":1,"kind":"activo"},{"text":"Probar el estofado y rectificar de sal si fuera necesario.","minutes":1,"kind":"activo"},{"text":"Servir el estofado bien caliente en platos hondos con el boniato integrado en la salsa.","minutes":2,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_079', 'Pollo al limón estilo asiático', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 35, 'facil', 'all', 560, 34, 48, 26, 2, true, false, '{"huevo","soja","sesamo"}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Maicena","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de girasol","amount":300,"unit":"ml"},{"name":"Zumo de limón","amount":60,"unit":"ml"},{"name":"Azúcar","amount":40,"unit":"g"},{"name":"Salsa de soja","amount":15,"unit":"ml"},{"name":"Caldo de pollo","amount":80,"unit":"ml"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Sésamo tostado","amount":5,"unit":"g"}]'::jsonb, '{"Cortar pechuga de pollo en trozos de bocado de unos 3 cm.","Batir huevo en un bol y añadir los trozos de pollo.","Dejar marinar el pollo en el huevo batido durante 5 min.","Rallar jengibre fresco y ajo finamente. Reservar.","Escurrir el exceso de huevo de los trozos de pollo.","Rebozar los trozos de pollo en maicena hasta cubrirlos bien. Sacudir el exceso.","Calentar aceite de girasol en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","Freír el pollo rebozado por tandas en el aceite caliente durante 4 min, hasta que esté dorado y crujiente.","Escurrir el pollo frito sobre papel absorbente. Reservar.","Mezclar en un cazo zumo de limón, azúcar, salsa de soja y caldo de pollo.","Añadir el jengibre y el ajo rallados al cazo con la mezcla de limón.","Calentar la salsa a fuego medio, removiendo, hasta que espese ligeramente, unos 4 min.","Verter la salsa caliente sobre el pollo frito y remover para que quede bien impregnado.","Espolvorear sésamo tostado por encima y servir enseguida."}', 'Trozos de pollo rebozados y fritos, bañados en una salsa agridulce de limón al estilo asiático.', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Empaniza el pollo y rocíalo con un poco de aceite. Cocínalo en la airfryer a 190°C durante 15-20 minutos, volteando a mitad, hasta que esté dorado y crujiente. La salsa se prepara en un cazo aparte y se mezcla con el pollo al final para mantener la textura."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Hornea el pollo empanizado a 200°C durante 20-25 minutos, volteándolo a mitad de cocción, para que quede dorado. Un truco es usar una rejilla sobre una bandeja para que el aire circule y el pollo quede más crujiente. La salsa se elabora en un cazo aparte y se añade al servir."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pechuga de pollo}} en trozos de bocado de unos 3 cm.","minutes":5,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol y añadir los trozos de pollo.","minutes":1,"kind":"prep"},{"text":"Dejar marinar el pollo en el huevo batido durante 5 min.","minutes":5,"kind":"espera"},{"text":"Rallar {{Jengibre fresco}} y {{Ajo}} finamente. Reservar.","minutes":3,"kind":"paralelo","during":2},{"text":"Escurrir el exceso de huevo de los trozos de pollo.","minutes":1,"kind":"prep"},{"text":"Rebozar los trozos de pollo en {{Maicena}} hasta cubrirlos bien. Sacudir el exceso.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de girasol}} en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","minutes":2,"kind":"activo"},{"text":"Freír el pollo rebozado por tandas en el aceite caliente durante 4 min, hasta que esté dorado y crujiente.","minutes":4,"kind":"activo"},{"text":"Escurrir el pollo frito sobre papel absorbente. Reservar.","minutes":1,"kind":"prep"},{"text":"Mezclar en un cazo {{Zumo de limón}}, {{Azúcar}}, {{Salsa de soja}} y {{Caldo de pollo}}.","minutes":1,"kind":"prep"},{"text":"Añadir el jengibre y el ajo rallados al cazo con la mezcla de limón.","minutes":1,"kind":"prep"},{"text":"Calentar la salsa a fuego medio, removiendo, hasta que espese ligeramente, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Verter la salsa caliente sobre el pollo frito y remover para que quede bien impregnado.","minutes":1,"kind":"activo"},{"text":"Espolvorear {{Sésamo tostado}} por encima y servir enseguida.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_080', 'Alitas de pollo glaseadas al ajo y miel', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, 'horno', 45, 'facil', 'all', 470, 32, 22, 28, 2, true, true, '{"soja"}', '[{"name":"Alitas de pollo","amount":600,"unit":"g"},{"name":"Miel","amount":40,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Salsa de soja","amount":20,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Picar ajo muy fino.","Mezclar en un bol miel, el ajo picado, salsa de soja, aceite de oliva, pimentón dulce, sal y pimienta negra.","Añadir alitas de pollo al bol y remover hasta que queden impregnadas por todos lados.","Dejar marinar las alitas 15 min a temperatura ambiente.","Colocar las alitas en una bandeja de horno con papel vegetal, separadas entre sí.","Hornear 25 min, dando la vuelta a las alitas en el minuto 12.","Pincelar las alitas con el jugo recogido en la bandeja.","Subir la temperatura del horno a 220 °C.","Hornear 8 min más, hasta que las alitas estén doradas, brillantes y pegajosas.","Reposar las alitas 3 min fuera del horno antes de servir.","Servir las alitas directamente en la bandeja o en un plato, con el glaseado restante por encima."}', 'Alitas de pollo al horno glaseadas con ajo y miel hasta quedar pegajosas y doradas.', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Marinar las alitas y hornear a 190-200°C durante 40-45 minutos. Voltéalas a mitad de cocción y pincela con la salsa en los últimos 15 minutos para un glaseado uniforme y dorado."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Marinar las alitas. Cocinar en la airfryer a 190°C durante 25-30 minutos, volteando cada 8-10 minutos. Pincela con la salsa en las últimas pasadas para un glaseado crujiente y delicioso."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Picar {{Ajo}} muy fino.","minutes":2,"kind":"prep"},{"text":"Mezclar en un bol {{Miel}}, el ajo picado, {{Salsa de soja}}, {{Aceite de oliva}}, {{Pimentón dulce}}, {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":2,"kind":"prep"},{"text":"Añadir {{Alitas de pollo}} al bol y remover hasta que queden impregnadas por todos lados.","minutes":2,"kind":"activo"},{"text":"Dejar marinar las alitas 15 min a temperatura ambiente.","minutes":15,"kind":"espera"},{"text":"Colocar las alitas en una bandeja de horno con papel vegetal, separadas entre sí.","minutes":2,"kind":"prep"},{"text":"Hornear 25 min, dando la vuelta a las alitas en el minuto 12.","minutes":25,"kind":"pasivo"},{"text":"Pincelar las alitas con el jugo recogido en la bandeja.","minutes":1,"kind":"activo"},{"text":"Subir la temperatura del horno a 220 °C.","minutes":1,"kind":"activo"},{"text":"Hornear 8 min más, hasta que las alitas estén doradas, brillantes y pegajosas.","minutes":8,"kind":"pasivo"},{"text":"Reposar las alitas 3 min fuera del horno antes de servir.","minutes":3,"kind":"espera"},{"text":"Servir las alitas directamente en la bandeja o en un plato, con el glaseado restante por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_081', 'Ternera a la jardinera', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 80, 'normal', 'all', 405, 34, 26, 18, 2, true, true, '{"sulfitos"}', '[{"name":"Carne de ternera para guisar","amount":350,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Guisantes","amount":80,"unit":"g"},{"name":"Judía verde","amount":80,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":50,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Caldo de carne","amount":200,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Cortar carne de ternera para guisar en trozos de bocado.","Picar cebolla y ajo fino.","Cortar zanahoria, patata y judía verde en dados o trozos similares.","Salpimentar la carne de ternera con sal y pimienta negra.","Calentar aceite de oliva en una cazuela a fuego fuerte hasta que humee.","Dorar la carne en la cazuela por todos los lados hasta que esté sellada y dorada.","Retirar la carne y reservar en un plato.","Bajar el fuego a medio y sofreír la cebolla y el ajo picados en la misma cazuela hasta que estén blandos.","Añadir tomate triturado y sofreír hasta que pierda el agua y se concentre.","Verter vino blanco y remover hasta que se evapore el alcohol.","Devolver la carne a la cazuela y añadir caldo de carne. Tapar y cocer a fuego suave.","Añadir la zanahoria y la patata cortadas a la cazuela y cocer tapado a fuego suave.","Incorporar la judía verde y guisantes y cocer hasta que las verduras estén tiernas.","Probar y rectificar de sal al gusto.","Servir bien caliente en plato hondo o fuente."}', 'Guiso de ternera con zanahoria, judía verde, guisantes y patata en una salsa ligera de tomate.', '[{"appliance":"horno","time":85,"difficulty":"normal","prepSummary":"Se doran la carne y las verduras en una olla apta para horno, se añade el resto de ingredientes y se cocina tapado en el horno a 170-180°C durante 60-70 minutos, logrando una cocción uniforme y una carne muy tierna."},{"appliance":"thermomix","time":80,"difficulty":"normal","prepSummary":"Pica y sofríe las verduras, dora la carne (en dos tandas si es necesario) y luego guisa todos los ingredientes a 95-100°C, velocidad cuchara y giro inverso, durante 60-70 minutos hasta que la carne esté tierna y la salsa ligada."},{"appliance":"olla_express","time":55,"difficulty":"normal","prepSummary":"Dora la carne y sofríe las verduras en la olla, añade el resto de ingredientes y cocina a presión durante 25-30 minutos desde que sube la válvula, logrando una carne muy tierna y un guiso con todo el sabor en mucho menos tiempo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Carne de ternera para guisar}} en trozos de bocado.","minutes":3,"kind":"prep"},{"text":"Picar {{Cebolla}} y {{Ajo}} fino.","minutes":3,"kind":"prep"},{"text":"Cortar {{Zanahoria}}, {{Patata}} y {{Judía verde}} en dados o trozos similares.","minutes":4,"kind":"prep"},{"text":"Salpimentar la carne de ternera con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela a fuego fuerte hasta que humee.","minutes":1,"kind":"activo"},{"text":"Dorar la carne en la cazuela por todos los lados hasta que esté sellada y dorada.","minutes":5,"kind":"activo"},{"text":"Retirar la carne y reservar en un plato.","minutes":1,"kind":"activo"},{"text":"Bajar el fuego a medio y sofreír la cebolla y el ajo picados en la misma cazuela hasta que estén blandos.","minutes":6,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y sofreír hasta que pierda el agua y se concentre.","minutes":3,"kind":"activo"},{"text":"Verter {{Vino blanco}} y remover hasta que se evapore el alcohol.","minutes":2,"kind":"activo"},{"text":"Devolver la carne a la cazuela y añadir {{Caldo de carne}}. Tapar y cocer a fuego suave.","minutes":45,"kind":"pasivo"},{"text":"Añadir la zanahoria y la patata cortadas a la cazuela y cocer tapado a fuego suave.","minutes":15,"kind":"pasivo"},{"text":"Incorporar la judía verde y {{Guisantes}} y cocer hasta que las verduras estén tiernas.","minutes":12,"kind":"pasivo"},{"text":"Probar y rectificar de sal al gusto.","minutes":1,"kind":"activo"},{"text":"Servir bien caliente en plato hondo o fuente.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_082', 'Pincho moruno con patatas fritas y alioli', 'carnes', 'cerdo', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'facil', 'all', 685, 34, 42, 42, 2, true, false, '{"huevo"}', '[{"name":"Carne de cerdo en dados (aguja o secreto)","amount":400,"unit":"g"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Ajo en polvo","amount":3,"unit":"g"},{"name":"Cúrcuma","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Aceite de oliva (para freír)","amount":400,"unit":"ml"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Sal","amount":6,"unit":"g"}]'::jsonb, '{"Mezclar pimentón dulce, comino molido, ajo en polvo y cúrcuma en un bol hasta integrar.","Añadir aceite de oliva, zumo de limón y sal al bol y mezclar hasta obtener una pasta homogénea.","Incorporar carne de cerdo en dados (aguja o secreto) al bol y remover hasta que todos los dados queden bien cubiertos.","Tapar el bol y refrigerar hasta que la carne haya marinado al menos 30 min.","Pelar patata y cortar en bastones uniformes de unos 1 cm de grosor.","Secar los bastones de patata con papel de cocina para eliminar el exceso de humedad.","Machacar o picar fino ajo hasta obtener una pasta muy fina.","Colocar huevo y el ajo picado en el vaso de la batidora. Añadir una pizca de sal.","Triturar con la batidora a velocidad baja, añadiendo aceite de oliva en hilo muy fino y constante.","Continuar añadiendo el aceite de oliva (para freír) en hilo hasta que el alioli emulsione y espese. Reservar en frío.","Calentar el aceite de oliva (para freír) restante en una sartén profunda a fuego fuerte hasta que alcance 180 °C.","Freír los bastones de patata en tandas durante 8 min, hasta que estén dorados y crujientes.","Escurrir las patatas fritas sobre papel de cocina y salar ligeramente. Reservar.","Ensartar la carne marinada en brochetas, distribuyendo los dados de forma uniforme.","Calentar plancha a fuego fuerte hasta que esté muy caliente.","Dorar los pinchos 3 min por cada lado, hasta que estén tostados por fuera y jugosos por dentro.","Servir los pinchos junto a las patatas fritas y el alioli aparte."}', 'Brochetas de cerdo marinadas con especias moriscas, servidas con patatas fritas y alioli casero.', '[{"appliance":"airfryer","time":50,"difficulty":"facil","prepSummary":"Los pinchos se cocinan a 190°C durante 18-20 minutos, volteándolos a mitad para un dorado uniforme. Las patatas se hacen a 180°C durante 20-25 minutos, rociadas con un poco de aceite y removiendo varias veces."},{"appliance":"horno","time":65,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Cocina los pinchos con función grill durante 20-25 minutos, dándoles la vuelta. Las patatas, cortadas en bastones y con poco aceite, se asan a 200°C durante 30-40 minutos hasta que estén tiernas y doradas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Mezclar {{Pimentón dulce}}, {{Comino molido}}, {{Ajo en polvo}} y {{Cúrcuma}} en un bol hasta integrar.","minutes":2,"kind":"prep"},{"text":"Añadir {{Aceite de oliva}}, {{Zumo de limón}} y {{Sal|gusto}} al bol y mezclar hasta obtener una pasta homogénea.","minutes":1,"kind":"prep"},{"text":"Incorporar {{Carne de cerdo en dados (aguja o secreto)}} al bol y remover hasta que todos los dados queden bien cubiertos.","minutes":2,"kind":"prep"},{"text":"Tapar el bol y refrigerar hasta que la carne haya marinado al menos 30 min.","minutes":30,"kind":"espera"},{"text":"Pelar {{Patata}} y cortar en bastones uniformes de unos 1 cm de grosor.","minutes":5,"kind":"paralelo","during":3},{"text":"Secar los bastones de patata con papel de cocina para eliminar el exceso de humedad.","minutes":2,"kind":"paralelo","during":3},{"text":"Machacar o picar fino {{Ajo}} hasta obtener una pasta muy fina.","minutes":2,"kind":"paralelo","during":3},{"text":"Colocar {{Huevo}} y el ajo picado en el vaso de la batidora. Añadir una pizca de sal.","minutes":1,"kind":"paralelo","part":"salsa","during":3},{"text":"Triturar con la batidora a velocidad baja, añadiendo {{Aceite de oliva|chorrito}} en hilo muy fino y constante.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Continuar añadiendo el aceite de oliva (para freír) en hilo hasta que el alioli emulsione y espese. Reservar en frío.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Calentar el aceite de oliva (para freír) restante en una sartén profunda a fuego fuerte hasta que alcance 180 °C.","minutes":4,"kind":"activo","part":"guarnicion"},{"text":"Freír los bastones de patata en tandas durante 8 min, hasta que estén dorados y crujientes.","minutes":8,"kind":"pasivo","part":"guarnicion"},{"text":"Escurrir las patatas fritas sobre papel de cocina y salar ligeramente. Reservar.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Ensartar la carne marinada en brochetas, distribuyendo los dados de forma uniforme.","minutes":3,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté muy caliente.","minutes":2,"kind":"activo","part":"principal"},{"text":"Dorar los pinchos 3 min por cada lado, hasta que estén tostados por fuera y jugosos por dentro.","minutes":6,"kind":"activo","part":"principal"},{"text":"Servir los pinchos junto a las patatas fritas y el alioli aparte.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_083', 'Chuletillas de cordero a la brasa con romero', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 420, 32, 1, 32, 2, true, true, '{}', '[{"name":"Chuletillas de cordero","amount":500,"unit":"g"},{"name":"Romero fresco","amount":5,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Sacar chuletillas de cordero de la nevera y dejar atemperar a temperatura ambiente.","Picar romero fresco fino y reservar.","Machacar ajo hasta obtener una pasta.","Mezclar el ajo machacado con aceite de oliva y el romero picado en un bol.","Untar las chuletillas con la mezcla de ajo y romero por ambos lados.","Añadir sal y pimienta negra por ambos lados de las chuletillas.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Colocar las chuletillas sobre la plancha y cocinar hasta que se doren, unos 2-3 min por cada lado.","Retirar las chuletillas de la plancha y dejar reposar para que los jugos se asienten.","Servir las chuletillas bien calientes con un poco de romero fresco por encima."}', 'Chuletillas de cordero a la brasa aromatizadas con ajo y romero fresco.', '[{"appliance":"airfryer","time":16,"difficulty":"facil","prepSummary":"Prepara las chuletillas con el romero, ajo, aceite, sal y pimienta. Precalienta la airfryer a 200°C y cocina las chuletillas durante 16 minutos, dándoles la vuelta a mitad para un dorado uniforme y jugoso."},{"appliance":"horno","time":22,"difficulty":"facil","prepSummary":"Marina las chuletillas con los ingredientes. Precalienta el horno a 220°C (con función grill si es posible) y hornea durante 22 minutos, dándoles la vuelta a mitad para un buen sellado y que queden tiernas por dentro."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Sacar {{Chuletillas de cordero}} de la nevera y dejar atemperar a temperatura ambiente.","minutes":15,"kind":"espera"},{"text":"Picar {{Romero fresco}} fino y reservar.","minutes":2,"kind":"prep"},{"text":"Machacar {{Ajo}} hasta obtener una pasta.","minutes":1,"kind":"prep"},{"text":"Mezclar el ajo machacado con {{Aceite de oliva|chorrito}} y el romero picado en un bol.","minutes":1,"kind":"prep"},{"text":"Untar las chuletillas con la mezcla de ajo y romero por ambos lados.","minutes":2,"kind":"prep"},{"text":"Añadir {{Sal|gusto}} y {{Pimienta negra|pizca}} por ambos lados de las chuletillas.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Colocar las chuletillas sobre la plancha y cocinar hasta que se doren, unos 2-3 min por cada lado.","minutes":5,"kind":"activo"},{"text":"Retirar las chuletillas de la plancha y dejar reposar para que los jugos se asienten.","minutes":2,"kind":"espera"},{"text":"Servir las chuletillas bien calientes con un poco de romero fresco por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_084', 'Cordero asado con patatas panadera', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 100, 'normal', 'all', 560, 42, 26, 32, 2, true, true, '{}', '[{"name":"Paletilla de cordero","amount":700,"unit":"g"},{"name":"Patata","amount":350,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Manteca de cerdo","amount":10,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Pelar patata y cortarlas en rodajas finas de unos 3 mm.","Pelar cebolla y cortarla en juliana fina.","Pelar ajo y machacarlo hasta formar una pasta.","Extender las patatas y la cebolla en una fuente de horno formando una cama uniforme.","Salpimentar las patatas y la cebolla con sal y pimienta negra.","Regar las patatas y la cebolla con aceite de oliva.","Untar paletilla de cordero con manteca de cerdo y el ajo machacado por toda la superficie.","Salpimentar la paletilla por ambas caras.","Colocar la paletilla sobre la cama de patatas y cebolla y añadir laurel.","Verter vino blanco y 50 ml de agua en el fondo de la fuente.","Hornear la fuente en el centro del horno a 180 °C durante 85 min, regando con los jugos cada 25 min.","Comprobar que la piel está dorada y crujiente y la carne muy tierna antes de retirar del horno.","Retirar la fuente del horno y dejar reposar la paletilla 10 min sin tapar.","Trinchar la paletilla y servir con las patatas panadera bien empapadas en el jugo de la fuente."}', 'Pierna de cordero asada al horno sobre una cama de patatas panadera empapadas en su jugo.', '[{"appliance":"horno","time":100,"difficulty":"normal","prepSummary":"Precalienta el horno a 180°C. Sazona la paletilla y colócala sobre una cama de patatas y cebolla laminadas con ajo y laurel. Riega con vino blanco y aceite, y asa durante 100 minutos, dando la vuelta a la carne a mitad de cocción para un dorado uniforme."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 180 °C.","minutes":10,"kind":"pasivo"},{"text":"Pelar {{Patata}} y cortarlas en rodajas finas de unos 3 mm.","minutes":5,"kind":"paralelo","during":0},{"text":"Pelar {{Cebolla}} y cortarla en juliana fina.","minutes":3,"kind":"paralelo","during":0},{"text":"Pelar {{Ajo}} y machacarlo hasta formar una pasta.","minutes":2,"kind":"paralelo","during":0},{"text":"Extender las patatas y la cebolla en una fuente de horno formando una cama uniforme.","minutes":2,"kind":"prep"},{"text":"Salpimentar las patatas y la cebolla con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep"},{"text":"Regar las patatas y la cebolla con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"prep"},{"text":"Untar {{Paletilla de cordero}} con {{Manteca de cerdo}} y el ajo machacado por toda la superficie.","minutes":3,"kind":"prep"},{"text":"Salpimentar la paletilla por ambas caras.","minutes":1,"kind":"prep"},{"text":"Colocar la paletilla sobre la cama de patatas y cebolla y añadir {{Laurel}}.","minutes":1,"kind":"prep"},{"text":"Verter {{Vino blanco}} y 50 ml de agua en el fondo de la fuente.","minutes":1,"kind":"prep"},{"text":"Hornear la fuente en el centro del horno a 180 °C durante 85 min, regando con los jugos cada 25 min.","minutes":85,"kind":"pasivo"},{"text":"Comprobar que la piel está dorada y crujiente y la carne muy tierna antes de retirar del horno.","minutes":2,"kind":"activo"},{"text":"Retirar la fuente del horno y dejar reposar la paletilla 10 min sin tapar.","minutes":10,"kind":"espera"},{"text":"Trinchar la paletilla y servir con las patatas panadera bien empapadas en el jugo de la fuente.","minutes":3,"kind":"emplatado"}]'::jsonb, true)
