  estrella = excluded.estrella;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('carnes_085', 'Cinta de lomo rellena de ciruelas y piñones', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 75, 'normal', 'all', 445, 38, 14, 26, 2, true, true, '{"frutos_secos","sulfitos"}', '[{"name":"Cinta de lomo de cerdo abierta en libro","amount":500,"unit":"g"},{"name":"Ciruelas pasas sin hueso","amount":50,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Bacon en lonchas","amount":50,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Caldo de carne","amount":75,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Extender cinta de lomo de cerdo abierta en libro sobre la mesa y salpimentar por dentro con sal y pimienta negra.","Repartir ciruelas pasas sin hueso y piñones de forma uniforme sobre la carne.","Enrollar la carne sobre sí misma apretando bien para que el relleno quede compacto en el interior.","Cubrir el rollo con bacon en lonchas, solapando cada loncha con la anterior.","Atar el rollo con hilo de cocina dando vueltas cada 2 cm para que mantenga la forma durante el horneado.","Calentar aceite de oliva en una sartén a fuego fuerte hasta que humee ligeramente.","Dorar el rollo en la sartén por todos los lados hasta que el bacon esté dorado y crujiente.","Colocar el rollo en una fuente de horno y añadir vino blanco y caldo de carne en la base.","Hornear a 180 °C durante 40 min, regando el rollo con los jugos de la fuente cada 15 min.","Retirar la fuente del horno y dejar reposar el rollo 10 min sin cortar para que los jugos se redistribuyan.","Retirar el hilo de cocina con unas tijeras con cuidado de no romper el rollo.","Cortar el rollo en rodajas de unos 2 cm con un cuchillo bien afilado.","Servir las rodajas regadas con la salsa de la fuente."}', 'Cinta de lomo enrollada y rellena de ciruelas pasas y piñones, asada al horno.', '[{"appliance":"horno","time":75,"difficulty":"normal","prepSummary":"Rellena y ata el lomo, séllalo en una sartén y luego ásalo en el horno a 180°C, regándolo con el vino y el caldo para una carne jugosa y una salsa deliciosa."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Sella el lomo relleno y luego cocínalo en la airfryer a 170°C durante unos 50-60 minutos, girándolo a mitad y añadiendo un poco de líquido para evitar que se seque."},{"appliance":"olla_express","time":45,"difficulty":"normal","prepSummary":"Dora el lomo relleno en la olla a presión, luego añade el vino y el caldo y cocina a fuego medio durante 30-35 minutos desde que sube la válvula para una carne muy tierna y una salsa concentrada."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 180 °C.","minutes":10,"kind":"pasivo"},{"text":"Extender {{Cinta de lomo de cerdo abierta en libro}} sobre la mesa y salpimentar por dentro con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":2,"kind":"prep"},{"text":"Repartir {{Ciruelas pasas sin hueso}} y {{Piñones}} de forma uniforme sobre la carne.","minutes":1,"kind":"prep"},{"text":"Enrollar la carne sobre sí misma apretando bien para que el relleno quede compacto en el interior.","minutes":2,"kind":"prep"},{"text":"Cubrir el rollo con {{Bacon en lonchas}}, solapando cada loncha con la anterior.","minutes":2,"kind":"prep"},{"text":"Atar el rollo con hilo de cocina dando vueltas cada 2 cm para que mantenga la forma durante el horneado.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una sartén a fuego fuerte hasta que humee ligeramente.","minutes":1,"kind":"activo"},{"text":"Dorar el rollo en la sartén por todos los lados hasta que el bacon esté dorado y crujiente.","minutes":5,"kind":"activo"},{"text":"Colocar el rollo en una fuente de horno y añadir {{Vino blanco}} y {{Caldo de carne}} en la base.","minutes":1,"kind":"prep"},{"text":"Hornear a 180 °C durante 40 min, regando el rollo con los jugos de la fuente cada 15 min.","minutes":40,"kind":"pasivo"},{"text":"Retirar la fuente del horno y dejar reposar el rollo 10 min sin cortar para que los jugos se redistribuyan.","minutes":10,"kind":"espera"},{"text":"Retirar el hilo de cocina con unas tijeras con cuidado de no romper el rollo.","minutes":1,"kind":"prep"},{"text":"Cortar el rollo en rodajas de unos 2 cm con un cuchillo bien afilado.","minutes":2,"kind":"prep"},{"text":"Servir las rodajas regadas con la salsa de la fuente.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_086', 'Pollo relleno de jamón y queso', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 45, 'normal', 'all', 620, 46, 32, 34, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Pechuga de pollo","amount":400,"unit":"g"},{"name":"Jamón cocido en lonchas","amount":80,"unit":"g"},{"name":"Queso para fundir en lonchas","amount":80,"unit":"g"},{"name":"Harina de trigo","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":300,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Abrir pechuga de pollo en forma de libro con un cuchillo, sin llegar a cortar del todo.","Salpimentar el interior de cada pechuga con sal y pimienta negra.","Colocar jamón cocido en lonchas sobre el interior de cada pechuga.","Colocar queso para fundir en lonchas sobre el jamón.","Cerrar cada pechuga sobre el relleno y sujetar con un palillo si es necesario.","Batir huevo en un bol hasta que esté homogéneo.","Disponer harina de trigo y pan rallado en platos separados.","Pasar cada pechuga rellena por la harina de trigo, cubriéndola bien por todos los lados.","Pasar a continuación cada pechuga por el huevo batido, asegurando que quede bien empapada.","Rebozar cada pechuga con el pan rallado, presionando ligeramente para que se adhiera.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Freír las pechugas rellenas 5 min por el primer lado, hasta que estén doradas.","Dar la vuelta a las pechugas y freír 5 min por el otro lado, hasta que estén doradas y el queso fundido.","Escurrir las pechugas sobre papel absorbente y retirar los palillos.","Cortar cada pechuga por la mitad y servir para mostrar el relleno fundido."}', 'Pechuga de pollo rellena de jamón y queso, empanada y frita hasta que el queso funde por dentro.', '[{"appliance":"airfryer","time":40,"difficulty":"normal","prepSummary":"Prepara el pollo relleno y empanado. Cocina en la airfryer a 190°C durante 20-25 minutos, volteando a mitad, hasta que esté dorado y crujiente."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Empana el pollo relleno y hornéalo a 200°C durante 30-35 minutos, girando a mitad, hasta que esté bien dorado y el queso fundido."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], true, '[{"text":"Abrir {{Pechuga de pollo}} en forma de libro con un cuchillo, sin llegar a cortar del todo.","minutes":3,"kind":"prep"},{"text":"Salpimentar el interior de cada pechuga con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep"},{"text":"Colocar {{Jamón cocido en lonchas}} sobre el interior de cada pechuga.","minutes":1,"kind":"prep"},{"text":"Colocar {{Queso para fundir en lonchas}} sobre el jamón.","minutes":1,"kind":"prep"},{"text":"Cerrar cada pechuga sobre el relleno y sujetar con un palillo si es necesario.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol hasta que esté homogéneo.","minutes":1,"kind":"prep"},{"text":"Disponer {{Harina de trigo}} y {{Pan rallado}} en platos separados.","minutes":1,"kind":"prep"},{"text":"Pasar cada pechuga rellena por la harina de trigo, cubriéndola bien por todos los lados.","minutes":2,"kind":"prep"},{"text":"Pasar a continuación cada pechuga por el huevo batido, asegurando que quede bien empapada.","minutes":1,"kind":"prep"},{"text":"Rebozar cada pechuga con el pan rallado, presionando ligeramente para que se adhiera.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} a fuego medio hasta que esté caliente.","minutes":3,"kind":"activo"},{"text":"Freír las pechugas rellenas 5 min por el primer lado, hasta que estén doradas.","minutes":5,"kind":"activo"},{"text":"Dar la vuelta a las pechugas y freír 5 min por el otro lado, hasta que estén doradas y el queso fundido.","minutes":5,"kind":"activo"},{"text":"Escurrir las pechugas sobre papel absorbente y retirar los palillos.","minutes":1,"kind":"activo"},{"text":"Cortar cada pechuga por la mitad y servir para mostrar el relleno fundido.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_087', 'Filetes empanados con patatas fritas', 'carnes', 'cerdo', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 660, 36, 52, 34, 2, true, false, '{"gluten","huevo"}', '[{"name":"Filetes de lomo de cerdo","amount":350,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Pan rallado","amount":100,"unit":"g"},{"name":"Harina de trigo","amount":30,"unit":"g"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Aceite de oliva","amount":400,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en bastones de unos 1 cm de grosor.","Secar bien los bastones de patata con papel absorbente para que queden crujientes al freír.","Salpimentar filetes de lomo de cerdo por ambos lados con sal y pimienta negra.","Batir huevo en un bol hondo hasta que la yema y la clara estén bien integradas.","Extender harina de trigo en un plato llano y pan rallado en otro plato llano.","Pasar cada filete por la harina, sacudir el exceso, sumergir en el huevo batido y cubrir con el pan rallado.","Presionar bien el pan rallado sobre cada filete para que quede una capa uniforme y compacta.","Calentar aceite de oliva en sartén grande a fuego fuerte hasta que alcance unos 180 °C.","Freír los filetes empanados 2 min por cada lado, hasta que estén bien dorados.","Retirar los filetes y escurrir sobre papel absorbente. Reservar en un lugar cálido.","Freír los bastones de patata en el mismo aceite a fuego fuerte, hasta que estén dorados y crujientes.","Retirar las patatas fritas y escurrir sobre papel absorbente. Salar al gusto.","Servir los filetes empanados calientes junto con las patatas fritas en el mismo plato."}', 'Filetes de lomo empanados y fritos, servidos con patatas fritas caseras.', '[{"appliance":"airfryer","time":45,"difficulty":"facil","prepSummary":"Prepara los filetes empanados y las patatas cortadas en bastones. Cocina las patatas en la airfryer a 190°C durante 20-25 minutos, agitándolas, y luego los filetes a 190°C por 12-15 minutos, dándoles la vuelta a mitad, para un resultado crujiente y menos graso."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Prepara los filetes empanados y las patatas cortadas en bastones. Hornea ambos en una bandeja con un poco de aceite a 200°C durante 25-30 minutos, volteando a mitad, hasta que estén dorados y crujientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en bastones de unos 1 cm de grosor.","minutes":5,"kind":"prep","part":"guarnicion"},{"text":"Secar bien los bastones de patata con papel absorbente para que queden crujientes al freír.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Salpimentar {{Filetes de lomo de cerdo}} por ambos lados con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep","part":"principal"},{"text":"Batir {{Huevo}} en un bol hondo hasta que la yema y la clara estén bien integradas.","minutes":1,"kind":"prep","part":"principal"},{"text":"Extender {{Harina de trigo}} en un plato llano y {{Pan rallado}} en otro plato llano.","minutes":1,"kind":"prep","part":"principal"},{"text":"Pasar cada filete por la harina, sacudir el exceso, sumergir en el huevo batido y cubrir con el pan rallado.","minutes":3,"kind":"prep","part":"principal"},{"text":"Presionar bien el pan rallado sobre cada filete para que quede una capa uniforme y compacta.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} grande a fuego fuerte hasta que alcance unos 180 °C.","minutes":3,"kind":"activo","part":"principal"},{"text":"Freír los filetes empanados 2 min por cada lado, hasta que estén bien dorados.","minutes":4,"kind":"activo","part":"principal"},{"text":"Retirar los filetes y escurrir sobre papel absorbente. Reservar en un lugar cálido.","minutes":1,"kind":"activo","part":"principal"},{"text":"Freír los bastones de patata en el mismo aceite a fuego fuerte, hasta que estén dorados y crujientes.","minutes":9,"kind":"activo","part":"guarnicion"},{"text":"Retirar las patatas fritas y escurrir sobre papel absorbente. Salar al gusto.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Servir los filetes empanados calientes junto con las patatas fritas en el mismo plato.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_088', 'Carne guisada con champiñones y vino blanco', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 70, 'facil', 'all', 440, 32, 14, 28, 2, true, true, '{"gluten","lactosa","sulfitos"}', '[{"name":"Carne de ternera para guisar","amount":400,"unit":"g"},{"name":"Champiñones","amount":250,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Harina de trigo","amount":15,"unit":"g"},{"name":"Vino blanco","amount":150,"unit":"ml"},{"name":"Caldo de carne","amount":200,"unit":"ml"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Cortar carne de ternera para guisar en trozos de bocado uniformes.","Salpimentar la carne con sal y pimienta negra por todos los lados.","Enharinar la carne con harina de trigo, sacudiendo el exceso.","Picar cebolla en brunoise fina.","Picar ajo fino.","Laminar champiñones en láminas de unos 4 mm.","Calentar aceite de oliva en una cazuela a fuego fuerte hasta que humee ligeramente.","Dorar la carne por todos los lados hasta que esté sellada y tome color dorado.","Retirar la carne de la cazuela y reservar en un plato.","Sofreír la cebolla picada y el ajo picado en la misma cazuela a fuego medio hasta que estén blandos.","Añadir los champiñones laminados y saltear a fuego medio hasta que suelten su agua y se doren.","Verter vino blanco y remover hasta que el alcohol se evapore y el líquido reduzca a la mitad.","Devolver la carne reservada a la cazuela.","Añadir caldo de carne, tapar y cocer a fuego suave hasta que la carne esté muy tierna.","Añadir nata para cocinar y remover hasta que la salsa espese ligeramente.","Probar y rectificar de sal antes de retirar del fuego.","Servir bien caliente en plato hondo o cazuela individual."}', 'Carne de ternera guisada con champiñones en una salsa cremosa de vino blanco.', '[{"appliance":"horno","time":95,"difficulty":"normal","prepSummary":"Se doran la carne y las verduras en una olla apta para horno, se añaden el resto de ingredientes y se cocina tapado en el horno precalentado a 160°C durante unos 75-80 minutos, hasta que la carne esté muy tierna. Permite una cocción uniforme y un guiso con sabores bien integrados"},{"appliance":"thermomix","time":70,"difficulty":"facil","prepSummary":"Se sofríen las verduras y se dora ligeramente la carne en el vaso. Luego se añaden los líquidos y el resto de ingredientes y se cocina a 100°C, giro inverso, velocidad cuchara, durante unos 55-60 minutos, logrando una carne tierna y una salsa perfectamente ligada."},{"appliance":"olla_express","time":50,"difficulty":"facil","prepSummary":"Se doran la carne y las verduras en la olla. Se incorporan el resto de ingredientes, se cierra la olla y se cocina a presión durante unos 30-35 minutos desde que sube la válvula. La carne quedará extremadamente tierna en mucho menos tiempo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Carne de ternera para guisar}} en trozos de bocado uniformes.","minutes":3,"kind":"prep"},{"text":"Salpimentar la carne con {{Sal|gusto}} y {{Pimienta negra|pizca}} por todos los lados.","minutes":1,"kind":"prep"},{"text":"Enharinar la carne con {{Harina de trigo}}, sacudiendo el exceso.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolla}} en brunoise fina.","minutes":3,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Laminar {{Champiñones}} en láminas de unos 4 mm.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una cazuela a fuego fuerte hasta que humee ligeramente.","minutes":1,"kind":"activo"},{"text":"Dorar la carne por todos los lados hasta que esté sellada y tome color dorado.","minutes":6,"kind":"activo"},{"text":"Retirar la carne de la cazuela y reservar en un plato.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada y el ajo picado en la misma cazuela a fuego medio hasta que estén blandos.","minutes":6,"kind":"activo"},{"text":"Añadir los champiñones laminados y saltear a fuego medio hasta que suelten su agua y se doren.","minutes":5,"kind":"activo"},{"text":"Verter {{Vino blanco}} y remover hasta que el alcohol se evapore y el líquido reduzca a la mitad.","minutes":3,"kind":"activo"},{"text":"Devolver la carne reservada a la cazuela.","minutes":1,"kind":"activo"},{"text":"Añadir {{Caldo de carne}}, tapar y cocer a fuego suave hasta que la carne esté muy tierna.","minutes":40,"kind":"pasivo"},{"text":"Añadir {{Nata para cocinar}} y remover hasta que la salsa espese ligeramente.","minutes":5,"kind":"activo"},{"text":"Probar y rectificar de sal antes de retirar del fuego.","minutes":1,"kind":"activo"},{"text":"Servir bien caliente en plato hondo o cazuela individual.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_089', 'Solomillo con salsa de queso de cabra y miel', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'normal', 'all', 515, 36, 16, 34, 2, false, true, '{"lactosa"}', '[{"name":"Solomillo de ternera","amount":350,"unit":"g"},{"name":"Queso de cabra en rulo","amount":100,"unit":"g"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Miel","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Sacar solomillo de ternera de la nevera para que atempere.","Salpimentar el solomillo por ambas caras con sal y pimienta negra.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee.","Marcar el solomillo 2 min por cada cara hasta que esté dorado por fuera y rosado por dentro.","Retirar el solomillo de la sartén y reservar en un plato.","Bajar el fuego a medio y añadir nata para cocinar a la misma sartén, removiendo para recoger los jugos.","Cortar queso de cabra en rulo en trozos pequeños.","Añadir el queso de cabra troceado a la sartén y remover hasta que se funda por completo.","Incorporar miel y remover hasta integrar.","Cocer la salsa a fuego medio hasta que esté cremosa y homogénea.","Devolver el solomillo a la sartén y napar con la salsa.","Calentar 1 min a fuego suave hasta que el solomillo esté bien caliente.","Servir el solomillo con la salsa de queso de cabra y miel por encima."}', 'Solomillo de ternera con una salsa cremosa de queso de cabra y miel.', '[{"appliance":"airfryer","time":25,"difficulty":"normal","prepSummary":"Precalienta la airfryer a 200°C y cocina el solomillo unos 15-18 minutos, volteándolo a mitad para un dorado perfecto. La salsa se prepara aparte en un cazo, calentando suavemente el queso de cabra, nata y miel hasta obtener una crema homogénea."},{"appliance":"horno","time":30,"difficulty":"normal","prepSummary":"Sella el solomillo en una sartén apta para horno a fuego fuerte y termina de cocinarlo en el horno precalentado a 190°C durante 10-15 minutos. Mientras, prepara la salsa en un cazo a fuego suave con el queso de cabra, nata y miel hasta que espese ligeramente."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Sacar {{Solomillo de ternera}} de la nevera para que atempere.","minutes":15,"kind":"espera"},{"text":"Salpimentar el solomillo por ambas caras con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte hasta que humee.","minutes":1,"kind":"activo"},{"text":"Marcar el solomillo 2 min por cada cara hasta que esté dorado por fuera y rosado por dentro.","minutes":4,"kind":"activo"},{"text":"Retirar el solomillo de la sartén y reservar en un plato.","minutes":1,"kind":"activo"},{"text":"Bajar el fuego a medio y añadir {{Nata para cocinar}} a la misma sartén, removiendo para recoger los jugos.","minutes":1,"kind":"activo"},{"text":"Cortar {{Queso de cabra en rulo}} en trozos pequeños.","minutes":1,"kind":"paralelo","during":5},{"text":"Añadir el queso de cabra troceado a la sartén y remover hasta que se funda por completo.","minutes":2,"kind":"activo"},{"text":"Incorporar {{Miel}} y remover hasta integrar.","minutes":1,"kind":"activo"},{"text":"Cocer la salsa a fuego medio hasta que esté cremosa y homogénea.","minutes":2,"kind":"pasivo"},{"text":"Devolver el solomillo a la sartén y napar con la salsa.","minutes":1,"kind":"activo"},{"text":"Calentar 1 min a fuego suave hasta que el solomillo esté bien caliente.","minutes":1,"kind":"pasivo"},{"text":"Servir el solomillo con la salsa de queso de cabra y miel por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_090', 'Escalopines al cava', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 430, 32, 12, 28, 2, true, true, '{"gluten","lactosa","sulfitos"}', '[{"name":"Escalopines de ternera","amount":350,"unit":"g"},{"name":"Harina de trigo","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Champiñones","amount":150,"unit":"g"},{"name":"Cava","amount":150,"unit":"ml"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Laminar champiñones en láminas de unos 3 mm.","Salpimentar escalopines de ternera por ambas caras con sal y pimienta negra.","Enharinar los escalopines con harina de trigo, sacudiendo el exceso.","Calentar aceite de oliva y la mitad de mantequilla en sartén a fuego fuerte.","Dorar los escalopines 1 min por cada cara hasta que estén dorados. Reservar en un plato.","Añadir el resto de la mantequilla a la misma sartén a fuego medio.","Saltear los champiñones laminados hasta que estén dorados y hayan soltado su agua.","Verter cava y llevar a ebullición a fuego fuerte hasta que reduzca a la mitad.","Añadir nata para cocinar y cocer a fuego medio hasta que la salsa espese ligeramente.","Incorporar los escalopines reservados a la sartén y calentar a fuego suave, napando con la salsa.","Servir enseguida, bien caliente."}', 'Escalopines de ternera con champiñones en una salsa ligera de cava.', '[{"appliance":"thermomix","time":30,"difficulty":"normal","prepSummary":"Dora los escalopines en la Thermomix (modo alta temperatura), retira y reserva. Luego, sofríe los champiñones, añade el cava y la nata, e incorpora la carne para que la salsa espese y se integren los sabores."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Laminar {{Champiñones}} en láminas de unos 3 mm.","minutes":3,"kind":"prep"},{"text":"Salpimentar {{Escalopines de ternera}} por ambas caras con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep"},{"text":"Enharinar los escalopines con {{Harina de trigo}}, sacudiendo el exceso.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} y la mitad de {{Mantequilla}} en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Dorar los escalopines 1 min por cada cara hasta que estén dorados. Reservar en un plato.","minutes":2,"kind":"activo"},{"text":"Añadir el resto de la mantequilla a la misma sartén a fuego medio.","minutes":1,"kind":"activo"},{"text":"Saltear los champiñones laminados hasta que estén dorados y hayan soltado su agua.","minutes":4,"kind":"activo"},{"text":"Verter {{Cava}} y llevar a ebullición a fuego fuerte hasta que reduzca a la mitad.","minutes":3,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}} y cocer a fuego medio hasta que la salsa espese ligeramente.","minutes":3,"kind":"activo"},{"text":"Incorporar los escalopines reservados a la sartén y calentar a fuego suave, napando con la salsa.","minutes":2,"kind":"activo"},{"text":"Servir enseguida, bien caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_091', 'Costillas confitadas con miel y mostaza', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 150, 'normal', 'all', 625, 40, 12, 46, 2, true, true, '{"mostaza"}', '[{"name":"Costillar de cerdo","amount":600,"unit":"g"},{"name":"Aceite de oliva suave","amount":300,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Tomillo","amount":2,"unit":"g"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Mostaza de Dijon","amount":15,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Salpimentar costillar de cerdo con sal y pimienta negra por ambos lados.","Colocar el costillar en una cazuela ancha o fuente honda de forma que quede en una sola capa.","Machacar ajo con el lateral del cuchillo hasta aplastarlo.","Verter aceite de oliva suave sobre el costillar hasta cubrirlo casi por completo.","Añadir el ajo machacado, laurel y tomillo al aceite.","Cocinar a fuego muy suave durante 120 min, hasta que la carne esté muy tierna pero entera.","Mezclar miel y mostaza de dijon en un bol pequeño hasta obtener un glaseado homogéneo.","Precalentar el horno a 220 °C con función grill.","Retirar el costillar del aceite y escurrir el exceso sobre un papel absorbente.","Pincelar el costillar por ambos lados con el glaseado de miel y mostaza.","Hornear en la bandeja superior del horno durante 10 min bajo el grill, hasta que esté dorado y brillante.","Retirar del horno y dejar reposar 3 min antes de cortar.","Cortar el costillar entre hueso y hueso y servir caliente."}', 'Costillar de cerdo confitado a fuego lento y glaseado con miel y mostaza.', '[{"appliance":"horno","time":200,"difficulty":"normal","prepSummary":"Para confitar, sumerge las costillas con el aceite y aromáticos en una fuente apta para horno y cocina a 120°C durante 3 horas. Escurre, glasea con la miel y mostaza, y hornea a 200°C unos 15-20 minutos hasta caramelizar."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Salpimentar {{Costillar de cerdo}} con {{Sal|gusto}} y {{Pimienta negra|pizca}} por ambos lados.","minutes":2,"kind":"prep"},{"text":"Colocar el costillar en una cazuela ancha o fuente honda de forma que quede en una sola capa.","minutes":1,"kind":"prep"},{"text":"Machacar {{Ajo}} con el lateral del cuchillo hasta aplastarlo.","minutes":1,"kind":"prep"},{"text":"Verter {{Aceite de oliva suave}} sobre el costillar hasta cubrirlo casi por completo.","minutes":1,"kind":"activo"},{"text":"Añadir el ajo machacado, {{Laurel}} y {{Tomillo}} al aceite.","minutes":1,"kind":"activo"},{"text":"Cocinar a fuego muy suave durante 120 min, hasta que la carne esté muy tierna pero entera.","minutes":120,"kind":"pasivo"},{"text":"Mezclar {{Miel}} y {{Mostaza de Dijon}} en un bol pequeño hasta obtener un glaseado homogéneo.","minutes":2,"kind":"paralelo","during":5},{"text":"Precalentar el horno a 220 °C con función grill.","minutes":10,"kind":"paralelo","during":5},{"text":"Retirar el costillar del aceite y escurrir el exceso sobre un papel absorbente.","minutes":2,"kind":"activo"},{"text":"Pincelar el costillar por ambos lados con el glaseado de miel y mostaza.","minutes":2,"kind":"activo"},{"text":"Hornear en la bandeja superior del horno durante 10 min bajo el grill, hasta que esté dorado y brillante.","minutes":10,"kind":"pasivo"},{"text":"Retirar del horno y dejar reposar 3 min antes de cortar.","minutes":3,"kind":"espera"},{"text":"Cortar el costillar entre hueso y hueso y servir caliente.","minutes":2,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_092', 'Brochetas de solomillo con pimientos', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'all', 410, 34, 10, 26, 2, true, true, '{}', '[{"name":"Solomillo de ternera en dados","amount":350,"unit":"g"},{"name":"Pimiento rojo","amount":150,"unit":"g"},{"name":"Pimiento verde","amount":100,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Orégano","amount":3,"unit":"g"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Cortar pimiento rojo, pimiento verde y cebolla en trozos cuadrados del mismo tamaño que los dados de carne.","Picar ajo fino.","Mezclar solomillo de ternera en dados con aceite de oliva, el ajo picado, orégano, sal y pimienta negra hasta cubrir bien.","Dejar marinar la carne con el adobo durante 15 min.","Ensartar en las brochetas alternando dado de carne, pimiento rojo, pimiento verde y cebolla hasta completarlas.","Calentar plancha a fuego fuerte hasta que humee.","Cocinar las brochetas 3 min por cada lado hasta que la carne esté dorada y las verduras tiernas.","Servir las brochetas recién hechas."}', 'Brochetas de solomillo de ternera con pimientos, marinadas y asadas a la plancha.', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Marinar la carne y los pimientos con aceite y especias. Precalentar la airfryer a 190-200°C. Cocinar las brochetas durante 18-22 minutos, girándolas a mitad del tiempo, hasta que la carne esté dorada y las verduras tiernas."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Marinar la carne y los pimientos con aceite y especias. Precalentar el horno a 200°C con calor arriba y abajo. Colocar las brochetas en una bandeja y hornear durante 25-30 minutos, dándoles la vuelta una vez, hasta que estén doradas y cocidas."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pimiento rojo}}, {{Pimiento verde}} y {{Cebolla}} en trozos cuadrados del mismo tamaño que los dados de carne.","minutes":5,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Mezclar {{Solomillo de ternera en dados}} con {{Aceite de oliva|chorrito}}, el ajo picado, {{Orégano|pizca}}, {{Sal|gusto}} y {{Pimienta negra|pizca}} hasta cubrir bien.","minutes":2,"kind":"activo"},{"text":"Dejar marinar la carne con el adobo durante 15 min.","minutes":15,"kind":"espera"},{"text":"Ensartar en las brochetas alternando dado de carne, pimiento rojo, pimiento verde y cebolla hasta completarlas.","minutes":3,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que humee.","minutes":2,"kind":"activo"},{"text":"Cocinar las brochetas 3 min por cada lado hasta que la carne esté dorada y las verduras tiernas.","minutes":6,"kind":"activo"},{"text":"Servir las brochetas recién hechas.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_093', 'Pollo a la naranja crujiente', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 40, 'normal', 'all', 560, 36, 48, 24, 2, true, false, '{"gluten","huevo","soja","sesamo"}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Maicena","amount":40,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Aceite de girasol","amount":200,"unit":"ml"},{"name":"Zumo de naranja","amount":150,"unit":"ml"},{"name":"Ralladura de naranja","amount":5,"unit":"g"},{"name":"Azúcar moreno","amount":30,"unit":"g"},{"name":"Salsa de soja","amount":20,"unit":"ml"},{"name":"Vinagre de arroz","amount":15,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Sésamo tostado","amount":5,"unit":"g"},{"name":"Cebolleta","amount":10,"unit":"g"}]'::jsonb, '{"Cortar pechuga de pollo en dados de 3 cm.","Picar ajo y jengibre fresco muy finos.","Picar cebolleta fina y reservar para el emplatado.","Batir huevo en un bol hasta que esté homogéneo.","Añadir los dados de pollo al bol con el huevo batido y mezclar hasta que queden bien impregnados.","Mezclar maicena y harina en un plato llano.","Rebozar los dados de pollo en la mezcla de maicena y harina, sacudiendo el exceso.","Calentar aceite de girasol en sartén honda a fuego fuerte hasta que alcance temperatura de fritura.","Freír los dados de pollo rebozados en tandas hasta que estén dorados y crujientes.","Escurrir el pollo frito sobre papel absorbente y reservar.","Mezclar en un cazo zumo de naranja, ralladura de naranja, azúcar moreno, salsa de soja y vinagre de arroz.","Añadir el ajo y el jengibre picados al cazo con la salsa.","Llevar la salsa a ebullición a fuego fuerte, removiendo hasta que rompa a hervir.","Reducir a fuego medio y cocer hasta que la salsa espese ligeramente.","Añadir el pollo frito a la salsa y saltear a fuego fuerte durante 1 min para que quede bien bañado.","Servir de inmediato espolvoreado con sésamo tostado y la cebolleta picada."}', 'Pollo rebozado y frito hasta quedar crujiente, bañado en una salsa brillante de naranja agridulce.', '[{"appliance":"airfryer","time":35,"difficulty":"normal","prepSummary":"Para el pollo crujiente, reboza las pechugas y rocíalas con un poco de aceite. Cocínalas en la airfryer a 190°C durante 18-20 minutos, volteando a mitad, hasta que estén doradas. La salsa se prepara aparte en una sartén."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Reboza el pollo y colócalo en una bandeja con rejilla para que circule el aire. Hornea a 200°C (con función ventilador si es posible) durante 25-30 minutos, dándole la vuelta una vez, hasta que esté bien dorado y crujiente. La salsa se elabora en paralelo en una cacerola."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pechuga de pollo}} en dados de 3 cm.","minutes":3,"kind":"prep","part":"principal"},{"text":"Picar {{Ajo}} y {{Jengibre fresco}} muy finos.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Picar {{Cebolleta}} fina y reservar para el emplatado.","minutes":1,"kind":"prep","part":"principal"},{"text":"Batir {{Huevo}} en un bol hasta que esté homogéneo.","minutes":1,"kind":"prep","part":"principal"},{"text":"Añadir los dados de pollo al bol con el huevo batido y mezclar hasta que queden bien impregnados.","minutes":1,"kind":"prep","part":"principal"},{"text":"Mezclar {{Maicena}} y {{Harina}} en un plato llano.","minutes":1,"kind":"prep","part":"principal"},{"text":"Rebozar los dados de pollo en la mezcla de maicena y harina, sacudiendo el exceso.","minutes":2,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de girasol}} en {{@Sartén}} honda a fuego fuerte hasta que alcance temperatura de fritura.","minutes":2,"kind":"activo","part":"principal"},{"text":"Freír los dados de pollo rebozados en tandas hasta que estén dorados y crujientes.","minutes":6,"kind":"activo","part":"principal"},{"text":"Escurrir el pollo frito sobre papel absorbente y reservar.","minutes":1,"kind":"prep","part":"principal"},{"text":"Mezclar en un cazo {{Zumo de naranja}}, {{Ralladura de naranja}}, {{Azúcar moreno}}, {{Salsa de soja}} y {{Vinagre de arroz}}.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Añadir el ajo y el jengibre picados al cazo con la salsa.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Llevar la salsa a ebullición a fuego fuerte, removiendo hasta que rompa a hervir.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Reducir a fuego medio y cocer hasta que la salsa espese ligeramente.","minutes":5,"kind":"pasivo","part":"salsa"},{"text":"Añadir el pollo frito a la salsa y saltear a fuego fuerte durante 1 min para que quede bien bañado.","minutes":1,"kind":"activo","part":"combinado"},{"text":"Servir de inmediato espolvoreado con {{Sésamo tostado}} y la cebolleta picada.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_094', 'Ternera Stroganoff', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 35, 'normal', 'all', 430, 34, 12, 26, 2, true, true, '{"lactosa","gluten"}', '[{"name":"Solomillo de ternera","amount":350,"unit":"g"},{"name":"Champiñones","amount":200,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Nata para cocinar","amount":150,"unit":"ml"},{"name":"Caldo de carne","amount":100,"unit":"ml"},{"name":"Mostaza de Dijon","amount":15,"unit":"g"},{"name":"Harina","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Mantequilla","amount":10,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"}]'::jsonb, '{"Cortar solomillo de ternera en tiras finas y salpimentar.","Laminar champiñones.","Picar cebolla en juliana fina.","Calentar aceite de oliva en sartén a fuego fuerte.","Sellar las tiras de solomillo en tandas hasta que estén doradas por fuera. Reservar.","Añadir mantequilla a la misma sartén y sofreír la cebolla a fuego medio hasta que esté transparente.","Incorporar los champiñones laminados y saltear a fuego fuerte hasta que suelten el agua y se doren.","Espolvorear harina y pimentón dulce sobre los champiñones y remover durante 1 min hasta que se cocine el crudo de la harina.","Añadir caldo de carne y mostaza de dijon y remover a fuego medio hasta que la salsa espese ligeramente.","Incorporar nata para cocinar, bajar el fuego a suave y cocer 3 min sin que hierva fuerte.","Devolver las tiras de solomillo reservadas a la sartén junto con sus jugos y calentar 2 min a fuego suave.","Picar perejil fresco finamente.","Espolvorear el perejil picado sobre el stroganoff y servir bien caliente."}', 'Tiras de ternera selladas en una salsa cremosa de champiñones y mostaza, el clásico ruso reconvertido en plato de cuchara rápido.', '[{"appliance":"thermomix","time":35,"difficulty":"normal","prepSummary":"La Thermomix permite picar y sofreír la cebolla y los champiñones, dorar la ternera en porciones y luego cocinar la salsa a temperatura controlada, espesándola a la perfección. El resultado es un Stroganoff completo y homogéneo."},{"appliance":"olla_express","time":30,"difficulty":"normal","prepSummary":"Utiliza la función de saltear o dora la ternera y sofríe las verduras en la propia olla. Luego, añade el resto de ingredientes para la salsa y cocina a fuego lento hasta que espese, o si prefieres, cocina a presión por un breve tiempo y luego reduce la salsa sin tapa."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Solomillo de ternera}} en tiras finas y salpimentar.","minutes":3,"kind":"prep"},{"text":"Laminar {{Champiñones}}.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolla}} en juliana fina.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Sellar las tiras de solomillo en tandas hasta que estén doradas por fuera. Reservar.","minutes":4,"kind":"activo"},{"text":"Añadir {{Mantequilla}} a la misma sartén y sofreír la cebolla a fuego medio hasta que esté transparente.","minutes":5,"kind":"activo"},{"text":"Incorporar los champiñones laminados y saltear a fuego fuerte hasta que suelten el agua y se doren.","minutes":5,"kind":"activo"},{"text":"Espolvorear {{Harina}} y {{Pimentón dulce}} sobre los champiñones y remover durante 1 min hasta que se cocine el crudo de la harina.","minutes":1,"kind":"activo"},{"text":"Añadir {{Caldo de carne}} y {{Mostaza de Dijon}} y remover a fuego medio hasta que la salsa espese ligeramente.","minutes":2,"kind":"activo"},{"text":"Incorporar {{Nata para cocinar}}, bajar el fuego a suave y cocer 3 min sin que hierva fuerte.","minutes":3,"kind":"pasivo"},{"text":"Devolver las tiras de solomillo reservadas a la sartén junto con sus jugos y calentar 2 min a fuego suave.","minutes":2,"kind":"activo"},{"text":"Picar {{Perejil fresco}} finamente.","minutes":1,"kind":"prep"},{"text":"Espolvorear el perejil picado sobre el stroganoff y servir bien caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, true)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  main_protein = excluded.main_protein,
  main_base = excluded.main_base,
  meal_roles = excluded.meal_roles,
  type = excluded.type,
  base_dish_id = excluded.base_dish_id,
  required_appliance = excluded.required_appliance,
  time_minutes = excluded.time_minutes,
  difficulty = excluded.difficulty,
  season = excluded.season,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  base_servings = excluded.base_servings,
  kid_friendly = excluded.kid_friendly,
  tupper_friendly = excluded.tupper_friendly,
  allergens = excluded.allergens,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  description = excluded.description,
  methods = excluded.methods,
  product_aliases = excluded.product_aliases,
  apetecible = excluded.apetecible,
  montaje = excluded.montaje,
  can_be_garnish = excluded.can_be_garnish,
  main_ingredients = excluded.main_ingredients,
  sauce_id = excluded.sauce_id,
  extra_proteins = excluded.extra_proteins,
  freezable = excluded.freezable,
  steps_rich = excluded.steps_rich,
  estrella = excluded.estrella;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('carnes_095', 'Carrillada con puré de patata y reducción', 'carnes', 'cerdo', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 160, 'normal', 'all', 520, 32, 38, 24, 2, true, true, '{"lactosa","sulfitos","gluten"}', '[{"name":"Carrillada de cerdo","amount":500,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Vino tinto","amount":200,"unit":"ml"},{"name":"Caldo de carne","amount":300,"unit":"ml"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Leche","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla, zanahoria, puerro y ajo en trozos pequeños.","Salpimentar carrillada de cerdo por ambos lados.","Enharinar las carrilladas con harina, sacudiendo el exceso.","Calentar aceite de oliva en una cazuela a fuego fuerte.","Dorar las carrilladas por todos los lados hasta que estén selladas. Reservar en un plato.","Sofreír la cebolla, la zanahoria, el puerro y el ajo en la misma cazuela a fuego medio hasta que estén tiernos.","Añadir laurel y las carrilladas reservadas a la cazuela.","Verter vino tinto y dejar reducir a fuego medio hasta que el alcohol evapore.","Añadir caldo de carne, tapar la cazuela y cocer a fuego suave hasta que la carne esté muy tierna.","Pelar y cortar patata en trozos medianos.","Cocer las patatas en una olla con agua y sal a fuego fuerte hasta que estén tiernas.","Calentar leche en un cazo a fuego suave hasta que esté caliente sin llegar a hervir.","Escurrir las patatas cocidas y triturar con la leche caliente y mantequilla hasta obtener un puré fino.","Salpimentar el puré y reservar tapado para mantener el calor.","Retirar las carrilladas de la cazuela y reservar en un plato.","Retirar el laurel y triturar la salsa de cocción con un batidor hasta obtener una crema homogénea.","Colar la salsa triturada a través de un colador fino y verter en la cazuela limpia.","Reducir la salsa colada a fuego medio hasta que nape el dorso de una cuchara.","Disponer el puré de patata en la base del plato y colocar las carrilladas encima.","Napar con la reducción de salsa y servir de inmediato."}', 'Carrillada de cerdo cocinada a fuego lento hasta deshacerse, servida sobre puré de patata y napada con su propia reducción.', '[{"appliance":"horno","time":210,"difficulty":"normal","prepSummary":"Sella la carrillada y sofríe las verduras en una cazuela apta para horno. Añade el resto de ingredientes líquidos y aromáticos, cubre y guisa en el horno a 150-160°C durante 2.5-3 horas hasta que esté muy tierna. Termina la salsa reduciendo en el fuego y prepara el puré aparte."},{"appliance":"thermomix","time":180,"difficulty":"normal","prepSummary":"Sofríe las verduras y sella la carrillada en el vaso. Añade el resto de ingredientes y programa 120-150 minutos a 90-100°C, velocidad cuchara, giro inverso. Retira la carne, tritura la salsa y prepara el puré en el mismo vaso para un resultado cremoso."},{"appliance":"olla_express","time":120,"difficulty":"normal","prepSummary":"Sella la carrillada y sofríe las verduras en la olla. Añade el vino, caldo y el resto de ingredientes. Cierra y cocina a presión alta durante 45-60 minutos. Tras despresurizar, retira la carne, tritura y reduce la salsa al fuego, y prepara el puré de patata aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar y picar {{Cebolla}}, {{Zanahoria}}, {{Puerro}} y {{Ajo}} en trozos pequeños.","minutes":8,"kind":"prep","part":"principal"},{"text":"Salpimentar {{Carrillada de cerdo}} por ambos lados.","minutes":2,"kind":"prep","part":"principal"},{"text":"Enharinar las carrilladas con {{Harina}}, sacudiendo el exceso.","minutes":2,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de oliva}} en una cazuela a fuego fuerte.","minutes":2,"kind":"activo","part":"principal"},{"text":"Dorar las carrilladas por todos los lados hasta que estén selladas. Reservar en un plato.","minutes":8,"kind":"activo","part":"principal"},{"text":"Sofreír la cebolla, la zanahoria, el puerro y el ajo en la misma cazuela a fuego medio hasta que estén tiernos.","minutes":10,"kind":"activo","part":"principal"},{"text":"Añadir {{Laurel}} y las carrilladas reservadas a la cazuela.","minutes":1,"kind":"activo","part":"principal"},{"text":"Verter {{Vino tinto}} y dejar reducir a fuego medio hasta que el alcohol evapore.","minutes":5,"kind":"activo","part":"principal"},{"text":"Añadir {{Caldo de carne}}, tapar la cazuela y cocer a fuego suave hasta que la carne esté muy tierna.","minutes":120,"kind":"pasivo","part":"principal"},{"text":"Pelar y cortar {{Patata}} en trozos medianos.","minutes":5,"kind":"paralelo","part":"guarnicion","during":8},{"text":"Cocer las patatas en una olla con agua y sal a fuego fuerte hasta que estén tiernas.","minutes":20,"kind":"pasivo","part":"guarnicion"},{"text":"Calentar {{Leche}} en un cazo a fuego suave hasta que esté caliente sin llegar a hervir.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Escurrir las patatas cocidas y triturar con la leche caliente y {{Mantequilla}} hasta obtener un puré fino.","minutes":4,"kind":"activo","part":"guarnicion"},{"text":"Salpimentar el puré y reservar tapado para mantener el calor.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Retirar las carrilladas de la cazuela y reservar en un plato.","minutes":1,"kind":"activo","part":"principal"},{"text":"Retirar el laurel y triturar la salsa de cocción con un batidor hasta obtener una crema homogénea.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Colar la salsa triturada a través de un colador fino y verter en la cazuela limpia.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Reducir la salsa colada a fuego medio hasta que nape el dorso de una cuchara.","minutes":10,"kind":"activo","part":"salsa"},{"text":"Disponer el puré de patata en la base del plato y colocar las carrilladas encima.","minutes":2,"kind":"emplatado","part":"combinado"},{"text":"Napar con la reducción de salsa y servir de inmediato.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_096', 'Pastel de carne con puré gratinado', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 75, 'normal', 'all', 500, 28, 35, 26, 4, true, true, '{"lactosa"}', '[{"name":"Carne picada de ternera","amount":600,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"g"},{"name":"Caldo de carne","amount":100,"unit":"ml"},{"name":"Salsa Worcestershire","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Patata","amount":800,"unit":"g"},{"name":"Leche","amount":150,"unit":"ml"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Queso rallado","amount":80,"unit":"g"},{"name":"Tomillo","amount":2,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en trozos de tamaño similar.","Cocer la patata en una olla con agua abundante y sal hasta que esté tierna.","Picar cebolla, zanahoria y ajo fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla, la zanahoria y el ajo hasta que estén blandos.","Añadir carne picada de ternera y dorar a fuego fuerte, deshaciendo los grumos.","Incorporar tomate triturado, caldo de carne, salsa worcestershire y tomillo.","Cocer a fuego medio hasta que la salsa espese. Salpimentar y reservar.","Precalentar el horno a 200 °C.","Calentar leche en un cazo a fuego suave hasta que esté caliente.","Escurrir la patata cocida y triturar en el mismo cazo.","Añadir la leche caliente y la mitad de mantequilla al puré y mezclar hasta que esté cremoso.","Extender la carne guisada en una fuente de horno formando una capa uniforme.","Cubrir la carne con el puré y alisar la superficie con un tenedor.","Repartir queso rallado y el resto de la mantequilla en trocitos por encima.","Hornear a 200 °C hasta que la superficie esté dorada.","Servir la fuente bien caliente en la mesa."}', 'Carne picada guisada con verduras, cubierta de puré de patata y gratinada al horno hasta dorarse.', '[{"appliance":"horno","time":95,"difficulty":"normal","prepSummary":"Prepara el sofrito y la carne en una sartén. Hierve las patatas para el puré. Monta el pastel en un recipiente apto para horno y gratina a 180-200°C durante 25-30 minutos hasta dorar."},{"appliance":"thermomix","time":85,"difficulty":"normal","prepSummary":"Pica y sofríe las verduras y la carne en el vaso. Cocina las patatas al vapor en el Varoma y tritúralas para el puré. Monta el pastel en un molde y gratina en el horno a 190°C unos 20-25 minutos."},{"appliance":"olla_express","time":70,"difficulty":"normal","prepSummary":"Sofríe las verduras y dora la carne en la olla, luego cocina a presión con el resto de ingredientes unos 15-20 minutos. Cuece las patatas a presión y haz el puré. Monta el pastel y gratina en el horno a 190°C durante 20-25 minutos."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Patata}} y cortar en trozos de tamaño similar.","minutes":5,"kind":"prep","part":"guarnicion"},{"text":"Cocer la patata en una olla con agua abundante y sal hasta que esté tierna.","minutes":20,"kind":"pasivo","part":"guarnicion"},{"text":"Picar {{Cebolla}}, {{Zanahoria}} y {{Ajo}} fino.","minutes":5,"kind":"paralelo","part":"principal","during":1},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo","part":"principal"},{"text":"Sofreír la cebolla, la zanahoria y el ajo hasta que estén blandos.","minutes":8,"kind":"activo","part":"principal"},{"text":"Añadir {{Carne picada de ternera}} y dorar a fuego fuerte, deshaciendo los grumos.","minutes":5,"kind":"activo","part":"principal"},{"text":"Incorporar {{Tomate triturado}}, {{Caldo de carne}}, {{Salsa Worcestershire}} y {{Tomillo|pizca}}.","minutes":1,"kind":"activo","part":"principal"},{"text":"Cocer a fuego medio hasta que la salsa espese. Salpimentar y reservar.","minutes":15,"kind":"pasivo","part":"principal"},{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"paralelo","part":"guarnicion","during":7},{"text":"Calentar {{Leche}} en un cazo a fuego suave hasta que esté caliente.","minutes":3,"kind":"paralelo","part":"guarnicion","during":7},{"text":"Escurrir la patata cocida y triturar en el mismo cazo.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Añadir la leche caliente y la mitad de {{Mantequilla}} al puré y mezclar hasta que esté cremoso.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Extender la carne guisada en una fuente de horno formando una capa uniforme.","minutes":2,"kind":"activo","part":"combinado"},{"text":"Cubrir la carne con el puré y alisar la superficie con un tenedor.","minutes":2,"kind":"activo","part":"combinado"},{"text":"Repartir {{Queso rallado}} y el resto de la mantequilla en trocitos por encima.","minutes":1,"kind":"activo","part":"combinado"},{"text":"Hornear a 200 °C hasta que la superficie esté dorada.","minutes":18,"kind":"pasivo","part":"combinado"},{"text":"Servir la fuente bien caliente en la mesa.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_097', 'Lomo a la miel y mostaza', 'carnes', 'cerdo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 380, 30, 20, 18, 2, true, true, '{"mostaza"}', '[{"name":"Lomo de cerdo (filetes)","amount":350,"unit":"g"},{"name":"Miel","amount":40,"unit":"g"},{"name":"Mostaza de Dijon","amount":30,"unit":"g"},{"name":"Mostaza a la antigua","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vinagre de manzana","amount":15,"unit":"ml"}]'::jsonb, '{"Picar ajo muy fino.","Mezclar en un bol miel, mostaza de dijon, mostaza a la antigua, el ajo picado y vinagre de manzana hasta integrar.","Salpimentar lomo de cerdo (filetes) por ambos lados.","Calentar aceite de oliva en sartén a fuego fuerte.","Dorar los filetes de lomo 2 min por cada lado hasta que estén sellados y dorados.","Bajar el fuego a medio y verter la mezcla de miel y mostaza sobre los filetes.","Cocinar 5 min, girando los filetes a mitad para que se impregnen bien, hasta que el glaseado espese y brille.","Retirar del fuego cuando la carne esté jugosa y el glaseado cubra los filetes.","Servir los filetes napados con el glaseado de la sartén."}', 'Filetes de lomo de cerdo glaseados en una salsa brillante de miel y dos mostazas, listos en menos de media hora.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Marinar los filetes de lomo en la mezcla de miel, mostazas, ajo, aceite y vinagre. Cocinar en la airfryer precalentada a 190°C durante 15-18 minutos, dándoles la vuelta a mitad, para un exterior dorado y un interior jugoso."},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Tras marinar los filetes, colocarlos en una fuente de horno. Hornear a 200°C durante 20-25 minutos, volteándolos una vez y rociando con la salsa para asegurar que queden tiernos y con un buen glaseado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Ajo}} muy fino.","minutes":2,"kind":"prep"},{"text":"Mezclar en un bol {{Miel}}, {{Mostaza de Dijon}}, {{Mostaza a la antigua}}, el ajo picado y {{Vinagre de manzana}} hasta integrar.","minutes":2,"kind":"prep"},{"text":"Salpimentar {{Lomo de cerdo (filetes)}} por ambos lados.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Dorar los filetes de lomo 2 min por cada lado hasta que estén sellados y dorados.","minutes":4,"kind":"activo"},{"text":"Bajar el fuego a medio y verter la mezcla de miel y mostaza sobre los filetes.","minutes":1,"kind":"activo"},{"text":"Cocinar 5 min, girando los filetes a mitad para que se impregnen bien, hasta que el glaseado espese y brille.","minutes":5,"kind":"activo"},{"text":"Retirar del fuego cuando la carne esté jugosa y el glaseado cubra los filetes.","minutes":1,"kind":"activo"},{"text":"Servir los filetes napados con el glaseado de la sartén.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_098', 'Jarrete de ternera al horno con verduras', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 200, 'normal', 'all', 480, 38, 30, 20, 2, true, true, '{"sulfitos","gluten"}', '[{"name":"Jarrete de ternera","amount":700,"unit":"g"},{"name":"Zanahoria","amount":150,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Puerro","amount":100,"unit":"g"},{"name":"Patata baby","amount":300,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Vino blanco","amount":150,"unit":"ml"},{"name":"Caldo de carne","amount":300,"unit":"ml"},{"name":"Tomate triturado","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Romero","amount":3,"unit":"g"},{"name":"Harina","amount":15,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Pelar y cortar zanahoria en trozos grandes.","Pelar y cortar cebolla en trozos grandes.","Limpiar y cortar puerro en rodajas gruesas.","Picar ajo fino.","Lavar patata baby y reservar enteras.","Salpimentar jarrete de ternera por todos los lados.","Enharinar el jarrete con harina, sacudiendo el exceso.","Calentar aceite de oliva en una cazuela apta para horno a fuego fuerte.","Dorar el jarrete por todos los lados hasta que esté bien sellado y con color.","Retirar el jarrete y reservar en un plato.","Sofreír la cebolla, el puerro y el ajo en la misma cazuela a fuego medio hasta que estén pochados.","Añadir la zanahoria y la patata baby y saltear 2 min a fuego medio.","Incorporar vino blanco y dejar reducir hasta que el alcohol se evapore.","Añadir tomate triturado, caldo de carne, laurel y romero y remover para integrar.","Devolver el jarrete a la cazuela, colocándolo sobre las verduras.","Tapar la cazuela y hornear a 180 °C hasta que la carne se separe del hueso con facilidad.","Retirar el laurel y el romero de la cazuela.","Servir el jarrete con las verduras y el jugo de cocción."}', 'Jarrete de ternera cocinado lentamente al horno junto a verduras de raíz, hasta que la carne se deshace sola del hueso.', '[{"appliance":"horno","time":200,"difficulty":"normal","prepSummary":"Sella el jarrete, sofríe las verduras y desglasa con vino. Añade el caldo, tomate y hierbas, y hornea cubierto a 160-170°C durante 3 horas y 20 minutos hasta que la carne esté muy tierna."},{"appliance":"olla_express","time":90,"difficulty":"normal","prepSummary":"Tras sellar la carne y sofreír las verduras, incorpora los líquidos y hierbas. Cocina en olla express a presión alta durante 60-75 minutos. Deja despresurizar y si es necesario, reduce la salsa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 180 °C.","minutes":15,"kind":"pasivo"},{"text":"Pelar y cortar {{Zanahoria}} en trozos grandes.","minutes":3,"kind":"prep"},{"text":"Pelar y cortar {{Cebolla}} en trozos grandes.","minutes":2,"kind":"paralelo","during":0},{"text":"Limpiar y cortar {{Puerro}} en rodajas gruesas.","minutes":2,"kind":"paralelo","during":0},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"paralelo","during":0},{"text":"Lavar {{Patata baby}} y reservar enteras.","minutes":2,"kind":"paralelo","during":0},{"text":"Salpimentar {{Jarrete de ternera}} por todos los lados.","minutes":1,"kind":"prep"},{"text":"Enharinar el jarrete con {{Harina}}, sacudiendo el exceso.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela apta para horno a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Dorar el jarrete por todos los lados hasta que esté bien sellado y con color.","minutes":8,"kind":"activo"},{"text":"Retirar el jarrete y reservar en un plato.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla, el puerro y el ajo en la misma cazuela a fuego medio hasta que estén pochados.","minutes":6,"kind":"activo"},{"text":"Añadir la zanahoria y la patata baby y saltear 2 min a fuego medio.","minutes":2,"kind":"activo"},{"text":"Incorporar {{Vino blanco}} y dejar reducir hasta que el alcohol se evapore.","minutes":3,"kind":"activo"},{"text":"Añadir {{Tomate triturado}}, {{Caldo de carne}}, {{Laurel}} y {{Romero|pizca}} y remover para integrar.","minutes":2,"kind":"activo"},{"text":"Devolver el jarrete a la cazuela, colocándolo sobre las verduras.","minutes":1,"kind":"activo"},{"text":"Tapar la cazuela y hornear a 180 °C hasta que la carne se separe del hueso con facilidad.","minutes":150,"kind":"pasivo"},{"text":"Retirar el laurel y el romero de la cazuela.","minutes":1,"kind":"activo"},{"text":"Servir el jarrete con las verduras y el jugo de cocción.","minutes":2,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_099', 'Solomillo Café de París', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'normal', 'all', 540, 33, 3, 44, 2, true, true, '{"lactosa","mostaza"}', '[{"name":"Solomillo de ternera","amount":350,"unit":"g"},{"name":"Mantequilla","amount":80,"unit":"g"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Cebollino","amount":5,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Chalota","amount":20,"unit":"g"},{"name":"Mostaza de Dijon","amount":10,"unit":"g"},{"name":"Brandy","amount":15,"unit":"ml"},{"name":"Pimentón dulce","amount":2,"unit":"g"},{"name":"Curry en polvo","amount":1,"unit":"g"},{"name":"Zumo de limón","amount":5,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Retirar solomillo de ternera de la nevera y dejar atemperar a temperatura ambiente.","Picar finamente perejil fresco, cebollino, ajo y chalota.","Ablandar mantequilla a temperatura ambiente hasta que esté cremosa.","Mezclar la mantequilla con el perejil, el cebollino, el ajo y la chalota picados.","Añadir mostaza de dijon, brandy, pimentón dulce, curry en polvo y zumo de limón a la mezcla de mantequilla.","Mezclar bien hasta obtener una mantequilla compuesta homogénea.","Formar un cilindro con la mantequilla compuesta enrollándola en film transparente.","Enfriar el cilindro de mantequilla en el congelador hasta que esté firme.","Salpimentar el solomillo de ternera por ambos lados.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Marcar el solomillo de ternera 2 min por cada lado hasta que esté dorado por fuera y rosado por dentro.","Retirar el solomillo de la sartén y dejar reposar fuera del fuego.","Cortar la mantequilla compuesta en rodajas de 1 cm.","Colocar 2 o 3 rodajas de mantequilla compuesta sobre cada medallón caliente y servir enseguida."}', 'Medallones de solomillo de ternera marcados a la plancha y coronados con mantequilla compuesta de hierbas, mostaza y un toque de brandy.', '[{"appliance":"airfryer","time":30,"difficulty":"normal","prepSummary":"Para el solomillo, precalienta la airfryer a 190-200°C y cocina el solomillo unos 15-20 minutos, dándole la vuelta a mitad, hasta el punto deseado. La mantequilla Café de París se prepara aparte mezclando todos los ingredientes picados y se sirve sobre el solomillo caliente."},{"appliance":"horno","time":35,"difficulty":"normal","prepSummary":"Sella el solomillo en una sartén muy caliente con aceite por 2-3 minutos por cada lado. Luego, trasládalo a una bandeja y hornea a 190°C durante 10-15 minutos para terminar la cocción. La mantequilla Café de París se elabora mezclando los ingredientes picados y se añade al solomi"}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Retirar {{Solomillo de ternera}} de la nevera y dejar atemperar a temperatura ambiente.","minutes":20,"kind":"espera"},{"text":"Picar finamente {{Perejil fresco}}, {{Cebollino}}, {{Ajo}} y {{Chalota}}.","minutes":5,"kind":"prep"},{"text":"Ablandar {{Mantequilla}} a temperatura ambiente hasta que esté cremosa.","minutes":2,"kind":"prep"},{"text":"Mezclar la mantequilla con el perejil, el cebollino, el ajo y la chalota picados.","minutes":2,"kind":"prep"},{"text":"Añadir {{Mostaza de Dijon}}, {{Brandy}}, {{Pimentón dulce}}, {{Curry en polvo}} y {{Zumo de limón}} a la mezcla de mantequilla.","minutes":1,"kind":"prep"},{"text":"Mezclar bien hasta obtener una mantequilla compuesta homogénea.","minutes":1,"kind":"activo"},{"text":"Formar un cilindro con la mantequilla compuesta enrollándola en film transparente.","minutes":2,"kind":"prep"},{"text":"Enfriar el cilindro de mantequilla en el congelador hasta que esté firme.","minutes":15,"kind":"pasivo"},{"text":"Salpimentar el solomillo de ternera por ambos lados.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego fuerte hasta que humee ligeramente.","minutes":2,"kind":"activo"},{"text":"Marcar el solomillo de ternera 2 min por cada lado hasta que esté dorado por fuera y rosado por dentro.","minutes":4,"kind":"activo"},{"text":"Retirar el solomillo de la sartén y dejar reposar fuera del fuego.","minutes":3,"kind":"espera"},{"text":"Cortar la mantequilla compuesta en rodajas de 1 cm.","minutes":1,"kind":"prep"},{"text":"Colocar 2 o 3 rodajas de mantequilla compuesta sobre cada medallón caliente y servir enseguida.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_100', 'Filete tártaro con patatas fritas al lado', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 620, 29, 38, 36, 2, false, false, '{"huevo","mostaza","pescado"}', '[{"name":"Solomillo de ternera (para tartar)","amount":300,"unit":"g"},{"name":"Yema de huevo","amount":2,"unit":"ud"},{"name":"Alcaparras","amount":20,"unit":"g"},{"name":"Pepinillos encurtidos","amount":30,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Mostaza de Dijon","amount":15,"unit":"g"},{"name":"Salsa Worcestershire","amount":10,"unit":"ml"},{"name":"Tabasco","amount":3,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de girasol","amount":300,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en bastones uniformes de unos 1 cm de grosor.","Calentar aceite de girasol en una sartén profunda a fuego medio hasta alcanzar 150 °C.","Freír las patatas en 2 tandas durante 6 min cada una hasta que estén tiernas pero sin dorar.","Subir el fuego a fuerte hasta que el aceite alcance 190 °C.","Freír las patatas de nuevo en 2 tandas durante 2 min hasta que estén doradas y crujientes.","Escurrir las patatas sobre papel absorbente y reservar en lugar templado.","Picar solomillo de ternera (para tartar) a cuchillo en dados muy pequeños; nunca usar picadora.","Picar alcaparras muy finamente.","Picar pepinillos encurtidos muy finamente.","Picar cebolla morada muy finamente.","Picar perejil fresco muy finamente.","Mezclar en un bol frío el solomillo picado con las alcaparras, los pepinillos, la cebolla morada y el perejil.","Añadir mostaza de dijon, salsa worcestershire, tabasco y aceite de oliva.","Mezclar con delicadeza hasta integrar sin machacar la carne; salpimentar al gusto.","Reservar la mezcla en la nevera hasta el momento de emplatar.","Salar las patatas fritas recién escurridas.","