insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('carnes_105', 'Magret de pato con puré de boniato y reducción de frutos rojos', 'carnes', 'pavo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 580, 30, 40, 32, 2, false, true, '{"lactosa","sulfitos"}', '[{"name":"Magret de pato","amount":350,"unit":"g"},{"name":"Boniato","amount":350,"unit":"g"},{"name":"Leche","amount":80,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Frutos rojos","amount":150,"unit":"g"},{"name":"Vino tinto","amount":100,"unit":"ml"},{"name":"Azúcar moreno","amount":30,"unit":"g"},{"name":"Vinagre de Módena","amount":10,"unit":"ml"}]'::jsonb, '{"Pelar boniato y cortar en trozos medianos.","Cocer el boniato en una olla con agua salada hasta que esté tierno.","Marcar la piel de magret de pato con un cuchillo en rombos sin llegar a la carne.","Salpimentar el magret por ambas caras.","Colocar el magret en sartén fría con la piel hacia abajo y encender el fuego medio.","Cocinar hasta que la piel esté dorada y crujiente, retirando la grasa que suelte con una cuchara.","Calentar frutos rojos, vino tinto, azúcar moreno y vinagre de módena en un cazo a fuego medio.","Reducir la mezcla a fuego medio hasta que la salsa esté espesa y nape la cuchara.","Dar la vuelta al magret y cocinar por el lado de la carne hasta alcanzar el punto deseado.","Retirar el magret de la sartén y dejar reposar sobre una tabla.","Escurrir el boniato cocido y triturar con leche y mantequilla hasta obtener un puré fino.","Cortar el magret en lonchas de 1 cm en sentido transversal a la fibra.","Disponer el puré en el plato, colocar las lonchas de magret encima y napar con la reducción de frutos rojos."}', 'Magret de pato con la piel crujiente, servido sobre un puré de boniato y napado con una reducción de frutos rojos.', '[{"appliance":"airfryer","time":50,"difficulty":"normal","prepSummary":"Para el magret, márcalo por el lado de la piel en una sartén y luego cocínalo en la airfryer a 180°C por 15-20 min. El boniato se puede asar en la misma airfryer hasta que esté tierno, facilitando el puré."},{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Sella el magret por el lado de la piel en una sartén y termina su cocción en el horno a 180°C durante 10-15 min. Aprovecha el horno para asar el boniato hasta que esté muy tierno para el puré."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Boniato}} y cortar en trozos medianos.","minutes":3,"kind":"prep","part":"guarnicion"},{"text":"Cocer el boniato en una olla con agua salada hasta que esté tierno.","minutes":18,"kind":"pasivo","part":"guarnicion"},{"text":"Marcar la piel de {{Magret de pato}} con un cuchillo en rombos sin llegar a la carne.","minutes":2,"kind":"prep","part":"principal"},{"text":"Salpimentar el magret por ambas caras.","minutes":1,"kind":"prep","part":"principal"},{"text":"Colocar el magret en {{@Sartén}} fría con la piel hacia abajo y encender el fuego medio.","minutes":1,"kind":"activo","part":"principal"},{"text":"Cocinar hasta que la piel esté dorada y crujiente, retirando la grasa que suelte con una cuchara.","minutes":9,"kind":"activo","part":"principal"},{"text":"Calentar {{Frutos rojos}}, {{Vino tinto}}, {{Azúcar moreno}} y {{Vinagre de Módena}} en un cazo a fuego medio.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Reducir la mezcla a fuego medio hasta que la salsa esté espesa y nape la cuchara.","minutes":10,"kind":"pasivo","part":"salsa"},{"text":"Dar la vuelta al magret y cocinar por el lado de la carne hasta alcanzar el punto deseado.","minutes":4,"kind":"activo","part":"principal"},{"text":"Retirar el magret de la sartén y dejar reposar sobre una tabla.","minutes":5,"kind":"espera","part":"principal"},{"text":"Escurrir el boniato cocido y triturar con {{Leche}} y {{Mantequilla}} hasta obtener un puré fino.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Cortar el magret en lonchas de 1 cm en sentido transversal a la fibra.","minutes":2,"kind":"prep","part":"principal"},{"text":"Disponer el puré en el plato, colocar las lonchas de magret encima y napar con la reducción de frutos rojos.","minutes":2,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_106', 'Chuletón a la parrilla con patatas fritas y alioli de ajo asado', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'all', 800, 45, 35, 55, 2, true, false, '{"huevo"}', '[{"name":"Chuletón de ternera","amount":700,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de girasol","amount":300,"unit":"ml"},{"name":"Cabeza de ajos","amount":1,"unit":"ud"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de oliva suave","amount":150,"unit":"ml"},{"name":"Zumo de limón","amount":5,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Envolver cabeza de ajos en papel de aluminio con aceite de oliva suave.","Hornear el paquete de ajos a 200 °C durante 40 min, hasta que los dientes estén blandos.","Pelar patata y cortar en bastones de 1 cm de grosor.","Sacar chuletón de ternera de la nevera para que atempere al menos 20 min antes de cocinarlo.","Calentar aceite de girasol en una sartén honda a fuego fuerte hasta que alcance 180 °C.","Freír las patatas en el aceite caliente durante 8 min, hasta que estén doradas y crujientes.","Escurrir las patatas fritas sobre papel absorbente y reservar.","Retirar los ajos del horno y dejar templar 5 min hasta poder manejarlos.","Extraer la pulpa de los dientes de ajo asados presionando cada diente desde la base.","Poner huevo y zumo de limón en el vaso de la batidora junto con la pulpa de ajo asado.","Triturar a velocidad baja y añadir el aceite de oliva suave en hilo fino hasta que emulsione y espese.","Salpimentar el chuletón atemperado por ambas caras antes de cocinarlo.","Calentar plancha a fuego fuerte hasta que humee.","Marcar el chuletón 4 min por el primer lado sin moverlo, hasta que se forme costra.","Dar la vuelta al chuletón y marcar 4 min por el otro lado hasta alcanzar el punto deseado.","Retirar el chuletón de la plancha y dejar reposar 5 min para que los jugos se asienten.","Cortar el chuletón en lonchas gruesas siguiendo el hueso.","Servir las lonchas de chuletón junto con las patatas fritas y el alioli de ajo asado aparte."}', 'Chuletón de ternera a la parrilla, cortado en lonchas gruesas, con patatas fritas y un alioli suave de ajo asado.', '[{"appliance":"airfryer","time":50,"difficulty":"facil","prepSummary":"El airfryer es ideal para las patatas fritas y el ajo asado. Para el chuletón, precalienta a 200°C y cocina unos 15-20 minutos, volteando a mitad, para un exterior crujiente y un interior jugoso. Las patatas quedan doradas y el ajo tierno para el alioli."},{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"El horno es excelente para asar el ajo y las patatas (horneadas). Para el chuletón, precalienta a 220°C y cocina unos 20-25 minutos, volteando, para un buen sellado y cocción uniforme. Las patatas se dorarán y el ajo quedará tierno y dulce."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo","part":"salsa"},{"text":"Envolver {{Cabeza de ajos}} en papel de aluminio con {{Aceite de oliva suave|chorrito}}.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Hornear el paquete de ajos a 200 °C durante 40 min, hasta que los dientes estén blandos.","minutes":40,"kind":"pasivo","part":"salsa"},{"text":"Pelar {{Patata}} y cortar en bastones de 1 cm de grosor.","minutes":5,"kind":"paralelo","part":"guarnicion","during":2},{"text":"Sacar {{Chuletón de ternera}} de la nevera para que atempere al menos 20 min antes de cocinarlo.","minutes":20,"kind":"paralelo","part":"principal","during":2},{"text":"Calentar {{Aceite de girasol}} en una sartén honda a fuego fuerte hasta que alcance 180 °C.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Freír las patatas en el aceite caliente durante 8 min, hasta que estén doradas y crujientes.","minutes":8,"kind":"pasivo","part":"guarnicion"},{"text":"Escurrir las patatas fritas sobre papel absorbente y reservar.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Retirar los ajos del horno y dejar templar 5 min hasta poder manejarlos.","minutes":5,"kind":"espera","part":"salsa"},{"text":"Extraer la pulpa de los dientes de ajo asados presionando cada diente desde la base.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Poner {{Huevo}} y {{Zumo de limón}} en el vaso de la batidora junto con la pulpa de ajo asado.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Triturar a velocidad baja y añadir el aceite de oliva suave en hilo fino hasta que emulsione y espese.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Salpimentar el chuletón atemperado por ambas caras antes de cocinarlo.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que humee.","minutes":2,"kind":"activo","part":"principal"},{"text":"Marcar el chuletón 4 min por el primer lado sin moverlo, hasta que se forme costra.","minutes":4,"kind":"activo","part":"principal"},{"text":"Dar la vuelta al chuletón y marcar 4 min por el otro lado hasta alcanzar el punto deseado.","minutes":4,"kind":"activo","part":"principal"},{"text":"Retirar el chuletón de la plancha y dejar reposar 5 min para que los jugos se asienten.","minutes":5,"kind":"espera","part":"principal"},{"text":"Cortar el chuletón en lonchas gruesas siguiendo el hueso.","minutes":1,"kind":"prep","part":"principal"},{"text":"Servir las lonchas de chuletón junto con las patatas fritas y el alioli de ajo asado aparte.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_107', 'Costillar de cerdo con puré de patata cremoso y salsa BBQ ahumada', 'carnes', 'cerdo', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 110, 'normal', 'all', 650, 33, 42, 38, 2, true, true, '{"lactosa","mostaza","sulfitos"}', '[{"name":"Costillar de cerdo","amount":600,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Leche","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Ketchup","amount":80,"unit":"g"},{"name":"Miel","amount":30,"unit":"g"},{"name":"Vinagre de manzana","amount":15,"unit":"ml"},{"name":"Pimentón ahumado","amount":6,"unit":"g"},{"name":"Mostaza","amount":10,"unit":"g"},{"name":"Ajo en polvo","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 150 °C.","Salpimentar costillar de cerdo por ambas caras.","Envolver el costillar en papel de aluminio y colocarlo sobre una bandeja de horno.","Hornear el costillar tapado a 150 °C hasta que la carne esté muy tierna y se separe fácilmente del hueso.","Mezclar ketchup, miel, vinagre de manzana, pimentón ahumado, mostaza y ajo en polvo en un bol hasta obtener la salsa BBQ.","Pelar patata y cortar en trozos medianos.","Llevar a ebullición un cazo con agua y sal, añadir la patata y cocer hasta que esté tierna.","Calentar leche en un cazo pequeño a fuego suave hasta que esté caliente, sin llegar a hervir.","Escurrir la patata cocida y triturar en el cazo con la leche caliente y mantequilla hasta obtener un puré liso.","Salpimentar el puré y reservar tapado para que se mantenga caliente.","Subir el horno a 220 °C.","Retirar el papel de aluminio y pincelar el costillar generosamente con la salsa BBQ.","Hornear el costillar destapado a 220 °C durante 7 min, pincelar de nuevo con la salsa BBQ y hornear 8 min más.","Retirar el costillar del horno y cortar entre hueso y hueso.","Servir el costillar sobre una base de puré de patata y añadir salsa BBQ restante por encima."}', 'Costillar de cerdo horneado hasta la ternura, glaseado con una salsa barbacoa ahumada y servido sobre puré de patata cremoso.', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Cocina el costillar lentamente a baja temperatura (aprox. 150-160°C) durante 90-100 minutos para que quede tierno, glaseando con la salsa BBQ en los últimos 20-30 minutos para caramelizar. Prepara el puré y la salsa en paralelo."},{"appliance":"olla_express","time":90,"difficulty":"normal","prepSummary":"Cocina el costillar en la olla express con un poco de líquido durante 35-45 minutos para una ternura excepcional. Luego, termina en el horno a 200°C durante 15-20 minutos, glaseando con la salsa BBQ para dorar y caramelizar. El puré se puede hacer también en la olla express."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 150 °C.","minutes":10,"kind":"activo","part":"principal"},{"text":"Salpimentar {{Costillar de cerdo}} por ambas caras.","minutes":2,"kind":"prep","part":"principal"},{"text":"Envolver el costillar en papel de aluminio y colocarlo sobre una bandeja de horno.","minutes":2,"kind":"prep","part":"principal"},{"text":"Hornear el costillar tapado a 150 °C hasta que la carne esté muy tierna y se separe fácilmente del hueso.","minutes":90,"kind":"pasivo","part":"principal"},{"text":"Mezclar {{Ketchup}}, {{Miel}}, {{Vinagre de manzana}}, {{Pimentón ahumado}}, {{Mostaza}} y {{Ajo en polvo}} en un bol hasta obtener la salsa BBQ.","minutes":3,"kind":"paralelo","part":"salsa","during":3},{"text":"Pelar {{Patata}} y cortar en trozos medianos.","minutes":5,"kind":"paralelo","part":"guarnicion","during":3},{"text":"Llevar a ebullición un cazo con agua y sal, añadir la patata y cocer hasta que esté tierna.","minutes":20,"kind":"paralelo","part":"guarnicion","during":3},{"text":"Calentar {{Leche}} en un cazo pequeño a fuego suave hasta que esté caliente, sin llegar a hervir.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Escurrir la patata cocida y triturar en el cazo con la leche caliente y {{Mantequilla}} hasta obtener un puré liso.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Salpimentar el puré y reservar tapado para que se mantenga caliente.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Subir el horno a 220 °C.","minutes":5,"kind":"activo","part":"principal"},{"text":"Retirar el papel de aluminio y pincelar el costillar generosamente con la salsa BBQ.","minutes":2,"kind":"activo","part":"principal"},{"text":"Hornear el costillar destapado a 220 °C durante 7 min, pincelar de nuevo con la salsa BBQ y hornear 8 min más.","minutes":15,"kind":"pasivo","part":"principal"},{"text":"Retirar el costillar del horno y cortar entre hueso y hueso.","minutes":2,"kind":"activo","part":"principal"},{"text":"Servir el costillar sobre una base de puré de patata y añadir salsa BBQ restante por encima.","minutes":2,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_108', 'Pollo asado con patatas panadera y salsa de sus jugos', 'carnes', 'pollo', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 70, 'facil', 'all', 560, 38, 32, 30, 2, true, true, '{"gluten"}', '[{"name":"Muslos y contramuslos de pollo","amount":500,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Caldo de pollo","amount":150,"unit":"ml"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Harina","amount":10,"unit":"g"},{"name":"Tomillo","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Pelar patata y cortarla en rodajas finas de unos 3 mm.","Cortar cebolla en juliana fina.","Colocar la patata y la cebolla en una fuente de horno.","Regar con la mitad de aceite de oliva, salpimentar y mezclar bien hasta cubrir todas las rodajas.","Salpimentar muslos y contramuslos de pollo por todas las caras.","Colocar el pollo sobre la cama de patatas y cebolla en la fuente.","Repartir ajo entero sin pelar alrededor del pollo.","Espolvorear tomillo y regar con el resto del aceite de oliva.","Hornear 45 min hasta que el pollo esté dorado y las patatas tiernas.","Voltear las patatas a mitad de cocción, hacia el minuto 22-23, para que se doren de manera uniforme.","Retirar el pollo y las patatas de la fuente y reservar calientes tapados con papel de aluminio.","Pasar los jugos de la fuente a un cazo y calentar a fuego medio.","Añadir harina y remover sin parar durante 1 min hasta que no queden grumos.","Verter vino blanco y raspar el fondo del cazo para soltar los jugos pegados.","Añadir caldo de pollo y dejar reducir a fuego medio hasta obtener una salsa ligera.","Servir el pollo junto a las patatas y napar con la salsa de sus jugos."}', 'Pollo asado al horno sobre patatas panadera, con una salsa ligera hecha con sus propios jugos de cocción.', '[{"appliance":"horno","time":70,"difficulty":"facil","prepSummary":"Asa el pollo y las patatas panadera en una bandeja de horno, permitiendo que los jugos del pollo impregnen las patatas. Al final, usa los jugos concentrados para ligar la salsa."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Cocina el pollo en la airfryer a 190°C hasta que esté dorado y crujiente, volteándolo a mitad. Las patatas y cebolla se asan por separado en la misma airfryer, y la salsa se prepara en un cazo con los mínimos jugos que se puedan recoger o con caldo adicional."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Pelar {{Patata}} y cortarla en rodajas finas de unos 3 mm.","minutes":4,"kind":"paralelo","during":0},{"text":"Cortar {{Cebolla}} en juliana fina.","minutes":2,"kind":"paralelo","during":0},{"text":"Colocar la patata y la cebolla en una fuente de horno.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Regar con la mitad de {{Aceite de oliva}}, salpimentar y mezclar bien hasta cubrir todas las rodajas.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Salpimentar {{Muslos y contramuslos de pollo}} por todas las caras.","minutes":1,"kind":"prep","part":"principal"},{"text":"Colocar el pollo sobre la cama de patatas y cebolla en la fuente.","minutes":1,"kind":"prep","part":"principal"},{"text":"Repartir {{Ajo}} entero sin pelar alrededor del pollo.","minutes":1,"kind":"prep","part":"principal"},{"text":"Espolvorear {{Tomillo|pizca}} y regar con el resto del aceite de oliva.","minutes":1,"kind":"prep","part":"principal"},{"text":"Hornear 45 min hasta que el pollo esté dorado y las patatas tiernas.","minutes":45,"kind":"pasivo","part":"principal"},{"text":"Voltear las patatas a mitad de cocción, hacia el minuto 22-23, para que se doren de manera uniforme.","minutes":2,"kind":"activo","part":"principal"},{"text":"Retirar el pollo y las patatas de la fuente y reservar calientes tapados con papel de aluminio.","minutes":1,"kind":"activo","part":"principal"},{"text":"Pasar los jugos de la fuente a un cazo y calentar a fuego medio.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Añadir {{Harina}} y remover sin parar durante 1 min hasta que no queden grumos.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Verter {{Vino blanco}} y raspar el fondo del cazo para soltar los jugos pegados.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Añadir {{Caldo de pollo}} y dejar reducir a fuego medio hasta obtener una salsa ligera.","minutes":4,"kind":"pasivo","part":"salsa"},{"text":"Servir el pollo junto a las patatas y napar con la salsa de sus jugos.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_109', 'Presa ibérica con patatas fritas y salsa de pimienta verde', 'carnes', 'cerdo', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 770, 34, 33, 52, 2, false, false, '{"lactosa"}', '[{"name":"Presa ibérica","amount":350,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de girasol","amount":300,"unit":"ml"},{"name":"Pimienta verde en grano","amount":20,"unit":"g"},{"name":"Nata para cocinar","amount":150,"unit":"ml"},{"name":"Caldo de carne","amount":80,"unit":"ml"},{"name":"Brandy","amount":20,"unit":"ml"},{"name":"Chalota","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en bastones de unos 1 cm de grosor.","Calentar aceite de girasol en una olla o sartén honda a fuego fuerte hasta que alcance unos 180 °C.","Freír los bastones de patata hasta que estén dorados y crujientes.","Escurrir las patatas sobre papel absorbente y reservar.","Picar chalota muy fina.","Salpimentar presa ibérica por ambas caras.","Calentar aceite de oliva en plancha a fuego fuerte.","Dorar la presa ibérica 3 min por cada cara hasta alcanzar el punto deseado.","Retirar la presa ibérica y dejar reposar en un plato.","Sofreír la chalota picada en la misma plancha a fuego medio hasta que esté transparente.","Añadir pimienta verde en grano y remover 1 min para que libere su aroma.","Verter brandy y dejar evaporar el alcohol a fuego fuerte hasta que deje de humear.","Añadir caldo de carne y nata para cocinar; remover para integrar.","Cocer a fuego medio hasta que la salsa espese y nape la cuchara.","Cortar la presa ibérica en lonchas de unos 2 cm.","Servir las lonchas napadas con la salsa de pimienta verde y las patatas fritas al lado."}', 'Presa ibérica a la plancha en una cremosa salsa de pimienta verde, servida con patatas fritas.', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"La presa se cocina a 190°C por 15-20 min, volteando a mitad para un sellado uniforme. Las patatas se hacen a 180°C por 20-25 min con poco aceite, agitándolas ocasionalmente. La salsa se prepara aparte en una sartén mientras se cocinan los otros elementos."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Las patatas se hornean a 200°C por 30-40 min con un chorrito de aceite, volteándolas para que doren parejo. La presa se sella primero en sartén y se termina en el horno a 200°C por 10-15 min. La salsa se elabora en una sartén aparte."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en bastones de unos 1 cm de grosor.","minutes":5,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de girasol}} en una olla o sartén honda a fuego fuerte hasta que alcance unos 180 °C.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Freír los bastones de patata hasta que estén dorados y crujientes.","minutes":10,"kind":"pasivo","part":"guarnicion"},{"text":"Escurrir las patatas sobre papel absorbente y reservar.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Picar {{Chalota}} muy fina.","minutes":2,"kind":"paralelo","part":"salsa","during":2},{"text":"Salpimentar {{Presa ibérica}} por ambas caras.","minutes":1,"kind":"paralelo","part":"principal","during":2},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Plancha}} a fuego fuerte.","minutes":1,"kind":"activo","part":"principal"},{"text":"Dorar la presa ibérica 3 min por cada cara hasta alcanzar el punto deseado.","minutes":6,"kind":"activo","part":"principal"},{"text":"Retirar la presa ibérica y dejar reposar en un plato.","minutes":5,"kind":"espera","part":"principal"},{"text":"Sofreír la chalota picada en la misma plancha a fuego medio hasta que esté transparente.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Añadir {{Pimienta verde en grano}} y remover 1 min para que libere su aroma.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Verter {{Brandy}} y dejar evaporar el alcohol a fuego fuerte hasta que deje de humear.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Añadir {{Caldo de carne}} y {{Nata para cocinar}}; remover para integrar.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Cocer a fuego medio hasta que la salsa espese y nape la cuchara.","minutes":5,"kind":"pasivo","part":"salsa"},{"text":"Cortar la presa ibérica en lonchas de unos 2 cm.","minutes":1,"kind":"prep","part":"combinado"},{"text":"Servir las lonchas napadas con la salsa de pimienta verde y las patatas fritas al lado.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_110', 'Hamburguesa de solomillo con patatas fritas y salsa de queso azul', 'carnes', 'ternera', 'pan', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 850, 40, 52, 50, 2, false, false, '{"gluten","lactosa"}', '[{"name":"Solomillo de ternera picado","amount":350,"unit":"g"},{"name":"Pan de hamburguesa","amount":2,"unit":"ud"},{"name":"Queso azul","amount":60,"unit":"g"},{"name":"Nata para cocinar","amount":80,"unit":"ml"},{"name":"Lechuga","amount":40,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de girasol","amount":300,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Formar 2 hamburguesas con solomillo de ternera picado, salpimentar y reservar en la nevera.","Reposar las hamburguesas en la nevera para que asienten.","Pelar patata y cortar en bastones de grosor uniforme.","Calentar aceite de girasol en una olla a fuego fuerte hasta que alcance 180 °C.","Freír los bastones de patata en el aceite de girasol caliente hasta que estén dorados y crujientes.","Escurrir las patatas fritas sobre papel absorbente y salar al gusto.","Desmenuzar queso azul en un cazo pequeño y añadir nata para cocinar.","Calentar la mezcla a fuego suave, remover hasta que el queso azul se funda y la salsa esté homogénea.","Calentar aceite de oliva en plancha a fuego fuerte hasta que humee ligeramente.","Cocinar las hamburguesas en la plancha 3 min por cada lado hasta que estén doradas al punto deseado.","Tostar pan de hamburguesa por su cara interior en la plancha hasta que esté ligeramente dorado.","Laminar tomate y cebolla morada en rodajas finas; separar hojas de lechuga.","Colocar lechuga, tomate y cebolla morada sobre la base del pan de hamburguesa tostado.","Disponer la hamburguesa sobre las verduras y verter la salsa de queso azul por encima.","Cerrar con la tapa del pan de hamburguesa y servir con las patatas fritas al lado."}', 'Hamburguesa de solomillo de ternera con una cremosa salsa de queso azul, servida con patatas fritas.', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Prepara las patatas con un poco de aceite y cocínalas en la airfryer a 190°C durante 20-25 minutos. Luego, cocina las hamburguesas a 180°C por 12-15 minutos, dándoles la vuelta a mitad, para un exterior crujiente y un interior jugoso."},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Dispón las patatas y las hamburguesas en bandejas separadas con un poco de aceite. Hornea a 200°C durante 30-40 minutos para las patatas y 15-20 minutos para las hamburguesas, asegurando un cocinado uniforme."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Formar 2 hamburguesas con {{Solomillo de ternera picado}}, salpimentar y reservar en la nevera.","minutes":2,"kind":"prep","part":"principal"},{"text":"Reposar las hamburguesas en la nevera para que asienten.","minutes":10,"kind":"espera","part":"principal"},{"text":"Pelar {{Patata}} y cortar en bastones de grosor uniforme.","minutes":5,"kind":"paralelo","part":"guarnicion","during":1},{"text":"Calentar {{Aceite de girasol}} en una olla a fuego fuerte hasta que alcance 180 °C.","minutes":3,"kind":"paralelo","part":"guarnicion","during":1},{"text":"Freír los bastones de patata en el aceite de girasol caliente hasta que estén dorados y crujientes.","minutes":8,"kind":"pasivo","part":"guarnicion"},{"text":"Escurrir las patatas fritas sobre papel absorbente y salar al gusto.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Desmenuzar {{Queso azul}} en un cazo pequeño y añadir {{Nata para cocinar}}.","minutes":1,"kind":"paralelo","part":"salsa","during":4},{"text":"Calentar la mezcla a fuego suave, remover hasta que el queso azul se funda y la salsa esté homogénea.","minutes":4,"kind":"activo","part":"salsa"},{"text":"Calentar {{Aceite de oliva}} en {{@Plancha}} a fuego fuerte hasta que humee ligeramente.","minutes":1,"kind":"activo","part":"principal"},{"text":"Cocinar las hamburguesas en la plancha 3 min por cada lado hasta que estén doradas al punto deseado.","minutes":6,"kind":"activo","part":"principal"},{"text":"Tostar {{Pan de hamburguesa}} por su cara interior en la plancha hasta que esté ligeramente dorado.","minutes":1,"kind":"activo","part":"principal"},{"text":"Laminar {{Tomate}} y {{Cebolla morada}} en rodajas finas; separar hojas de {{Lechuga}}.","minutes":2,"kind":"prep","part":"combinado"},{"text":"Colocar lechuga, tomate y cebolla morada sobre la base del pan de hamburguesa tostado.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Disponer la hamburguesa sobre las verduras y verter la salsa de queso azul por encima.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Cerrar con la tapa del pan de hamburguesa y servir con las patatas fritas al lado.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_111', 'Costillas de cordero con puré de boniato y salsa de menta', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 630, 32, 34, 38, 2, true, true, '{"lactosa","sulfitos"}', '[{"name":"Costillas de cordero (chuletillas)","amount":400,"unit":"g"},{"name":"Boniato","amount":350,"unit":"g"},{"name":"Leche","amount":80,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Menta fresca","amount":15,"unit":"g"},{"name":"Azúcar","amount":15,"unit":"g"},{"name":"Vinagre de vino blanco","amount":20,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Pelar boniato y cortar en trozos medianos.","Cocer el boniato en agua con sal hasta que esté tierno.","Laminar ajo.","Picar menta fresca muy fina.","Mezclar la menta picada con vinagre de vino blanco y azúcar en un cazo.","Calentar el cazo a fuego suave hasta que el azúcar se disuelva.","Retirar el cazo del fuego y reservar la salsa de menta para que temple.","Salpimentar costillas de cordero (chuletillas) y dejar atemperar.","Escurrir el boniato cocido.","Calentar leche en el cazo a fuego suave hasta que esté caliente.","Triturar el boniato escurrido con la leche caliente y mantequilla hasta obtener un puré fino.","Salpimentar el puré y reservar tapado.","Calentar aceite de oliva en sartén a fuego fuerte.","Añadir el ajo laminado y sofreír hasta que empiece a dorarse.","Añadir las costillas y dorar 2 min por cada lado hasta que estén doradas por fuera y rosadas por dentro.","Retirar las costillas de la sartén y dejar reposar.","Servir las costillas sobre el puré de boniato y rociar con la salsa de menta."}', 'Costillas de cordero doradas a la plancha, servidas sobre puré de boniato y con una salsa fresca de menta.', '[{"appliance":"airfryer","time":30,"difficulty":"normal","prepSummary":"Cocina las chuletillas a 190-200°C por 12-15 min, volteando a mitad, para un exterior crujiente. Asa el boniato en cubos a 180°C por 15-20 min hasta que esté tierno para el puré."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Asa el boniato en trozos y las chuletillas de cordero en el horno precalentado a 200-220°C. El boniato tardará unos 30-40 min y las chuletillas 15-20 min, volteándolas para un dorado uniforme."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Boniato}} y cortar en trozos medianos.","minutes":3,"kind":"prep","part":"guarnicion"},{"text":"Cocer el boniato en agua con sal hasta que esté tierno.","minutes":15,"kind":"pasivo","part":"guarnicion"},{"text":"Laminar {{Ajo}}.","minutes":1,"kind":"paralelo","part":"principal","during":1},{"text":"Picar {{Menta fresca}} muy fina.","minutes":2,"kind":"paralelo","part":"salsa","during":1},{"text":"Mezclar la menta picada con {{Vinagre de vino blanco}} y {{Azúcar}} en un cazo.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Calentar el cazo a fuego suave hasta que el azúcar se disuelva.","minutes":3,"kind":"pasivo","part":"salsa"},{"text":"Retirar el cazo del fuego y reservar la salsa de menta para que temple.","minutes":1,"kind":"espera","part":"salsa"},{"text":"Salpimentar {{Costillas de cordero (chuletillas)}} y dejar atemperar.","minutes":2,"kind":"prep","part":"principal"},{"text":"Escurrir el boniato cocido.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Calentar {{Leche}} en el cazo a fuego suave hasta que esté caliente.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Triturar el boniato escurrido con la leche caliente y {{Mantequilla}} hasta obtener un puré fino.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Salpimentar el puré y reservar tapado.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo","part":"principal"},{"text":"Añadir el ajo laminado y sofreír hasta que empiece a dorarse.","minutes":1,"kind":"activo","part":"principal"},{"text":"Añadir las costillas y dorar 2 min por cada lado hasta que estén doradas por fuera y rosadas por dentro.","minutes":4,"kind":"activo","part":"principal"},{"text":"Retirar las costillas de la sartén y dejar reposar.","minutes":2,"kind":"espera","part":"principal"},{"text":"Servir las costillas sobre el puré de boniato y rociar con la salsa de menta.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_112', 'Pollo Marry Me con tomate seco y parmesano', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 30, 'normal', 'all', 500, 38, 8, 32, 2, true, true, '{"lactosa"}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Tomate seco en aceite","amount":40,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Nata para cocinar","amount":200,"unit":"ml"},{"name":"Caldo de pollo","amount":100,"unit":"ml"},{"name":"Parmesano rallado","amount":40,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Albahaca fresca","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Cortar pechuga de pollo en filetes de grosor uniforme.","Salpimentar los filetes por ambas caras.","Picar ajo fino.","Cortar tomate seco en aceite en tiras pequeñas.","Calentar aceite de oliva en sartén a fuego fuerte.","Dorar los filetes de pollo 3 min por cada cara hasta que estén dorados. Reservar.","Sofreír el ajo picado y el tomate seco en la misma sartén a fuego medio hasta que estén fragantes.","Añadir pimentón dulce y remover para integrarlo con el sofrito.","Añadir caldo de pollo y nata para cocinar y remover para mezclar bien.","Añadir parmesano rallado y remover hasta que se integre en la salsa.","Cocer la salsa a fuego medio hasta que espese, unos 4 min.","Incorporar los filetes de pollo reservados y napar con la salsa.","Cocer a fuego suave 3 min hasta que el pollo esté bien caliente y la salsa lo cubra.","Picar albahaca fresca fina y espolvorear sobre el plato. Servir de inmediato."}', 'Pechuga de pollo en una salsa cremosa de tomate seco y parmesano, el viral que promete pedida de mano.', '[{"appliance":"horno","time":35,"difficulty":"normal","prepSummary":"Sella las pechugas en una sartén y luego pásalas a una fuente apta para horno. Vierte la salsa con el resto de ingredientes (excepto albahaca) sobre el pollo y hornea a 190°C durante 20-25 minutos, hasta que el pollo esté cocido y la salsa burbujeante. Un truco es cubrir la fuent"},{"appliance":"thermomix","time":28,"difficulty":"facil","prepSummary":"Trocea el ajo y sofríelo. Añade las pechugas troceadas y sofríe hasta que doren. Incorpora el resto de ingredientes (excepto albahaca y parte del parmesano), programa 18-20 min a 90°C, giro inverso, velocidad cuchara. El truco es añadir el parmesano y la albahaca al final para ma"},{"appliance":"olla_express","time":20,"difficulty":"normal","prepSummary":"Sella las pechugas de pollo en la olla. Añade el tomate seco, ajo, nata, caldo y pimentón. Cierra la olla y cocina a presión alta durante 5-7 minutos. Despresuriza, retira el pollo, y si la salsa está líquida, reduce a fuego alto unos minutos. El truco es no sobrecocer el pollo p"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Pechuga de pollo}} en filetes de grosor uniforme.","minutes":3,"kind":"prep"},{"text":"Salpimentar los filetes por ambas caras.","minutes":1,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Cortar {{Tomate seco en aceite}} en tiras pequeñas.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Dorar los filetes de pollo 3 min por cada cara hasta que estén dorados. Reservar.","minutes":6,"kind":"activo"},{"text":"Sofreír el ajo picado y el tomate seco en la misma sartén a fuego medio hasta que estén fragantes.","minutes":2,"kind":"activo"},{"text":"Añadir {{Pimentón dulce|pizca}} y remover para integrarlo con el sofrito.","minutes":1,"kind":"activo"},{"text":"Añadir {{Caldo de pollo}} y {{Nata para cocinar}} y remover para mezclar bien.","minutes":1,"kind":"activo"},{"text":"Añadir {{Parmesano rallado}} y remover hasta que se integre en la salsa.","minutes":1,"kind":"activo"},{"text":"Cocer la salsa a fuego medio hasta que espese, unos 4 min.","minutes":4,"kind":"pasivo"},{"text":"Incorporar los filetes de pollo reservados y napar con la salsa.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave 3 min hasta que el pollo esté bien caliente y la salsa lo cubra.","minutes":3,"kind":"pasivo"},{"text":"Picar {{Albahaca fresca}} fina y espolvorear sobre el plato. Servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_113', 'Alitas de pollo al gochujang', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, 'horno', 50, 'normal', 'all', 560, 34, 22, 34, 2, false, true, '{"soja","sesamo","gluten"}', '[{"name":"Alitas de pollo","amount":600,"unit":"g"},{"name":"Gochujang","amount":40,"unit":"g"},{"name":"Salsa de soja","amount":20,"unit":"ml"},{"name":"Miel","amount":30,"unit":"g"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Jengibre fresco","amount":8,"unit":"g"},{"name":"Sésamo tostado","amount":5,"unit":"g"},{"name":"Cebolleta","amount":10,"unit":"g"},{"name":"Aceite de girasol","amount":15,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Picar ajo y jengibre fresco muy finos.","Mezclar gochujang, salsa de soja, miel, aceite de sésamo, el ajo picado y el jengibre picado en un bol hasta obtener una salsa homogénea.","Picar cebolleta fina y reservar.","Secar alitas de pollo con papel de cocina y colocarlas en una bandeja con papel de horno.","Rociar las alitas con aceite de girasol y salpimentar.","Hornear las alitas a 200 °C durante 30 min, dándoles la vuelta a los 15 min, hasta que estén doradas.","Retirar las alitas del horno y pincelarlas generosamente con la mezcla de gochujang por ambos lados.","Devolver las alitas al horno a 200 °C durante 8 min, hasta que el glaseado esté pegajoso y caramelizado.","Servir las alitas espolvoreadas con sésamo tostado y la cebolleta picada."}', 'Alitas de pollo horneadas hasta quedar crujientes y glaseadas con gochujang, dulce y picante a la vez.', '[{"appliance":"airfryer","time":25,"difficulty":"normal","prepSummary":"Marinar las alitas con la mezcla de gochujang. Cocinar en la airfryer a 190°C durante 20-25 minutos, volteándolas a mitad de cocción para asegurar un dorado uniforme y una piel crujiente."},{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Tras marinar las alitas, hornear a 200°C (con ventilador si es posible) durante 45-50 minutos. Voltear las alitas una o dos veces y pincelar con la salsa durante los últimos minutos para un glaseado perfecto."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Picar {{Ajo}} y {{Jengibre fresco}} muy finos.","minutes":3,"kind":"prep"},{"text":"Mezclar {{Gochujang}}, {{Salsa de soja}}, {{Miel}}, {{Aceite de sésamo}}, el ajo picado y el jengibre picado en un bol hasta obtener una salsa homogénea.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolleta}} fina y reservar.","minutes":1,"kind":"prep"},{"text":"Secar {{Alitas de pollo}} con papel de cocina y colocarlas en una bandeja con papel de horno.","minutes":2,"kind":"prep"},{"text":"Rociar las alitas con {{Aceite de girasol}} y salpimentar.","minutes":1,"kind":"prep"},{"text":"Hornear las alitas a 200 °C durante 30 min, dándoles la vuelta a los 15 min, hasta que estén doradas.","minutes":30,"kind":"pasivo"},{"text":"Retirar las alitas del horno y pincelarlas generosamente con la mezcla de gochujang por ambos lados.","minutes":2,"kind":"activo"},{"text":"Devolver las alitas al horno a 200 °C durante 8 min, hasta que el glaseado esté pegajoso y caramelizado.","minutes":8,"kind":"pasivo"},{"text":"Servir las alitas espolvoreadas con {{Sésamo tostado}} y la cebolleta picada.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_114', 'Costillas coreanas glaseadas (estilo galbi)', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, 'horno', 150, 'normal', 'all', 560, 32, 24, 34, 2, true, true, '{"soja","sesamo"}', '[{"name":"Costillas de ternera (corte fino estilo galbi)","amount":600,"unit":"g"},{"name":"Salsa de soja","amount":80,"unit":"ml"},{"name":"Pera","amount":100,"unit":"g"},{"name":"Azúcar moreno","amount":40,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Aceite de sésamo","amount":15,"unit":"ml"},{"name":"Sésamo tostado","amount":8,"unit":"g"},{"name":"Cebolleta","amount":15,"unit":"g"}]'::jsonb, '{"Pelar pera y cortar en trozos.","Pelar ajo y jengibre fresco.","Triturar la pera, el ajo y el jengibre hasta obtener un puré fino.","Añadir salsa de soja, azúcar moreno y aceite de sésamo al puré y mezclar hasta integrar.","Sumergir costillas de ternera (corte fino estilo galbi) en la marinada, cubrir y refrigerar mínimo 120 min.","Precalentar el horno a 200 °C.","Retirar las costillas de la marinada y escurrir, reservando la marinada sobrante.","Picar cebolleta fina y reservar.","Colocar las costillas escurridas en una bandeja con papel de horno.","Hornear las costillas a 200 °C durante 20 min.","Retirar la bandeja del horno y pincelar las costillas con la marinada reservada.","Hornear de nuevo a 200 °C durante 15 min, hasta que estén doradas y el glaseado pegajoso.","Retirar las costillas del horno y dejar reposar 3 min.","Servir las costillas espolvoreadas con sésamo tostado y la cebolleta picada."}', 'Costillas de ternera cortadas finas y marinadas al estilo coreano, horneadas hasta quedar pegajosas y glaseadas.', '[{"appliance":"horno","time":150,"difficulty":"normal","prepSummary":"Marinar las costillas al menos 4 horas. Hornear a 160°C durante 120 minutos, luego subir a 180-200°C los últimos 30 minutos, pintando con la marinada reducida para un glaseado perfecto y tierno."},{"appliance":"airfryer","time":40,"difficulty":"normal","prepSummary":"Marinar bien las costillas. Cocinar en la airfryer a 180°C durante 35-45 minutos, volteando cada 10-15 minutos y pincelando con la marinada para lograr un glaseado crujiente y tierno."},{"appliance":"olla_express","time":50,"difficulty":"normal","prepSummary":"Marinar las costillas. Cocer en la olla express con parte de la marinada durante 30-35 minutos a presión para ablandar. Luego, terminar en el horno o airfryer a alta temperatura (200°C) durante 15-20 minutos para caramelizar el glaseado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Pera}} y cortar en trozos.","minutes":2,"kind":"prep"},{"text":"Pelar {{Ajo}} y {{Jengibre fresco}}.","minutes":2,"kind":"prep"},{"text":"Triturar la pera, el ajo y el jengibre hasta obtener un puré fino.","minutes":2,"kind":"activo"},{"text":"Añadir {{Salsa de soja}}, {{Azúcar moreno}} y {{Aceite de sésamo}} al puré y mezclar hasta integrar.","minutes":2,"kind":"activo"},{"text":"Sumergir {{Costillas de ternera (corte fino estilo galbi)}} en la marinada, cubrir y refrigerar mínimo 120 min.","minutes":120,"kind":"espera"},{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Retirar las costillas de la marinada y escurrir, reservando la marinada sobrante.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolleta}} fina y reservar.","minutes":2,"kind":"prep"},{"text":"Colocar las costillas escurridas en una bandeja con papel de horno.","minutes":2,"kind":"activo"},{"text":"Hornear las costillas a 200 °C durante 20 min.","minutes":20,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y pincelar las costillas con la marinada reservada.","minutes":2,"kind":"activo"},{"text":"Hornear de nuevo a 200 °C durante 15 min, hasta que estén doradas y el glaseado pegajoso.","minutes":15,"kind":"pasivo"},{"text":"Retirar las costillas del horno y dejar reposar 3 min.","minutes":3,"kind":"espera"},{"text":"Servir las costillas espolvoreadas con {{Sésamo tostado}} y la cebolleta picada.","minutes":1,"kind":"emplatado"}]'::jsonb, true)
