insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('carnes_115', 'Smash burger con queso cheddar doble', 'carnes', 'ternera', 'pan', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 800, 38, 40, 52, 2, true, false, '{"gluten","lactosa","huevo"}', '[{"name":"Carne picada de ternera","amount":300,"unit":"g"},{"name":"Pan de hamburguesa","amount":2,"unit":"ud"},{"name":"Queso cheddar (lonchas)","amount":4,"unit":"ud"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Pepinillos en rodajas","amount":20,"unit":"g"},{"name":"Ketchup","amount":20,"unit":"g"},{"name":"Mostaza americana","amount":15,"unit":"g"},{"name":"Mayonesa","amount":20,"unit":"g"}]'::jsonb, '{"Dividir carne picada de ternera en 4 porciones iguales y formar bolas.","Salpimentar las 4 bolas de carne por todos los lados.","Laminar cebolla en juliana muy fina.","Mezclar ketchup, mostaza americana y mayonesa en un bol pequeño hasta integrar. Reservar.","Calentar plancha a fuego fuerte hasta que humee.","Fundir mantequilla en plancha a fuego medio.","Tostar pan de hamburguesa por la cara interior hasta que esté dorado. Reservar.","Subir el fuego a fuego fuerte y colocar las 4 bolas de carne en plancha dejando espacio entre ellas.","Aplastar cada bola con una espátula firme hasta dejarla muy fina, formando un borde crujiente.","Cocer las hamburguesas sin moverlas durante 2 min hasta que los bordes estén bien dorados.","Dar la vuelta a cada hamburguesa con la espátula.","Colocar 1 loncha de queso cheddar (lonchas) sobre cada hamburguesa.","Cocer 1 min más hasta que el queso cheddar se funda completamente.","Extender la mezcla de salsas sobre la base de pan tostado.","Añadir la cebolla en juliana y pepinillos en rodajas sobre la salsa.","Apilar 2 hamburguesas con queso por ración sobre los pepinillos.","Cerrar con la tapa de pan tostado y servir de inmediato."}', 'Dos capas de carne aplastada en la plancha con bordes crujientes, dobles de queso cheddar fundido, entre pan de hamburguesa.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Para las smash burgers, precalienta la airfryer a 200°C. Aplasta bien la carne y cocina cada patty 4-5 minutos, dándole la vuelta y añadiendo el queso al final para que se funda. Tuesta los panes brevemente."},{"appliance":"horno","time":22,"difficulty":"normal","prepSummary":"Precalienta el horno a 230°C con una bandeja de hierro fundido o una bandeja de hornear boca abajo dentro. Coloca las patties aplastadas en la bandeja muy caliente y cocina 3-4 minutos por lado, añadiendo el queso al final. Tuesta los panes aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Dividir {{Carne picada de ternera}} en 4 porciones iguales y formar bolas.","minutes":2,"kind":"prep"},{"text":"Salpimentar las 4 bolas de carne por todos los lados.","minutes":1,"kind":"prep"},{"text":"Laminar {{Cebolla}} en juliana muy fina.","minutes":2,"kind":"prep"},{"text":"Mezclar {{Ketchup}}, {{Mostaza americana}} y {{Mayonesa}} en un bol pequeño hasta integrar. Reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que humee.","minutes":2,"kind":"activo"},{"text":"Fundir {{Mantequilla}} en {{@Plancha}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Tostar {{Pan de hamburguesa}} por la cara interior hasta que esté dorado. Reservar.","minutes":1,"kind":"activo"},{"text":"Subir el fuego a fuego fuerte y colocar las 4 bolas de carne en {{@Plancha}} dejando espacio entre ellas.","minutes":1,"kind":"activo"},{"text":"Aplastar cada bola con una espátula firme hasta dejarla muy fina, formando un borde crujiente.","minutes":1,"kind":"activo"},{"text":"Cocer las hamburguesas sin moverlas durante 2 min hasta que los bordes estén bien dorados.","minutes":2,"kind":"pasivo"},{"text":"Dar la vuelta a cada hamburguesa con la espátula.","minutes":1,"kind":"activo"},{"text":"Colocar 1 loncha de {{Queso cheddar (lonchas)}} sobre cada hamburguesa.","minutes":1,"kind":"activo"},{"text":"Cocer 1 min más hasta que el queso cheddar se funda completamente.","minutes":1,"kind":"pasivo"},{"text":"Extender la mezcla de salsas sobre la base de pan tostado.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Añadir la cebolla en juliana y {{Pepinillos en rodajas}} sobre la salsa.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Apilar 2 hamburguesas con queso por ración sobre los pepinillos.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Cerrar con la tapa de pan tostado y servir de inmediato.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_116', 'Callos a la madrileña', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 210, 'facil', 'invierno', 480, 30, 18, 30, 4, false, true, '{"sulfitos"}', '[{"name":"Callos de ternera limpios","amount":1000,"unit":"g"},{"name":"Pata de ternera","amount":300,"unit":"g"},{"name":"Chorizo","amount":150,"unit":"g"},{"name":"Morcilla","amount":150,"unit":"g"},{"name":"Jamón","amount":80,"unit":"g"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"g"},{"name":"Pimentón dulce","amount":10,"unit":"g"},{"name":"Pimentón picante","amount":3,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Laurel","amount":2,"unit":"ud"},{"name":"Guindilla","amount":1,"unit":"ud"},{"name":"Vino blanco","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"}]'::jsonb, '{"Cortar chorizo y morcilla en rodajas gruesas y jamón en trozos pequeños. Reservar.","Picar cebolla fina y ajo fino. Reservar por separado.","Llevar a ebullición una olla grande con abundante agua. Añadir callos de ternera limpios y pata de ternera.","Escaldar los callos y la pata 5 min. Escurrir y enjuagar bajo agua fría hasta que estén limpios.","Colocar los callos y la pata en la olla limpios, cubiertos de agua fría. Añadir la mitad de la cebolla picada, laurel y vino blanco.","Cocer a fuego suave tapado, espumando de vez en cuando, hasta que los callos y la pata estén tiernos.","Calentar aceite de oliva en una cazuela a fuego medio. Sofreír la cebolla picada restante hasta que esté blanda.","Añadir el ajo picado y sofreír junto a la cebolla hasta que esté dorado, sin que se queme.","Retirar la cazuela del fuego. Añadir pimentón dulce y pimentón picante y remover rápido para que no se quemen.","Volver la cazuela al fuego suave. Añadir tomate triturado y remover para integrar con el sofrito.","Cocer el sofrito a fuego suave hasta que el tomate pierda el agua y quede concentrado.","Incorporar el chorizo, la morcilla y el jamón troceados al sofrito. Remover para integrar.","Sofreír el conjunto a fuego medio hasta que el chorizo y la morcilla suelten su grasa.","Escurrir los callos y la pata cocidos, reservando el caldo de cocción colado. Añadirlos a la cazuela.","Añadir guindilla a la cazuela junto con el laurel ya cocido recuperado del caldo.","Cubrir con el caldo de cocción colado hasta que los callos queden justos cubiertos. Remover con suavidad.","Cocer a fuego suave tapado hasta que la salsa espese y quede untuosa.","Retirar del fuego y dejar reposar tapado para que los sabores se asienten.","Servir los callos bien calientes en cazuela o plato hondo."}', 'Guiso tradicional madrileño de callos, chorizo y morcilla en una salsa untuosa de pimentón, que mejora de un día para otro.', '[{"appliance":"horno","time":270,"difficulty":"normal","prepSummary":"Tras un sofrito inicial en la cazuela, se añaden todos los ingredientes y se cocinan cubiertos en el horno precalentado a 150-160°C durante 3.5-4 horas, logrando una cocción lenta y uniforme que ablanda los callos y la pata."},{"appliance":"olla_express","time":100,"difficulty":"normal","prepSummary":"Se realiza un sofrito en la propia olla, se incorporan el resto de ingredientes con el vino y se cocinan a presión alta durante 45-60 minutos. Luego se despresuriza y se deja reducir a fuego lento unos minutos para espesar la salsa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], true, '[{"text":"Cortar {{Chorizo}} y {{Morcilla}} en rodajas gruesas y {{Jamón}} en trozos pequeños. Reservar.","minutes":5,"kind":"prep"},{"text":"Picar {{Cebolla}} fina y {{Ajo}} fino. Reservar por separado.","minutes":5,"kind":"prep"},{"text":"Llevar a ebullición una olla grande con abundante agua. Añadir {{Callos de ternera limpios}} y {{Pata de ternera}}.","minutes":2,"kind":"activo"},{"text":"Escaldar los callos y la pata 5 min. Escurrir y enjuagar bajo agua fría hasta que estén limpios.","minutes":5,"kind":"pasivo"},{"text":"Colocar los callos y la pata en la olla limpios, cubiertos de agua fría. Añadir la mitad de la cebolla picada, {{Laurel}} y {{Vino blanco}}.","minutes":3,"kind":"activo"},{"text":"Cocer a fuego suave tapado, espumando de vez en cuando, hasta que los callos y la pata estén tiernos.","minutes":120,"kind":"pasivo"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela a fuego medio. Sofreír la cebolla picada restante hasta que esté blanda.","minutes":10,"kind":"activo"},{"text":"Añadir el ajo picado y sofreír junto a la cebolla hasta que esté dorado, sin que se queme.","minutes":3,"kind":"activo"},{"text":"Retirar la cazuela del fuego. Añadir {{Pimentón dulce}} y {{Pimentón picante}} y remover rápido para que no se quemen.","minutes":1,"kind":"activo"},{"text":"Volver la cazuela al fuego suave. Añadir {{Tomate triturado}} y remover para integrar con el sofrito.","minutes":2,"kind":"activo"},{"text":"Cocer el sofrito a fuego suave hasta que el tomate pierda el agua y quede concentrado.","minutes":10,"kind":"pasivo"},{"text":"Incorporar el chorizo, la morcilla y el jamón troceados al sofrito. Remover para integrar.","minutes":3,"kind":"activo"},{"text":"Sofreír el conjunto a fuego medio hasta que el chorizo y la morcilla suelten su grasa.","minutes":5,"kind":"activo"},{"text":"Escurrir los callos y la pata cocidos, reservando el caldo de cocción colado. Añadirlos a la cazuela.","minutes":3,"kind":"activo"},{"text":"Añadir {{Guindilla}} a la cazuela junto con el laurel ya cocido recuperado del caldo.","minutes":1,"kind":"activo"},{"text":"Cubrir con el caldo de cocción colado hasta que los callos queden justos cubiertos. Remover con suavidad.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego suave tapado hasta que la salsa espese y quede untuosa.","minutes":55,"kind":"pasivo"},{"text":"Retirar del fuego y dejar reposar tapado para que los sabores se asienten.","minutes":15,"kind":"espera"},{"text":"Servir los callos bien calientes en cazuela o plato hondo.","minutes":2,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_117', 'Hígado encebollado', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 420, 28, 20, 24, 2, false, false, '{"gluten","sulfitos"}', '[{"name":"Hígado de ternera","amount":350,"unit":"g"},{"name":"Cebolla","amount":300,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Vino blanco","amount":30,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"}]'::jsonb, '{"Cortar cebolla en juliana fina.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla a fuego suave hasta que esté muy blanda y dorada.","Cortar hígado de ternera en filetes finos.","Salpimentar los filetes de hígado de ternera.","Enharinar los filetes con harina, sacudiendo el exceso.","Picar ajo fino.","Picar perejil fresco fino.","Retirar la cebolla de la sartén y reservar en un plato.","Añadir aceite de oliva a la misma sartén y subir a fuego fuerte.","Dorar el hígado de ternera enharinado 1-2 min por cada lado hasta que esté sellado.","Añadir el ajo picado y remover 30 segundos hasta que empiece a dorarse.","Añadir vino blanco y remover hasta que se evapore el alcohol.","Incorporar la cebolla reservada y mezclar hasta que todo esté caliente.","Espolvorear con el perejil picado y servir enseguida."}', 'Lonchas de hígado de ternera doradas entre cebolla muy pochada, un clásico que se prepara en un momento.', '[{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Pica el ajo y perejil. Sofríe la cebolla picada con aceite a 120°C/Varoma, velocidad cuchara, durante 15-20 minutos hasta que esté muy tierna. Añade el hígado enharinado, el vino y el ajo, y cocina a 100°C, giro inverso, velocidad cuchara, 5-7 minutos. Sirve con perejil fresco."},{"appliance":"olla_express","time":20,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en la olla abierta hasta que estén tiernos. Dora el hígado enharinado rápidamente, añade el vino y cierra la olla. Cocina 1-2 minutos desde que sube la presión. Libera la presión, rectifica la salsa y termina con perejil."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Cebolla}} en juliana fina.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla a fuego suave hasta que esté muy blanda y dorada.","minutes":15,"kind":"pasivo"},{"text":"Cortar {{Hígado de ternera}} en filetes finos.","minutes":2,"kind":"paralelo","during":2},{"text":"Salpimentar los filetes de hígado de ternera.","minutes":1,"kind":"paralelo","during":2},{"text":"Enharinar los filetes con {{Harina}}, sacudiendo el exceso.","minutes":1,"kind":"paralelo","during":2},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"paralelo","during":2},{"text":"Picar {{Perejil fresco}} fino.","minutes":1,"kind":"paralelo","during":2},{"text":"Retirar la cebolla de la sartén y reservar en un plato.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} a la misma sartén y subir a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Dorar el hígado de ternera enharinado 1-2 min por cada lado hasta que esté sellado.","minutes":3,"kind":"activo"},{"text":"Añadir el ajo picado y remover 30 segundos hasta que empiece a dorarse.","minutes":1,"kind":"activo"},{"text":"Añadir {{Vino blanco}} y remover hasta que se evapore el alcohol.","minutes":1,"kind":"activo"},{"text":"Incorporar la cebolla reservada y mezclar hasta que todo esté caliente.","minutes":1,"kind":"activo"},{"text":"Espolvorear con el perejil picado y servir enseguida.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_118', 'Manitas de cerdo guisadas', 'carnes', 'cerdo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 200, 'normal', 'invierno', 420, 26, 15, 26, 4, false, true, '{"gluten","sulfitos"}', '[{"name":"Manitas de cerdo partidas por la mitad","amount":1200,"unit":"g"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Zanahoria","amount":150,"unit":"g"},{"name":"Puerro","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"g"},{"name":"Vino blanco","amount":100,"unit":"ml"},{"name":"Pimentón dulce","amount":8,"unit":"g"},{"name":"Laurel","amount":2,"unit":"ud"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Caldo de carne","amount":500,"unit":"ml"}]'::jsonb, '{"Chamuscar manitas de cerdo partidas por la mitad con un soplete o llama para eliminar los pelos restantes.","Enjuagar las manitas bajo agua fría hasta que el agua salga limpia.","Llevar a ebullición agua abundante en una olla grande e introducir las manitas.","Escaldar las manitas 5 min desde que rompa a hervir, escurrir y reservar.","Pelar y picar cebolla, zanahoria, puerro y ajo en trozos finos.","Calentar aceite de oliva en una olla grande a fuego medio.","Sofreír la cebolla, la zanahoria, el puerro y el ajo picados hasta que estén tiernos y ligeramente dorados.","Retirar la olla del fuego y añadir pimentón dulce, removiendo rápido para que no se queme.","Añadir tomate triturado y harina, mezclar bien y volver al fuego medio.","Cocer el conjunto removiendo sin parar durante 2 min hasta que la harina pierda el sabor a crudo.","Incorporar las manitas escaldadas, vino blanco y laurel; subir a fuego fuerte.","Dejar reducir el alcohol 2 min sin tapar, removiendo de vez en cuando.","Verter caldo de carne, tapar la olla y bajar a fuego suave.","Cocer a fuego suave tapado durante 150 min hasta que las manitas estén muy tiernas y la salsa untuosa.","Retirar el laurel y rectificar de sal si fuera necesario.","Reposar el guiso tapado fuera del fuego 10 min antes de servir.","Servir las manitas con abundante salsa por encima."}', 'Manitas de cerdo guisadas lentamente hasta quedar gelatinosas y untuosas, el clásico guiso de invierno de toda la vida.', '[{"appliance":"horno","time":210,"difficulty":"normal","prepSummary":"Sella las manitas y sofríe las verduras en una cazuela apta para horno. Añade el resto de ingredientes y cocina tapado a 160-170°C durante 3-3.5 horas, removiendo ocasionalmente para una cocción uniforme y tierna."},{"appliance":"thermomix","time":180,"difficulty":"normal","prepSummary":"Pica y sofríe las verduras en el vaso. Incorpora las manitas selladas, el resto de ingredientes y cocina a 95°C, giro inverso, velocidad cuchara durante 180 minutos para una cocción controlada y homogénea."},{"appliance":"olla_express","time":80,"difficulty":"normal","prepSummary":"Sella las manitas y sofríe las verduras en la olla. Añade el resto de ingredientes y cocina a presión durante 45-60 minutos desde que sube la válvula, logrando una ternura perfecta en una fracción del tiempo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Chamuscar {{Manitas de cerdo partidas por la mitad}} con un soplete o llama para eliminar los pelos restantes.","minutes":5,"kind":"prep"},{"text":"Enjuagar las manitas bajo agua fría hasta que el agua salga limpia.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición agua abundante en una olla grande e introducir las manitas.","minutes":2,"kind":"activo"},{"text":"Escaldar las manitas 5 min desde que rompa a hervir, escurrir y reservar.","minutes":5,"kind":"pasivo"},{"text":"Pelar y picar {{Cebolla}}, {{Zanahoria}}, {{Puerro}} y {{Ajo}} en trozos finos.","minutes":8,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla grande a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla, la zanahoria, el puerro y el ajo picados hasta que estén tiernos y ligeramente dorados.","minutes":12,"kind":"activo"},{"text":"Retirar la olla del fuego y añadir {{Pimentón dulce}}, removiendo rápido para que no se queme.","minutes":1,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y {{Harina}}, mezclar bien y volver al fuego medio.","minutes":1,"kind":"activo"},{"text":"Cocer el conjunto removiendo sin parar durante 2 min hasta que la harina pierda el sabor a crudo.","minutes":2,"kind":"activo"},{"text":"Incorporar las manitas escaldadas, {{Vino blanco}} y {{Laurel}}; subir a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Dejar reducir el alcohol 2 min sin tapar, removiendo de vez en cuando.","minutes":2,"kind":"activo"},{"text":"Verter {{Caldo de carne}}, tapar la olla y bajar a fuego suave.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave tapado durante 150 min hasta que las manitas estén muy tiernas y la salsa untuosa.","minutes":150,"kind":"pasivo"},{"text":"Retirar el laurel y rectificar de sal si fuera necesario.","minutes":1,"kind":"activo"},{"text":"Reposar el guiso tapado fuera del fuego 10 min antes de servir.","minutes":10,"kind":"espera"},{"text":"Servir las manitas con abundante salsa por encima.","minutes":2,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_119', 'Wrap de pollo crujiente, aguacate y salsa césar', 'carnes', 'pollo', 'pan', ARRAY['segundo','plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 700, 34, 48, 38, 2, true, false, '{"gluten","huevo","lactosa","pescado","mostaza"}', '[{"name":"Pechuga de pollo","amount":300,"unit":"g"},{"name":"Pan rallado","amount":60,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Aceite de girasol","amount":200,"unit":"ml"},{"name":"Tortillas de trigo grandes","amount":2,"unit":"ud"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Lechuga","amount":60,"unit":"g"},{"name":"Tomate","amount":60,"unit":"g"},{"name":"Yogur natural","amount":40,"unit":"g"},{"name":"Parmesano rallado","amount":15,"unit":"g"},{"name":"Anchoas en aceite","amount":8,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Mostaza de Dijon","amount":5,"unit":"g"}]'::jsonb, '{"Cortar pechuga de pollo en tiras de unos 2 cm de grosor y salpimentar.","Batir huevo en un bol.","Pasar cada tira de pollo por harina, luego por el huevo batido y finalmente por pan rallado, presionando para que el rebozado se adhiera bien.","Calentar aceite de girasol en sartén a fuego fuerte hasta que alcance unos 175 °C.","Freír las tiras de pollo rebozadas hasta que estén doradas y crujientes por fuera y cocidas por dentro.","Escurrir el pollo frito sobre papel absorbente y reservar.","Triturar yogur natural, parmesano rallado, anchoas en aceite, ajo, zumo de limón y mostaza de dijon hasta obtener una salsa homogénea.","Laminar aguacate, cortar lechuga en juliana y cortar tomate en dados.","Calentar tortillas de trigo grandes en sartén a fuego medio, 30 segundos por cada lado, hasta que estén flexibles.","Repartir la lechuga, el tomate y el aguacate sobre cada tortilla.","Colocar las tiras de pollo crujiente sobre las verduras y salsear con la salsa césar.","Enrollar cada tortilla bien apretada formando un wrap y cortar por la mitad en diagonal para servir."}', 'Tortilla rellena de pollo crujiente, aguacate fresco y una cremosa salsa césar casera, lista en dos minutos de montaje.', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Para el pollo crujiente, precalienta la airfryer a 190-200°C. Rocía el pollo empanado con un poco de aceite y cocina durante 15-20 minutos, dándole la vuelta a mitad, hasta que esté dorado y crujiente. Prepara la salsa mezclando el resto de ingredientes."},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Para el pollo crujiente, precalienta el horno a 200-220°C con calor arriba y abajo. Coloca el pollo empanado en una bandeja con papel de horno, rocía con un poco de aceite y hornea durante 20-25 minutos, volteando a mitad, hasta que esté dorado y crujiente. La salsa se prepara me"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['pescado_azul']::main_protein[], false, '[{"text":"Cortar {{Pechuga de pollo}} en tiras de unos 2 cm de grosor y salpimentar.","minutes":3,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol.","minutes":1,"kind":"prep"},{"text":"Pasar cada tira de pollo por {{Harina}}, luego por el huevo batido y finalmente por {{Pan rallado}}, presionando para que el rebozado se adhiera bien.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de girasol}} en {{@Sartén}} a fuego fuerte hasta que alcance unos 175 °C.","minutes":2,"kind":"activo"},{"text":"Freír las tiras de pollo rebozadas hasta que estén doradas y crujientes por fuera y cocidas por dentro.","minutes":4,"kind":"activo"},{"text":"Escurrir el pollo frito sobre papel absorbente y reservar.","minutes":1,"kind":"prep"},{"text":"Triturar {{Yogur natural}}, {{Parmesano rallado}}, {{Anchoas en aceite}}, {{Ajo}}, {{Zumo de limón}} y {{Mostaza de Dijon}} hasta obtener una salsa homogénea.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Laminar {{Aguacate}}, cortar {{Lechuga}} en juliana y cortar {{Tomate}} en dados.","minutes":3,"kind":"prep","part":"combinado"},{"text":"Calentar {{Tortillas de trigo grandes}} en {{@Sartén}} a fuego medio, 30 segundos por cada lado, hasta que estén flexibles.","minutes":1,"kind":"activo","part":"combinado"},{"text":"Repartir la lechuga, el tomate y el aguacate sobre cada tortilla.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Colocar las tiras de pollo crujiente sobre las verduras y salsear con la salsa césar.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Enrollar cada tortilla bien apretada formando un wrap y cortar por la mitad en diagonal para servir.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_120', 'Quesadillas de queso y jamón con guacamole', 'carnes', 'cerdo', 'pan', ARRAY['segundo','plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 600, 26, 42, 36, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Tortillas de trigo grandes","amount":4,"unit":"ud"},{"name":"Queso rallado","amount":160,"unit":"g"},{"name":"Jamón cocido","amount":100,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Tomate","amount":60,"unit":"g"},{"name":"Cebolla morada","amount":20,"unit":"g"},{"name":"Cilantro fresco","amount":5,"unit":"g"},{"name":"Zumo de lima","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Picar cebolla morada en dados muy finos.","Cortar tomate en dados pequeños.","Picar cilantro fresco fino.","Partir aguacate por la mitad, retirar el hueso y extraer la pulpa a un bol.","Machacar la pulpa del aguacate con un tenedor hasta obtener una pasta con textura.","Añadir la cebolla morada picada, el tomate en dados, el cilantro picado y zumo de lima al aguacate machacado.","Mezclar bien hasta integrar y reservar el guacamole.","Extender queso rallado y jamón cocido sobre la mitad de cada tortillas de trigo grandes.","Doblar cada tortilla por la mitad para cerrar la quesadilla.","Calentar aceite de oliva en plancha a fuego medio.","Colocar las quesadillas en la plancha y cocinar 2-3 min por cada lado hasta que estén doradas y el queso fundido.","Cortar cada quesadilla en triángulos.","Servir las quesadillas calientes acompañadas del guacamole."}', 'Quesadillas de queso fundido y jamón, doradas en la plancha, servidas con guacamole fresco.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Rellena las tortillas, dóblalas y cocina de 6 a 8 minutos por tanda, dándoles la vuelta a mitad, hasta que estén doradas y el queso fundido. Quedarán crujientes y deliciosas."},{"appliance":"horno","time":18,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con calor arriba y abajo. Coloca las quesadillas rellenas en una bandeja con papel de horno y hornea durante 8-10 minutos, hasta que el queso se derrita y las tortillas estén doradas y crujientes."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Cebolla morada}} en dados muy finos.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Cortar {{Tomate}} en dados pequeños.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Picar {{Cilantro fresco}} fino.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Partir {{Aguacate}} por la mitad, retirar el hueso y extraer la pulpa a un bol.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Machacar la pulpa del aguacate con un tenedor hasta obtener una pasta con textura.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Añadir la cebolla morada picada, el tomate en dados, el cilantro picado y {{Zumo de lima}} al aguacate machacado.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Mezclar bien hasta integrar y reservar el guacamole.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Extender {{Queso rallado}} y {{Jamón cocido}} sobre la mitad de cada {{Tortillas de trigo grandes}}.","minutes":2,"kind":"prep","part":"principal"},{"text":"Doblar cada tortilla por la mitad para cerrar la quesadilla.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Plancha}} a fuego medio.","minutes":1,"kind":"activo","part":"principal"},{"text":"Colocar las quesadillas en la plancha y cocinar 2-3 min por cada lado hasta que estén doradas y el queso fundido.","minutes":5,"kind":"activo","part":"principal"},{"text":"Cortar cada quesadilla en triángulos.","minutes":1,"kind":"prep","part":"combinado"},{"text":"Servir las quesadillas calientes acompañadas del guacamole.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_121', 'Bowl de quinoa, pollo y verduras crudas', 'carnes', 'pollo', 'quinoa', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 560, 40, 50, 23, 2, true, true, '{}', '[{"name":"Quinoa","amount":120,"unit":"g"},{"name":"Pechuga de pollo","amount":300,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Pepino","amount":100,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Enjuagar quinoa bajo agua fría hasta que el agua salga clara.","Llevar a ebullición una olla con agua y sal, añadir la quinoa y cocer a fuego medio.","Cocer la quinoa tapada a fuego suave hasta que esté tierna y haya absorbido el agua.","Escurrir la quinoa si ha quedado agua y extenderla en un bol para que temple.","Pelar zanahoria y cortarla en bastones finos.","Cortar pepino en medias lunas y tomate cherry por la mitad.","Cortar aguacate en láminas.","Exprimir limón y rociar las láminas de aguacate con unas gotas de zumo para que no se oxiden.","Calentar plancha a fuego fuerte con aceite de oliva.","Colocar pechuga de pollo entera en la plancha y cocinar 5 min por el primer lado hasta que se dore.","Dar la vuelta a la pechuga de pollo y cocinar 4 min más hasta que esté cocida por dentro.","Retirar la pechuga de pollo de la plancha y dejar reposar 3 min antes de cortarla.","Cortar la pechuga de pollo en tiras.","Repartir la quinoa en la base de 2 boles.","Disponer encima las tiras de pollo, la zanahoria, el pepino, el tomate cherry y el aguacate en montones separados.","Aliñar con el resto del zumo de limón y aceite de oliva al gusto justo antes de servir."}', 'Bowl fresco de quinoa con pollo a la plancha y verduras crudas variadas, listo en poco más de veinte minutos.', '[{"appliance":"airfryer","time":30,"difficulty":"facil","prepSummary":"Cocina la pechuga de pollo a 190°C durante 15-18 minutos, volteándola a mitad para un dorado uniforme. La quinoa se puede cocer en un recipiente apto con agua en la misma airfryer o de forma tradicional."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Hornea la pechuga de pollo a 190°C durante 20-25 minutos hasta que esté bien cocida. La quinoa se puede preparar en una olla apta para horno con agua o en una olla convencional."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina la quinoa en el cestillo (15-20 min/Varoma/vel 1) y el pollo troceado al vapor en el Varoma simultáneamente para una cocción eficiente y jugosa."},{"appliance":"vaporera","time":20,"difficulty":"facil","prepSummary":"Cuece la quinoa y la pechuga de pollo (entera o troceada) al vapor simultáneamente durante 15-20 minutos. El pollo quedará muy jugoso y saludable."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Cocina la quinoa y el pollo troceado en la olla express con un poco de agua durante 5-7 minutos a partir de que suba la válvula para una cocción ultrarrápida."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Enjuagar {{Quinoa}} bajo agua fría hasta que el agua salga clara.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición una olla con agua y {{Sal|gusto}}, añadir la quinoa y cocer a fuego medio.","minutes":2,"kind":"activo","part":"principal"},{"text":"Cocer la quinoa tapada a fuego suave hasta que esté tierna y haya absorbido el agua.","minutes":13,"kind":"pasivo","part":"principal"},{"text":"Escurrir la quinoa si ha quedado agua y extenderla en un bol para que temple.","minutes":1,"kind":"activo","part":"principal"},{"text":"Pelar {{Zanahoria}} y cortarla en bastones finos.","minutes":3,"kind":"paralelo","part":"guarnicion","during":2},{"text":"Cortar {{Pepino}} en medias lunas y {{Tomate cherry}} por la mitad.","minutes":2,"kind":"paralelo","part":"guarnicion","during":2},{"text":"Cortar {{Aguacate}} en láminas.","minutes":1,"kind":"paralelo","part":"guarnicion","during":2},{"text":"Exprimir {{Limón}} y rociar las láminas de aguacate con unas gotas de zumo para que no se oxiden.","minutes":1,"kind":"paralelo","part":"guarnicion","during":2},{"text":"Calentar {{@Plancha}} a fuego fuerte con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"activo","part":"principal"},{"text":"Colocar {{Pechuga de pollo}} entera en la plancha y cocinar 5 min por el primer lado hasta que se dore.","minutes":5,"kind":"pasivo","part":"principal"},{"text":"Dar la vuelta a la pechuga de pollo y cocinar 4 min más hasta que esté cocida por dentro.","minutes":4,"kind":"pasivo","part":"principal"},{"text":"Retirar la pechuga de pollo de la plancha y dejar reposar 3 min antes de cortarla.","minutes":3,"kind":"espera","part":"principal"},{"text":"Cortar la pechuga de pollo en tiras.","minutes":1,"kind":"prep","part":"principal"},{"text":"Repartir la quinoa en la base de 2 boles.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Disponer encima las tiras de pollo, la zanahoria, el pepino, el tomate cherry y el aguacate en montones separados.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Aliñar con el resto del zumo de limón y aceite de oliva al gusto justo antes de servir.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_122', 'Sándwich club de pollo, bacon y huevo', 'carnes', 'pollo', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 650, 46, 38, 32, 2, true, false, '{"gluten","huevo"}', '[{"name":"Pan de molde","amount":6,"unit":"ud"},{"name":"Pechuga de pollo","amount":200,"unit":"g"},{"name":"Bacon en lonchas","amount":70,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Lechuga","amount":40,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Salpimentar pechuga de pollo por ambas caras.","Calentar plancha a fuego fuerte con aceite de oliva.","Cocinar la pechuga de pollo 4 min por cada lado hasta que esté dorada y cocinada por dentro.","Lavar y secar lechuga y reservar.","Cortar tomate en rodajas finas y reservar.","Retirar la pechuga de pollo de la plancha y dejar templar 2 min.","Cortar la pechuga de pollo en filetes finos y reservar.","Dorar bacon en lonchas en la misma plancha a fuego fuerte 2 min por cada lado hasta que estén crujientes.","Retirar el bacon de la plancha y reservar sobre papel absorbente.","Cocinar huevo en la misma plancha a fuego medio hasta que la clara esté cuajada y la yema al punto.","Retirar los huevos de la plancha y reservar.","Tostar pan de molde en la misma plancha a fuego medio hasta que estén doradas y crujientes.","Untar una cara de cada tostada con mayonesa.","Montar el primer piso: colocar una tostada, disponer la lechuga, las rodajas de tomate y los filetes de pollo.","Cubrir con una segunda tostada con la cara de mayonesa hacia abajo.","Añadir encima el bacon crujiente y los huevos fritos.","Cerrar con la tercera tostada, sujetar con palillos y cortar en triángulos para servir."}', 'Sándwich de tres pisos con pollo a la plancha, bacon crujiente, huevo y mayonesa, sujeto con palillos.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Cocina las lonchas de pollo y el bacon en la airfryer a 190°C hasta que estén dorados y crujientes. Tuesta el pan y cocina los huevos en un ramekin apto para airfryer a 180°C para un resultado tipo frito."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C y hornea el pollo y el bacon en una bandeja hasta que estén cocidos y crujientes. Tuesta el pan y hornea los huevos en la misma bandeja o en ramequines para un efecto de huevo frito."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Salpimentar {{Pechuga de pollo}} por ambas caras.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"activo"},{"text":"Cocinar la pechuga de pollo 4 min por cada lado hasta que esté dorada y cocinada por dentro.","minutes":8,"kind":"pasivo"},{"text":"Lavar y secar {{Lechuga}} y reservar.","minutes":1,"kind":"paralelo","during":2},{"text":"Cortar {{Tomate}} en rodajas finas y reservar.","minutes":1,"kind":"paralelo","during":2},{"text":"Retirar la pechuga de pollo de la plancha y dejar templar 2 min.","minutes":2,"kind":"espera"},{"text":"Cortar la pechuga de pollo en filetes finos y reservar.","minutes":1,"kind":"prep"},{"text":"Dorar {{Bacon en lonchas}} en la misma plancha a fuego fuerte 2 min por cada lado hasta que estén crujientes.","minutes":4,"kind":"activo"},{"text":"Retirar el bacon de la plancha y reservar sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Cocinar {{Huevo}} en la misma plancha a fuego medio hasta que la clara esté cuajada y la yema al punto.","minutes":3,"kind":"activo"},{"text":"Retirar los huevos de la plancha y reservar.","minutes":1,"kind":"activo"},{"text":"Tostar {{Pan de molde}} en la misma plancha a fuego medio hasta que estén doradas y crujientes.","minutes":2,"kind":"activo"},{"text":"Untar una cara de cada tostada con {{Mayonesa}}.","minutes":1,"kind":"prep"},{"text":"Montar el primer piso: colocar una tostada, disponer la lechuga, las rodajas de tomate y los filetes de pollo.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Cubrir con una segunda tostada con la cara de mayonesa hacia abajo.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Añadir encima el bacon crujiente y los huevos fritos.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Cerrar con la tercera tostada, sujetar con palillos y cortar en triángulos para servir.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_123', 'Ensalada César exprés con pollo de bolsa', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 480, 34, 18, 30, 2, false, false, '{"gluten","lactosa","huevo","pescado","mostaza"}', '[{"name":"Lechuga romana","amount":200,"unit":"g"},{"name":"Pollo asado de bolsa","amount":200,"unit":"g"},{"name":"Pan de molde","amount":60,"unit":"g"},{"name":"Queso parmesano","amount":30,"unit":"g"},{"name":"Salsa César","amount":60,"unit":"g"},{"name":"Anchoas en aceite","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pan de molde en dados de 1 cm aproximadamente.","Calentar sartén a fuego medio con aceite de oliva.","Tostar los dados de pan de molde en la sartén hasta que estén dorados y crujientes.","Retirar los picatostes de la sartén y reservar.","Lavar y secar lechuga romana, luego trocearla en tiras de tamaño de bocado.","Desmenuzar pollo asado de bolsa en tiras con las manos.","Picar anchoas en aceite en trozos pequeños.","Rallar queso parmesano en lascas finas con un pelador o rallador.","Disponer la lechuga en un bol grande y aliñar con salsa césar, mezclando bien hasta que quede repartida.","Añadir el pollo desmenuzado y las anchoas picadas al bol y mezclar de nuevo.","Repartir los picatostes y el queso parmesano rallado por encima de la ensalada.","Servir inmediatamente para que los picatostes conserven el punto crujiente."}', 'Ensalada César exprés con pollo de bolsa, picatostes caseros y aliño clásico, lista en diez minutos.', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Para los picatostes, corta el pan en dados, rocía con aceite y cocínalos en la airfryer a 180°C durante 5-7 minutos. Añade el pollo de bolsa troceado los últimos 3-5 minutos para calentarlo y dorarlo ligeramente."},{"appliance":"horno","time":18,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Corta el pan en dados, rocía con aceite y hornea 8-10 minutos hasta dorar. El pollo troceado se puede calentar o dorar ligeramente junto a los picatostes durante los últimos 5-7 minutos."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, ARRAY['pescado_azul']::main_protein[], false, '[{"text":"Cortar {{Pan de molde}} en dados de 1 cm aproximadamente.","minutes":2,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"activo"},{"text":"Tostar los dados de pan de molde en la sartén hasta que estén dorados y crujientes.","minutes":3,"kind":"activo"},{"text":"Retirar los picatostes de la sartén y reservar.","minutes":1,"kind":"activo"},{"text":"Lavar y secar {{Lechuga romana}}, luego trocearla en tiras de tamaño de bocado.","minutes":2,"kind":"prep"},{"text":"Desmenuzar {{Pollo asado de bolsa}} en tiras con las manos.","minutes":1,"kind":"prep"},{"text":"Picar {{Anchoas en aceite}} en trozos pequeños.","minutes":1,"kind":"prep"},{"text":"Rallar {{Queso parmesano}} en lascas finas con un pelador o rallador.","minutes":1,"kind":"prep"},{"text":"Disponer la lechuga en un bol grande y aliñar con {{Salsa César}}, mezclando bien hasta que quede repartida.","minutes":1,"kind":"activo"},{"text":"Añadir el pollo desmenuzado y las anchoas picadas al bol y mezclar de nuevo.","minutes":1,"kind":"activo"},{"text":"Repartir los picatostes y el queso parmesano rallado por encima de la ensalada.","minutes":1,"kind":"emplatado"},{"text":"Servir inmediatamente para que los picatostes conserven el punto crujiente.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_124', 'Tacos de pollo rápidos con pico de gallo', 'carnes', 'pollo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 470, 34, 40, 20, 2, true, false, '{"gluten"}', '[{"name":"Pechuga de pollo","amount":300,"unit":"g"},{"name":"Tortillas de trigo","amount":6,"unit":"ud"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Cebolla morada","amount":50,"unit":"g"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cortar pechuga de pollo en tiras finas de unos 1 cm.","Salpimentar el pollo con comino molido, pimentón dulce y sal; mezclar bien.","Picar tomate en dados pequeños.","Picar cebolla morada en dados pequeños.","Picar cilantro fresco fino.","Exprimir lima y reservar el zumo.","Mezclar el tomate, la cebolla morada y el cilantro con la mitad del zumo de lima y sal.","Reservar el pico de gallo.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Saltear las tiras de pollo 5 min, removiendo, hasta que estén doradas y cocidas por dentro.","Calentar tortillas de trigo en sartén limpia, 20 segundos por cada lado, hasta que estén flexibles.","Rellenar cada tortilla con el pollo salteado y una cucharada generosa de pico de gallo.","Añadir el zumo de lima restante por encima y servir de inmediato."}', 'Tacos rápidos de pollo especiado con pico de gallo fresco de tomate, cebolla morada y cilantro.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Cocina las pechugas de pollo sazonadas con las especias en la airfryer a 190°C durante 15-18 minutos, dándoles la vuelta a mitad para un dorado uniforme y un interior jugoso. Calienta las tortillas brevemente."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Asa las pechugas de pollo sazonadas en el horno precalentado a 200°C durante 20-22 minutos, hasta que estén bien cocidas y ligeramente doradas. Las tortillas se pueden calentar en el mismo horno al final."},{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Prepara el pico de gallo picando los ingredientes en el vaso. Luego, cocina las pechugas de pollo sazonadas al vapor en el Varoma durante 15-18 minutos, para obtener un pollo tierno y fácil de desmenuzar."},{"appliance":"vaporera","time":25,"difficulty":"facil","prepSummary":"Cocina las pechugas de pollo sazonadas en la vaporera durante unos 20 minutos hasta que estén tiernas y cocidas, ideales para desmenuzar. Mientras, prepara el pico de gallo."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Cocina las pechugas de pollo sazonadas en la olla express con un poco de agua o caldo durante 5-7 minutos desde que sube la presión, para un pollo muy tierno y rápido de desmenuzar."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pechuga de pollo}} en tiras finas de unos 1 cm.","minutes":3,"kind":"prep","part":"principal"},{"text":"Salpimentar el pollo con {{Comino molido}}, {{Pimentón dulce}} y {{Sal|gusto}}; mezclar bien.","minutes":1,"kind":"prep","part":"principal"},{"text":"Picar {{Tomate}} en dados pequeños.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Picar {{Cebolla morada}} en dados pequeños.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Picar {{Cilantro fresco}} fino.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Exprimir {{Lima}} y reservar el zumo.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Mezclar el tomate, la cebolla morada y el cilantro con la mitad del zumo de lima y {{Sal|gusto}}.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Reservar el pico de gallo.","kind":"espera","part":"salsa"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte hasta que humee ligeramente.","minutes":1,"kind":"activo","part":"principal"},{"text":"Saltear las tiras de pollo 5 min, removiendo, hasta que estén doradas y cocidas por dentro.","minutes":5,"kind":"activo","part":"principal"},{"text":"Calentar {{Tortillas de trigo}} en {{@Sartén}} limpia, 20 segundos por cada lado, hasta que estén flexibles.","minutes":2,"kind":"activo","part":"combinado"},{"text":"Rellenar cada tortilla con el pollo salteado y una cucharada generosa de pico de gallo.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Añadir el zumo de lima restante por encima y servir de inmediato.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true)
