  estrella = excluded.estrella;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('carnes_125', 'Tosta de sobrasada y miel con queso', 'carnes', 'cerdo', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 520, 20, 40, 30, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Pan rústico","amount":4,"unit":"ud"},{"name":"Sobrasada","amount":150,"unit":"g"},{"name":"Queso semicurado en lonchas","amount":80,"unit":"g"},{"name":"Miel","amount":30,"unit":"g"}]'::jsonb, '{"Tostar pan rústico bajo el grill del horno hasta que estén doradas y crujientes.","Retirar el pan del horno y extender sobrasada sobre cada tosta mientras aún están calientes.","Colocar queso semicurado en lonchas sobre la sobrasada, cubriendo bien la superficie.","Gratinar las tostas bajo el grill hasta que el queso empiece a fundirse.","Retirar las tostas del horno y rociar miel sobre cada una.","Servir inmediatamente mientras el queso está fundente."}', 'Tostas crujientes de sobrasada con queso fundido y un toque dulce de miel.', '[{"appliance":"airfryer","time":8,"difficulty":"facil","prepSummary":"Coloca el pan con la sobrasada y el queso en la airfryer precalentada a 190°C. Cocina durante 6-8 minutos, o hasta que el pan esté crujiente y el queso fundido y burbujeante. Añade la miel al servir."},{"appliance":"horno","time":12,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con calor arriba y abajo. Dispón las tostas con la sobrasada y el queso en una bandeja y hornea durante 8-10 minutos, hasta que el pan dore y el queso se funda. Termina con un chorrito de miel."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Tostar {{Pan rústico}} bajo el grill del horno hasta que estén doradas y crujientes.","minutes":4,"kind":"pasivo"},{"text":"Retirar el pan del horno y extender {{Sobrasada}} sobre cada tosta mientras aún están calientes.","minutes":2,"kind":"activo"},{"text":"Colocar {{Queso semicurado en lonchas}} sobre la sobrasada, cubriendo bien la superficie.","minutes":1,"kind":"activo"},{"text":"Gratinar las tostas bajo el grill hasta que el queso empiece a fundirse.","minutes":3,"kind":"pasivo"},{"text":"Retirar las tostas del horno y rociar {{Miel|chorrito}} sobre cada una.","minutes":1,"kind":"activo"},{"text":"Servir inmediatamente mientras el queso está fundente.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_126', 'Sándwich de pastrami y mostaza', 'carnes', 'ternera', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 560, 36, 42, 26, 2, true, false, '{"gluten","mostaza","lactosa"}', '[{"name":"Pan de centeno","amount":4,"unit":"ud"},{"name":"Pastrami de ternera en lonchas","amount":200,"unit":"g"},{"name":"Mostaza a la antigua","amount":30,"unit":"g"},{"name":"Pepinillos encurtidos","amount":40,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"}]'::jsonb, '{"Laminar pepinillos encurtidos en rodajas finas.","Untar mantequilla por una cara de 2 rebanadas de pan de centeno.","Untar mostaza a la antigua por una cara de las otras 2 rebanadas de pan de centeno.","Calentar sartén a fuego medio sin aceite hasta que esté bien caliente.","Tostar las rebanadas con mantequilla por la cara untada hasta que se doren.","Calentar pastrami de ternera en lonchas en la misma sartén hasta que estén templadas.","Montar cada sándwich con el pastrami templado y los pepinillos laminados entre las rebanadas.","Cortar cada sándwich por la mitad en diagonal y servir templado."}', 'Sándwich de pastrami templado con mostaza a la antigua y pepinillos encurtidos.', '[{"appliance":"airfryer","time":10,"difficulty":"facil","prepSummary":"Unta el pan con mantequilla, monta el sándwich y cocínalo en la airfryer precalentada a 180-190°C durante 6-8 minutos, dándole la vuelta a mitad, hasta que esté dorado y el pastrami caliente."},{"appliance":"horno","time":18,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C (o usa la función grill). Unta el pan con mantequilla, monta el sándwich y hornea durante 8-12 minutos, vigilando que el pan quede crujiente y el pastrami bien caliente."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Laminar {{Pepinillos encurtidos}} en rodajas finas.","minutes":2,"kind":"prep"},{"text":"Untar {{Mantequilla}} por una cara de 2 rebanadas de {{Pan de centeno}}.","minutes":1,"kind":"prep"},{"text":"Untar {{Mostaza a la antigua}} por una cara de las otras 2 rebanadas de pan de centeno.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio sin aceite hasta que esté bien caliente.","minutes":1,"kind":"activo"},{"text":"Tostar las rebanadas con mantequilla por la cara untada hasta que se doren.","minutes":2,"kind":"activo"},{"text":"Calentar {{Pastrami de ternera en lonchas}} en la misma sartén hasta que estén templadas.","minutes":2,"kind":"activo"},{"text":"Montar cada sándwich con el pastrami templado y los pepinillos laminados entre las rebanadas.","minutes":1,"kind":"emplatado"},{"text":"Cortar cada sándwich por la mitad en diagonal y servir templado.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_127', 'Ensalada de pollo asado de bolsa con nueces y queso', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 460, 32, 14, 30, 2, true, false, '{"frutos_secos","lactosa","sulfitos"}', '[{"name":"Mezcla de hojas verdes","amount":150,"unit":"g"},{"name":"Pollo asado de bolsa","amount":200,"unit":"g"},{"name":"Nueces","amount":40,"unit":"g"},{"name":"Queso parmesano en virutas","amount":50,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar mezcla de hojas verdes bajo agua fría y escurrir bien en un colador.","Cortar tomate cherry por la mitad.","Desmenuzar pollo asado de bolsa en tiras con las manos.","Picar nueces groseramente con un cuchillo.","Repartir la mezcla de hojas verdes en 2 platos o boles.","Añadir el pollo desmenuzado, las nueces picadas y los tomates cherry sobre las hojas.","Distribuir queso parmesano en virutas por encima.","Aliñar con aceite de oliva, vinagre balsámico y sal justo antes de servir."}', 'Ensalada rápida con pollo asado de bolsa, nueces crujientes y queso, lista en diez minutos.', '[{"appliance":"airfryer","time":10,"difficulty":"facil","prepSummary":"Para darle un toque crujiente y templado al pollo asado, caliéntalo en la airfryer a 180°C durante 5-7 minutos. Desmenúzalo y mézclalo con los demás ingredientes."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Si buscas un pollo más crujiente y templado, hornéalo a 180°C durante 10-12 minutos. Luego, desmenúzalo y úsalo en la ensalada para un contraste de texturas."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Mezcla de hojas verdes}} bajo agua fría y escurrir bien en un colador.","minutes":2,"kind":"prep"},{"text":"Cortar {{Tomate cherry}} por la mitad.","minutes":1,"kind":"prep"},{"text":"Desmenuzar {{Pollo asado de bolsa}} en tiras con las manos.","minutes":2,"kind":"prep"},{"text":"Picar {{Nueces}} groseramente con un cuchillo.","minutes":1,"kind":"prep"},{"text":"Repartir la mezcla de hojas verdes en 2 platos o boles.","minutes":1,"kind":"emplatado"},{"text":"Añadir el pollo desmenuzado, las nueces picadas y los tomates cherry sobre las hojas.","minutes":1,"kind":"emplatado"},{"text":"Distribuir {{Queso parmesano en virutas}} por encima.","minutes":1,"kind":"emplatado"},{"text":"Aliñar con {{Aceite de oliva|chorrito}}, {{Vinagre balsámico|chorrito}} y {{Sal|gusto}} justo antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_128', 'Tosta de paté, higos y rúcula', 'carnes', 'cerdo', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 420, 14, 38, 24, 2, false, false, '{"gluten","lactosa"}', '[{"name":"Pan rústico","amount":4,"unit":"ud"},{"name":"Paté de cerdo","amount":120,"unit":"g"},{"name":"Higos frescos","amount":3,"unit":"ud"},{"name":"Rúcula","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Lavar higos frescos bajo el grifo y secarlos con papel de cocina.","Laminar los higos frescos en rodajas finas de unos 3-4 mm.","Tostar pan rústico en una tostadora o sartén a fuego medio hasta que estén doradas y crujientes.","Untar paté de cerdo en capa generosa sobre cada rebanada tostada.","Repartir las láminas de higo sobre el paté de cada tosta.","Colocar rúcula sobre cada tosta.","Terminar con aceite de oliva por encima y servir de inmediato."}', 'Tostas de paté con higos frescos laminados y rúcula, un contraste dulce y amargo muy rápido de montar.', '[{"appliance":"airfryer","time":8,"difficulty":"facil","prepSummary":"Para tostar el pan, precalienta la airfryer a 190°C y cocina las rebanadas durante 4-6 minutos, volteándolas a mitad, hasta que estén crujientes. Luego, unta el paté y decora con higos y rúcula."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con calor arriba y abajo. Tuesta las rebanadas de pan rústico directamente sobre la rejilla durante 5-7 minutos hasta que estén doradas. Monta la tosta con el paté, los higos y la rúcula."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Higos frescos}} bajo el grifo y secarlos con papel de cocina.","minutes":1,"kind":"prep"},{"text":"Laminar los higos frescos en rodajas finas de unos 3-4 mm.","minutes":2,"kind":"prep"},{"text":"Tostar {{Pan rústico}} en una tostadora o sartén a fuego medio hasta que estén doradas y crujientes.","minutes":3,"kind":"activo"},{"text":"Untar {{Paté de cerdo}} en capa generosa sobre cada rebanada tostada.","minutes":1,"kind":"emplatado"},{"text":"Repartir las láminas de higo sobre el paté de cada tosta.","minutes":1,"kind":"emplatado"},{"text":"Colocar {{Rúcula}} sobre cada tosta.","minutes":1,"kind":"emplatado"},{"text":"Terminar con {{Aceite de oliva|chorrito}} por encima y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_129', 'Croque monsieur rápido', 'carnes', 'cerdo', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 20, 'facil', 'all', 540, 28, 34, 32, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Pan de molde","amount":4,"unit":"ud"},{"name":"Jamón cocido en lonchas","amount":120,"unit":"g"},{"name":"Queso emmental en lonchas","amount":80,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Leche","amount":150,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"}]'::jsonb, '{"Fundir mantequilla en un cazo a fuego medio hasta que esté líquida.","Añadir harina de golpe y remover sin parar durante 1 min hasta que la mezcla forme una pasta homogénea.","Verter leche poco a poco sin dejar de remover hasta que no queden grumos.","Cocer a fuego medio sin dejar de remover hasta que la bechamel espese, unos 3 min.","Añadir nuez moscada y remover para integrar. Retirar el cazo del fuego y reservar.","Precalentar el horno con grill a 220 °C.","Extender una capa fina de bechamel sobre 2 rebanadas de pan de molde.","Repartir jamón cocido en lonchas sobre las 2 rebanadas untadas con bechamel.","Colocar queso emmental en lonchas sobre el jamón, reservando 2 lonchas para la cobertura.","Cerrar cada sándwich con las 2 rebanadas de pan de molde restantes.","Cubrir la parte superior de cada sándwich con el resto de la bechamel.","Repartir las lonchas de queso emmental reservadas por encima de la bechamel.","Hornear los sándwiches bajo el grill a 220 °C hasta que el queso esté dorado y burbujeante, unos 7 min.","Retirar del horno y dejar templar 2 min antes de servir.","Servir los sándwiches en el plato, con el queso gratinado hacia arriba."}', 'Sándwich de jamón y queso gratinado con bechamel casera, listo en el tiempo que tarda el horno.', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Prepara la bechamel en un cazo. Monta los sándwiches con jamón, queso y bechamel, y hornea a 180-200°C durante 15-20 minutos hasta que estén dorados y el queso fundido."},{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Prepara la bechamel por separado. Monta los sándwiches y cocínalos en la airfryer a 180°C durante 10-12 minutos, dándoles la vuelta a mitad, hasta que estén crujientes y el queso derretido."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Fundir {{Mantequilla}} en un cazo a fuego medio hasta que esté líquida.","minutes":1,"kind":"activo"},{"text":"Añadir {{Harina}} de golpe y remover sin parar durante 1 min hasta que la mezcla forme una pasta homogénea.","minutes":1,"kind":"activo"},{"text":"Verter {{Leche}} poco a poco sin dejar de remover hasta que no queden grumos.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego medio sin dejar de remover hasta que la bechamel espese, unos 3 min.","minutes":3,"kind":"activo"},{"text":"Añadir {{Nuez moscada|pizca}} y remover para integrar. Retirar el cazo del fuego y reservar.","minutes":1,"kind":"activo"},{"text":"Precalentar el horno con grill a 220 °C.","minutes":5,"kind":"pasivo"},{"text":"Extender una capa fina de bechamel sobre 2 rebanadas de {{Pan de molde}}.","minutes":1,"kind":"paralelo","during":5},{"text":"Repartir {{Jamón cocido en lonchas}} sobre las 2 rebanadas untadas con bechamel.","minutes":1,"kind":"paralelo","during":5},{"text":"Colocar {{Queso emmental en lonchas}} sobre el jamón, reservando 2 lonchas para la cobertura.","minutes":1,"kind":"paralelo","during":5},{"text":"Cerrar cada sándwich con las 2 rebanadas de pan de molde restantes.","minutes":1,"kind":"paralelo","during":5},{"text":"Cubrir la parte superior de cada sándwich con el resto de la bechamel.","minutes":1,"kind":"activo"},{"text":"Repartir las lonchas de queso emmental reservadas por encima de la bechamel.","minutes":1,"kind":"activo"},{"text":"Hornear los sándwiches bajo el grill a 220 °C hasta que el queso esté dorado y burbujeante, unos 7 min.","minutes":7,"kind":"pasivo"},{"text":"Retirar del horno y dejar templar 2 min antes de servir.","minutes":2,"kind":"espera"},{"text":"Servir los sándwiches en el plato, con el queso gratinado hacia arriba.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_130', 'Tortilla francesa de pavo y queso con ensalada de aguacate, tomate cherry y queso de cabra', 'carnes', 'pavo', NULL, ARRAY['segundo','plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 430, 28, 12, 30, 2, true, false, '{"huevo","lactosa","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Pechuga de pavo en lonchas","amount":80,"unit":"g"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Queso de cabra","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Cortar aguacate en dados y tomate cherry por la mitad.","Desmenuzar queso de cabra sobre los dados de aguacate y los tomates cherry.","Aliñar la ensalada con aceite de oliva, vinagre de jerez y sal.","Batir huevo en un bol con sal al gusto hasta que estén homogéneos.","Calentar sartén con aceite de oliva a fuego medio.","Verter el huevo batido y repartirlo por toda la sartén formando una capa fina.","Colocar pechuga de pavo en lonchas y queso rallado sobre una mitad cuando la base empiece a cuajar.","Doblar la tortilla por la mitad y cocer 2 min hasta que el queso se funda.","Servir la tortilla acompañada de la ensalada de aguacate, tomate cherry y queso de cabra."}', 'Tortilla francesa rellena de pavo y queso fundido, con una ensalada fresca de aguacate, tomate cherry y queso de cabra.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Para la tortilla, bate los huevos con el pavo y el queso rallado. Vierte la mezcla en un molde apto para airfryer y cocina a 180°C durante 10-12 minutos hasta que esté cuajada y ligeramente dorada. La ensalada se prepara aparte."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Bate los huevos con el pavo y el queso rallado, vierte la mezcla en un molde apto para horno y hornea durante 12-15 minutos hasta que esté cuajada y ligeramente dorada. La ensalada se prepara aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Aguacate}} en dados y {{Tomate cherry}} por la mitad.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Desmenuzar {{Queso de cabra}} sobre los dados de aguacate y los tomates cherry.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Aliñar la ensalada con {{Aceite de oliva|chorrito}}, {{Vinagre de Jerez}} y {{Sal|gusto}}.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Batir {{Huevo}} en un bol con sal al gusto hasta que estén homogéneos.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Sartén}} con {{Aceite de oliva|chorrito}} a fuego medio.","minutes":1,"kind":"activo","part":"principal"},{"text":"Verter el huevo batido y repartirlo por toda la sartén formando una capa fina.","minutes":1,"kind":"activo","part":"principal"},{"text":"Colocar {{Pechuga de pavo en lonchas}} y {{Queso rallado}} sobre una mitad cuando la base empiece a cuajar.","minutes":1,"kind":"activo","part":"principal"},{"text":"Doblar la tortilla por la mitad y cocer 2 min hasta que el queso se funda.","minutes":2,"kind":"pasivo","part":"principal"},{"text":"Servir la tortilla acompañada de la ensalada de aguacate, tomate cherry y queso de cabra.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_131', 'Pechuga de pollo a la plancha con ensalada de aguacate, maíz y lima', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 480, 40, 24, 24, 2, true, false, '{}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Maíz dulce cocido","amount":100,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Cilantro fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Cortar pechuga de pollo en filetes de grosor uniforme.","Salpimentar los filetes por ambos lados con sal y pimienta negra.","Calentar plancha con aceite de oliva a fuego fuerte hasta que humee.","Cocinar los filetes 5 min por el primer lado sin moverlos, hasta que se doren.","Dar la vuelta a los filetes y cocinar 5 min más hasta que estén bien hechos por dentro.","Cortar aguacate en dados.","Exprimir lima y reservar el zumo.","Picar cilantro fresco fino.","Mezclar el aguacate en dados con maíz dulce cocido, el cilantro picado y la mitad del zumo de lima.","Aliñar la ensalada con el resto del zumo de lima, un chorrito de aceite de oliva y sal al gusto.","Retirar los filetes de la plancha y dejar reposar 3 min.","Servir los filetes de pollo junto a la ensalada de aguacate y maíz."}', 'Pechuga de pollo a la plancha con una ensalada fresca de aguacate, maíz dulce y un toque ácido de lima.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 200°C. Sazona la pechuga, rocíala con un poco de aceite y cocina unos 15-18 minutos, dándole la vuelta a mitad, para un exterior dorado y jugoso."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Sazona la pechuga, rocíala con un poco de aceite y hornea durante 20-25 minutos hasta que esté bien cocida y ligeramente dorada, asegurando que no se seque."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pechuga de pollo}} en filetes de grosor uniforme.","minutes":2,"kind":"prep","part":"principal"},{"text":"Salpimentar los filetes por ambos lados con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} con {{Aceite de oliva|chorrito}} a fuego fuerte hasta que humee.","minutes":2,"kind":"activo","part":"principal"},{"text":"Cocinar los filetes 5 min por el primer lado sin moverlos, hasta que se doren.","minutes":5,"kind":"pasivo","part":"principal"},{"text":"Dar la vuelta a los filetes y cocinar 5 min más hasta que estén bien hechos por dentro.","minutes":5,"kind":"pasivo","part":"principal"},{"text":"Cortar {{Aguacate}} en dados.","minutes":2,"kind":"paralelo","part":"guarnicion","during":3},{"text":"Exprimir {{Lima}} y reservar el zumo.","minutes":1,"kind":"paralelo","part":"guarnicion","during":3},{"text":"Picar {{Cilantro fresco}} fino.","minutes":1,"kind":"paralelo","part":"guarnicion","during":3},{"text":"Mezclar el aguacate en dados con {{Maíz dulce cocido}}, el cilantro picado y la mitad del zumo de lima.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Aliñar la ensalada con el resto del zumo de lima, un chorrito de aceite de oliva y sal al gusto.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Retirar los filetes de la plancha y dejar reposar 3 min.","minutes":3,"kind":"espera","part":"principal"},{"text":"Servir los filetes de pollo junto a la ensalada de aguacate y maíz.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_132', 'Lomo a la plancha con ensalada de aguacate, tomate cherry y queso feta', 'carnes', 'cerdo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 500, 36, 12, 34, 2, true, false, '{"lactosa"}', '[{"name":"Lomo de cerdo en filetes","amount":350,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Tomate cherry","amount":120,"unit":"g"},{"name":"Queso feta","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Orégano seco","amount":2,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cortar aguacate en dados medianos y tomate cherry por la mitad.","Desmenuzar queso feta sobre el aguacate y el tomate cherry.","Aliñar la ensalada con aceite de oliva, orégano seco y sal.","Salpimentar lomo de cerdo en filetes por ambas caras.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Colocar los filetes en la plancha y cocinar 3 min por cada lado hasta que estén dorados.","Retirar los filetes de la plancha y dejar reposar 2 min.","Servir el lomo junto con la ensalada de aguacate, tomate cherry y queso feta."}', 'Lomo de cerdo a la plancha con una ensalada fresca de aguacate, tomate cherry y queso feta.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cocina los filetes de lomo sazonados y ligeramente aceitados durante 10-12 minutos, volteándolos a mitad para un dorado uniforme y un interior jugoso."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C (preferiblemente con función grill o ventilador). Coloca los filetes de lomo sazonados y aceitados en una bandeja y hornea durante 15-20 minutos, volteándolos una vez, hasta que estén dorados y cocidos."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Aguacate}} en dados medianos y {{Tomate cherry}} por la mitad.","minutes":3,"kind":"prep","part":"guarnicion"},{"text":"Desmenuzar {{Queso feta}} sobre el aguacate y el tomate cherry.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Aliñar la ensalada con {{Aceite de oliva|chorrito}}, {{Orégano seco|pizca}} y {{Sal|gusto}}.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Salpimentar {{Lomo de cerdo en filetes}} por ambas caras.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté bien caliente.","minutes":1,"kind":"activo","part":"principal"},{"text":"Colocar los filetes en la plancha y cocinar 3 min por cada lado hasta que estén dorados.","minutes":6,"kind":"activo","part":"principal"},{"text":"Retirar los filetes de la plancha y dejar reposar 2 min.","minutes":2,"kind":"espera","part":"principal"},{"text":"Servir el lomo junto con la ensalada de aguacate, tomate cherry y queso feta.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_133', 'Pollo a la plancha con especias cajún y ensalada de aguacate, maíz y cilantro', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 470, 40, 22, 22, 2, false, false, '{}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Especias cajún","amount":8,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Maíz dulce cocido","amount":100,"unit":"g"},{"name":"Cilantro fresco","amount":5,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Cortar pechuga de pollo en filetes uniformes de unos 2 cm de grosor.","Salpimentar los filetes con especias cajún y sal por ambas caras.","Calentar plancha con aceite de oliva a fuego fuerte hasta que humee.","Cocinar los filetes en plancha 5 min por el primer lado sin moverlos, hasta que se doren.","Cortar aguacate en dados de unos 2 cm.","Picar cilantro fresco fino.","Dar la vuelta a los filetes y cocinar 5 min más hasta que estén hechos por dentro.","Exprimir lima y reservar el zumo.","Mezclar el aguacate en dados con maíz dulce cocido y el cilantro picado en un bol.","Aliñar la ensalada con el zumo de lima, aceite de oliva y sal al gusto.","Retirar los filetes de la plancha y reposar 3 min antes de cortar.","Cortar los filetes en tiras.","Servir las tiras de pollo junto a la ensalada de aguacate, maíz y cilantro."}', 'Pollo a la plancha con especias cajún y una ensalada refrescante de aguacate, maíz y cilantro.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Marinar el pollo con las especias y aceite. Cocinar en la airfryer precalentada a 190°C durante 15-18 minutos, volteando a mitad, para un exterior dorado y un interior jugoso. La ensalada se prepara aparte."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Marinar el pollo con las especias y aceite. Hornear en el horno precalentado a 200°C durante 20-25 minutos, hasta que esté bien cocido y ligeramente dorado. La ensalada se prepara en frío."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pechuga de pollo}} en filetes uniformes de unos 2 cm de grosor.","minutes":2,"kind":"prep","part":"principal"},{"text":"Salpimentar los filetes con {{Especias cajún}} y {{Sal|gusto}} por ambas caras.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} con {{Aceite de oliva|chorrito}} a fuego fuerte hasta que humee.","minutes":2,"kind":"activo","part":"principal"},{"text":"Cocinar los filetes en {{@Plancha}} 5 min por el primer lado sin moverlos, hasta que se doren.","minutes":5,"kind":"pasivo","part":"principal"},{"text":"Cortar {{Aguacate}} en dados de unos 2 cm.","minutes":2,"kind":"paralelo","part":"guarnicion","during":3},{"text":"Picar {{Cilantro fresco}} fino.","minutes":1,"kind":"paralelo","part":"guarnicion","during":3},{"text":"Dar la vuelta a los filetes y cocinar 5 min más hasta que estén hechos por dentro.","minutes":5,"kind":"pasivo","part":"principal"},{"text":"Exprimir {{Lima}} y reservar el zumo.","minutes":1,"kind":"paralelo","part":"guarnicion","during":6},{"text":"Mezclar el aguacate en dados con {{Maíz dulce cocido}} y el cilantro picado en un bol.","minutes":1,"kind":"paralelo","part":"guarnicion","during":6},{"text":"Aliñar la ensalada con el zumo de lima, {{Aceite de oliva|chorrito}} y sal al gusto.","minutes":1,"kind":"paralelo","part":"guarnicion","during":6},{"text":"Retirar los filetes de la plancha y reposar 3 min antes de cortar.","minutes":3,"kind":"espera","part":"principal"},{"text":"Cortar los filetes en tiras.","minutes":1,"kind":"prep","part":"principal"},{"text":"Servir las tiras de pollo junto a la ensalada de aguacate, maíz y cilantro.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_134', 'Filete de pavo a la plancha con ensalada de aguacate, tomate y mostaza a la antigua', 'carnes', 'pavo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 420, 38, 14, 22, 2, true, false, '{"mostaza","sulfitos"}', '[{"name":"Filete de pavo","amount":350,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Mostaza a la antigua","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Cortar aguacate en láminas y tomate en gajos.","Mezclar mostaza a la antigua, aceite de oliva, vinagre de vino y sal en un bol hasta integrar.","Salpimentar filete de pavo por ambas caras.","Calentar plancha con aceite de oliva a fuego fuerte.","Cocinar el filete de pavo 3 min por cada lado hasta que esté dorado y bien hecho por dentro.","Disponer las láminas de aguacate y los gajos de tomate en el plato.","Aliñar la ensalada con la vinagreta de mostaza.","Servir el filete de pavo junto a la ensalada aliñada."}', 'Filete de pavo a la plancha con una ensalada de aguacate y tomate aliñada con mostaza a la antigua.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Cocina el filete de pavo durante 12-15 minutos, dándole la vuelta a mitad, hasta que esté dorado y jugoso."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200-220°C, preferiblemente con función grill. Coloca el filete en una bandeja y cocina 15-20 minutos, volteándolo una vez, hasta que esté hecho y ligeramente dorado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Aguacate}} en láminas y {{Tomate}} en gajos.","minutes":3,"kind":"prep","part":"guarnicion"},{"text":"Mezclar {{Mostaza a la antigua}}, {{Aceite de oliva|chorrito}}, {{Vinagre de vino}} y {{Sal|gusto}} en un bol hasta integrar.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Salpimentar {{Filete de pavo}} por ambas caras.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} con {{Aceite de oliva|chorrito}} a fuego fuerte.","minutes":1,"kind":"activo","part":"principal"},{"text":"Cocinar el filete de pavo 3 min por cada lado hasta que esté dorado y bien hecho por dentro.","minutes":6,"kind":"activo","part":"principal"},{"text":"Disponer las láminas de aguacate y los gajos de tomate en el plato.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Aliñar la ensalada con la vinagreta de mostaza.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Servir el filete de pavo junto a la ensalada aliñada.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true)
