insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('carnes_135', 'Bowl mexicano de pollo, arroz y frijoles', 'carnes', 'pollo', 'arroz', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 620, 40, 68, 20, 2, true, true, '{}', '[{"name":"Pechuga de pollo","amount":300,"unit":"g"},{"name":"Arroz blanco","amount":150,"unit":"g"},{"name":"Frijoles negros cocidos","amount":200,"unit":"g"},{"name":"Maíz dulce cocido","amount":80,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Cebolla morada","amount":40,"unit":"g"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Llevar a ebullición agua con sal en un cazo y cocer arroz blanco según el tiempo del envase.","Cortar pechuga de pollo en dados de tamaño uniforme.","Sazonar los dados de pechuga de pollo con comino molido, pimentón dulce y sal.","Picar tomate y cebolla morada en dados pequeños y reservar.","Escurrir el arroz blanco cocido y reservar caliente.","Calentar aceite de oliva en sartén a fuego fuerte.","Saltear los dados de pechuga de pollo hasta que estén dorados por fuera y cocidos por dentro.","Calentar frijoles negros cocidos en un cazo a fuego medio hasta que estén calientes.","Repartir el arroz blanco en la base de 2 boles.","Disponer encima el pollo salteado, los frijoles negros y maíz dulce cocido en montones separados.","Añadir el tomate y la cebolla morada picados sobre el resto de ingredientes del bol.","Exprimir lima sobre cada bol y servir de inmediato."}', 'Bowl mexicano completo con pollo especiado, arroz, frijoles negros y maíz, listo en boles individuales.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Corta el pollo en dados, sazona y cocina en la airfryer a 190°C durante 15-18 minutos, volteando a mitad, hasta que esté dorado y cocido."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Hornea la pechuga de pollo sazonada a 200°C durante 20-25 minutos hasta que esté bien cocida y ligeramente dorada."},{"appliance":"thermomix","time":30,"difficulty":"normal","prepSummary":"Cocina el arroz en el vaso y el pollo en el Varoma (o sofríe en el vaso) para integrar todos los ingredientes de forma eficiente."},{"appliance":"vaporera","time":25,"difficulty":"facil","prepSummary":"Cocina el arroz y la pechuga de pollo troceada al vapor durante 20-25 minutos hasta que estén tiernos y jugosos."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Cocina el arroz y la pechuga de pollo en la olla express por separado durante unos 5-7 minutos desde que sube la presión para una cocción rápida."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Llevar a ebullición agua con sal en un cazo y cocer {{Arroz blanco}} según el tiempo del envase.","minutes":12,"kind":"pasivo","part":"guarnicion"},{"text":"Cortar {{Pechuga de pollo}} en dados de tamaño uniforme.","minutes":3,"kind":"prep","part":"principal"},{"text":"Sazonar los dados de pechuga de pollo con {{Comino molido|pizca}}, {{Pimentón dulce|pizca}} y {{Sal|gusto}}.","minutes":1,"kind":"prep","part":"principal"},{"text":"Picar {{Tomate}} y {{Cebolla morada}} en dados pequeños y reservar.","minutes":3,"kind":"prep","part":"principal"},{"text":"Escurrir el arroz blanco cocido y reservar caliente.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo","part":"principal"},{"text":"Saltear los dados de pechuga de pollo hasta que estén dorados por fuera y cocidos por dentro.","minutes":7,"kind":"activo","part":"principal"},{"text":"Calentar {{Frijoles negros cocidos}} en un cazo a fuego medio hasta que estén calientes.","minutes":3,"kind":"pasivo","part":"guarnicion"},{"text":"Repartir el arroz blanco en la base de 2 boles.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Disponer encima el pollo salteado, los frijoles negros y {{Maíz dulce cocido}} en montones separados.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Añadir el tomate y la cebolla morada picados sobre el resto de ingredientes del bol.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Exprimir {{Lima}} sobre cada bol y servir de inmediato.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_136', 'Vol-au-vent de setas y foie', 'carnes', 'none', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 45, 'elaborada', 'invierno', 480, 12, 28, 36, 2, false, false, '{"gluten","lactosa","sulfitos"}', '[{"name":"Vol-au-vent de hojaldre","amount":4,"unit":"ud"},{"name":"Foie fresco o mi-cuit","amount":100,"unit":"g"},{"name":"Setas variadas","amount":250,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Vino oloroso","amount":30,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Picar cebolla fino.","Limpiar setas variadas y cortar en trozos medianos.","Fundir mantequilla en sartén a fuego medio.","Sofreír la cebolla picada a fuego suave hasta que esté transparente.","Añadir las setas troceadas y saltear a fuego medio hasta que suelten el agua y se doren ligeramente.","Verter vino oloroso y remover hasta que reduzca.","Añadir nata para cocinar y remover a fuego suave hasta que la salsa espese ligeramente.","Salpimentar con sal y pimienta negra.","Retirar la sartén del fuego.","Cortar foie fresco o mi-cuit en dados de unos 2 cm.","Añadir los dados de foie a la sartén fuera del fuego y remover con suavidad hasta que se funda parcialmente.","Calentar vol-au-vent de hojaldre en el horno a 180 °C durante 5 min.","Rellenar los vol-au-vent calientes con la mezcla de setas y foie.","Servir de inmediato para conservar el hojaldre crujiente."}', 'Vol-au-vent de hojaldre relleno de una cremosa mezcla de setas salteadas y foie, listo para una ocasión especial.', '[{"appliance":"horno","time":40,"difficulty":"elaborada","prepSummary":"Prepara el sofrito de cebolla y setas en una sartén. Sella el foie y desglasa con vino, luego añade la nata. Rellena los vol-au-vents y hornea a 180°C durante 15-20 minutos hasta que estén dorados y el relleno caliente."},{"appliance":"airfryer","time":30,"difficulty":"normal","prepSummary":"Prepara el relleno de setas, foie y nata en una sartén. Calienta los vol-au-vents vacíos en la airfryer a 180°C durante 5-7 minutos hasta que estén crujientes. Rellénalos y calienta todo junto 3-5 minutos más para servir."},{"appliance":"thermomix","time":35,"difficulty":"normal","prepSummary":"Sofríe la cebolla y las setas en el vaso. Añade el vino, la nata y el foie mi-cuit (o fresco sellado aparte), cocina a 90°C, velocidad cuchara hasta obtener una crema. Rellena los vol-au-vents previamente horneados para mantener su textura crujiente."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Cebolla}} fino.","minutes":2,"kind":"prep"},{"text":"Limpiar {{Setas variadas}} y cortar en trozos medianos.","minutes":3,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada a fuego suave hasta que esté transparente.","minutes":5,"kind":"pasivo"},{"text":"Añadir las setas troceadas y saltear a fuego medio hasta que suelten el agua y se doren ligeramente.","minutes":7,"kind":"activo"},{"text":"Verter {{Vino oloroso}} y remover hasta que reduzca.","minutes":2,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}} y remover a fuego suave hasta que la salsa espese ligeramente.","minutes":4,"kind":"activo"},{"text":"Salpimentar con {{Sal|gusto}} y {{Pimienta negra|pizca}}.","minutes":1,"kind":"activo"},{"text":"Retirar la sartén del fuego.","minutes":1,"kind":"activo"},{"text":"Cortar {{Foie fresco o mi-cuit}} en dados de unos 2 cm.","minutes":2,"kind":"prep"},{"text":"Añadir los dados de foie a la sartén fuera del fuego y remover con suavidad hasta que se funda parcialmente.","minutes":1,"kind":"activo"},{"text":"Calentar {{Vol-au-vent de hojaldre}} en el horno a 180 °C durante 5 min.","minutes":5,"kind":"pasivo"},{"text":"Rellenar los vol-au-vent calientes con la mezcla de setas y foie.","minutes":2,"kind":"emplatado"},{"text":"Servir de inmediato para conservar el hojaldre crujiente.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_137', 'Croquetas de pollo asado', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 75, 'normal', 'all', 420, 22, 32, 22, 4, true, false, '{"gluten","lactosa","huevo"}', '[{"name":"Pollo asado desmenuzado","amount":300,"unit":"g"},{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Harina","amount":70,"unit":"g"},{"name":"Leche","amount":700,"unit":"ml"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Pan rallado","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":500,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"}]'::jsonb, '{"Picar cebolla muy fina.","Desmenuzar pollo asado desmenuzado en trozos pequeños.","Fundir mantequilla en una cazuela a fuego medio.","Sofreír la cebolla picada a fuego suave hasta que esté transparente.","Añadir harina y remover sin parar a fuego medio hasta que se tueste, unos 2 min.","Verter leche poco a poco sin dejar de remover hasta que no quede ningún grumo.","Añadir el pollo desmenuzado, sal y nuez moscada; remover para integrar.","Cocer la masa a fuego suave, removiendo con frecuencia, hasta que se despegue de las paredes.","Extender la masa en una fuente y cubrir con film a piel para que no forme costra.","Refrigerar la masa en la nevera hasta que esté completamente fría y firme.","Batir huevo en un bol hondo.","Extender pan rallado en un plato llano.","Formar las croquetas con las manos, dándoles forma alargada y uniforme.","Pasar cada croqueta por el huevo batido y después por el pan rallado, cubriendo bien toda la superficie.","Calentar aceite de oliva en una sartén honda hasta alcanzar 180 °C.","Freír las croquetas en tandas hasta que estén doradas por fuera, unos 2-3 min por tanda.","Escurrir las croquetas sobre papel absorbente para retirar el exceso de aceite.","Servir las croquetas calientes."}', 'Croquetas cremosas hechas con restos de pollo asado, bechamel casera y un rebozado crujiente.', '[{"appliance":"airfryer","time":75,"difficulty":"normal","prepSummary":"Prepara la bechamel de forma tradicional. Una vez formadas y empanadas las croquetas, rocíalas ligeramente con aceite y cocínalas en la airfryer a 190-200°C durante 12-15 minutos, dándoles la vuelta a mitad, hasta que estén doradas y crujientes."},{"appliance":"horno","time":75,"difficulty":"normal","prepSummary":"Tras preparar la bechamel y empanar las croquetas, colócalas en una bandeja de horno con papel y rocía con un poco de aceite. Hornea a 200°C (con ventilador si es posible) durante 20-25 minutos, volteándolas a mitad, hasta que estén doradas."},{"appliance":"thermomix","time":60,"difficulty":"normal","prepSummary":"Utiliza la Thermomix para preparar la bechamel: pica la cebolla, sofríela con la mantequilla y luego añade la harina, leche, pollo y especias, cocinando a temperatura y velocidad controladas hasta obtener una masa perfecta. Luego, forma y fríe las croquetas de manera tradicional."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Picar {{Cebolla}} muy fina.","minutes":3,"kind":"prep"},{"text":"Desmenuzar {{Pollo asado desmenuzado}} en trozos pequeños.","minutes":3,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en una cazuela a fuego medio.","minutes":2,"kind":"activo"},{"text":"Sofreír la cebolla picada a fuego suave hasta que esté transparente.","minutes":5,"kind":"activo"},{"text":"Añadir {{Harina}} y remover sin parar a fuego medio hasta que se tueste, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Verter {{Leche}} poco a poco sin dejar de remover hasta que no quede ningún grumo.","minutes":5,"kind":"activo"},{"text":"Añadir el pollo desmenuzado, {{Sal|gusto}} y {{Nuez moscada|pizca}}; remover para integrar.","minutes":2,"kind":"activo"},{"text":"Cocer la masa a fuego suave, removiendo con frecuencia, hasta que se despegue de las paredes.","minutes":10,"kind":"activo"},{"text":"Extender la masa en una fuente y cubrir con film a piel para que no forme costra.","minutes":5,"kind":"activo"},{"text":"Refrigerar la masa en la nevera hasta que esté completamente fría y firme.","minutes":180,"kind":"espera"},{"text":"Batir {{Huevo}} en un bol hondo.","minutes":1,"kind":"prep"},{"text":"Extender {{Pan rallado}} en un plato llano.","minutes":1,"kind":"prep"},{"text":"Formar las croquetas con las manos, dándoles forma alargada y uniforme.","minutes":10,"kind":"prep"},{"text":"Pasar cada croqueta por el huevo batido y después por el pan rallado, cubriendo bien toda la superficie.","minutes":5,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en una sartén honda hasta alcanzar 180 °C.","minutes":4,"kind":"activo"},{"text":"Freír las croquetas en tandas hasta que estén doradas por fuera, unos 2-3 min por tanda.","minutes":9,"kind":"activo"},{"text":"Escurrir las croquetas sobre papel absorbente para retirar el exceso de aceite.","minutes":2,"kind":"activo"},{"text":"Servir las croquetas calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_138', 'Croquetas de cocido de la abuela', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 75, 'normal', 'all', 410, 20, 32, 22, 4, true, false, '{"gluten","lactosa","huevo"}', '[{"name":"Carne de cocido desmenuzada","amount":300,"unit":"g"},{"name":"Caldo de cocido","amount":500,"unit":"ml"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Harina","amount":70,"unit":"g"},{"name":"Leche","amount":250,"unit":"ml"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Pan rallado","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":500,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Desmenuzar carne de cocido desmenuzada con las manos hasta obtener hebras muy finas.","Fundir mantequilla en una cazuela a fuego suave hasta que se derrita por completo.","Añadir harina de golpe y remover sin parar con una varilla durante 2 min hasta que la mezcla forme una pasta dorada.","Verter caldo de cocido poco a poco sin dejar de remover con la varilla para evitar grumos.","Añadir leche poco a poco, alternando con el caldo, sin parar de remover hasta integrar todo.","Incorporar la carne desmenuzada, sal y nuez moscada; remover bien para integrar.","Cocer la masa a fuego suave sin dejar de remover hasta que se despegue de las paredes de la cazuela.","Extender la masa en una fuente y cubrir con film a piel para que no forme costra.","Enfriar la fuente en la nevera hasta que la masa esté completamente fría y firme.","Batir huevo en un bol hondo hasta que la yema y la clara estén bien integradas.","Poner pan rallado en un plato llano y disponer el bol con el huevo batido al lado.","Tomar porciones de masa fría y dar forma alargada con las manos hasta formar cada croqueta.","Pasar cada croqueta primero por el huevo batido y después por el pan rallado, cubriendo bien toda la superficie.","Calentar aceite de oliva en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","Freír las croquetas en tandas pequeñas durante 2-3 min hasta que estén doradas por todos los lados.","Escurrir las croquetas fritas sobre papel absorbente para retirar el exceso de aceite.","Servir las croquetas recién fritas y bien calientes."}', 'Croquetas hechas con los restos del cocido de la abuela, cremosas por dentro y crujientes por fuera.', '[{"appliance":"thermomix","time":60,"difficulty":"normal","prepSummary":"La Thermomix es ideal para la masa de las croquetas. Sofríe la mantequilla y harina, añade líquidos y carne, y cocina a 90°C, velocidad 4, durante 8-10 minutos, obteniendo una bechamel perfecta y sin grumos. El resto del proceso (enfriar, formar y freír) se mantiene igual."},{"appliance":"airfryer","time":80,"difficulty":"normal","prepSummary":"Para un acabado crujiente y más saludable, precalienta la airfryer a 190°C. Rocía ligeramente las croquetas ya empanadas con aceite y cocina durante 12-15 minutos, dándoles la vuelta a mitad, hasta que estén doradas y crujientes. La masa se prepara de forma tradicional."},{"appliance":"horno","time":85,"difficulty":"normal","prepSummary":"Para una versión horneada, precalienta el horno a 200°C. Coloca las croquetas empanadas en una bandeja con papel de horno y un chorrito de aceite. Hornea durante 20-25 minutos, volteando a mitad, hasta que estén doradas y cocidas por dentro. La masa se prepara de forma tradiciona"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Desmenuzar {{Carne de cocido desmenuzada}} con las manos hasta obtener hebras muy finas.","minutes":5,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en una cazuela a fuego suave hasta que se derrita por completo.","minutes":2,"kind":"activo"},{"text":"Añadir {{Harina}} de golpe y remover sin parar con una varilla durante 2 min hasta que la mezcla forme una pasta dorada.","minutes":2,"kind":"activo"},{"text":"Verter {{Caldo de cocido}} poco a poco sin dejar de remover con la varilla para evitar grumos.","minutes":3,"kind":"activo"},{"text":"Añadir {{Leche}} poco a poco, alternando con el caldo, sin parar de remover hasta integrar todo.","minutes":3,"kind":"activo"},{"text":"Incorporar la carne desmenuzada, {{Sal|gusto}} y {{Nuez moscada|pizca}}; remover bien para integrar.","minutes":2,"kind":"activo"},{"text":"Cocer la masa a fuego suave sin dejar de remover hasta que se despegue de las paredes de la cazuela.","minutes":9,"kind":"activo"},{"text":"Extender la masa en una fuente y cubrir con film a piel para que no forme costra.","minutes":2,"kind":"prep"},{"text":"Enfriar la fuente en la nevera hasta que la masa esté completamente fría y firme.","minutes":180,"kind":"espera"},{"text":"Batir {{Huevo}} en un bol hondo hasta que la yema y la clara estén bien integradas.","minutes":1,"kind":"prep"},{"text":"Poner {{Pan rallado}} en un plato llano y disponer el bol con el huevo batido al lado.","minutes":1,"kind":"prep"},{"text":"Tomar porciones de masa fría y dar forma alargada con las manos hasta formar cada croqueta.","minutes":8,"kind":"prep"},{"text":"Pasar cada croqueta primero por el huevo batido y después por el pan rallado, cubriendo bien toda la superficie.","minutes":5,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","minutes":4,"kind":"activo"},{"text":"Freír las croquetas en tandas pequeñas durante 2-3 min hasta que estén doradas por todos los lados.","minutes":3,"kind":"activo"},{"text":"Escurrir las croquetas fritas sobre papel absorbente para retirar el exceso de aceite.","minutes":1,"kind":"activo"},{"text":"Servir las croquetas recién fritas y bien calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_139', 'Empanadillas de morcilla y piñones', 'carnes', 'cerdo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 40, 'normal', 'all', 430, 14, 34, 28, 4, false, false, '{"gluten","frutos_secos"}', '[{"name":"Obleas de empanadilla","amount":16,"unit":"ud"},{"name":"Morcilla","amount":250,"unit":"g"},{"name":"Piñones","amount":40,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":500,"unit":"ml"}]'::jsonb, '{"Picar cebolla en brunoise fina.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada a fuego medio hasta que esté transparente.","Retirar la piel de morcilla y desmenuzar la carne directamente en la sartén.","Añadir piñones y mezclar con la morcilla a fuego medio.","Cocinar el relleno hasta que la morcilla esté integrada y ligeramente crujiente.","Retirar la sartén del fuego y dejar templar el relleno.","Extender obleas de empanadilla sobre una superficie limpia.","Colocar una cucharada del relleno en el centro de cada oblea.","Humedecer los bordes de cada oblea con un poco de agua.","Doblar cada oblea por la mitad y sellar los bordes presionando con un tenedor.","Calentar aceite de oliva en sartén hasta alcanzar 180 °C.","Freír las empanadillas en tandas hasta que estén doradas por un lado.","Dar la vuelta a las empanadillas y freír hasta que estén doradas por el otro lado.","Escurrir las empanadillas sobre papel absorbente y servir calientes."}', 'Empanadillas fritas y crujientes rellenas de morcilla y piñones, con la sorpresa oscura del relleno al morderlas.', '[{"appliance":"airfryer","time":25,"difficulty":"normal","prepSummary":"Prepara el relleno sofriendo la cebolla y la morcilla, luego rellena las obleas. Cocina las empanadillas en la airfryer a 190°C durante 12-15 minutos, volteándolas a mitad, hasta que estén doradas y crujientes con muy poco aceite."},{"appliance":"horno","time":30,"difficulty":"normal","prepSummary":"Elabora el relleno sofriendo la cebolla y la morcilla. Rellena las obleas, séllalas y hornea a 200°C durante 15-20 minutos, pincelándolas con huevo batido o un poco de aceite para un acabado dorado y crujiente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Picar {{Cebolla}} en brunoise fina.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada a fuego medio hasta que esté transparente.","minutes":5,"kind":"activo"},{"text":"Retirar la piel de {{Morcilla}} y desmenuzar la carne directamente en la sartén.","minutes":2,"kind":"activo"},{"text":"Añadir {{Piñones}} y mezclar con la morcilla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Cocinar el relleno hasta que la morcilla esté integrada y ligeramente crujiente.","minutes":3,"kind":"activo"},{"text":"Retirar la sartén del fuego y dejar templar el relleno.","minutes":5,"kind":"espera"},{"text":"Extender {{Obleas de empanadilla}} sobre una superficie limpia.","minutes":1,"kind":"prep"},{"text":"Colocar una cucharada del relleno en el centro de cada oblea.","minutes":3,"kind":"prep"},{"text":"Humedecer los bordes de cada oblea con un poco de agua.","minutes":1,"kind":"prep"},{"text":"Doblar cada oblea por la mitad y sellar los bordes presionando con un tenedor.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} hasta alcanzar 180 °C.","minutes":3,"kind":"activo"},{"text":"Freír las empanadillas en tandas hasta que estén doradas por un lado.","minutes":3,"kind":"activo"},{"text":"Dar la vuelta a las empanadillas y freír hasta que estén doradas por el otro lado.","minutes":3,"kind":"activo"},{"text":"Escurrir las empanadillas sobre papel absorbente y servir calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_140', 'Tarta de puerros y bacon', 'carnes', 'cerdo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 60, 'normal', 'all', 480, 18, 30, 32, 6, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Masa quebrada","amount":1,"unit":"ud"},{"name":"Puerro","amount":400,"unit":"g"},{"name":"Bacon en dados","amount":150,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Nata para cocinar","amount":200,"unit":"ml"},{"name":"Queso rallado","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"},{"name":"Nuez moscada","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C con calor arriba y abajo.","Lavar puerro y cortar en rodajas finas.","Forrar un molde de tarta con masa quebrada y pinchar la base con un tenedor.","Hornear la base en blanco a 190 °C durante 10 min.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír bacon en dados en la sartén 4 min hasta que empiece a dorarse.","Añadir el puerro cortado y sofreír a fuego medio 10 min hasta que esté blando.","Retirar la sartén del fuego y reservar el sofrito para que temple.","Batir huevo con nata para cocinar en un bol hasta integrar.","Añadir sal, pimienta negra y nuez moscada al bol y mezclar.","Repartir el sofrito de puerro y bacon sobre la base precocida de forma uniforme.","Verter la mezcla de huevo y nata sobre el relleno con cuidado.","Espolvorear queso rallado de forma uniforme sobre la superficie.","Hornear a 180 °C durante 30 min hasta que la tarta esté cuajada y dorada.","Retirar del horno y dejar templar 5 min antes de desmoldar.","Cortar en porciones y servir."}', 'Tarta salada de puerros pochados y bacon crujiente sobre una base de masa quebrada, cuajada al horno.', '[{"appliance":"horno","time":70,"difficulty":"normal","prepSummary":"Prepara el relleno salteando puerros y bacon, luego mézclalo con los huevos, nata y queso. Vierte sobre la masa quebrada en un molde y hornea a 180-200°C durante 40-50 minutos hasta que esté dorada y cuajada."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Saltea los puerros y el bacon por separado. Monta la tarta en un molde apto para airfryer. Cocina a 160-170°C durante 35-45 minutos, vigilando que no se dore demasiado rápido, hasta que el relleno esté cuajado y la masa dorada."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 190 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Lavar {{Puerro}} y cortar en rodajas finas.","minutes":5,"kind":"prep"},{"text":"Forrar un molde de tarta con {{Masa quebrada}} y pinchar la base con un tenedor.","minutes":3,"kind":"prep"},{"text":"Hornear la base en blanco a 190 °C durante 10 min.","minutes":10,"kind":"pasivo"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír {{Bacon en dados}} en la sartén 4 min hasta que empiece a dorarse.","minutes":4,"kind":"activo"},{"text":"Añadir el puerro cortado y sofreír a fuego medio 10 min hasta que esté blando.","minutes":10,"kind":"activo"},{"text":"Retirar la sartén del fuego y reservar el sofrito para que temple.","minutes":5,"kind":"espera"},{"text":"Batir {{Huevo}} con {{Nata para cocinar}} en un bol hasta integrar.","minutes":2,"kind":"prep"},{"text":"Añadir {{Sal|gusto}}, {{Pimienta negra|pizca}} y {{Nuez moscada|pizca}} al bol y mezclar.","minutes":1,"kind":"prep"},{"text":"Repartir el sofrito de puerro y bacon sobre la base precocida de forma uniforme.","minutes":2,"kind":"activo"},{"text":"Verter la mezcla de huevo y nata sobre el relleno con cuidado.","minutes":1,"kind":"activo"},{"text":"Espolvorear {{Queso rallado}} de forma uniforme sobre la superficie.","minutes":1,"kind":"activo"},{"text":"Hornear a 180 °C durante 30 min hasta que la tarta esté cuajada y dorada.","minutes":30,"kind":"pasivo"},{"text":"Retirar del horno y dejar templar 5 min antes de desmoldar.","minutes":5,"kind":"espera"},{"text":"Cortar en porciones y servir.","minutes":2,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_141', 'Pastel de patata y carne (shepherd''s pie casero)', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 60, 'normal', 'all', 520, 28, 40, 26, 4, true, true, '{"lactosa"}', '[{"name":"Patata","amount":800,"unit":"g"},{"name":"Carne picada de ternera","amount":400,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Guisantes","amount":80,"unit":"g"},{"name":"Caldo de carne","amount":150,"unit":"ml"},{"name":"Leche","amount":80,"unit":"ml"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Tomate concentrado","amount":20,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en trozos grandes.","Cocer las patatas en una olla con agua y sal hasta que estén tiernas.","Picar cebolla en dados pequeños.","Cortar zanahoria en dados pequeños.","Precalentar el horno a 200 °C.","Escurrir las patatas cocidas y volcarlas en un bol grande.","Añadir mantequilla y leche a las patatas escurridas.","Triturar las patatas con la mantequilla y la leche hasta obtener un puré suave.","Salpimentar el puré con pimienta negra y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla y la zanahoria picadas hasta que estén blandas.","Añadir carne picada de ternera y deshacer los grumos con una cuchara.","Dorar la carne a fuego medio-fuerte hasta que esté bien dorada.","Añadir guisantes, caldo de carne y tomate concentrado; remover para integrar.","Cocer a fuego medio hasta que la salsa reduzca y espese.","Verter el relleno de carne en una fuente de horno formando una capa uniforme.","Cubrir el relleno con el puré de patata y alisar la superficie con un tenedor creando surcos.","Hornear a 200 °C hasta que la superficie esté dorada.","Reposar la fuente fuera del horno antes de servir.","Servir en plato hondo racionando con una espátula."}', 'Pastel de carne picada con verduras cubierto de puré de patata dorado al horno.', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Prepara el puré de patata y el sofrito de carne en la encimera. Monta el pastel en una fuente apta para horno y hornea a 180-200°C durante 25-30 minutos, hasta que el puré esté dorado y burbujeante."},{"appliance":"thermomix","time":65,"difficulty":"facil","prepSummary":"Utiliza la Thermomix para cocinar las patatas al vapor y hacer el puré, así como para preparar el sofrito de carne. Luego, monta el pastel en una fuente y gratina en el horno a 200°C durante 15-20 minutos para un acabado perfecto."},{"appliance":"olla_express","time":55,"difficulty":"normal","prepSummary":"Acelera la cocción de las patatas y el sofrito de carne usando la olla express. Una vez listos, monta el pastel en una fuente y gratina en el horno a 200°C durante 15-20 minutos para obtener el gratinado característico."},{"appliance":"airfryer","time":65,"difficulty":"normal","prepSummary":"Prepara el puré de patata y el sofrito de carne por separado en la encimera. Monta el pastel en un recipiente apto para airfryer y cocina a 180°C durante 20-25 minutos, hasta que el puré esté dorado y burbujeante."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Patata}} y cortar en trozos grandes.","minutes":5,"kind":"prep"},{"text":"Cocer las patatas en una olla con agua y {{Sal|gusto}} hasta que estén tiernas.","minutes":20,"kind":"pasivo"},{"text":"Picar {{Cebolla}} en dados pequeños.","minutes":3,"kind":"paralelo","during":1},{"text":"Cortar {{Zanahoria}} en dados pequeños.","minutes":3,"kind":"paralelo","during":1},{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"paralelo","during":1},{"text":"Escurrir las patatas cocidas y volcarlas en un bol grande.","minutes":1,"kind":"prep","part":"principal"},{"text":"Añadir {{Mantequilla}} y {{Leche}} a las patatas escurridas.","minutes":1,"kind":"prep","part":"principal"},{"text":"Triturar las patatas con la mantequilla y la leche hasta obtener un puré suave.","minutes":3,"kind":"activo","part":"principal"},{"text":"Salpimentar el puré con {{Pimienta negra|pizca}} y reservar.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Sofreír la cebolla y la zanahoria picadas hasta que estén blandas.","minutes":6,"kind":"activo","part":"guarnicion"},{"text":"Añadir {{Carne picada de ternera}} y deshacer los grumos con una cuchara.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Dorar la carne a fuego medio-fuerte hasta que esté bien dorada.","minutes":8,"kind":"activo","part":"guarnicion"},{"text":"Añadir {{Guisantes}}, {{Caldo de carne}} y {{Tomate concentrado}}; remover para integrar.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Cocer a fuego medio hasta que la salsa reduzca y espese.","minutes":10,"kind":"pasivo","part":"guarnicion"},{"text":"Verter el relleno de carne en una fuente de horno formando una capa uniforme.","minutes":2,"kind":"activo","part":"combinado"},{"text":"Cubrir el relleno con el puré de patata y alisar la superficie con un tenedor creando surcos.","minutes":2,"kind":"activo","part":"combinado"},{"text":"Hornear a 200 °C hasta que la superficie esté dorada.","minutes":22,"kind":"pasivo","part":"combinado"},{"text":"Reposar la fuente fuera del horno antes de servir.","minutes":5,"kind":"espera","part":"combinado"},{"text":"Servir en plato hondo racionando con una espátula.","minutes":2,"kind":"emplatado","part":"combinado"}]'::jsonb, true),
  ('carnes_142', 'Calzone de jamón y queso', 'carnes', 'cerdo', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 40, 'normal', 'all', 620, 28, 62, 28, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Masa de pizza","amount":300,"unit":"g"},{"name":"Jamón cocido en lonchas","amount":100,"unit":"g"},{"name":"Queso mozzarella","amount":150,"unit":"g"},{"name":"Tomate frito","amount":60,"unit":"g"},{"name":"Orégano seco","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Harina","amount":20,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 220 °C con calor arriba y abajo, introduciendo la bandeja vacía para que se caliente.","Espolvorear la superficie de trabajo con harina y dividir masa de pizza en 2 porciones iguales.","Estirar cada porción con un rodillo hasta obtener 2 círculos de unos 25 cm de diámetro.","Laminar queso mozzarella en lonchas finas si no viene ya loncheada.","Untar la mitad de cada círculo con tomate frito, dejando 1 cm de borde libre.","Repartir jamón cocido en lonchas sobre el tomate frito de cada círculo.","Distribuir la mozzarella sobre el jamón cocido.","Espolvorear orégano seco sobre el relleno de cada calzone.","Doblar cada círculo por la mitad sobre el relleno y sellar el borde presionando con los dedos.","Rematar el sellado repasando el borde con un tenedor para que no se abra al hornear.","Pincelar la superficie de cada calzone con aceite de oliva.","Colocar los calzones sobre la bandeja caliente y hornear hasta que estén dorados y crujientes.","Retirar del horno y dejar templar hasta que el relleno no queme al cortar.","Servir los calzones en plato, enteros o cortados por la mitad."}', 'Calzone casero de jamón y queso con tomate frito, dorado y crujiente por fuera, fundente por dentro.', '[{"appliance":"horno","time":40,"difficulty":"normal","prepSummary":"Precalienta el horno a 200°C. Rellena la masa, sella bien los bordes y hornea durante 25-30 minutos, o hasta que esté dorado y el queso burbujee. Para un acabado más crujiente, pincela con aceite de oliva antes de hornear."},{"appliance":"airfryer","time":30,"difficulty":"facil","prepSummary":"Divide la masa en porciones más pequeñas para formar mini calzones individuales. Precalienta la airfryer a 180°C. Cocina cada calzone durante 15-20 minutos, dándoles la vuelta a mitad de cocción, hasta que estén dorados y crujientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 220 °C con calor arriba y abajo, introduciendo la bandeja vacía para que se caliente.","minutes":10,"kind":"pasivo"},{"text":"Espolvorear la superficie de trabajo con {{Harina}} y dividir {{Masa de pizza}} en 2 porciones iguales.","minutes":2,"kind":"prep"},{"text":"Estirar cada porción con un rodillo hasta obtener 2 círculos de unos 25 cm de diámetro.","minutes":3,"kind":"prep"},{"text":"Laminar {{Queso mozzarella}} en lonchas finas si no viene ya loncheada.","minutes":2,"kind":"prep"},{"text":"Untar la mitad de cada círculo con {{Tomate frito}}, dejando 1 cm de borde libre.","minutes":1,"kind":"activo"},{"text":"Repartir {{Jamón cocido en lonchas}} sobre el tomate frito de cada círculo.","minutes":1,"kind":"activo"},{"text":"Distribuir la mozzarella sobre el jamón cocido.","minutes":1,"kind":"activo"},{"text":"Espolvorear {{Orégano seco|pizca}} sobre el relleno de cada calzone.","minutes":1,"kind":"activo"},{"text":"Doblar cada círculo por la mitad sobre el relleno y sellar el borde presionando con los dedos.","minutes":2,"kind":"activo"},{"text":"Rematar el sellado repasando el borde con un tenedor para que no se abra al hornear.","minutes":1,"kind":"activo"},{"text":"Pincelar la superficie de cada calzone con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"activo"},{"text":"Colocar los calzones sobre la bandeja caliente y hornear hasta que estén dorados y crujientes.","minutes":17,"kind":"pasivo"},{"text":"Retirar del horno y dejar templar hasta que el relleno no queme al cortar.","minutes":3,"kind":"espera"},{"text":"Servir los calzones en plato, enteros o cortados por la mitad.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_143', 'Buñuelos de queso y jamón', 'carnes', 'cerdo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'all', 380, 14, 26, 24, 4, true, false, '{"gluten","lactosa","huevo"}', '[{"name":"Harina","amount":120,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Leche","amount":200,"unit":"ml"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Queso rallado","amount":100,"unit":"g"},{"name":"Jamón cocido en dados","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":500,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Calentar leche con mantequilla y sal en un cazo a fuego medio hasta que rompa a hervir.","Retirar el cazo del fuego y añadir harina de golpe.","Remover enérgicamente con una espátula hasta que la masa se despegue de las paredes del cazo.","Dejar templar la masa en el cazo.","Incorporar huevo a la masa uno a uno, batiendo bien después de cada uno hasta integrar por completo.","Añadir queso rallado a la masa y mezclar hasta integrar.","Añadir jamón cocido en dados y mezclar hasta que quede repartido de forma uniforme.","Calentar aceite de oliva en una sartén honda a fuego medio-fuerte hasta alcanzar 175 °C.","Formar bolitas de masa con 2 cucharas y freírlas en tandas hasta que estén doradas y hayan crecido, unos 4 min por tanda.","Escurrir los buñuelos sobre papel absorbente.","Servir los buñuelos templados."}', 'Buñuelos salados de queso y jamón, dorados y crujientes por fuera, fundentes por dentro.', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Prepara la masa de los buñuelos. Forma las porciones, rocíalas ligeramente con aceite y cocínalas en la airfryer precalentada a 190°C durante 15-20 minutos, dándoles la vuelta a mitad de cocción hasta que estén dorados y crujientes."},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Una vez hecha la masa, forma los buñuelos y pincélalos con un poco de aceite de oliva. Hornéalos en el horno precalentado a 200°C durante 20-25 minutos, o hasta que estén bien dorados y cocidos por dentro."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Calentar {{Leche}} con {{Mantequilla}} y {{Sal|gusto}} en un cazo a fuego medio hasta que rompa a hervir.","minutes":5,"kind":"activo"},{"text":"Retirar el cazo del fuego y añadir {{Harina}} de golpe.","minutes":1,"kind":"activo"},{"text":"Remover enérgicamente con una espátula hasta que la masa se despegue de las paredes del cazo.","minutes":2,"kind":"activo"},{"text":"Dejar templar la masa en el cazo.","minutes":3,"kind":"espera"},{"text":"Incorporar {{Huevo}} a la masa uno a uno, batiendo bien después de cada uno hasta integrar por completo.","minutes":4,"kind":"activo"},{"text":"Añadir {{Queso rallado}} a la masa y mezclar hasta integrar.","minutes":1,"kind":"activo"},{"text":"Añadir {{Jamón cocido en dados}} y mezclar hasta que quede repartido de forma uniforme.","minutes":1,"kind":"activo"},{"text":"Calentar {{Aceite de oliva|abundante}} en una sartén honda a fuego medio-fuerte hasta alcanzar 175 °C.","minutes":4,"kind":"activo"},{"text":"Formar bolitas de masa con 2 cucharas y freírlas en tandas hasta que estén doradas y hayan crecido, unos 4 min por tanda.","minutes":8,"kind":"activo"},{"text":"Escurrir los buñuelos sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Servir los buñuelos templados.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('carnes_144', 'Croquetas de jamón cocido y queso', 'carnes', 'cerdo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 70, 'normal', 'all', 420, 18, 32, 24, 4, true, false, '{"gluten","lactosa","huevo"}', '[{"name":"Jamón cocido en dados","amount":200,"unit":"g"},{"name":"Queso rallado","amount":80,"unit":"g"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Harina","amount":70,"unit":"g"},{"name":"Leche","amount":700,"unit":"ml"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Pan rallado","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":500,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Fundir mantequilla en una cazuela a fuego medio hasta que esté completamente derretida.","Añadir harina de golpe y remover sin parar con una varilla hasta obtener una pasta homogénea.","Verter leche poco a poco, sin dejar de remover, hasta integrar todo el líquido sin grumos.","Añadir jamón cocido en dados y queso rallado; remover para integrarlos en la bechamel.","Añadir sal y nuez moscada; remover para repartir los condimentos.","Cocer la masa a fuego suave, removiendo con frecuencia, hasta que esté muy espesa y se despegue de las paredes.","Extender la masa en una fuente y cubrir con film a piel para evitar costra.","Refrigerar la masa en la nevera hasta que esté completamente firme.","Batir huevo en un bol hondo hasta homogeneizar.","Poner pan rallado en un plato llano para el empanado.","Formar porciones de masa con las manos dándoles forma alargada y uniforme.","Pasar cada croqueta por el huevo batido, escurrir el exceso y rebozar bien en el pan rallado.","Calentar aceite de oliva en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","Freír las croquetas en tandas, sin amontonarlas, hasta que estén doradas por todos los lados.","Escurrir las croquetas fritas sobre papel absorbente para eliminar el exceso de aceite.","Servir las croquetas recién fritas y bien calientes."}', 'Croquetas cremosas de jamón cocido y queso fundido, con el interior que se estira al partirlas.', '[{"appliance":"thermomix","time":70,"difficulty":"normal","prepSummary":"Prepara la bechamel en la Thermomix: funde la mantequilla, añade la harina y cocina unos minutos, luego incorpora la leche gradualmente a velocidad 4-5 a 90-100°C hasta espesar. Esto asegura una bechamel perfecta y sin grumos, el paso más crítico de la receta."},{"appliance":"airfryer","time":70,"difficulty":"normal","prepSummary":"Una vez formadas y empanadas, cocina las croquetas en la airfryer precalentada a 190-200°C durante 12-15 minutos, rociándolas ligeramente con aceite. Gíralas a mitad de cocción para un dorado uniforme y una textura crujiente sin apenas aceite."},{"appliance":"horno","time":70,"difficulty":"normal","prepSummary":"Para una versión más ligera, hornea las croquetas ya empanadas en una bandeja con papel de horno, rociadas con un poco de aceite, a 200°C (con ventilador si es posible) durante 15-20 minutos. Voltéalas a mitad de cocción para que se doren por todos lados."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Fundir {{Mantequilla}} en una cazuela a fuego medio hasta que esté completamente derretida.","minutes":2,"kind":"activo"},{"text":"Añadir {{Harina}} de golpe y remover sin parar con una varilla hasta obtener una pasta homogénea.","minutes":2,"kind":"activo"},{"text":"Verter {{Leche}} poco a poco, sin dejar de remover, hasta integrar todo el líquido sin grumos.","minutes":5,"kind":"activo"},{"text":"Añadir {{Jamón cocido en dados}} y {{Queso rallado}}; remover para integrarlos en la bechamel.","minutes":2,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y {{Nuez moscada|pizca}}; remover para repartir los condimentos.","minutes":1,"kind":"activo"},{"text":"Cocer la masa a fuego suave, removiendo con frecuencia, hasta que esté muy espesa y se despegue de las paredes.","minutes":10,"kind":"activo"},{"text":"Extender la masa en una fuente y cubrir con film a piel para evitar costra.","minutes":2,"kind":"prep"},{"text":"Refrigerar la masa en la nevera hasta que esté completamente firme.","minutes":180,"kind":"espera"},{"text":"Batir {{Huevo}} en un bol hondo hasta homogeneizar.","minutes":1,"kind":"prep"},{"text":"Poner {{Pan rallado}} en un plato llano para el empanado.","minutes":1,"kind":"prep"},{"text":"Formar porciones de masa con las manos dándoles forma alargada y uniforme.","minutes":5,"kind":"prep"},{"text":"Pasar cada croqueta por el huevo batido, escurrir el exceso y rebozar bien en el pan rallado.","minutes":5,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","minutes":4,"kind":"activo"},{"text":"Freír las croquetas en tandas, sin amontonarlas, hasta que estén doradas por todos los lados.","minutes":3,"kind":"activo"},{"text":"Escurrir las croquetas fritas sobre papel absorbente para eliminar el exceso de aceite.","minutes":1,"kind":"prep"},{"text":"Servir las croquetas recién fritas y bien calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, true)
