insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('carnes_145', 'Gyozas caseras con salsa de soja y sésamo', 'carnes', 'cerdo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 440, 20, 38, 22, 2, true, false, '{"gluten","soja","sesamo"}', '[{"name":"Obleas para gyoza","amount":18,"unit":"ud"},{"name":"Carne picada de cerdo","amount":250,"unit":"g"},{"name":"Col china","amount":150,"unit":"g"},{"name":"Cebolleta","amount":30,"unit":"g"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Salsa de soja","amount":40,"unit":"ml"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Vinagre de arroz","amount":15,"unit":"ml"},{"name":"Semillas de sésamo","amount":5,"unit":"g"}]'::jsonb, '{"Cortar col china en tiras muy finas y picar fino.","Salar la col picada y dejar reposar hasta que suelte agua.","Escurrir la col apretándola con las manos para eliminar el exceso de agua.","Picar fino cebolleta, jengibre fresco y ajo.","Mezclar en un bol carne picada de cerdo, la col escurrida, la cebolleta, el jengibre y el ajo picados.","Añadir 10 ml de salsa de soja y aceite de sésamo al bol y mezclar hasta integrar.","Colocar una cucharadita de relleno en el centro de cada obleas para gyoza.","Humedecer los bordes de cada oblea con agua y cerrar en forma de media luna haciendo pliegues para sellar.","Calentar aceite de oliva en sartén a fuego medio-alto.","Colocar las gyozas con la base plana hacia abajo en la sartén caliente.","Dorar la base de las gyozas hasta que esté crujiente y dorada.","Añadir 60 ml de agua a la sartén y tapar de inmediato.","Cocer al vapor, tapado, hasta que la masa esté translúcida.","Mezclar el resto de la salsa de soja con vinagre de arroz y semillas de sésamo en un bol pequeño.","Destapar la sartén y dejar evaporar el agua restante hasta que la base recupere el crujiente.","Servir las gyozas calientes acompañadas de la salsa de soja y sésamo."}', 'Gyozas caseras de cerdo y col, doradas por la base y jugosas por dentro, para mojar en salsa de soja y sésamo.', '[{"appliance":"airfryer","time":40,"difficulty":"normal","prepSummary":"Para un acabado crujiente y con menos aceite, rocía ligeramente las gyozas con aceite y cocínalas en la airfryer a 190°C durante 15-18 minutos, volteándolas a mitad de cocción hasta que estén doradas."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Hornea las gyozas para una versión más saludable y crujiente. Pincélalas con un poco de aceite y cuécelas a 200°C durante 20-25 minutos, hasta que estén bien doradas."},{"appliance":"thermomix","time":45,"difficulty":"normal","prepSummary":"Usa la Thermomix para picar y mezclar el relleno de forma rápida y homogénea. Luego, cocina las gyozas al vapor en el recipiente Varoma durante 18-20 minutos para una textura tierna y jugosa."},{"appliance":"vaporera","time":40,"difficulty":"normal","prepSummary":"La vaporera es ideal para cocinar las gyozas de manera tradicional, obteniendo una masa suave y un relleno jugoso. Cocínalas al vapor durante 12-15 minutos hasta que estén bien cocidas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Col china}} en tiras muy finas y picar fino.","minutes":3,"kind":"prep"},{"text":"Salar la col picada y dejar reposar hasta que suelte agua.","minutes":5,"kind":"espera"},{"text":"Escurrir la col apretándola con las manos para eliminar el exceso de agua.","minutes":1,"kind":"prep"},{"text":"Picar fino {{Cebolleta}}, {{Jengibre fresco}} y {{Ajo}}.","minutes":3,"kind":"prep"},{"text":"Mezclar en un bol {{Carne picada de cerdo}}, la col escurrida, la cebolleta, el jengibre y el ajo picados.","minutes":1,"kind":"prep"},{"text":"Añadir 10 ml de {{Salsa de soja}} y {{Aceite de sésamo}} al bol y mezclar hasta integrar.","minutes":1,"kind":"prep"},{"text":"Colocar una cucharadita de relleno en el centro de cada {{Obleas para gyoza}}.","minutes":2,"kind":"prep"},{"text":"Humedecer los bordes de cada oblea con agua y cerrar en forma de media luna haciendo pliegues para sellar.","minutes":5,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego medio-alto.","minutes":1,"kind":"activo"},{"text":"Colocar las gyozas con la base plana hacia abajo en la sartén caliente.","minutes":1,"kind":"activo"},{"text":"Dorar la base de las gyozas hasta que esté crujiente y dorada.","minutes":3,"kind":"activo"},{"text":"Añadir 60 ml de agua a la sartén y tapar de inmediato.","minutes":1,"kind":"activo"},{"text":"Cocer al vapor, tapado, hasta que la masa esté translúcida.","minutes":5,"kind":"pasivo"},{"text":"Mezclar el resto de la salsa de soja con {{Vinagre de arroz}} y {{Semillas de sésamo}} en un bol pequeño.","minutes":1,"kind":"paralelo","during":12},{"text":"Destapar la sartén y dejar evaporar el agua restante hasta que la base recupere el crujiente.","minutes":1,"kind":"activo"},{"text":"Servir las gyozas calientes acompañadas de la salsa de soja y sésamo.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('cenas_rapidas_001', 'Sándwich mixto', 'cenas_rapidas', 'none', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 348, 16, 32, 18, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Pan de molde","amount":4,"unit":"ud"},{"name":"Jamón cocido","amount":80,"unit":"g"},{"name":"Queso en lonchas","amount":60,"unit":"g"},{"name":"Mantequilla","amount":10,"unit":"g"}]'::jsonb, '{"Untar mantequilla por una cara de cada rebanada de pan de molde.","Colocar jamón cocido sobre la cara sin mantequilla de 2 rebanadas.","Añadir queso en lonchas encima del jamón cocido y tapar con las otras 2 rebanadas, con la mantequilla hacia afuera.","Calentar sartén a fuego medio y colocar los sándwiches con la cara con mantequilla hacia abajo.","Tostar hasta que la base esté dorada, girar y tostar el otro lado hasta que el queso en lonchas esté fundido.","Cortar cada sándwich en diagonal y servir de inmediato."}', 'Sándwich tostado de jamón cocido y queso fundido', '[{"appliance":"airfryer","time":9,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Unta el pan con mantequilla, monta el sándwich y cocina durante 8-10 minutos, dándole la vuelta a mitad para un dorado uniforme y queso bien fundido."},{"appliance":"horno","time":12,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con calor arriba y abajo. Unta el pan con mantequilla, monta el sándwich y hornea sobre papel de horno durante 10-12 minutos, o hasta que esté dorado y el queso fundido."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Untar {{Mantequilla}} por una cara de cada rebanada de {{Pan de molde}}.","minutes":1,"kind":"prep"},{"text":"Colocar {{Jamón cocido}} sobre la cara sin mantequilla de 2 rebanadas.","minutes":1,"kind":"prep"},{"text":"Añadir {{Queso en lonchas}} encima del jamón cocido y tapar con las otras 2 rebanadas, con la mantequilla hacia afuera.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio y colocar los sándwiches con la cara con mantequilla hacia abajo.","minutes":1,"kind":"activo"},{"text":"Tostar hasta que la base esté dorada, girar y tostar el otro lado hasta que el queso en lonchas esté fundido.","minutes":2,"kind":"activo"},{"text":"Cortar cada sándwich en diagonal y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('cenas_rapidas_002', 'Tosta de tomate con jamón', 'cenas_rapidas', 'none', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 312, 14, 30, 16, 2, true, false, '{"gluten"}', '[{"name":"Pan de hogaza","amount":150,"unit":"g"},{"name":"Tomate maduro","amount":150,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Cortar pan de hogaza en rebanadas de unos 2 cm de grosor.","Cortar tomate maduro por la mitad en sentido transversal.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Tostar las rebanadas de pan en la plancha hasta que estén doradas por ambas caras.","Frotar el tomate partido sobre cada rebanada tostada hasta impregnar bien la superficie.","Añadir aceite de oliva sobre cada rebanada.","Colocar jamón serrano sobre las tostas y servir de inmediato."}', 'Pan tostado con tomate rallado, aceite y jamón serrano', '[{"appliance":"airfryer","time":10,"difficulty":"facil","prepSummary":"Tuesta las rebanadas de pan en la airfryer a 180°C durante 4-6 minutos, hasta que estén doradas y crujientes. Después, unta el tomate maduro sobre el pan tostado, añade el jamón serrano y finaliza con un chorrito de aceite de oliva virgen extra."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C, preferiblemente con función grill. Tuesta las rebanadas de pan durante 5-8 minutos hasta que estén bien doradas. Una vez tostadas, unta el tomate maduro, coloca el jamón serrano y rocía con aceite de oliva."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Cortar {{Pan de hogaza}} en rebanadas de unos 2 cm de grosor.","minutes":1,"kind":"prep"},{"text":"Cortar {{Tomate maduro}} por la mitad en sentido transversal.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté bien caliente.","minutes":1,"kind":"activo"},{"text":"Tostar las rebanadas de pan en la plancha hasta que estén doradas por ambas caras.","minutes":2,"kind":"activo"},{"text":"Frotar el tomate partido sobre cada rebanada tostada hasta impregnar bien la superficie.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} sobre cada rebanada.","minutes":1,"kind":"activo"},{"text":"Colocar {{Jamón serrano}} sobre las tostas y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('cenas_rapidas_003', 'Ensalada de quinoa, feta y granada', 'cenas_rapidas', 'none', 'quinoa', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 366, 15, 36, 18, 2, true, true, '{"lactosa"}', '[{"name":"Quinoa","amount":140,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Queso feta","amount":80,"unit":"g"},{"name":"Granada","amount":60,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Llevar a ebullición 280 ml de agua en un cazo a fuego fuerte y añadir quinoa.","Cocer la quinoa a fuego suave, tapada, hasta que absorba toda el agua y esté tierna.","Cortar tomate cherry por la mitad.","Cortar pepino en dados pequeños.","Laminar cebolla morada en medias lunas finas.","Extraer los granos de granada y reservar.","Cortar queso feta en dados de 1 cm.","Escurrir la quinoa cocida y extenderla en un bol amplio para que se enfríe.","Exprimir limón y mezclar el zumo con aceite de oliva en un bol pequeño hasta integrar.","Añadir al bol con la quinoa los tomates cherry, el pepino, la cebolla morada, los granos de granada y el queso feta.","Verter el aliño sobre la ensalada y mezclar con suavidad hasta que todo quede bien impregnado.","Servir la ensalada en platos hondos, repartiendo bien todos los ingredientes."}', 'Ensalada fría de quinoa con feta, granada, cherry y pepino', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Cocina la quinoa con agua en el vaso del Thermomix (15-20 min, 100°C, velocidad cuchara). Mientras, pica los vegetales y mezcla todo con el aderezo."},{"appliance":"vaporera","time":25,"difficulty":"facil","prepSummary":"Coloca la quinoa con el doble de agua en un recipiente apto para vaporera y cocina al vapor durante 20-25 minutos hasta que esté tierna. Luego, mezcla con los vegetales frescos y el aderezo."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Cocina la quinoa con el doble de agua en la olla express durante 5-7 minutos desde que sube la válvula. Deja despresurizar y luego mezcla con los ingredientes frescos y el aliño."},{"appliance":"microondas","time":15,"difficulty":"facil","prepSummary":"Combina la quinoa con el doble de agua en un recipiente apto para microondas, tapa y cocina a máxima potencia durante 10-12 minutos, o hasta que el agua se absorba. Mezcla con el resto de ingredientes."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Llevar a ebullición 280 ml de agua en un cazo a fuego fuerte y añadir {{Quinoa}}.","minutes":2,"kind":"activo"},{"text":"Cocer la quinoa a fuego suave, tapada, hasta que absorba toda el agua y esté tierna.","minutes":15,"kind":"pasivo"},{"text":"Cortar {{Tomate cherry}} por la mitad.","minutes":2,"kind":"paralelo","during":1},{"text":"Cortar {{Pepino}} en dados pequeños.","minutes":1,"kind":"paralelo","during":1},{"text":"Laminar {{Cebolla morada}} en medias lunas finas.","minutes":1,"kind":"paralelo","during":1},{"text":"Extraer los granos de {{Granada}} y reservar.","minutes":2,"kind":"paralelo","during":1},{"text":"Cortar {{Queso feta}} en dados de 1 cm.","minutes":1,"kind":"paralelo","during":1},{"text":"Escurrir la quinoa cocida y extenderla en un bol amplio para que se enfríe.","minutes":3,"kind":"espera"},{"text":"Exprimir {{Limón}} y mezclar el zumo con {{Aceite de oliva|chorrito}} en un bol pequeño hasta integrar.","minutes":1,"kind":"prep"},{"text":"Añadir al bol con la quinoa los tomates cherry, el pepino, la cebolla morada, los granos de granada y el queso feta.","minutes":1,"kind":"activo"},{"text":"Verter el aliño sobre la ensalada y mezclar con suavidad hasta que todo quede bien impregnado.","minutes":1,"kind":"activo"},{"text":"Servir la ensalada en platos hondos, repartiendo bien todos los ingredientes.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('cenas_rapidas_004', 'Pan tumaca con embutido', 'cenas_rapidas', 'none', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 368, 16, 32, 20, 2, true, false, '{"gluten"}', '[{"name":"Pan de payés","amount":150,"unit":"g"},{"name":"Tomate maduro","amount":120,"unit":"g"},{"name":"Fuet","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Cortar pan de payés en rebanadas de unos 2 cm de grosor.","Cortar tomate maduro por la mitad para frotar directamente sobre el pan.","Laminar fuet en rodajas finas.","Tostar las rebanadas de pan en plancha a fuego fuerte hasta que estén doradas por ambas caras.","Frotar cada rebanada tostada con las mitades de tomate maduro hasta que la miga quede bien impregnada.","Añadir aceite de oliva por encima de cada rebanada.","Disponer las rodajas de fuet sobre las rebanadas y servir de inmediato."}', 'Pan catalán con tomate rallado, aceite y fuet', '[{"appliance":"airfryer","time":8,"difficulty":"facil","prepSummary":"Tuesta el pan de payés en la airfryer a 180-200°C durante 3-5 minutos hasta que esté dorado y crujiente. Mientras, ralla el tomate y corta el fuet. Monta el pan con tomate, aceite y fuet."},{"appliance":"horno","time":12,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Tuesta las rebanadas de pan durante 4-6 minutos hasta que estén doradas. Ralla el tomate, aliña con aceite y monta sobre el pan tostado con el fuet."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pan de payés}} en rebanadas de unos 2 cm de grosor.","minutes":1,"kind":"prep"},{"text":"Cortar {{Tomate maduro}} por la mitad para frotar directamente sobre el pan.","minutes":1,"kind":"prep"},{"text":"Laminar {{Fuet}} en rodajas finas.","minutes":1,"kind":"prep"},{"text":"Tostar las rebanadas de pan en {{@Plancha}} a fuego fuerte hasta que estén doradas por ambas caras.","minutes":2,"kind":"activo"},{"text":"Frotar cada rebanada tostada con las mitades de tomate maduro hasta que la miga quede bien impregnada.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} por encima de cada rebanada.","minutes":1,"kind":"activo"},{"text":"Disponer las rodajas de fuet sobre las rebanadas y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('cenas_rapidas_005', 'Tostada de aguacate y tomate', 'cenas_rapidas', 'none', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 298, 6, 28, 18, 2, true, false, '{"gluten"}', '[{"name":"Pan de hogaza","amount":120,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Tomate cherry","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar pan de hogaza en 2 rebanadas de grosor medio.","Cortar tomate cherry por la mitad y reservar.","Exprimir limón y reservar el zumo.","Tostar las rebanadas de pan en plancha a fuego fuerte hasta que estén doradas por ambas caras.","Abrir aguacate, retirar el hueso y volcar la pulpa en un bol.","Añadir el zumo de limón reservado sobre la pulpa de aguacate y aplastar con un tenedor hasta obtener una pasta rústica.","Untar la pasta de aguacate sobre las rebanadas tostadas de manera generosa.","Disponer los tomates cherry cortados sobre el aguacate y regar con aceite de oliva."}', 'Tostada de pan con aguacate machacado y tomate cherry', '[{"appliance":"airfryer","time":10,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Tuesta el pan durante 5-7 minutos, volteándolo a mitad, hasta que esté crujiente y dorado. Un truco es rociar un poco de aceite de oliva antes de tostar para un extra de sabor."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C, preferiblemente con función grill. Tuesta el pan directamente sobre la rejilla durante 5-7 minutos, vigilando que no se queme, para un tostado uniforme. Monta la tostada con el resto de ingredientes."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pan de hogaza}} en 2 rebanadas de grosor medio.","minutes":1,"kind":"prep"},{"text":"Cortar {{Tomate cherry}} por la mitad y reservar.","minutes":1,"kind":"prep"},{"text":"Exprimir {{Limón}} y reservar el zumo.","minutes":1,"kind":"prep"},{"text":"Tostar las rebanadas de pan en {{@Plancha}} a fuego fuerte hasta que estén doradas por ambas caras.","minutes":3,"kind":"activo"},{"text":"Abrir {{Aguacate}}, retirar el hueso y volcar la pulpa en un bol.","minutes":1,"kind":"prep"},{"text":"Añadir el zumo de limón reservado sobre la pulpa de aguacate y aplastar con un tenedor hasta obtener una pasta rústica.","minutes":1,"kind":"activo"},{"text":"Untar la pasta de aguacate sobre las rebanadas tostadas de manera generosa.","minutes":1,"kind":"activo"},{"text":"Disponer los tomates cherry cortados sobre el aguacate y regar con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('cenas_rapidas_006', 'Salchichas con puré', 'cenas_rapidas', 'cerdo', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 452, 18, 32, 28, 2, true, true, '{"lactosa"}', '[{"name":"Salchichas frescas","amount":250,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Leche","amount":60,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en trozos de tamaño similar.","Cubrir la patata con agua fría en un cazo, llevar a ebullición a fuego fuerte y cocer a fuego medio hasta que esté tierna, unos 18 min.","Calentar plancha a fuego medio con aceite de oliva.","Colocar salchichas frescas en la plancha caliente y dorar por todos los lados hasta que estén doradas y cocidas por dentro, unos 8 min.","Escurrir la patata cocida y devolver al cazo a fuego suave para evaporar el exceso de humedad, 1 min.","Añadir mantequilla y leche a la patata escurrida y aplastar con un tenedor o pasapurés hasta obtener un puré liso.","Servir el puré en el plato y colocar las salchichas encima."}', 'Salchichas frescas a la plancha con puré de patata casero', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Para las salchichas, precalienta la airfryer a 190°C y cocínalas durante 15-20 minutos, volteándolas a mitad de cocción para que queden doradas y crujientes por fuera."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Cocina las salchichas en una bandeja de horno precalentado a 200°C durante 20-25 minutos, dándoles la vuelta una vez para un dorado uniforme y un interior jugoso."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Prepara un puré de patatas perfecto cociendo las patatas troceadas al vapor en el Varoma (20-25 min) y luego triturándolas en el vaso con la leche y mantequilla hasta lograr una textura cremosa."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en trozos de tamaño similar.","minutes":3,"kind":"prep"},{"text":"Cubrir la patata con agua fría en un cazo, llevar a ebullición a fuego fuerte y cocer a fuego medio hasta que esté tierna, unos 18 min.","minutes":20,"kind":"pasivo"},{"text":"Calentar {{@Plancha}} a fuego medio con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"activo"},{"text":"Colocar {{Salchichas frescas}} en la plancha caliente y dorar por todos los lados hasta que estén doradas y cocidas por dentro, unos 8 min.","minutes":8,"kind":"activo"},{"text":"Escurrir la patata cocida y devolver al cazo a fuego suave para evaporar el exceso de humedad, 1 min.","minutes":1,"kind":"activo"},{"text":"Añadir {{Mantequilla}} y {{Leche}} a la patata escurrida y aplastar con un tenedor o pasapurés hasta obtener un puré liso.","minutes":2,"kind":"activo"},{"text":"Servir el puré en el plato y colocar las salchichas encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('cenas_rapidas_007', 'Nachos con guacamole', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 382, 8, 36, 24, 2, true, false, '{}', '[{"name":"Nachos de maíz","amount":150,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Cebolla","amount":30,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Cilantro","amount":5,"unit":"g"}]'::jsonb, '{"Cortar tomate en dados pequeños y reservar.","Picar cebolla muy fina y reservar.","Picar cilantro fino y reservar.","Partir limón por la mitad y exprimir el zumo en un bol.","Partir aguacate por la mitad, retirar el hueso y extraer la pulpa con una cuchara al bol con el zumo de limón.","Aplastar la pulpa de aguacate con un tenedor hasta obtener una textura grumosa al gusto.","Añadir el tomate, la cebolla y el cilantro al bol y mezclar hasta integrar.","Disponer nachos de maíz en un plato amplio y servir el guacamole en un bol aparte para mojar."}', 'Nachos de maíz con guacamole casero de aguacate', NULL, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Tomate}} en dados pequeños y reservar.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolla}} muy fina y reservar.","minutes":1,"kind":"prep"},{"text":"Picar {{Cilantro}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Partir {{Limón}} por la mitad y exprimir el zumo en un bol.","minutes":1,"kind":"prep"},{"text":"Partir {{Aguacate}} por la mitad, retirar el hueso y extraer la pulpa con una cuchara al bol con el zumo de limón.","minutes":1,"kind":"prep"},{"text":"Aplastar la pulpa de aguacate con un tenedor hasta obtener una textura grumosa al gusto.","minutes":1,"kind":"activo"},{"text":"Añadir el tomate, la cebolla y el cilantro al bol y mezclar hasta integrar.","minutes":1,"kind":"activo"},{"text":"Disponer {{Nachos de maíz}} en un plato amplio y servir el guacamole en un bol aparte para mojar.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('cenas_rapidas_008', 'Bruschetta de tomate', 'cenas_rapidas', 'none', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 268, 6, 30, 14, 2, true, false, '{"gluten"}', '[{"name":"Pan chapata","amount":150,"unit":"g"},{"name":"Tomate maduro","amount":200,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Albahaca","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Cortar pan chapata en rebanadas de unos 2 cm de grosor.","Cortar tomate maduro en dados pequeños y reservar en un bol.","Pelar ajo y reservar el diente entero para frotar.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Tostar las rebanadas de pan en la plancha hasta que estén doradas por ambas caras.","Frotar el ajo por la superficie de cada rebanada tostada mientras aún está caliente.","Repartir el tomate en dados sobre las rebanadas.","Aliñar con aceite de oliva por encima de cada bruschetta.","Distribuir albahaca fresca sobre el tomate y servir de inmediato."}', 'Tostadas de pan con tomate fresco, ajo y albahaca', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Tuesta las rebanadas de pan durante 5-7 minutos hasta que estén doradas y crujientes, dándoles la vuelta a mitad de cocción. Esto asegura un tostado uniforme y rápido."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con calor arriba y abajo. Coloca las rebanadas de pan en una bandeja y tuéstalas durante 7-10 minutos, o hasta que estén doradas y crujientes. Vigila para que no se quemen."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pan chapata}} en rebanadas de unos 2 cm de grosor.","minutes":1,"kind":"prep"},{"text":"Cortar {{Tomate maduro}} en dados pequeños y reservar en un bol.","minutes":2,"kind":"prep"},{"text":"Pelar {{Ajo}} y reservar el diente entero para frotar.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Tostar las rebanadas de pan en la {{@Plancha}} hasta que estén doradas por ambas caras.","minutes":3,"kind":"activo"},{"text":"Frotar el ajo por la superficie de cada rebanada tostada mientras aún está caliente.","minutes":1,"kind":"activo"},{"text":"Repartir el tomate en dados sobre las rebanadas.","minutes":1,"kind":"emplatado"},{"text":"Aliñar con {{Aceite de oliva|chorrito}} por encima de cada bruschetta.","minutes":1,"kind":"emplatado"},{"text":"Distribuir {{Albahaca|gusto}} fresca sobre el tomate y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('cenas_rapidas_009', 'Rollitos de jamón y queso', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 262, 18, 2, 20, 2, true, true, '{"lactosa"}', '[{"name":"Jamón cocido","amount":120,"unit":"g"},{"name":"Queso en porciones","amount":80,"unit":"g"},{"name":"Pepinillos","amount":30,"unit":"g"}]'::jsonb, '{"Laminar pepinillos en rodajas finas a lo largo y reservar.","Extender jamón cocido en lonchas sobre una superficie plana.","Colocar queso en porciones en el extremo de cada loncha de jamón cocido.","Distribuir las rodajas de pepinillos sobre el queso en porciones.","Enrollar cada loncha de jamón cocido apretando para que el relleno quede compacto.","Servir los rollitos fríos dispuestos en un plato."}', 'Lonchas de jamón cocido enrolladas con queso y pepinillo', '[]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Laminar {{Pepinillos}} en rodajas finas a lo largo y reservar.","minutes":1,"kind":"prep"},{"text":"Extender {{Jamón cocido}} en lonchas sobre una superficie plana.","minutes":1,"kind":"prep"},{"text":"Colocar {{Queso en porciones}} en el extremo de cada loncha de jamón cocido.","minutes":1,"kind":"prep"},{"text":"Distribuir las rodajas de pepinillos sobre el queso en porciones.","minutes":1,"kind":"prep"},{"text":"Enrollar cada loncha de jamón cocido apretando para que el relleno quede compacto.","minutes":1,"kind":"activo"},{"text":"Servir los rollitos fríos dispuestos en un plato.","kind":"emplatado"}]'::jsonb, NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
