insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('cenas_rapidas_010', 'Tabla de quesos y embutidos', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 412, 22, 4, 34, 2, true, false, '{"lactosa","gluten"}', '[{"name":"Queso curado","amount":80,"unit":"g"},{"name":"Chorizo","amount":60,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Aceitunas","amount":40,"unit":"g"},{"name":"Pan de barra","amount":80,"unit":"g"}]'::jsonb, '{"Cortar queso curado en cuñas o tacos de tamaño bocado.","Laminar chorizo en rodajas finas y doblarlas ligeramente.","Cortar pan de barra en rebanadas de unos 2 cm de grosor.","Disponer el queso, el chorizo y jamón serrano en lonchas sobre una tabla amplia, agrupando cada producto.","Colocar aceitunas en un bol pequeño y situarlo en un extremo de la tabla junto con las rebanadas de pan."}', 'Tabla para compartir con queso curado, chorizo y jamón', '[]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Cortar {{Queso curado}} en cuñas o tacos de tamaño bocado.","minutes":1,"kind":"prep"},{"text":"Laminar {{Chorizo}} en rodajas finas y doblarlas ligeramente.","minutes":1,"kind":"prep"},{"text":"Cortar {{Pan de barra}} en rebanadas de unos 2 cm de grosor.","minutes":1,"kind":"prep"},{"text":"Disponer el queso, el chorizo y {{Jamón serrano}} en lonchas sobre una tabla amplia, agrupando cada producto.","minutes":1,"kind":"emplatado"},{"text":"Colocar {{Aceitunas|gusto}} en un bol pequeño y situarlo en un extremo de la tabla junto con las rebanadas de pan.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('cenas_rapidas_012', 'Gazpacho con picatostes', 'cenas_rapidas', 'none', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 198, 4, 18, 12, 2, true, true, '{"gluten","sulfitos"}', '[{"name":"Tomate maduro","amount":400,"unit":"g"},{"name":"Pepino","amount":60,"unit":"g"},{"name":"Pimiento verde","amount":40,"unit":"g"},{"name":"Ajo","amount":4,"unit":"g"},{"name":"Pan","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar tomate maduro en trozos grandes y colocar en el vaso de la batidora.","Cortar pepino en trozos y añadir al vaso.","Cortar pimiento verde en trozos y añadir al vaso.","Añadir ajo al vaso.","Trocear pan y sumergirlo en agua fría durante 1 min; escurrir y añadir al vaso.","Triturar todos los ingredientes del vaso a máxima potencia hasta que la mezcla esté completamente lisa.","Añadir aceite de oliva y vinagre al vaso; triturar 30 segundos más hasta integrar.","Colar la mezcla por un colador fino sobre un bol, presionando con una cuchara para extraer todo el líquido.","Cortar el pan sobrante en dados pequeños y tostar en sartén a fuego medio hasta que estén dorados; reservar.","Servir el gazpacho frío en boles y repartir los dados de pan tostado por encima."}', 'Gazpacho frío servido con picatostes crujientes', '[{"appliance":"thermomix","time":10,"difficulty":"facil","prepSummary":"Introduce los tomates, pepino, pimiento, ajo, aceite y vinagre en el vaso de la Thermomix. Tritura a velocidad progresiva 5-10 durante 1-2 minutos hasta lograr una textura fina y homogénea. Sirve muy frío con los picatostes."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Tomate maduro}} en trozos grandes y colocar en el vaso de la batidora.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pepino}} en trozos y añadir al vaso.","minutes":1,"kind":"prep"},{"text":"Cortar {{Pimiento verde}} en trozos y añadir al vaso.","minutes":1,"kind":"prep"},{"text":"Añadir {{Ajo}} al vaso.","minutes":1,"kind":"prep"},{"text":"Trocear {{Pan}} y sumergirlo en agua fría durante 1 min; escurrir y añadir al vaso.","minutes":1,"kind":"prep"},{"text":"Triturar todos los ingredientes del vaso a máxima potencia hasta que la mezcla esté completamente lisa.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva}} y {{Vinagre|gusto}} al vaso; triturar 30 segundos más hasta integrar.","minutes":1,"kind":"activo"},{"text":"Colar la mezcla por un colador fino sobre un bol, presionando con una cuchara para extraer todo el líquido.","minutes":2,"kind":"activo"},{"text":"Cortar el pan sobrante en dados pequeños y tostar en {{@Sartén}} a fuego medio hasta que estén dorados; reservar.","minutes":3,"kind":"activo"},{"text":"Servir el gazpacho frío en boles y repartir los dados de pan tostado por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('cenas_rapidas_013', 'Tostas de aguacate y huevo poché', 'cenas_rapidas', 'huevo', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 384, 15, 30, 23, 2, true, false, '{"huevo","gluten"}', '[{"name":"Pan de hogaza","amount":120,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Cilantro","amount":5,"unit":"g"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pan de hogaza en 2 rebanadas de grosor medio.","Picar cilantro fino y reservar.","Exprimir lima y reservar el zumo.","Abrir aguacate, retirar el hueso y extraer la pulpa en un bol.","Machacar la pulpa de aguacate con un tenedor hasta obtener una textura cremosa con algunos grumos.","Añadir el zumo de lima y el cilantro picado al aguacate machacado y mezclar hasta integrar.","Llevar agua a ebullición en un cazo a fuego fuerte; añadir vinagre y bajar a fuego suave hasta mantener un hervor leve.","Tostar las rebanadas de pan de hogaza en la tostadora hasta que estén doradas y crujientes.","Cascar huevo de uno en uno en un cuenco pequeño e introducirlos suavemente en el agua con vinagre.","Cocer los huevos 3 min hasta que la clara esté cuajada y la yema líquida.","Retirar los huevos poché con una espumadera y escurrir sobre papel de cocina.","Untar el guacamole de forma generosa sobre las tostas.","Colocar 1 huevo poché sobre cada tosta y servir de inmediato."}', 'Tostas de pan crujiente con guacamole casero (aguacate, lima y cilantro) y huevo poché de yema jugosa', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Tuesta el pan en la airfryer a 190°C durante 4-5 minutos hasta que quede dorado y crujiente. Mientras, escalfa los huevos en un cazo con agua y un chorro de vinagre 3 minutos. Monta las tostas con el aguacate machacado y el huevo poché por encima."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pan de hogaza}} en 2 rebanadas de grosor medio.","minutes":1,"kind":"prep"},{"text":"Picar {{Cilantro|gusto}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Exprimir {{Lima}} y reservar el zumo.","minutes":1,"kind":"prep"},{"text":"Abrir {{Aguacate}}, retirar el hueso y extraer la pulpa en un bol.","minutes":1,"kind":"prep"},{"text":"Machacar la pulpa de aguacate con un tenedor hasta obtener una textura cremosa con algunos grumos.","minutes":1,"kind":"activo"},{"text":"Añadir el zumo de lima y el cilantro picado al aguacate machacado y mezclar hasta integrar.","minutes":1,"kind":"activo"},{"text":"Llevar agua a ebullición en un cazo a fuego fuerte; añadir {{Vinagre}} y bajar a fuego suave hasta mantener un hervor leve.","minutes":3,"kind":"activo"},{"text":"Tostar las rebanadas de pan de hogaza en la tostadora hasta que estén doradas y crujientes.","minutes":3,"kind":"pasivo"},{"text":"Cascar {{Huevo}} de uno en uno en un cuenco pequeño e introducirlos suavemente en el agua con vinagre.","minutes":1,"kind":"activo"},{"text":"Cocer los huevos 3 min hasta que la clara esté cuajada y la yema líquida.","minutes":3,"kind":"pasivo"},{"text":"Retirar los huevos poché con una espumadera y escurrir sobre papel de cocina.","minutes":1,"kind":"activo"},{"text":"Untar el guacamole de forma generosa sobre las tostas.","minutes":1,"kind":"activo"},{"text":"Colocar 1 huevo poché sobre cada tosta y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('cenas_rapidas_016', 'Tostas de salmón ahumado y aguacate', 'cenas_rapidas', 'pescado_azul', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 12, 'facil', 'all', 398, 19, 29, 22, 2, true, false, '{"gluten","pescado","lactosa"}', '[{"name":"Pan de hogaza","amount":120,"unit":"g"},{"name":"Salmón ahumado","amount":100,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Queso crema","amount":60,"unit":"g"},{"name":"Eneldo","amount":3,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar pan de hogaza en 4 rebanadas de grosor medio.","Pelar y deshuesar aguacate, y laminarlo en tiras finas.","Exprimir limón y reservar el zumo en un cuenco pequeño.","Tostar las rebanadas de pan en sartén a fuego medio hasta que estén doradas por ambos lados.","Untar queso crema sobre cada rebanada tostada, cubriendo toda la superficie.","Disponer las láminas de aguacate sobre el queso crema, repartidas entre las 4 rebanadas.","Repartir salmón ahumado sobre el aguacate, cubriendo cada tosta de forma uniforme.","Rociar unas gotas del zumo de limón reservado sobre cada tosta.","Espolvorear eneldo sobre cada tosta y servir de inmediato."}', 'Tostas de pan crujiente con queso crema, aguacate, salmón ahumado y eneldo', '[]'::jsonb, '{}', true, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pan de hogaza}} en 4 rebanadas de grosor medio.","minutes":1,"kind":"prep"},{"text":"Pelar y deshuesar {{Aguacate}}, y laminarlo en tiras finas.","minutes":2,"kind":"prep"},{"text":"Exprimir {{Limón}} y reservar el zumo en un cuenco pequeño.","minutes":1,"kind":"prep"},{"text":"Tostar las rebanadas de pan en {{@Sartén}} a fuego medio hasta que estén doradas por ambos lados.","minutes":4,"kind":"activo"},{"text":"Untar {{Queso crema}} sobre cada rebanada tostada, cubriendo toda la superficie.","minutes":1,"kind":"activo"},{"text":"Disponer las láminas de aguacate sobre el queso crema, repartidas entre las 4 rebanadas.","minutes":1,"kind":"activo"},{"text":"Repartir {{Salmón ahumado}} sobre el aguacate, cubriendo cada tosta de forma uniforme.","minutes":1,"kind":"activo"},{"text":"Rociar unas gotas del zumo de limón reservado sobre cada tosta.","minutes":1,"kind":"activo"},{"text":"Espolvorear {{Eneldo|pizca}} sobre cada tosta y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('cenas_rapidas_017', 'Tostas de burrata, tomate y albahaca', 'cenas_rapidas', 'none', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 12, 'facil', 'all', 406, 15, 32, 23, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Pan de hogaza","amount":120,"unit":"g"},{"name":"Burrata","amount":150,"unit":"g"},{"name":"Tomate maduro","amount":150,"unit":"g"},{"name":"Albahaca fresca","amount":5,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar pan de hogaza en rebanadas de unos 2 cm de grosor.","Cortar tomate maduro en rodajas finas y reservar.","Calentar una sartén o plancha a fuego fuerte hasta que esté bien caliente.","Tostar las rebanadas de pan en la sartén caliente hasta que estén doradas por ambas caras.","Frotar cada rebanada tostada con un trozo de tomate maduro por la superficie hasta impregnarla.","Repartir las rodajas de tomate maduro restantes sobre las rebanadas de pan.","Romper burrata con las manos y distribuirla sobre el tomate de cada tosta.","Repartir albahaca fresca entera o rasgada por encima de la burrata.","Acabar con aceite de oliva virgen extra sobre cada tosta y servir de inmediato."}', 'Tostas de pan crujiente con burrata cremosa, tomate maduro y albahaca fresca', '[]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pan de hogaza}} en rebanadas de unos 2 cm de grosor.","minutes":1,"kind":"prep"},{"text":"Cortar {{Tomate maduro}} en rodajas finas y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar una sartén o plancha a fuego fuerte hasta que esté bien caliente.","minutes":1,"kind":"activo"},{"text":"Tostar las rebanadas de pan en la sartén caliente hasta que estén doradas por ambas caras.","minutes":3,"kind":"activo"},{"text":"Frotar cada rebanada tostada con un trozo de tomate maduro por la superficie hasta impregnarla.","minutes":1,"kind":"activo"},{"text":"Repartir las rodajas de tomate maduro restantes sobre las rebanadas de pan.","minutes":1,"kind":"emplatado"},{"text":"Romper {{Burrata}} con las manos y distribuirla sobre el tomate de cada tosta.","minutes":1,"kind":"emplatado"},{"text":"Repartir {{Albahaca fresca}} entera o rasgada por encima de la burrata.","minutes":1,"kind":"emplatado"},{"text":"Acabar con {{Aceite de oliva virgen extra|chorrito}} sobre cada tosta y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('cenas_rapidas_014', 'Tortilla wrap de atún', 'cenas_rapidas', 'pescado_azul', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 368, 22, 32, 16, 2, true, true, '{"gluten","pescado","huevo"}', '[{"name":"Tortilla de trigo","amount":2,"unit":"ud"},{"name":"Atún en conserva","amount":120,"unit":"g"},{"name":"Lechuga","amount":50,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Maíz dulce","amount":40,"unit":"g"},{"name":"Mayonesa","amount":20,"unit":"g"}]'::jsonb, '{"Escurrir atún en conserva presionando bien la lata para eliminar el líquido.","Cortar tomate en dados pequeños y trocear lechuga en tiras finas.","Mezclar el atún escurrido con mayonesa en un bol hasta integrar bien.","Extender la mezcla de atún en el centro de tortilla de trigo, dejando 3 cm libres en los bordes.","Repartir la lechuga y el tomate cortado sobre la mezcla de atún.","Añadir maíz dulce distribuido de forma uniforme sobre cada tortilla.","Enrollar cada tortilla con firmeza plegando primero los laterales y luego enroscando hacia adelante hasta cerrar el wrap.","Cortar cada wrap por la mitad en diagonal y servir de inmediato."}', 'Wrap de tortilla de trigo con atún, lechuga y maíz', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Para darle un toque crujiente y caliente, rellena las tortillas con los ingredientes y dóblalas. Precalienta la airfryer a 180°C y cocina los wraps durante 5-7 minutos, volteándolos a mitad, hasta que estén dorados y crujientes."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Escurrir {{Atún en conserva}} presionando bien la lata para eliminar el líquido.","minutes":1,"kind":"prep"},{"text":"Cortar {{Tomate}} en dados pequeños y trocear {{Lechuga}} en tiras finas.","minutes":2,"kind":"prep"},{"text":"Mezclar el atún escurrido con {{Mayonesa|gusto}} en un bol hasta integrar bien.","minutes":1,"kind":"prep"},{"text":"Extender la mezcla de atún en el centro de {{Tortilla de trigo}}, dejando 3 cm libres en los bordes.","minutes":1,"kind":"activo"},{"text":"Repartir la lechuga y el tomate cortado sobre la mezcla de atún.","minutes":1,"kind":"activo"},{"text":"Añadir {{Maíz dulce}} distribuido de forma uniforme sobre cada tortilla.","minutes":1,"kind":"activo"},{"text":"Enrollar cada tortilla con firmeza plegando primero los laterales y luego enroscando hacia adelante hasta cerrar el wrap.","minutes":1,"kind":"activo"},{"text":"Cortar cada wrap por la mitad en diagonal y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('cenas_rapidas_015', 'Sopa fría de melón', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 178, 6, 22, 8, 2, true, true, '{"lactosa"}', '[{"name":"Melón","amount":400,"unit":"g"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Yogur natural","amount":80,"unit":"g"},{"name":"Menta","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Pelar melón y cortar en trozos grandes, retirando las pepitas.","Cortar jamón serrano en virutas finas con un cuchillo y reservar.","Añadir los trozos de melón, yogur natural, menta y aceite de oliva a un vaso batidor.","Triturar todos los ingredientes hasta obtener una crema lisa y homogénea.","Refrigerar la sopa en la nevera hasta que esté bien fría, al menos 30 min.","Servir la sopa en cuencos fríos y repartir las virutas de jamón serrano por encima."}', 'Sopa fría de melón con yogur, menta y jamón serrano', '[{"appliance":"thermomix","time":10,"difficulty":"facil","prepSummary":"Introduce el melón troceado, el yogur, la menta y el aceite de oliva en el vaso. Tritura a velocidad progresiva 5-10 hasta obtener una crema fina y homogénea. Sirve muy frío, decorado con el jamón serrano."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Pelar {{Melón}} y cortar en trozos grandes, retirando las pepitas.","minutes":3,"kind":"prep"},{"text":"Cortar {{Jamón serrano}} en virutas finas con un cuchillo y reservar.","minutes":1,"kind":"prep"},{"text":"Añadir los trozos de melón, {{Yogur natural}}, {{Menta|pizca}} y {{Aceite de oliva|chorrito}} a un vaso batidor.","minutes":1,"kind":"prep"},{"text":"Triturar todos los ingredientes hasta obtener una crema lisa y homogénea.","minutes":2,"kind":"activo"},{"text":"Refrigerar la sopa en la nevera hasta que esté bien fría, al menos 30 min.","minutes":30,"kind":"espera"},{"text":"Servir la sopa en cuencos fríos y repartir las virutas de jamón serrano por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('desayunos_001', 'Bol de yogur con fruta y avena', 'desayunos', 'none', 'avena', ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 320, 13, 52, 7, 2, true, false, '{"lactosa","gluten"}', '[{"name":"Yogur natural","amount":250,"unit":"g"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Fresas","amount":100,"unit":"g"},{"name":"Copos de avena","amount":40,"unit":"g"},{"name":"Miel","amount":15,"unit":"ml"}]'::jsonb, '{"Laminar plátano en rodajas de unos 5 mm.","Cortar fresas en cuartos, retirando el pedúnculo.","Repartir yogur natural a partes iguales en 2 boles.","Disponer las rodajas de plátano y las fresas cortadas sobre el yogur.","Repartir copos de avena por encima de la fruta.","Verter miel en hilo fino sobre cada bol y servir."}', 'Bol de yogur natural con plátano, fresas, avena y un toque de miel', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Laminar {{Plátano}} en rodajas de unos 5 mm.","minutes":1,"kind":"prep"},{"text":"Cortar {{Fresas}} en cuartos, retirando el pedúnculo.","minutes":1,"kind":"prep"},{"text":"Repartir {{Yogur natural}} a partes iguales en 2 boles.","minutes":1,"kind":"emplatado"},{"text":"Disponer las rodajas de plátano y las fresas cortadas sobre el yogur.","minutes":1,"kind":"emplatado"},{"text":"Repartir {{Copos de avena}} por encima de la fruta.","minutes":1,"kind":"emplatado"},{"text":"Verter {{Miel|chorrito}} en hilo fino sobre cada bol y servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('desayunos_002', 'Tostada de tomate y aceite', 'desayunos', 'none', 'pan', ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 6, 'facil', 'all', 230, 6, 34, 8, 2, true, false, '{"gluten"}', '[{"name":"Pan","amount":160,"unit":"g"},{"name":"Tomate maduro","amount":120,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Rallar tomate maduro sobre un bol hasta obtener la pulpa; desechar la piel.","Tostar pan en la tostadora hasta que esté dorado y crujiente.","Repartir la pulpa de tomate rallado sobre las tostadas de forma uniforme.","Añadir aceite de oliva sobre cada tostada y terminar con sal."}', 'Clásica tostada de pan con tomate rallado, aceite de oliva y sal', NULL, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Rallar {{Tomate maduro}} sobre un bol hasta obtener la pulpa; desechar la piel.","minutes":2,"kind":"prep"},{"text":"Tostar {{Pan}} en la tostadora hasta que esté dorado y crujiente.","minutes":3,"kind":"pasivo"},{"text":"Repartir la pulpa de tomate rallado sobre las tostadas de forma uniforme.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} sobre cada tostada y terminar con {{Sal|gusto}}.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('desayunos_003', 'Tostada con mantequilla y mermelada', 'desayunos', 'none', 'pan', ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 290, 6, 44, 10, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Pan","amount":160,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Mermelada","amount":40,"unit":"g"}]'::jsonb, '{"Tostar pan en la tostadora o bajo el grill hasta que esté dorado y crujiente.","Untar mantequilla sobre el pan recién tostado mientras aún está caliente, para que se funda.","Extender mermelada por encima de la mantequilla y servir de inmediato."}', 'Tostada clásica con mantequilla y mermelada', NULL, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Tostar {{Pan}} en la tostadora o bajo el grill hasta que esté dorado y crujiente.","minutes":3,"kind":"activo"},{"text":"Untar {{Mantequilla}} sobre el pan recién tostado mientras aún está caliente, para que se funda.","minutes":1,"kind":"emplatado"},{"text":"Extender {{Mermelada}} por encima de la mantequilla y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  main_protein = excluded.main_protein,
  main_base = excluded.main_base,
  meal_roles = excluded.meal_roles,
  type = excluded.type,
  base_dish_id = excluded.base_dish_id,
  required_appliance = excluded.required_appliance,
  time_minutes = excluded.time_minutes,
  difficulty = excluded.difficulty,
  season = excluded.season,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  base_servings = excluded.base_servings,
  kid_friendly = excluded.kid_friendly,
  tupper_friendly = excluded.tupper_friendly,
  allergens = excluded.allergens,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  description = excluded.description,
  methods = excluded.methods,
  product_aliases = excluded.product_aliases,
  apetecible = excluded.apetecible,
  montaje = excluded.montaje,
  can_be_garnish = excluded.can_be_garnish,
  main_ingredients = excluded.main_ingredients,
  sauce_id = excluded.sauce_id,
  extra_proteins = excluded.extra_proteins,
  freezable = excluded.freezable,
  steps_rich = excluded.steps_rich,
  estrella = excluded.estrella;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('desayunos_004', 'Tostada de jamón serrano y aceite', 'desayunos', 'none', 'pan', ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 6, 'facil', 'all', 300, 15, 32, 12, 2, true, false, '{"gluten"}', '[{"name":"Pan","amount":160,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Tomate maduro","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Rallar tomate maduro sobre un bol pequeño hasta obtener la pulpa; desechar la piel.","Tostar pan en la tostadora o en una sartén a fuego medio hasta que esté dorado y crujiente.","Untar la pulpa de tomate rallado sobre cada rebanada tostada de manera uniforme.","Regar con aceite de oliva por encima del tomate.","Disponer jamón serrano sobre cada tostada y servir de inmediato."}', 'Tostada con tomate, aceite y jamón serrano', NULL, '{}', NULL, true, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Rallar {{Tomate maduro}} sobre un bol pequeño hasta obtener la pulpa; desechar la piel.","minutes":2,"kind":"prep"},{"text":"Tostar {{Pan}} en la tostadora o en una sartén a fuego medio hasta que esté dorado y crujiente.","minutes":2,"kind":"activo"},{"text":"Untar la pulpa de tomate rallado sobre cada rebanada tostada de manera uniforme.","minutes":1,"kind":"activo"},{"text":"Regar con {{Aceite de oliva|chorrito}} por encima del tomate.","minutes":1,"kind":"activo"},{"text":"Disponer {{Jamón serrano}} sobre cada tostada y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('desayunos_005', 'Tostada de pavo y queso', 'desayunos', 'none', 'pan', ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 6, 'facil', 'all', 310, 18, 33, 11, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Pan","amount":160,"unit":"g"},{"name":"Pechuga de pavo","amount":80,"unit":"g"},{"name":"Queso en lonchas","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":5,"unit":"ml"}]'::jsonb, '{"Calentar plancha a fuego fuerte hasta que esté bien caliente.","Tostar pan en la plancha hasta que esté dorado por ambas caras.","Colocar queso en lonchas sobre el pan tostado y esperar hasta que empiece a fundir con el calor residual.","Disponer pechuga de pavo sobre el queso.","Añadir aceite de oliva por encima y servir de inmediato."}', 'Tostada de fiambre de pavo con queso', NULL, '{}', NULL, true, NULL, '{}', NULL, ARRAY['pavo']::main_protein[], false, '[{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté bien caliente.","minutes":1,"kind":"activo"},{"text":"Tostar {{Pan}} en la {{@Plancha}} hasta que esté dorado por ambas caras.","minutes":3,"kind":"activo"},{"text":"Colocar {{Queso en lonchas}} sobre el pan tostado y esperar hasta que empiece a fundir con el calor residual.","minutes":1,"kind":"espera"},{"text":"Disponer {{Pechuga de pavo}} sobre el queso.","kind":"prep"},{"text":"Añadir {{Aceite de oliva|chorrito}} por encima y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('desayunos_006', 'Tostada de aguacate', 'desayunos', 'none', 'pan', ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 7, 'facil', 'all', 340, 7, 36, 18, 2, true, false, '{"gluten"}', '[{"name":"Pan","amount":160,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":5,"unit":"ml"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Cortar pan en rebanadas y tostar en la tostadora hasta que estén doradas y crujientes.","Partir limón por la mitad y exprimir el zumo en un bol pequeño.","Abrir aguacate, retirar el hueso y extraer la pulpa con una cuchara al bol.","Añadir el zumo de limón y sal a la pulpa; machacar con un tenedor hasta obtener una crema rústica.","Extender la crema de aguacate sobre las tostadas y añadir aceite de oliva por encima antes de servir."}', 'Tostada de aguacate machacado con limón y aceite de oliva', NULL, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pan}} en rebanadas y tostar en la tostadora hasta que estén doradas y crujientes.","minutes":3,"kind":"activo"},{"text":"Partir {{Limón}} por la mitad y exprimir el zumo en un bol pequeño.","minutes":1,"kind":"paralelo","during":0},{"text":"Abrir {{Aguacate}}, retirar el hueso y extraer la pulpa con una cuchara al bol.","minutes":1,"kind":"prep"},{"text":"Añadir el zumo de limón y {{Sal|gusto}} a la pulpa; machacar con un tenedor hasta obtener una crema rústica.","minutes":1,"kind":"activo"},{"text":"Extender la crema de aguacate sobre las tostadas y añadir {{Aceite de oliva|chorrito}} por encima antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('desayunos_007', 'Leche con cereales', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 3, 'facil', 'all', 280, 10, 46, 6, 2, true, false, '{"lactosa","gluten"}', '[{"name":"Leche","amount":400,"unit":"ml"},{"name":"Cereales","amount":80,"unit":"g"}]'::jsonb, '{"Repartir cereales en 2 boles individuales.","Verter leche sobre los cereales de cada bol.","Servir de inmediato para que los cereales no se ablanden."}', 'Bol de leche con cereales, desayuno rápido de siempre', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Repartir {{Cereales}} en 2 boles individuales.","minutes":1,"kind":"prep"},{"text":"Verter {{Leche}} sobre los cereales de cada bol.","minutes":1,"kind":"activo"},{"text":"Servir de inmediato para que los cereales no se ablanden.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('desayunos_008', 'Porridge de avena con plátano', 'desayunos', 'none', 'avena', ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 330, 12, 54, 7, 2, true, false, '{"lactosa","gluten"}', '[{"name":"Copos de avena","amount":80,"unit":"g"},{"name":"Leche","amount":350,"unit":"ml"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Miel","amount":15,"unit":"ml"}]'::jsonb, '{"Laminar plátano en rodajas de unos 5 mm y reservar.","Verter leche y copos de avena en un cazo y calentar a fuego suave, removiendo con frecuencia.","Cocer la mezcla a fuego suave, removiendo sin parar, hasta que espese y tenga textura cremosa, unos 5 min.","Repartir el porridge en 2 boles, disponer las rodajas de plátano encima y añadir miel por encima."}', 'Gachas de avena con leche, plátano y miel', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Laminar {{Plátano}} en rodajas de unos 5 mm y reservar.","minutes":2,"kind":"prep"},{"text":"Verter {{Leche}} y {{Copos de avena}} en un cazo y calentar a fuego suave, removiendo con frecuencia.","minutes":1,"kind":"activo"},{"text":"Cocer la mezcla a fuego suave, removiendo sin parar, hasta que espese y tenga textura cremosa, unos 5 min.","minutes":5,"kind":"activo"},{"text":"Repartir el porridge en 2 boles, disponer las rodajas de plátano encima y añadir {{Miel|chorrito}} por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('desayunos_009', 'Batido de plátano, avena y canela', 'desayunos', 'none', 'avena', ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 323, 9.5, 56, 7.5, 2, true, false, '{"lactosa","gluten"}', '[{"name":"Plátano","amount":2,"unit":"ud"},{"name":"Leche","amount":350,"unit":"ml"},{"name":"Copos de avena","amount":40,"unit":"g"},{"name":"Canela molida","amount":2,"unit":"g"},{"name":"Miel","amount":20,"unit":"ml"}]'::jsonb, '{"Pelar plátano y cortar en trozos.","Añadir los trozos de plátano, leche, copos de avena y canela molida al vaso de la batidora.","Triturar a máxima potencia hasta obtener una mezcla cremosa y sin grumos.","Añadir miel y triturar unos segundos más hasta que quede integrada.","Repartir el batido en 2 vasos y servir."}', 'Batido cremoso y espeso de plátano, avena y canela, listo para tomar con cuchara.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Plátano}} y cortar en trozos.","minutes":1,"kind":"prep"},{"text":"Añadir los trozos de plátano, {{Leche}}, {{Copos de avena}} y {{Canela molida}} al vaso de la batidora.","minutes":1,"kind":"activo"},{"text":"Triturar a máxima potencia hasta obtener una mezcla cremosa y sin grumos.","minutes":2,"kind":"activo"},{"text":"Añadir {{Miel}} y triturar unos segundos más hasta que quede integrada.","minutes":1,"kind":"activo"},{"text":"Repartir el batido en 2 vasos y servir.","kind":"emplatado"}]'::jsonb, true),
  ('desayunos_010', 'Smoothie verde de espinacas, piña y jengibre', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 130, 2, 32, 1, 2, true, false, '{}', '[{"name":"Espinacas frescas","amount":60,"unit":"g"},{"name":"Piña natural","amount":250,"unit":"g"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Jengibre fresco","amount":8,"unit":"g"},{"name":"Agua","amount":150,"unit":"ml"}]'::jsonb, '{"Lavar espinacas frescas bajo el grifo y escurrir bien.","Pelar piña natural y cortar en trozos.","Pelar plátano y cortar en trozos.","Pelar jengibre fresco y rallar fino.","Añadir las espinacas, la piña, el plátano, el jengibre y agua al vaso de la batidora.","Triturar a máxima potencia hasta que el smoothie quede fino y sin grumos.","Servir en vasos altos de inmediato."}', 'Smoothie verde intenso de espinacas, piña y jengibre, sorprendentemente dulce a pesar del color.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Espinacas frescas}} bajo el grifo y escurrir bien.","minutes":1,"kind":"prep"},{"text":"Pelar {{Piña natural}} y cortar en trozos.","minutes":1,"kind":"prep"},{"text":"Pelar {{Plátano}} y cortar en trozos.","minutes":1,"kind":"prep"},{"text":"Pelar {{Jengibre fresco}} y rallar fino.","minutes":1,"kind":"prep"},{"text":"Añadir las espinacas, la piña, el plátano, el jengibre y {{Agua}} al vaso de la batidora.","minutes":1,"kind":"activo"},{"text":"Triturar a máxima potencia hasta que el smoothie quede fino y sin grumos.","minutes":2,"kind":"activo"},{"text":"Servir en vasos altos de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('desayunos_011', 'Smoothie de frutos rojos y yogur', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 172, 6, 24, 5, 2, true, false, '{"lactosa"}', '[{"name":"Frutos rojos congelados","amount":250,"unit":"g"},{"name":"Yogur natural","amount":200,"unit":"g"},{"name":"Leche","amount":100,"unit":"ml"},{"name":"Miel","amount":15,"unit":"ml"}]'::jsonb, '{"Añadir frutos rojos congelados, yogur natural y leche al vaso de la batidora.","Triturar a máxima potencia hasta obtener una mezcla lisa y homogénea.","Añadir miel y triturar unos segundos más hasta que quede integrada.","Repartir el smoothie en 2 vasos y servir de inmediato."}', 'Smoothie rosa vivo de frutos rojos y yogur, cremoso y con un punto ácido.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Añadir {{Frutos rojos congelados}}, {{Yogur natural}} y {{Leche}} al vaso de la batidora.","minutes":1,"kind":"prep"},{"text":"Triturar a máxima potencia hasta obtener una mezcla lisa y homogénea.","minutes":1,"kind":"activo"},{"text":"Añadir {{Miel}} y triturar unos segundos más hasta que quede integrada.","minutes":1,"kind":"activo"},{"text":"Repartir el smoothie en 2 vasos y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('desayunos_012', 'Batido de cacao, plátano y avellanas', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 350, 11, 43, 17, 2, true, false, '{"lactosa","frutos_secos"}', '[{"name":"Plátano","amount":2,"unit":"ud"},{"name":"Leche","amount":350,"unit":"ml"},{"name":"Cacao en polvo","amount":20,"unit":"g"},{"name":"Avellanas","amount":30,"unit":"g"},{"name":"Miel","amount":10,"unit":"ml"}]'::jsonb, '{"Pelar plátano y cortar en trozos grandes.","Añadir el plátano troceado, leche, cacao en polvo y avellanas al vaso de la batidora.","Triturar a máxima potencia hasta que las avellanas estén bien integradas y la mezcla esté cremosa.","Añadir miel y triturar unos segundos hasta que quede integrada.","Repartir en 2 vasos y servir bien frío."}', 'Batido espeso y achocolatado de cacao, plátano y avellanas, sabe a capricho.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Plátano}} y cortar en trozos grandes.","minutes":1,"kind":"prep"},{"text":"Añadir el plátano troceado, {{Leche}}, {{Cacao en polvo}} y {{Avellanas}} al vaso de la batidora.","minutes":1,"kind":"activo"},{"text":"Triturar a máxima potencia hasta que las avellanas estén bien integradas y la mezcla esté cremosa.","minutes":2,"kind":"activo"},{"text":"Añadir {{Miel|chorrito}} y triturar unos segundos hasta que quede integrada.","minutes":1,"kind":"activo"},{"text":"Repartir en 2 vasos y servir bien frío.","kind":"emplatado"}]'::jsonb, true),
  ('desayunos_013', 'Smoothie bowl de mango y coco', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 8, 'facil', 'all', 285, 3, 39, 15, 2, true, false, '{}', '[{"name":"Mango congelado","amount":300,"unit":"g"},{"name":"Plátano congelado","amount":1,"unit":"ud"},{"name":"Leche de coco","amount":100,"unit":"ml"},{"name":"Coco rallado","amount":15,"unit":"g"},{"name":"Zumo de lima","amount":10,"unit":"ml"}]'::jsonb, '{"Añadir mango congelado, plátano congelado, leche de coco y zumo de lima al vaso de la batidora.","Triturar a velocidad alta hasta obtener una textura espesa tipo helado, parando para remover si la batidora se atasca.","Repartir la mezcla en 2 boles y alisar la superficie con el dorso de una cuchara.","Repartir coco rallado por encima y servir de inmediato."}', 'Smoothie bowl de mango y coco de color naranja intenso, con virutas de coco por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Añadir {{Mango congelado}}, {{Plátano congelado}}, {{Leche de coco}} y {{Zumo de lima}} al vaso de la batidora.","minutes":1,"kind":"prep"},{"text":"Triturar a velocidad alta hasta obtener una textura espesa tipo helado, parando para remover si la batidora se atasca.","minutes":2,"kind":"activo"},{"text":"Repartir la mezcla en 2 boles y alisar la superficie con el dorso de una cuchara.","minutes":1,"kind":"emplatado"},{"text":"Repartir {{Coco rallado}} por encima y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true)
