insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('desayunos_014', 'Bowl de yogur griego con granola y frutos rojos', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 338, 17, 37, 13, 2, true, false, '{"lactosa","gluten"}', '[{"name":"Yogur griego","amount":300,"unit":"g"},{"name":"Granola","amount":60,"unit":"g"},{"name":"Frutos rojos","amount":150,"unit":"g"},{"name":"Miel","amount":15,"unit":"ml"}]'::jsonb, '{"Repartir yogur griego en 2 boles.","Disponer frutos rojos sobre el yogur.","Repartir granola por encima de los frutos rojos.","Terminar con miel sobre cada bol y servir enseguida."}', 'Bowl de yogur griego en capas bien visibles, con granola crujiente y frutos rojos frescos.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Repartir {{Yogur griego}} en 2 boles.","minutes":1,"kind":"emplatado"},{"text":"Disponer {{Frutos rojos}} sobre el yogur.","minutes":1,"kind":"emplatado"},{"text":"Repartir {{Granola}} por encima de los frutos rojos.","minutes":1,"kind":"emplatado"},{"text":"Terminar con {{Miel|chorrito}} sobre cada bol y servir enseguida.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('desayunos_015', 'Bowl de avena de un día para otro con manzana y canela', 'desayunos', 'none', 'avena', ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 344, 12, 52, 10, 2, true, true, '{"lactosa","gluten"}', '[{"name":"Copos de avena","amount":80,"unit":"g"},{"name":"Leche","amount":300,"unit":"ml"},{"name":"Yogur natural","amount":100,"unit":"g"},{"name":"Manzana","amount":1,"unit":"ud"},{"name":"Canela molida","amount":3,"unit":"g"},{"name":"Miel","amount":20,"unit":"ml"}]'::jsonb, '{"Rallar manzana con piel, desechando el corazón.","Mezclar en un bol copos de avena, leche, yogur natural, la manzana rallada y canela molida.","Añadir miel y remover hasta que quede todo integrado.","Repartir la mezcla en 2 tarros o boles con tapa.","Tapar y dejar reposar en la nevera un mínimo de 6 horas o toda la noche.","Remover el contenido de cada tarro antes de servir."}', 'Avena remojada de un día para otro con manzana y canela, lista al abrir la nevera.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Rallar {{Manzana}} con piel, desechando el corazón.","minutes":2,"kind":"prep"},{"text":"Mezclar en un bol {{Copos de avena}}, {{Leche}}, {{Yogur natural}}, la manzana rallada y {{Canela molida|pizca}}.","minutes":2,"kind":"activo"},{"text":"Añadir {{Miel|chorrito}} y remover hasta que quede todo integrado.","minutes":1,"kind":"activo"},{"text":"Repartir la mezcla en 2 tarros o boles con tapa.","minutes":1,"kind":"activo"},{"text":"Tapar y dejar reposar en la nevera un mínimo de 6 horas o toda la noche.","minutes":360,"kind":"espera"},{"text":"Remover el contenido de cada tarro antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('desayunos_016', 'Porridge de avena con plátano y miel', 'desayunos', 'none', 'avena', ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 350, 11, 56, 9, 2, true, false, '{"lactosa","gluten"}', '[{"name":"Copos de avena","amount":80,"unit":"g"},{"name":"Leche","amount":350,"unit":"ml"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Miel","amount":25,"unit":"ml"}]'::jsonb, '{"Laminar plátano en rodajas y reservar.","Verter leche y copos de avena en un cazo y calentar a fuego suave sin dejar de remover.","Cocer a fuego suave sin dejar de remover hasta que la mezcla espese y tenga textura cremosa.","Repartir el porridge caliente en 2 boles.","Disponer las rodajas de plátano por encima del porridge y terminar con un hilo de miel."}', 'Porridge de avena cremoso y caliente con plátano y un hilo de miel por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Laminar {{Plátano}} en rodajas y reservar.","minutes":1,"kind":"prep"},{"text":"Verter {{Leche}} y {{Copos de avena}} en un cazo y calentar a fuego suave sin dejar de remover.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego suave sin dejar de remover hasta que la mezcla espese y tenga textura cremosa.","minutes":5,"kind":"activo"},{"text":"Repartir el porridge caliente en 2 boles.","minutes":1,"kind":"emplatado"},{"text":"Disponer las rodajas de plátano por encima del porridge y terminar con un hilo de {{Miel}}.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('desayunos_017', 'Bowl de açaí con fruta y coco', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 8, 'facil', 'all', 236, 3, 29, 12, 2, true, false, '{"gluten"}', '[{"name":"Pulpa de açaí congelada","amount":200,"unit":"g"},{"name":"Plátano congelado","amount":1,"unit":"ud"},{"name":"Frutos rojos","amount":100,"unit":"g"},{"name":"Coco rallado","amount":15,"unit":"g"},{"name":"Granola","amount":20,"unit":"g"}]'::jsonb, '{"Trocear pulpa de açaí congelada en trozos pequeños para facilitar el triturado.","Trocear plátano congelado en rodajas gruesas.","Triturar la pulpa de açaí y el plátano en la batidora hasta obtener una textura espesa tipo helado.","Añadir un chorrito de agua si la mezcla no tritura bien, y continuar hasta que quede homogénea.","Repartir la mezcla en 2 boles y alisar la superficie con una cuchara.","Disponer frutos rojos, granola y coco rallado por encima formando montoncitos.","Servir de inmediato antes de que la mezcla pierda su textura helada."}', 'Bowl de açaí morado intenso, coronado con fruta fresca y coco.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Trocear {{Pulpa de açaí congelada}} en trozos pequeños para facilitar el triturado.","minutes":2,"kind":"prep"},{"text":"Trocear {{Plátano congelado}} en rodajas gruesas.","minutes":1,"kind":"prep"},{"text":"Triturar la pulpa de açaí y el plátano en la batidora hasta obtener una textura espesa tipo helado.","minutes":2,"kind":"activo"},{"text":"Añadir un chorrito de agua si la mezcla no tritura bien, y continuar hasta que quede homogénea.","minutes":1,"kind":"activo"},{"text":"Repartir la mezcla en 2 boles y alisar la superficie con una cuchara.","minutes":1,"kind":"emplatado"},{"text":"Disponer {{Frutos rojos}}, {{Granola}} y {{Coco rallado}} por encima formando montoncitos.","minutes":1,"kind":"emplatado"},{"text":"Servir de inmediato antes de que la mezcla pierda su textura helada.","kind":"emplatado"}]'::jsonb, true),
  ('desayunos_018', 'Tostada francesa con canela y sirope de arce', 'desayunos', 'none', 'pan', ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 395, 15, 52, 14, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Pan","amount":160,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Leche","amount":100,"unit":"ml"},{"name":"Canela molida","amount":3,"unit":"g"},{"name":"Mantequilla","amount":10,"unit":"g"},{"name":"Sirope de arce","amount":30,"unit":"ml"}]'::jsonb, '{"Batir huevo con leche y canela molida en un plato hondo hasta que la mezcla esté homogénea.","Cortar pan en rebanadas de unos 2 cm de grosor.","Remojar cada rebanada de pan en la mezcla de huevo por ambos lados hasta que empape bien.","Calentar sartén a fuego medio y fundir mantequilla hasta que espume.","Dorar las rebanadas de pan en la sartén durante 2 min por el primer lado hasta que estén doradas.","Dar la vuelta a las rebanadas y dorar 2 min por el otro lado hasta que estén doradas y esponjosas.","Servir las rebanadas de inmediato con sirope de arce por encima."}', 'Tostada francesa dorada por fuera y esponjosa por dentro, con canela y sirope de arce, el capricho de domingo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Batir {{Huevo}} con {{Leche}} y {{Canela molida|pizca}} en un plato hondo hasta que la mezcla esté homogénea.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pan}} en rebanadas de unos 2 cm de grosor.","minutes":1,"kind":"prep"},{"text":"Remojar cada rebanada de pan en la mezcla de huevo por ambos lados hasta que empape bien.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio y fundir {{Mantequilla}} hasta que espume.","minutes":1,"kind":"activo"},{"text":"Dorar las rebanadas de pan en la sartén durante 2 min por el primer lado hasta que estén doradas.","minutes":2,"kind":"activo"},{"text":"Dar la vuelta a las rebanadas y dorar 2 min por el otro lado hasta que estén doradas y esponjosas.","minutes":2,"kind":"activo"},{"text":"Servir las rebanadas de inmediato con {{Sirope de arce}} por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('desayunos_019', 'Tostada de plátano, mantequilla de cacahuete y miel', 'desayunos', 'none', 'pan', ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 6, 'facil', 'all', 408, 13, 63, 13, 2, true, false, '{"gluten","cacahuetes"}', '[{"name":"Pan","amount":160,"unit":"g"},{"name":"Mantequilla de cacahuete","amount":40,"unit":"g"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Miel","amount":15,"unit":"ml"}]'::jsonb, '{"Tostar pan en la tostadora hasta que esté dorado y crujiente.","Laminar plátano en rodajas finas mientras el pan se tuesta.","Untar mantequilla de cacahuete sobre las tostadas calientes.","Disponer las rodajas de plátano sobre la mantequilla de cacahuete.","Terminar con un hilo de miel por encima y servir de inmediato."}', 'Tostada cremosa y dulce de mantequilla de cacahuete, con plátano en rodajas y miel por encima.', NULL, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Tostar {{Pan}} en la tostadora hasta que esté dorado y crujiente.","minutes":3,"kind":"pasivo"},{"text":"Laminar {{Plátano}} en rodajas finas mientras el pan se tuesta.","minutes":2,"kind":"paralelo","during":0},{"text":"Untar {{Mantequilla de cacahuete}} sobre las tostadas calientes.","minutes":1,"kind":"activo"},{"text":"Disponer las rodajas de plátano sobre la mantequilla de cacahuete.","minutes":1,"kind":"emplatado"},{"text":"Terminar con un hilo de {{Miel}} por encima y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('desayunos_020', 'Pan tumaca clásico con jamón', 'desayunos', 'none', 'pan', ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 396, 20, 43, 16, 2, true, false, '{"gluten"}', '[{"name":"Pan rústico","amount":160,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Tomate maduro","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Jamón serrano","amount":80,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Cortar tomate maduro por la mitad.","Tostar pan rústico en una tostadora o bajo el grill hasta que esté dorado y crujiente.","Frotar ajo cortado por la mitad sobre el pan aún caliente.","Frotar el tomate maduro sobre el pan hasta que quede impregnado de pulpa; desechar la piel.","Regar con aceite de oliva y añadir sal.","Disponer jamón serrano por encima y servir de inmediato."}', 'Pan tostado frotado con tomate y aceite, coronado con jamón serrano, el clásico de siempre.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Cortar {{Tomate maduro}} por la mitad.","minutes":1,"kind":"prep"},{"text":"Tostar {{Pan rústico}} en una tostadora o bajo el grill hasta que esté dorado y crujiente.","minutes":3,"kind":"activo"},{"text":"Frotar {{Ajo}} cortado por la mitad sobre el pan aún caliente.","minutes":1,"kind":"activo"},{"text":"Frotar el tomate maduro sobre el pan hasta que quede impregnado de pulpa; desechar la piel.","minutes":1,"kind":"activo"},{"text":"Regar con {{Aceite de oliva|chorrito}} y añadir {{Sal|gusto}}.","minutes":1,"kind":"activo"},{"text":"Disponer {{Jamón serrano}} por encima y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('desayunos_021', 'Tortitas americanas con sirope y frutos rojos', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 564, 18, 94, 17, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Harina","amount":140,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Leche","amount":250,"unit":"ml"},{"name":"Levadura química","amount":6,"unit":"g"},{"name":"Azúcar","amount":20,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Sirope de arce","amount":30,"unit":"ml"},{"name":"Frutos rojos","amount":100,"unit":"g"}]'::jsonb, '{"Mezclar harina, levadura química y azúcar en un bol hasta que estén bien integrados.","Batir huevo con leche en otro bol hasta obtener una mezcla homogénea.","Añadir los líquidos a los ingredientes secos y mezclar con varillas hasta que no queden grumos grandes.","Calentar sartén a fuego medio y fundir mantequilla hasta que cubra el fondo.","Verter un cucharón de masa en la sartén y cocinar 2 min, hasta que aparezcan burbujas en la superficie.","Dar la vuelta a la tortita y cocinar 2 min más, hasta que esté dorada por ese lado.","Repetir los 2 pasos anteriores con el resto de la masa, engrasando la sartén si es necesario.","Apilar las tortitas en el plato, verter sirope de arce por encima y distribuir frutos rojos."}', 'Torre de tortitas americanas doradas y esponjosas, con sirope cayendo por los lados y frutos rojos.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Mezclar {{Harina}}, {{Levadura química}} y {{Azúcar}} en un bol hasta que estén bien integrados.","minutes":2,"kind":"prep"},{"text":"Batir {{Huevo}} con {{Leche}} en otro bol hasta obtener una mezcla homogénea.","minutes":2,"kind":"prep"},{"text":"Añadir los líquidos a los ingredientes secos y mezclar con varillas hasta que no queden grumos grandes.","minutes":2,"kind":"activo"},{"text":"Calentar {{@Sartén}} a fuego medio y fundir {{Mantequilla}} hasta que cubra el fondo.","minutes":1,"kind":"activo"},{"text":"Verter un cucharón de masa en la sartén y cocinar 2 min, hasta que aparezcan burbujas en la superficie.","minutes":2,"kind":"activo"},{"text":"Dar la vuelta a la tortita y cocinar 2 min más, hasta que esté dorada por ese lado.","minutes":2,"kind":"activo"},{"text":"Repetir los 2 pasos anteriores con el resto de la masa, engrasando la sartén si es necesario.","minutes":6,"kind":"activo"},{"text":"Apilar las tortitas en el plato, verter {{Sirope de arce}} por encima y distribuir {{Frutos rojos}}.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('desayunos_022', 'Gofres caseros con nata y fresas', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, 'gofrera', 22, 'facil', 'all', 653, 18, 76, 30, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Harina","amount":140,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Leche","amount":220,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Levadura química","amount":6,"unit":"g"},{"name":"Azúcar","amount":15,"unit":"g"},{"name":"Nata para montar","amount":80,"unit":"g"},{"name":"Fresas","amount":150,"unit":"g"},{"name":"Azúcar glas","amount":5,"unit":"g"}]'::jsonb, '{"Fundir mantequilla en un cazo a fuego suave hasta que se derrita por completo.","Retirar el cazo del fuego y dejar templar la mantequilla fundida durante 3 min.","Mezclar en un bol harina, levadura química y azúcar hasta integrar.","Batir huevo con leche y la mantequilla templada en otro bol hasta homogeneizar.","Añadir la mezcla líquida sobre los ingredientes secos y remover hasta obtener una masa lisa sin grumos.","Calentar la gofrera según las instrucciones del fabricante hasta que alcance la temperatura de cocción.","Laminar fresas en rodajas finas y reservar.","Verter un cucharón de masa en la gofrera caliente y cerrar.","Cocer el gofre hasta que esté dorado y crujiente, unos 4 min.","Montar nata para montar con unas varillas hasta que espese y forme picos firmes.","Añadir azúcar glas a la nata y remover con suavidad para integrar.","Retirar el gofre de la gofrera y repetir el proceso con el resto de masa hasta agotar.","Servir los gofres calientes con la nata montada y las fresas laminadas por encima."}', 'Gofres caseros de cuadrícula dorada y crujiente, con nata montada y fresas frescas encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Fundir {{Mantequilla}} en un cazo a fuego suave hasta que se derrita por completo.","minutes":2,"kind":"activo"},{"text":"Retirar el cazo del fuego y dejar templar la mantequilla fundida durante 3 min.","minutes":3,"kind":"espera"},{"text":"Mezclar en un bol {{Harina}}, {{Levadura química}} y {{Azúcar}} hasta integrar.","minutes":1,"kind":"prep"},{"text":"Batir {{Huevo}} con {{Leche}} y la mantequilla templada en otro bol hasta homogeneizar.","minutes":1,"kind":"prep"},{"text":"Añadir la mezcla líquida sobre los ingredientes secos y remover hasta obtener una masa lisa sin grumos.","minutes":2,"kind":"activo"},{"text":"Calentar la gofrera según las instrucciones del fabricante hasta que alcance la temperatura de cocción.","minutes":3,"kind":"pasivo"},{"text":"Laminar {{Fresas}} en rodajas finas y reservar.","minutes":2,"kind":"paralelo","during":5},{"text":"Verter un cucharón de masa en la gofrera caliente y cerrar.","minutes":1,"kind":"activo"},{"text":"Cocer el gofre hasta que esté dorado y crujiente, unos 4 min.","minutes":4,"kind":"pasivo"},{"text":"Montar {{Nata para montar}} con unas varillas hasta que espese y forme picos firmes.","minutes":2,"kind":"paralelo","during":8},{"text":"Añadir {{Azúcar glas}} a la nata y remover con suavidad para integrar.","minutes":1,"kind":"activo"},{"text":"Retirar el gofre de la gofrera y repetir el proceso con el resto de masa hasta agotar.","minutes":4,"kind":"activo"},{"text":"Servir los gofres calientes con la nata montada y las fresas laminadas por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('desayunos_023', 'Huevos revueltos cremosos con cebollino', 'desayunos', 'huevo', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 8, 'facil', 'all', 317, 17, 2, 27, 2, true, false, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Nata para cocinar","amount":30,"unit":"ml"},{"name":"Cebollino fresco","amount":8,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Picar cebollino fresco muy fino y reservar.","Cascar huevo en un bol, añadir sal y batir lo justo hasta que la yema y la clara se integren.","Calentar sartén a fuego suave y fundir mantequilla hasta que cubra el fondo sin dorarse.","Verter los huevos batidos y remover sin parar con una espátula, retirando la sartén del fuego cada 20 segundos para controlar el calor.","Añadir nata para cocinar cuando los huevos empiecen a cuajar pero sigan brillantes.","Remover fuera del fuego hasta alcanzar una textura cremosa y suave.","Repartir en platos, espolvorear con el cebollino picado y servir de inmediato."}', 'Huevos revueltos de textura sedosa, con el verde fresco del cebollino picado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Cebollino fresco}} muy fino y reservar.","minutes":1,"kind":"prep"},{"text":"Cascar {{Huevo}} en un bol, añadir {{Sal|gusto}} y batir lo justo hasta que la yema y la clara se integren.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego suave y fundir {{Mantequilla}} hasta que cubra el fondo sin dorarse.","minutes":1,"kind":"activo"},{"text":"Verter los huevos batidos y remover sin parar con una espátula, retirando la sartén del fuego cada 20 segundos para controlar el calor.","minutes":3,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}} cuando los huevos empiecen a cuajar pero sigan brillantes.","minutes":1,"kind":"activo"},{"text":"Remover fuera del fuego hasta alcanzar una textura cremosa y suave.","minutes":1,"kind":"activo"},{"text":"Repartir en platos, espolvorear con el cebollino picado y servir de inmediato.","kind":"emplatado"}]'::jsonb, true)
