insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('desayunos_024', 'Bol de requesón con miel y nueces', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 326, 20, 20, 19, 2, true, true, '{"lactosa","frutos_secos"}', '[{"name":"Requesón","amount":300,"unit":"g"},{"name":"Miel","amount":30,"unit":"ml"},{"name":"Nueces","amount":40,"unit":"g"},{"name":"Canela molida","amount":1,"unit":"g"}]'::jsonb, '{"Trocear nueces groseramente con un cuchillo.","Repartir requesón en 2 boles.","Distribuir las nueces troceadas por encima del requesón.","Añadir miel en hilo fino sobre cada bol.","Espolvorear canela molida y servir de inmediato."}', 'Bol de requesón blanco y cremoso, con el dorado de la miel y el crujiente de la nuez.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Trocear {{Nueces}} groseramente con un cuchillo.","minutes":2,"kind":"prep"},{"text":"Repartir {{Requesón}} en 2 boles.","minutes":1,"kind":"activo"},{"text":"Distribuir las nueces troceadas por encima del requesón.","minutes":1,"kind":"activo"},{"text":"Añadir {{Miel|chorrito}} en hilo fino sobre cada bol.","minutes":1,"kind":"emplatado"},{"text":"Espolvorear {{Canela molida|pizca}} y servir de inmediato.","kind":"emplatado"}]'::jsonb, true),
  ('desayunos_025', 'Tostada de aguacate y huevo frito', 'desayunos', 'huevo', 'pan', ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 12, 'facil', 'all', 478, 15, 46, 27, 2, true, false, '{"gluten","huevo"}', '[{"name":"Pan","amount":160,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Tostar pan en la tostadora hasta que esté dorado y crujiente.","Cortar aguacate por la mitad, retirar el hueso y extraer la pulpa con una cuchara a un bol.","Exprimir limón sobre la pulpa de aguacate.","Añadir sal al aguacate y machacar con un tenedor hasta obtener una crema rústica.","Calentar aceite de oliva en sartén a fuego medio-alto.","Freír huevo hasta que la clara esté cuajada y la yema siga líquida.","Extender la crema de aguacate sobre las tostadas.","Colocar un huevo frito sobre cada tostada y servir de inmediato."}', 'Tostada de aguacate cremoso con huevo frito y la yema rota encima, el clásico de brunch.', NULL, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Tostar {{Pan}} en la tostadora hasta que esté dorado y crujiente.","minutes":3,"kind":"pasivo"},{"text":"Cortar {{Aguacate}} por la mitad, retirar el hueso y extraer la pulpa con una cuchara a un bol.","minutes":2,"kind":"prep"},{"text":"Exprimir {{Limón}} sobre la pulpa de aguacate.","minutes":1,"kind":"prep"},{"text":"Añadir {{Sal|gusto}} al aguacate y machacar con un tenedor hasta obtener una crema rústica.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio-alto.","minutes":1,"kind":"activo"},{"text":"Freír {{Huevo}} hasta que la clara esté cuajada y la yema siga líquida.","minutes":2,"kind":"activo"},{"text":"Extender la crema de aguacate sobre las tostadas.","minutes":1,"kind":"emplatado"},{"text":"Colocar un huevo frito sobre cada tostada y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true),
  ('ensaladas_verduras_001', 'Ensalada mixta', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 218, 9, 10, 17, 2, true, false, '{"lactosa","sulfitos"}', '[{"name":"Lechuga","amount":150,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Queso fresco","amount":80,"unit":"g"},{"name":"Aceitunas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Lavar lechuga bajo agua fría y escurrir bien.","Cortar la lechuga en trozos de bocado y distribuir en una ensaladera.","Cortar tomate en gajos y añadir a la ensaladera.","Cortar pepino en rodajas y añadir a la ensaladera.","Laminar cebolla en aros finos y añadir a la ensaladera.","Cortar queso fresco en dados de 1 cm y añadir a la ensaladera.","Añadir aceitunas a la ensaladera.","Aliñar con aceite de oliva y vinagre, remover con suavidad y servir de inmediato."}', 'Ensalada mixta de lechuga, tomate, pepino, cebolla, aceitunas y queso fresco', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Lechuga}} bajo agua fría y escurrir bien.","minutes":1,"kind":"prep"},{"text":"Cortar la lechuga en trozos de bocado y distribuir en una ensaladera.","minutes":1,"kind":"prep"},{"text":"Cortar {{Tomate}} en gajos y añadir a la ensaladera.","minutes":1,"kind":"prep"},{"text":"Cortar {{Pepino}} en rodajas y añadir a la ensaladera.","minutes":1,"kind":"prep"},{"text":"Laminar {{Cebolla}} en aros finos y añadir a la ensaladera.","minutes":1,"kind":"prep"},{"text":"Cortar {{Queso fresco}} en dados de 1 cm y añadir a la ensaladera.","minutes":1,"kind":"prep"},{"text":"Añadir {{Aceitunas}} a la ensaladera.","minutes":1,"kind":"prep"},{"text":"Aliñar con {{Aceite de oliva|chorrito}} y {{Vinagre}}, remover con suavidad y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_002', 'Pisto manchego', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'verano', 186, 4, 16, 12, 2, true, true, '{}', '[{"name":"Calabacín","amount":200,"unit":"g"},{"name":"Pimiento rojo","amount":120,"unit":"g"},{"name":"Pimiento verde","amount":120,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate maduro","amount":200,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"}]'::jsonb, '{"Pelar cebolla y ajo, y cortar la cebolla en dados pequeños y picar el ajo fino.","Cortar pimiento rojo y pimiento verde en dados pequeños.","Cortar calabacín en dados pequeños.","Escaldar tomate maduro en agua hirviendo 30 segundos, pelar y cortar en dados pequeños.","Calentar aceite de oliva en una cazuela a fuego medio hasta que esté caliente.","Sofreír la cebolla y el ajo picados a fuego medio hasta que la cebolla esté translúcida, unos 5 min.","Añadir el pimiento rojo y el pimiento verde en dados y sofreír a fuego medio hasta que estén tiernos, unos 5 min.","Incorporar el calabacín en dados, remover y cocer a fuego medio hasta que empiece a ablandarse, unos 5 min.","Añadir el tomate en dados, remover para integrar y tapar la cazuela.","Cocer a fuego suave tapado hasta que todas las verduras estén tiernas y el conjunto pierda exceso de agua, unos 12 min.","Retirar la tapa, remover y servir el pisto caliente o templado."}', 'Fritada de verduras al estilo manchego con calabacín y pimientos', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Corta las verduras en trozos similares. Rocía con aceite de oliva y cocina en la airfryer a 180-190°C durante 20-25 minutos, removiendo a mitad, hasta que estén tiernas y ligeramente doradas. Añade el tomate al final para que se integre."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Mezcla todas las verduras picadas con aceite de oliva, sal y pimienta en una bandeja de horno. Hornea a 190-200°C durante 40-45 minutos, removiendo ocasionalmente, hasta que estén muy tiernas y caramelizadas, añadiendo el tomate a mitad de cocción."},{"appliance":"thermomix","time":40,"difficulty":"facil","prepSummary":"Trocea las verduras en el vaso. Sofríe la cebolla y el ajo con aceite, luego añade los pimientos y el calabacín, y cocina. Incorpora el tomate y programa 20-25 minutos a temperatura Varoma, velocidad cuchara, giro inverso, hasta obtener un pisto tierno."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla con aceite. Añade los pimientos, calabacín y tomate, cierra la olla y cocina 5-7 minutos desde que sube la válvula. Despresuriza y remueve hasta espesar ligeramente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Cebolla}} y {{Ajo}}, y cortar la cebolla en dados pequeños y picar el ajo fino.","minutes":3,"kind":"prep"},{"text":"Cortar {{Pimiento rojo}} y {{Pimiento verde}} en dados pequeños.","minutes":3,"kind":"prep"},{"text":"Cortar {{Calabacín}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Escaldar {{Tomate maduro}} en agua hirviendo 30 segundos, pelar y cortar en dados pequeños.","minutes":4,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una cazuela a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el ajo picados a fuego medio hasta que la cebolla esté translúcida, unos 5 min.","minutes":5,"kind":"activo"},{"text":"Añadir el pimiento rojo y el pimiento verde en dados y sofreír a fuego medio hasta que estén tiernos, unos 5 min.","minutes":5,"kind":"activo"},{"text":"Incorporar el calabacín en dados, remover y cocer a fuego medio hasta que empiece a ablandarse, unos 5 min.","minutes":5,"kind":"activo"},{"text":"Añadir el tomate en dados, remover para integrar y tapar la cazuela.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave tapado hasta que todas las verduras estén tiernas y el conjunto pierda exceso de agua, unos 12 min.","minutes":12,"kind":"pasivo"},{"text":"Retirar la tapa, remover y servir el pisto caliente o templado.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_003', 'Menestra de verduras con jamón', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 198, 6, 18, 10, 2, true, true, '{"gluten"}', '[{"name":"Alcachofas","amount":150,"unit":"g"},{"name":"Judías verdes","amount":100,"unit":"g"},{"name":"Guisantes","amount":80,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Harina","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Pelar zanahoria y cortar en rodajas de 0,5 cm.","Pelar cebolla y picar en brunoise fina.","Limpiar alcachofas retirando las hojas duras externas y cortar en cuartos.","Despuntar judías verdes y cortar en trozos de 3 cm.","Llevar a ebullición una olla con agua salada a fuego fuerte.","Cocer la zanahoria en el agua hirviendo 8 min hasta que esté tierna pero firme.","Retirar la zanahoria con una espumadera y reservar.","Cocer las judías verdes en la misma agua 5 min hasta que estén al dente.","Retirar las judías verdes y reservar.","Cocer las alcachofas en la misma agua 6 min hasta que estén tiernas.","Retirar las alcachofas, reservar, y guardar 150 ml del agua de cocción.","Añadir guisantes a la misma agua caliente y cocer 3 min hasta que estén tiernos.","Retirar los guisantes y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada a fuego medio 5 min hasta que esté transparente y comience a dorarse.","Añadir jamón serrano y saltear 1 min hasta que suelte su grasa.","Añadir harina sobre la cebolla y el jamón.","Remover sin parar 1 min hasta que la harina se integre y pierda el sabor a crudo.","Verter los 150 ml del agua de cocción reservada poco a poco, removiendo sin parar.","Remover hasta que la salsa ligue y no tenga grumos.","Incorporar la zanahoria, las judías verdes, las alcachofas y los guisantes reservados.","Mezclar con cuidado para no romper las verduras.","Cocer todo junto a fuego suave 5 min hasta que la salsa envuelva bien las verduras.","Servir la menestra caliente en platos hondos distribuyendo bien las verduras y el jamón."}', 'Menestra de verduras de temporada rehogadas con jamón', '[{"appliance":"horno","time":35,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el jamón en una sartén. Mezcla con las verduras en una fuente apta para horno, añade un poco de caldo y hornea a 180-200°C hasta que estén tiernas, unos 20-25 minutos."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Trocea y sofríe la cebolla y el jamón. Añade las verduras y un poco de caldo, cocinando a temperatura Varoma o 100°C, velocidad cuchara, hasta que estén tiernas, unos 20-25 minutos."},{"appliance":"vaporera","time":35,"difficulty":"facil","prepSummary":"Cocina las verduras al vapor hasta que estén tiernas pero firmes. En una sartén aparte, sofríe la cebolla y el jamón. Mezcla todo con las verduras al vapor y un chorrito de aceite de oliva, añadiendo la harina disuelta en un poco de caldo para ligar si se desea."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el jamón en la olla. Añade las verduras más duras con un poco de caldo y cocina a presión 5-7 minutos. Libera la presión, añade los guisantes y la harina disuelta en caldo para espesar, cocinando unos minutos más sin presión."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], true, '[{"text":"Pelar {{Zanahoria}} y cortar en rodajas de 0,5 cm.","minutes":2,"kind":"prep"},{"text":"Pelar {{Cebolla}} y picar en brunoise fina.","minutes":2,"kind":"prep"},{"text":"Limpiar {{Alcachofas}} retirando las hojas duras externas y cortar en cuartos.","minutes":3,"kind":"prep"},{"text":"Despuntar {{Judías verdes}} y cortar en trozos de 3 cm.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición una olla con agua salada a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer la zanahoria en el agua hirviendo 8 min hasta que esté tierna pero firme.","minutes":8,"kind":"pasivo"},{"text":"Retirar la zanahoria con una espumadera y reservar.","minutes":1,"kind":"activo"},{"text":"Cocer las judías verdes en la misma agua 5 min hasta que estén al dente.","minutes":5,"kind":"pasivo"},{"text":"Retirar las judías verdes y reservar.","minutes":1,"kind":"activo"},{"text":"Cocer las alcachofas en la misma agua 6 min hasta que estén tiernas.","minutes":6,"kind":"pasivo"},{"text":"Retirar las alcachofas, reservar, y guardar 150 ml del agua de cocción.","minutes":1,"kind":"activo"},{"text":"Añadir {{Guisantes}} a la misma agua caliente y cocer 3 min hasta que estén tiernos.","minutes":3,"kind":"pasivo"},{"text":"Retirar los guisantes y reservar.","minutes":1,"kind":"activo"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada a fuego medio 5 min hasta que esté transparente y comience a dorarse.","minutes":5,"kind":"activo"},{"text":"Añadir {{Jamón serrano}} y saltear 1 min hasta que suelte su grasa.","minutes":1,"kind":"activo"},{"text":"Añadir {{Harina}} sobre la cebolla y el jamón.","minutes":1,"kind":"activo"},{"text":"Remover sin parar 1 min hasta que la harina se integre y pierda el sabor a crudo.","minutes":1,"kind":"activo"},{"text":"Verter los 150 ml del agua de cocción reservada poco a poco, removiendo sin parar.","minutes":2,"kind":"activo"},{"text":"Remover hasta que la salsa ligue y no tenga grumos.","minutes":1,"kind":"activo"},{"text":"Incorporar la zanahoria, las judías verdes, las alcachofas y los guisantes reservados.","minutes":1,"kind":"activo"},{"text":"Mezclar con cuidado para no romper las verduras.","minutes":1,"kind":"activo"},{"text":"Cocer todo junto a fuego suave 5 min hasta que la salsa envuelva bien las verduras.","minutes":5,"kind":"pasivo"},{"text":"Servir la menestra caliente en platos hondos distribuyendo bien las verduras y el jamón.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_004', 'Calabacín relleno de carne', 'ensaladas_verduras', 'cerdo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 45, 'normal', 'all', 348, 22, 12, 24, 2, true, true, '{}', '[{"name":"Calabacín","amount":400,"unit":"g"},{"name":"Carne picada de cerdo","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar calabacín por la mitad a lo largo y vaciar la pulpa con una cuchara, dejando una pared de 1 cm; reservar la pulpa.","Picar cebolla y ajo muy finos; picar también la pulpa reservada del calabacín.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada y el ajo picado hasta que estén blandos y translúcidos, unos 4 min.","Añadir la pulpa picada del calabacín y saltear a fuego medio hasta que evapore el agua, unos 3 min.","Incorporar carne picada de cerdo y sofreír a fuego fuerte, removiendo, hasta que pierda el color rosado.","Añadir tomate triturado, remover y cocer a fuego medio hasta que la salsa reduzca y ligue, unos 5 min.","Precalentar el horno a 190 °C con calor arriba y abajo.","Disponer las barquitas de calabacín en una bandeja de horno y rellenarlas generosamente con el sofrito de carne.","Hornear a 190 °C durante 25 min hasta que el calabacín esté tierno y los bordes ligeramente dorados.","Retirar la bandeja del horno y servir los calabacines rellenos en caliente."}', 'Calabacines rellenos de carne picada gratinados con tomate', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Prepara el relleno salteando la carne con cebolla, ajo y tomate. Rellena los calabacines ahuecados y hornea a 180-200°C durante 25-30 minutos hasta que el calabacín esté tierno y el relleno bien integrado."},{"appliance":"airfryer","time":40,"difficulty":"normal","prepSummary":"Tras preparar el relleno en sartén, rellena los calabacines y cocina en la airfryer a 180°C durante 20-25 minutos. Vigila que el calabacín quede tierno y el relleno bien caliente, logrando un exterior ligeramente crujiente."},{"appliance":"thermomix","time":45,"difficulty":"normal","prepSummary":"Prepara el sofrito y la carne picada en el vaso de la Thermomix. Cocina los calabacines ahuecados al vapor en el Varoma mientras se hace el relleno. Luego, rellena y sirve, obteniendo un plato jugoso y cocinado de forma eficiente."},{"appliance":"vaporera","time":45,"difficulty":"normal","prepSummary":"Cocina el relleno de carne picada con cebolla, ajo y tomate en una sartén. Ahueca los calabacines y cuécelos al vapor durante 20-25 minutos hasta que estén tiernos. Rellena los calabacines con la carne y sirve un plato ligero y saludable."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Calabacín}} por la mitad a lo largo y vaciar la pulpa con una cuchara, dejando una pared de 1 cm; reservar la pulpa.","minutes":5,"kind":"prep"},{"text":"Picar {{Cebolla}} y {{Ajo}} muy finos; picar también la pulpa reservada del calabacín.","minutes":4,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada y el ajo picado hasta que estén blandos y translúcidos, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Añadir la pulpa picada del calabacín y saltear a fuego medio hasta que evapore el agua, unos 3 min.","minutes":3,"kind":"activo"},{"text":"Incorporar {{Carne picada de cerdo}} y sofreír a fuego fuerte, removiendo, hasta que pierda el color rosado.","minutes":4,"kind":"activo"},{"text":"Añadir {{Tomate triturado}}, remover y cocer a fuego medio hasta que la salsa reduzca y ligue, unos 5 min.","minutes":5,"kind":"activo"},{"text":"Precalentar el horno a 190 °C con calor arriba y abajo.","minutes":5,"kind":"pasivo"},{"text":"Disponer las barquitas de calabacín en una bandeja de horno y rellenarlas generosamente con el sofrito de carne.","minutes":2,"kind":"prep"},{"text":"Hornear a 190 °C durante 25 min hasta que el calabacín esté tierno y los bordes ligeramente dorados.","minutes":25,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y servir los calabacines rellenos en caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_005', 'Espinacas a la catalana', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 208, 6, 12, 16, 2, false, true, '{"frutos_secos"}', '[{"name":"Espinacas frescas","amount":300,"unit":"g"},{"name":"Pasas","amount":20,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Laminar ajo en láminas finas.","Calentar sartén a fuego medio sin aceite y tostar piñones hasta que estén dorados; retirar y reservar.","Añadir aceite de oliva a la misma sartén y calentar a fuego medio.","Sofreír el ajo laminado hasta que esté dorado sin que se queme.","Añadir espinacas frescas a la sartén y saltear a fuego fuerte hasta que reduzcan por completo.","Añadir pasas y los piñones tostados; remover para mezclar bien.","Salpimentar con sal y servir de inmediato."}', 'Espinacas salteadas con pasas y piñones al estilo catalán', '[{"appliance":"thermomix","time":18,"difficulty":"facil","prepSummary":"Pica el ajo, luego sofríelo con el aceite y los piñones. Añade las espinacas y las pasas, y cocina a 100°C, giro inverso, velocidad cuchara, hasta que las espinacas estén a tu gusto (aprox. 10-12 minutos)."},{"appliance":"vaporera","time":15,"difficulty":"facil","prepSummary":"Cocina las espinacas al vapor hasta que estén tiernas (unos 5-7 minutos). Mientras, saltea el ajo picado, los piñones y las pasas en una sartén con aceite de oliva hasta dorar. Mezcla las espinacas cocidas con el sofrito."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Laminar {{Ajo}} en láminas finas.","minutes":2,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio sin aceite y tostar {{Piñones}} hasta que estén dorados; retirar y reservar.","minutes":3,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} a la misma sartén y calentar a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo laminado hasta que esté dorado sin que se queme.","minutes":2,"kind":"activo"},{"text":"Añadir {{Espinacas frescas}} a la sartén y saltear a fuego fuerte hasta que reduzcan por completo.","minutes":3,"kind":"activo"},{"text":"Añadir {{Pasas}} y los piñones tostados; remover para mezclar bien.","minutes":1,"kind":"activo"},{"text":"Salpimentar con {{Sal|gusto}} y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_006', 'Pimientos rellenos de carne', 'ensaladas_verduras', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'all', 382, 24, 18, 24, 2, true, true, '{}', '[{"name":"Pimientos rojos","amount":4,"unit":"ud"},{"name":"Carne picada de ternera","amount":250,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Picar cebolla en trozos finos.","Picar ajo fino.","Cortar la parte superior de pimientos rojos a modo de tapa y retirar las semillas y nervios del interior.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada hasta que esté transparente, unos 4 min.","Añadir el ajo picado y sofreír 1 min hasta que desprenda aroma.","Añadir carne picada de ternera y saltear a fuego fuerte hasta que pierda el color rosado.","Añadir tomate triturado, mezclar y cocer a fuego medio 5 min hasta que la salsa reduzca ligeramente.","Retirar la sartén del fuego y dejar templar el relleno 2 min.","Rellenar cada pimiento con la mezcla de carne hasta el borde y tapar con su parte superior.","Disponer los pimientos rellenos en una bandeja de horno y hornear a 200 °C durante 30 min hasta que la piel se arrugue.","Retirar la bandeja del horno y servir los pimientos en plato."}', 'Pimientos rojos rellenos de carne picada al horno con tomate', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Sofreír la cebolla, ajo, carne y tomate para el relleno en una sartén. Rellenar los pimientos y hornear a 180-200°C durante 40-50 minutos, hasta que estén tiernos y ligeramente dorados."},{"appliance":"airfryer","time":45,"difficulty":"normal","prepSummary":"Preparar el relleno sofriéndolo previamente en una sartén. Rellenar los pimientos cortados por la mitad y cocinar en la airfryer a 185°C durante 25-35 minutos, hasta que los pimientos estén tiernos y el relleno caliente. Un truco es rociar con un poco de aceite para un mejor dorado."},{"appliance":"thermomix","time":55,"difficulty":"normal","prepSummary":"Preparar el relleno en el vaso de la Thermomix (picar cebolla/ajo, sofreír, añadir carne y tomate, cocinar). Rellenar los pimientos y cocinarlos al vapor en el Varoma durante 25-35 minutos, velocidad Varoma, hasta que estén tiernos. El truco es asegurarse de que los pimientos no se deshagan durante la cocción al vapor."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Picar {{Cebolla}} en trozos finos.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Cortar la parte superior de {{Pimientos rojos}} a modo de tapa y retirar las semillas y nervios del interior.","minutes":5,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada hasta que esté transparente, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Añadir el ajo picado y sofreír 1 min hasta que desprenda aroma.","minutes":1,"kind":"activo"},{"text":"Añadir {{Carne picada de ternera}} y saltear a fuego fuerte hasta que pierda el color rosado.","minutes":4,"kind":"activo"},{"text":"Añadir {{Tomate triturado}}, mezclar y cocer a fuego medio 5 min hasta que la salsa reduzca ligeramente.","minutes":5,"kind":"activo"},{"text":"Retirar la sartén del fuego y dejar templar el relleno 2 min.","minutes":2,"kind":"espera"},{"text":"Rellenar cada pimiento con la mezcla de carne hasta el borde y tapar con su parte superior.","minutes":3,"kind":"prep"},{"text":"Disponer los pimientos rellenos en una bandeja de horno y hornear a 200 °C durante 30 min hasta que la piel se arrugue.","minutes":30,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y servir los pimientos en plato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_007', 'Berenjenas rellenas', 'ensaladas_verduras', 'cerdo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'all', 362, 20, 16, 24, 2, true, true, '{"lactosa"}', '[{"name":"Berenjena","amount":400,"unit":"g"},{"name":"Carne picada de cerdo","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Queso rallado","amount":30,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 190 °C con calor arriba y abajo.","Lavar berenjena y cortar cada una por la mitad a lo largo.","Vaciar la pulpa de cada mitad con una cuchara, dejando 1 cm de pared. Reservar la pulpa y las cáscaras por separado.","Picar la pulpa reservada en trozos pequeños. Reservar.","Picar cebolla fina y picar ajo fino. Reservar.","Pintar las cáscaras por dentro con aceite de oliva y colocarlas en una bandeja de horno con la cavidad hacia arriba.","Hornear las cáscaras a 190 °C durante 10 min, hasta que estén ligeramente tiernas.","Calentar el aceite de oliva restante en sartén a fuego medio.","Sofreír la cebolla picada a fuego medio durante 3 min, hasta que esté blanda y translúcida.","Añadir el ajo picado y sofreír 1 min más a fuego medio, hasta que desprenda aroma.","Añadir carne picada de cerdo y saltear a fuego fuerte, removiendo, hasta que esté dorada y sin partes rosadas, unos 4 min.","Añadir la pulpa de berenjena picada y mezclar. Sofreír 3 min a fuego medio hasta que esté tierna.","Añadir tomate triturado, mezclar y cocer a fuego suave 5 min, hasta que el relleno reduzca y quede jugoso pero no líquido.","Retirar la sartén del fuego. Rellenar cada cáscara de berenjena con el sofrito, distribuyendo el relleno a partes iguales.","Repartir queso rallado sobre el relleno de cada berenjena.","Hornear a 190 °C durante 12 min y, los últimos 3 min, activar el gratinador hasta que el queso esté dorado y burbujeante.","Retirar del horno y servir las berenjenas rellenas inmediatamente."}', 'Berenjenas rellenas de carne picada gratinadas con queso', '[{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Vacía las berenjenas y hornéalas a 180°C unos 30-35 min hasta que estén tiernas. Prepara el sofrito con la carne y rellena. Gratina a 200°C o con función grill durante 10-15 min hasta dorar. El truco es no pasarse con la cocción inicial de la berenjena para que mantenga su forma."},{"appliance":"airfryer","time":45,"difficulty":"normal","prepSummary":"Corta las berenjenas por la mitad, vacía y cocínalas en la airfryer a 180°C durante 20-25 min. Mientras, prepara el sofrito de carne y verduras en una sartén. Rellena las berenjenas y gratina en la airfryer a 190°C por 8-10 min. Un truco es pincelar las berenjenas con aceite para"},{"appliance":"thermomix","time":50,"difficulty":"normal","prepSummary":"Prepara el sofrito de carne y verduras en la Thermomix (velocidad cuchara, 120°C, 15 min). Cocina las berenjenas cortadas por la mitad al vapor en el Varoma (25-30 min, Varoma, vel 1). Luego, rellena y gratina en el horno o airfryer. El truco es usar el Varoma para una cocción un"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 190 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Lavar {{Berenjena}} y cortar cada una por la mitad a lo largo.","minutes":2,"kind":"prep"},{"text":"Vaciar la pulpa de cada mitad con una cuchara, dejando 1 cm de pared. Reservar la pulpa y las cáscaras por separado.","minutes":4,"kind":"prep"},{"text":"Picar la pulpa reservada en trozos pequeños. Reservar.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolla}} fina y picar {{Ajo}} fino. Reservar.","minutes":3,"kind":"prep"},{"text":"Pintar las cáscaras por dentro con {{Aceite de oliva|chorrito}} y colocarlas en una bandeja de horno con la cavidad hacia arriba.","minutes":2,"kind":"prep"},{"text":"Hornear las cáscaras a 190 °C durante 10 min, hasta que estén ligeramente tiernas.","minutes":10,"kind":"pasivo"},{"text":"Calentar el aceite de oliva restante en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada a fuego medio durante 3 min, hasta que esté blanda y translúcida.","minutes":3,"kind":"activo"},{"text":"Añadir el ajo picado y sofreír 1 min más a fuego medio, hasta que desprenda aroma.","minutes":1,"kind":"activo"},{"text":"Añadir {{Carne picada de cerdo}} y saltear a fuego fuerte, removiendo, hasta que esté dorada y sin partes rosadas, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Añadir la pulpa de berenjena picada y mezclar. Sofreír 3 min a fuego medio hasta que esté tierna.","minutes":3,"kind":"activo"},{"text":"Añadir {{Tomate triturado}}, mezclar y cocer a fuego suave 5 min, hasta que el relleno reduzca y quede jugoso pero no líquido.","minutes":5,"kind":"activo"},{"text":"Retirar la sartén del fuego. Rellenar cada cáscara de berenjena con el sofrito, distribuyendo el relleno a partes iguales.","minutes":2,"kind":"activo"},{"text":"Repartir {{Queso rallado}} sobre el relleno de cada berenjena.","minutes":1,"kind":"prep"},{"text":"Hornear a 190 °C durante 12 min y, los últimos 3 min, activar el gratinador hasta que el queso esté dorado y burbujeante.","minutes":15,"kind":"pasivo"},{"text":"Retirar del horno y servir las berenjenas rellenas inmediatamente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_008', 'Verduras a la plancha', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'verano', 156, 4, 12, 10, 2, true, true, '{}', '[{"name":"Calabacín","amount":150,"unit":"g"},{"name":"Berenjena","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Espárragos trigueros","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Laminar calabacín en rodajas de 0,5 cm.","Laminar berenjena en rodajas de 0,5 cm.","Cortar pimiento rojo en tiras anchas.","Retirar la parte leñosa de espárragos trigueros.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Pincelar plancha con aceite de oliva y colocar las láminas de calabacín.","Dorar las láminas de calabacín 3 min por cada lado hasta que aparezcan marcas.","Retirar el calabacín y colocar las láminas de berenjena en la plancha.","Dorar las láminas de berenjena 3 min por cada lado hasta que estén tiernas.","Retirar la berenjena y colocar las tiras de pimiento rojo en la plancha.","Dorar las tiras de pimiento rojo 3 min por cada lado hasta que estén blandas y con los bordes tostados.","Retirar el pimiento rojo y colocar los espárragos trigueros en la plancha.","Dorar los espárragos trigueros 3 min por cada lado hasta que estén tiernos y con marcas.","Disponer todas las verduras en una fuente y aliñar con aceite de oliva.","Servir de inmediato."}', 'Verduras de temporada asadas a la plancha con aceite', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Corta las verduras en trozos similares, mézclalas con el aceite de oliva y sazona. Cocina en la airfryer precalentada a 190°C durante 15-18 minutos, agitando la cesta a mitad para un dorado uniforme y una textura tierna por dentro."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Corta las verduras, úntalas con aceite de oliva y sazona. Extiéndelas en una bandeja de horno y ásalas durante 20-25 minutos, dándoles la vuelta a mitad, hasta que estén tiernas y ligeramente caramelizadas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Laminar {{Calabacín}} en rodajas de 0,5 cm.","minutes":2,"kind":"prep"},{"text":"Laminar {{Berenjena}} en rodajas de 0,5 cm.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pimiento rojo}} en tiras anchas.","minutes":1,"kind":"prep"},{"text":"Retirar la parte leñosa de {{Espárragos trigueros}}.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Pincelar {{@Plancha}} con {{Aceite de oliva|chorrito}} y colocar las láminas de calabacín.","minutes":1,"kind":"activo"},{"text":"Dorar las láminas de calabacín 3 min por cada lado hasta que aparezcan marcas.","minutes":6,"kind":"pasivo"},{"text":"Retirar el calabacín y colocar las láminas de berenjena en la plancha.","minutes":1,"kind":"activo"},{"text":"Dorar las láminas de berenjena 3 min por cada lado hasta que estén tiernas.","minutes":6,"kind":"pasivo"},{"text":"Retirar la berenjena y colocar las tiras de pimiento rojo en la plancha.","minutes":1,"kind":"activo"},{"text":"Dorar las tiras de pimiento rojo 3 min por cada lado hasta que estén blandas y con los bordes tostados.","minutes":6,"kind":"pasivo"},{"text":"Retirar el pimiento rojo y colocar los espárragos trigueros en la plancha.","minutes":1,"kind":"activo"},{"text":"Dorar los espárragos trigueros 3 min por cada lado hasta que estén tiernos y con marcas.","minutes":6,"kind":"pasivo"},{"text":"Disponer todas las verduras en una fuente y aliñar con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"emplatado"},{"text":"Servir de inmediato.","kind":"emplatado"}]'::jsonb, NULL)
