  estrella = excluded.estrella;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella
) values
  ('ensaladas_verduras_009', 'Escalivada', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'horno', 50, 'facil', 'verano', 168, 3, 14, 12, 2, true, true, '{}', '[{"name":"Berenjena","amount":200,"unit":"g"},{"name":"Pimiento rojo","amount":200,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Lavar berenjena, pimiento rojo, cebolla y tomate bajo el grifo y secar con papel de cocina.","Disponer la berenjena, el pimiento rojo, la cebolla y el tomate enteros en una bandeja de horno.","Hornear las verduras a 200 °C hasta que la piel esté completamente chamuscada y la pulpa tierna, unos 40 min.","Retirar la bandeja del horno y tapar con papel de aluminio hasta que las verduras templen, unos 15 min.","Pelar la piel de la berenjena, el pimiento rojo, la cebolla y el tomate templados, retirando también las semillas del pimiento.","Cortar la pulpa de todas las verduras en tiras de 1 cm de ancho.","Disponer las tiras de verdura en una fuente, alternando los colores.","Aliñar con aceite de oliva repartido de forma uniforme sobre las verduras.","Servir la escalivada templada o a temperatura ambiente."}', 'Verduras asadas al horno, peladas y aliñadas al estilo catalán', '[{"appliance":"horno","time":50,"difficulty":"facil","prepSummary":"Asa las verduras enteras o en trozos grandes a 180-200°C durante 45-50 minutos, hasta que estén muy tiernas y ligeramente chamuscadas. Pela y aliña con aceite de oliva."},{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Corta las verduras en trozos grandes, úntalas con aceite y cocínalas en la airfryer a 190°C durante 30-35 minutos, volteando a mitad de cocción, hasta que estén tiernas y doradas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"prep"},{"text":"Lavar {{Berenjena}}, {{Pimiento rojo}}, {{Cebolla}} y {{Tomate}} bajo el grifo y secar con papel de cocina.","minutes":3,"kind":"prep"},{"text":"Disponer la berenjena, el pimiento rojo, la cebolla y el tomate enteros en una bandeja de horno.","minutes":2,"kind":"prep"},{"text":"Hornear las verduras a 200 °C hasta que la piel esté completamente chamuscada y la pulpa tierna, unos 40 min.","minutes":40,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y tapar con papel de aluminio hasta que las verduras templen, unos 15 min.","minutes":15,"kind":"espera"},{"text":"Pelar la piel de la berenjena, el pimiento rojo, la cebolla y el tomate templados, retirando también las semillas del pimiento.","minutes":5,"kind":"prep"},{"text":"Cortar la pulpa de todas las verduras en tiras de 1 cm de ancho.","minutes":3,"kind":"prep"},{"text":"Disponer las tiras de verdura en una fuente, alternando los colores.","minutes":2,"kind":"prep"},{"text":"Aliñar con {{Aceite de oliva|chorrito}} repartido de forma uniforme sobre las verduras.","minutes":1,"kind":"emplatado"},{"text":"Servir la escalivada templada o a temperatura ambiente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_010', 'Judías verdes rehogadas', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 132, 4, 10, 8, 2, true, true, '{}', '[{"name":"Judías verdes","amount":350,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Jamón serrano","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Laminar ajo en láminas finas.","Cortar jamón serrano en taquitos pequeños.","Llevar a ebullición una olla con agua abundante y sal a fuego fuerte.","Añadir judías verdes cuando el agua rompa a hervir y cocer 10 min a fuego medio hasta que estén tiernas.","Escurrir las judías verdes y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Añadir el ajo laminado y sofreír a fuego medio hasta que empiece a dorarse.","Añadir el jamón en taquitos y saltear 1 min a fuego medio hasta que se dore ligeramente.","Añadir las judías verdes escurridas y saltear 2 min a fuego medio removiendo para que se impregnen del sofrito.","Servir las judías rehogadas en el plato."}', 'Judías verdes cocidas y rehogadas con ajo y jamón', '[{"appliance":"thermomix","time":25,"difficulty":"normal","prepSummary":"Cocina las judías verdes al vapor en el Varoma durante 18-20 minutos. Mientras, sofríe el ajo picado y el jamón serrano en el vaso con aceite de oliva a 120°C, 5 min, Vel. Cuchara. Incorpora las judías cocidas y mezcla."},{"appliance":"vaporera","time":22,"difficulty":"facil","prepSummary":"Cocina las judías verdes al vapor hasta que estén tiernas (15-20 min). En una sartén aparte, sofríe el ajo picado y el jamón serrano con el aceite de oliva hasta que el jamón esté crujiente. Mezcla las judías con el sofrito."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Cocina las judías verdes en la olla express con un poco de agua durante 3-5 minutos desde que sube la válvula. Escurre bien. En la misma olla abierta o en una sartén, sofríe el ajo y el jamón con el aceite hasta dorar, luego añade las judías y saltea brevemente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Laminar {{Ajo}} en láminas finas.","minutes":2,"kind":"prep"},{"text":"Cortar {{Jamón serrano}} en taquitos pequeños.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición una olla con agua abundante y sal a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Añadir {{Judías verdes}} cuando el agua rompa a hervir y cocer 10 min a fuego medio hasta que estén tiernas.","minutes":10,"kind":"pasivo"},{"text":"Escurrir las judías verdes y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Añadir el ajo laminado y sofreír a fuego medio hasta que empiece a dorarse.","minutes":2,"kind":"activo"},{"text":"Añadir el jamón en taquitos y saltear 1 min a fuego medio hasta que se dore ligeramente.","minutes":1,"kind":"activo"},{"text":"Añadir las judías verdes escurridas y saltear 2 min a fuego medio removiendo para que se impregnen del sofrito.","minutes":2,"kind":"activo"},{"text":"Servir las judías rehogadas en el plato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_011', 'Brócoli gratinado', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 25, 'facil', 'invierno', 212, 10, 10, 14, 2, true, true, '{"lactosa","gluten"}', '[{"name":"Brócoli","amount":400,"unit":"g"},{"name":"Bechamel","amount":100,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Separar brócoli en ramilletes de tamaño similar.","Llevar a ebullición agua con sal en una olla a fuego fuerte.","Cocer los ramilletes de brócoli en el agua hirviendo durante 5 min, hasta que estén al dente.","Precalentar el horno a 220 °C con función gratinador.","Escurrir bien el brócoli y extenderlo en una fuente de horno apta para gratinar.","Repartir aceite de oliva sobre el brócoli escurrido.","Cubrir el brócoli con bechamel, distribuyéndola de forma uniforme.","Espolvorear queso rallado sobre la bechamel para cubrir toda la superficie.","Hornear a 220 °C con gratinador durante 10 min, hasta que el queso esté dorado y burbujeante.","Retirar la fuente del horno y servir el brócoli gratinado de inmediato."}', 'Brócoli al vapor gratinado con bechamel y queso', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Cocina el brócoli al vapor o hervido hasta que esté tierno. Mézclalo con la bechamel en una fuente apta para horno, cubre con el queso rallado y gratina a 190-200°C durante 15-20 minutos, hasta que esté dorado y burbujeante."},{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Cuece el brócoli al vapor. En un recipiente pequeño apto para airfryer, mezcla el brócoli con la bechamel, cubre con el queso rallado y cocina a 180°C durante 10-15 minutos, hasta que el queso esté fundido y dorado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Separar {{Brócoli}} en ramilletes de tamaño similar.","minutes":3,"kind":"prep"},{"text":"Llevar a ebullición agua con sal en una olla a fuego fuerte.","minutes":4,"kind":"activo"},{"text":"Cocer los ramilletes de brócoli en el agua hirviendo durante 5 min, hasta que estén al dente.","minutes":5,"kind":"pasivo"},{"text":"Precalentar el horno a 220 °C con función gratinador.","minutes":5,"kind":"paralelo","during":2},{"text":"Escurrir bien el brócoli y extenderlo en una fuente de horno apta para gratinar.","minutes":1,"kind":"prep"},{"text":"Repartir {{Aceite de oliva|chorrito}} sobre el brócoli escurrido.","minutes":1,"kind":"prep"},{"text":"Cubrir el brócoli con {{Bechamel}}, distribuyéndola de forma uniforme.","minutes":1,"kind":"prep"},{"text":"Espolvorear {{Queso rallado}} sobre la bechamel para cubrir toda la superficie.","minutes":1,"kind":"prep"},{"text":"Hornear a 220 °C con gratinador durante 10 min, hasta que el queso esté dorado y burbujeante.","minutes":10,"kind":"pasivo"},{"text":"Retirar la fuente del horno y servir el brócoli gratinado de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_012', 'Coliflor rebozada', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'invierno', 238, 8, 18, 14, 2, true, true, '{"gluten","huevo"}', '[{"name":"Coliflor","amount":400,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Separar coliflor en ramilletes del mismo tamaño para que se cuezan de manera uniforme.","Llevar a ebullición una olla con agua abundante y sal.","Añadir los ramilletes de coliflor y cocer 8 min a fuego medio hasta que estén tiernos pero firmes.","Escurrir los ramilletes de coliflor en un colador y extender sobre un paño limpio hasta que se enfríen.","Batir huevo en un bol hondo hasta que esté homogéneo.","Poner harina en un plato llano.","Pasar cada ramillete de coliflor primero por la harina y sacudir el exceso.","Sumergir cada ramillete enharinado en el huevo batido hasta que quede bien cubierto.","Calentar aceite de oliva en sartén a fuego fuerte hasta que el aceite esté bien caliente.","Freír los ramilletes rebozados a fuego medio-fuerte hasta que se doren por todos los lados.","Dar la vuelta a los ramilletes con cuidado durante la fritura para que se doren de manera uniforme.","Retirar los ramilletes y escurrir sobre papel absorbente para eliminar el exceso de aceite.","Servir de inmediato."}', 'Ramilletes de coliflor cocidos, rebozados y fritos', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Precocina la coliflor al vapor hasta que esté tierna. Reboza los floretes, rocíalos con aceite y cocínalos en la airfryer a 190°C durante 18-20 minutos, volteando a mitad, hasta que estén dorados y crujientes."},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Hierve o cuece la coliflor hasta que esté tierna. Reboza los trozos, colócalos en una bandeja de horno con papel y rocía con aceite. Hornea a 200°C durante 25-30 minutos, volteando a mitad, hasta que estén bien dorados."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Separar {{Coliflor}} en ramilletes del mismo tamaño para que se cuezan de manera uniforme.","minutes":3,"kind":"prep"},{"text":"Llevar a ebullición una olla con agua abundante y {{Sal|gusto}}.","minutes":4,"kind":"activo"},{"text":"Añadir los ramilletes de coliflor y cocer 8 min a fuego medio hasta que estén tiernos pero firmes.","minutes":8,"kind":"pasivo"},{"text":"Escurrir los ramilletes de coliflor en un colador y extender sobre un paño limpio hasta que se enfríen.","minutes":3,"kind":"espera"},{"text":"Batir {{Huevo}} en un bol hondo hasta que esté homogéneo.","minutes":1,"kind":"prep"},{"text":"Poner {{Harina}} en un plato llano.","minutes":1,"kind":"prep"},{"text":"Pasar cada ramillete de coliflor primero por la harina y sacudir el exceso.","minutes":2,"kind":"prep"},{"text":"Sumergir cada ramillete enharinado en el huevo batido hasta que quede bien cubierto.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego fuerte hasta que el aceite esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Freír los ramilletes rebozados a fuego medio-fuerte hasta que se doren por todos los lados.","minutes":4,"kind":"activo"},{"text":"Dar la vuelta a los ramilletes con cuidado durante la fritura para que se doren de manera uniforme.","kind":"activo"},{"text":"Retirar los ramilletes y escurrir sobre papel absorbente para eliminar el exceso de aceite.","minutes":1,"kind":"activo"},{"text":"Servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_013', 'Ensalada campera', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'verano', 248, 6, 26, 14, 2, true, true, '{"sulfitos"}', '[{"name":"Patata","amount":250,"unit":"g"},{"name":"Tomate","amount":120,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceitunas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Lavar patata y colocarlas enteras con piel en una olla cubiertas de agua fría con sal.","Llevar a ebullición a fuego fuerte y cocer las patatas a fuego medio hasta que estén tiernas, unos 20 min.","Cortar tomate en gajos medianos y reservar.","Cortar pimiento verde en tiras finas y reservar.","Cortar cebolla en aros finos y reservar.","Escurrir las patatas cocidas y dejar templar 3 min hasta que se puedan manipular.","Pelar las patatas templadas y cortar en rodajas gruesas de unos 1 cm.","Disponer las rodajas de patata en una fuente y añadir el tomate, el pimiento verde y la cebolla por encima.","Añadir aceitunas repartidas por la ensalada.","Aliñar con aceite de oliva y vinagre, remover con suavidad y servir templada."}', 'Ensalada templada de patata con verduras y aceitunas', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Corta las patatas en dados, rocíalas con un poco de aceite y sal. Cocínalas en la airfryer a 190°C durante 20-22 minutos, agitándolas a mitad de cocción, hasta que estén tiernas y ligeramente doradas."},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Corta las patatas en dados, mézclalas con un chorrito de aceite y sal. Hornea a 200°C durante 30-35 minutos, removiendo ocasionalmente, hasta que estén tiernas y ligeramente doradas."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Trocea las patatas y cuécelas al vapor en el Varoma durante 20-25 minutos. Mientras, pica el resto de las verduras con la Thermomix para un montaje rápido."},{"appliance":"vaporera","time":25,"difficulty":"facil","prepSummary":"Corta las patatas en dados y cuécelas al vapor durante 20-25 minutos hasta que estén tiernas. Este método conserva mejor sus nutrientes y textura para la ensalada."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Corta las patatas en dados, añade un vaso de agua a la olla y cuécelas al vapor o sumergidas durante 5-7 minutos desde que sube la válvula, para una cocción ultrarrápida."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Patata}} y colocarlas enteras con piel en una olla cubiertas de agua fría con sal.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición a fuego fuerte y cocer las patatas a fuego medio hasta que estén tiernas, unos 20 min.","minutes":22,"kind":"pasivo"},{"text":"Cortar {{Tomate}} en gajos medianos y reservar.","minutes":2,"kind":"paralelo","during":1},{"text":"Cortar {{Pimiento verde}} en tiras finas y reservar.","minutes":1,"kind":"paralelo","during":1},{"text":"Cortar {{Cebolla}} en aros finos y reservar.","minutes":1,"kind":"paralelo","during":1},{"text":"Escurrir las patatas cocidas y dejar templar 3 min hasta que se puedan manipular.","minutes":3,"kind":"espera"},{"text":"Pelar las patatas templadas y cortar en rodajas gruesas de unos 1 cm.","minutes":2,"kind":"prep"},{"text":"Disponer las rodajas de patata en una fuente y añadir el tomate, el pimiento verde y la cebolla por encima.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceitunas}} repartidas por la ensalada.","minutes":1,"kind":"activo"},{"text":"Aliñar con {{Aceite de oliva|chorrito}} y {{Vinagre}}, remover con suavidad y servir templada.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_015', 'Ensaladilla rusa', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'verano', 342, 12, 28, 22, 2, true, true, '{"huevo","pescado","sulfitos"}', '[{"name":"Patata","amount":250,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Atún en conserva","amount":80,"unit":"g"},{"name":"Huevo cocido","amount":2,"unit":"ud"},{"name":"Pimiento morrón","amount":60,"unit":"g"},{"name":"Pepinillos","amount":30,"unit":"g"},{"name":"Mayonesa","amount":70,"unit":"g"},{"name":"Aceitunas","amount":25,"unit":"g"}]'::jsonb, '{"Pelar patata y zanahoria, y cortar ambas en dados de 1 cm.","Llevar a ebullición una olla con agua abundante y sal.","Añadir los dados de patata y zanahoria a la olla y cocer a fuego medio durante 9 min.","Añadir guisantes a la olla en los últimos 3 min de cocción, hasta que estén tiernos.","Escurrir la patata, la zanahoria y los guisantes, extender en una bandeja y dejar enfriar.","Picar pimiento morrón y pepinillos en dados pequeños.","Laminar aceitunas en rodajas finas y reservar unas pocas para decorar.","Cortar huevo cocido en rodajas; reservar unas rodajas para decorar y picar el resto en dados.","Escurrir atún en conserva y desmenuzar con un tenedor.","Mezclar en un bol grande la patata, la zanahoria y los guisantes con el atún desmenuzado.","Añadir el pimiento morrón, los pepinillos, las aceitunas picadas y el huevo en dados al bol.","Añadir mayonesa y remover con suavidad hasta que todos los ingredientes queden bien ligados.","Cubrir el bol con film y refrigerar al menos 60 min hasta que la ensaladilla esté bien fría.","Servir decorando la superficie con las rodajas de huevo cocido reservadas y las aceitunas laminadas."}', 'Ensaladilla rusa cremosa con atún, huevo, pimiento morrón y pepinillos', '[{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Cocina las patatas, zanahorias y guisantes al vapor en el Varoma durante 20-25 minutos a temperatura Varoma, mientras hierves el huevo en el vaso. Luego trocea y mezcla con el resto de ingredientes."},{"appliance":"vaporera","time":30,"difficulty":"facil","prepSummary":"Cuece al vapor las patatas y zanahorias troceadas junto con los guisantes y el huevo durante 20-25 minutos hasta que estén tiernos. Enfría, trocea y mezcla con la mayonesa y el resto de ingredientes."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Cocina las patatas, zanahorias, guisantes y el huevo en la olla express con un poco de agua durante 6-8 minutos desde que sube la válvula. Despresuriza, enfría, trocea y mezcla con el resto."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['pescado_azul']::main_protein[], false, '[{"text":"Pelar {{Patata}} y {{Zanahoria}}, y cortar ambas en dados de 1 cm.","minutes":5,"kind":"prep"},{"text":"Llevar a ebullición una olla con agua abundante y {{Sal|gusto}}.","minutes":3,"kind":"activo"},{"text":"Añadir los dados de patata y zanahoria a la olla y cocer a fuego medio durante 9 min.","minutes":9,"kind":"pasivo"},{"text":"Añadir {{Guisantes}} a la olla en los últimos 3 min de cocción, hasta que estén tiernos.","minutes":3,"kind":"activo"},{"text":"Escurrir la patata, la zanahoria y los guisantes, extender en una bandeja y dejar enfriar.","minutes":10,"kind":"espera"},{"text":"Picar {{Pimiento morrón}} y {{Pepinillos}} en dados pequeños.","minutes":3,"kind":"prep"},{"text":"Laminar {{Aceitunas}} en rodajas finas y reservar unas pocas para decorar.","minutes":2,"kind":"prep"},{"text":"Cortar {{Huevo cocido}} en rodajas; reservar unas rodajas para decorar y picar el resto en dados.","minutes":2,"kind":"prep"},{"text":"Escurrir {{Atún en conserva}} y desmenuzar con un tenedor.","minutes":1,"kind":"prep"},{"text":"Mezclar en un bol grande la patata, la zanahoria y los guisantes con el atún desmenuzado.","minutes":2,"kind":"activo"},{"text":"Añadir el pimiento morrón, los pepinillos, las aceitunas picadas y el huevo en dados al bol.","minutes":1,"kind":"activo"},{"text":"Añadir {{Mayonesa}} y remover con suavidad hasta que todos los ingredientes queden bien ligados.","minutes":2,"kind":"activo"},{"text":"Cubrir el bol con film y refrigerar al menos 60 min hasta que la ensaladilla esté bien fría.","minutes":60,"kind":"espera"},{"text":"Servir decorando la superficie con las rodajas de huevo cocido reservadas y las aceitunas laminadas.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_016', 'Alcachofas salteadas', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'invierno', 168, 5, 14, 10, 2, false, true, '{}', '[{"name":"Alcachofas","amount":400,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Jamón serrano","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Exprimir limón en un bol grande con agua fría para evitar que las alcachofas se oxiden.","Limpiar alcachofas retirando las hojas exteriores duras, pelando el tallo y dejando solo el corazón.","Cortar cada corazón de alcachofa en cuartos e introducirlos en el bol con agua y limón hasta usarlos.","Laminar ajo en láminas finas.","Cortar jamón serrano en taquitos pequeños.","Picar perejil fino y reservar.","Escurrir los cuartos de alcachofa y colocarlos en la cesta del vaporizador; cocer al vapor hasta que estén tiernos, unos 10 min.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír el ajo laminado en la sartén a fuego medio hasta que empiece a dorarse, unos 2 min.","Añadir los taquitos de jamón serrano y saltear a fuego medio hasta que estén ligeramente crujientes, 1 min.","Incorporar los cuartos de alcachofa cocidos y saltear a fuego fuerte hasta que se doren ligeramente por los bordes, unos 3 min.","Servir las alcachofas salteadas con el perejil picado esparcido por encima."}', 'Corazones de alcachofa salteados con ajo y jamón', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Prepara las alcachofas limpias y troceadas. Mézclalas con aceite, ajo picado, sal y pimienta. Cocina en la airfryer precalentada a 190°C durante 15-18 minutos, removiendo a mitad. Añade el jamón serrano los últimos 3-4 minutos para que quede crujiente y sirve con limón y perejil."},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Limpia y trocea las alcachofas, mézclalas con aceite de oliva, ajo picado, sal y pimienta. Extiéndelas en una bandeja de horno y asa a 200°C durante 25-30 minutos, hasta que estén tiernas y doradas. Incorpora el jamón serrano los últimos 5 minutos para que se dore y termina con l"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Exprimir {{Limón}} en un bol grande con agua fría para evitar que las alcachofas se oxiden.","minutes":1,"kind":"prep"},{"text":"Limpiar {{Alcachofas}} retirando las hojas exteriores duras, pelando el tallo y dejando solo el corazón.","minutes":6,"kind":"prep"},{"text":"Cortar cada corazón de alcachofa en cuartos e introducirlos en el bol con agua y limón hasta usarlos.","minutes":2,"kind":"prep"},{"text":"Laminar {{Ajo}} en láminas finas.","minutes":1,"kind":"prep"},{"text":"Cortar {{Jamón serrano}} en taquitos pequeños.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Escurrir los cuartos de alcachofa y colocarlos en la cesta del vaporizador; cocer al vapor hasta que estén tiernos, unos 10 min.","minutes":10,"kind":"pasivo"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo laminado en la sartén a fuego medio hasta que empiece a dorarse, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Añadir los taquitos de jamón serrano y saltear a fuego medio hasta que estén ligeramente crujientes, 1 min.","minutes":1,"kind":"activo"},{"text":"Incorporar los cuartos de alcachofa cocidos y saltear a fuego fuerte hasta que se doren ligeramente por los bordes, unos 3 min.","minutes":3,"kind":"activo"},{"text":"Servir las alcachofas salteadas con el perejil picado esparcido por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_017', 'Tumbet mallorquín', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'horno', 40, 'normal', 'verano', 268, 4, 24, 18, 2, true, true, '{}', '[{"name":"Patata","amount":200,"unit":"g"},{"name":"Berenjena","amount":200,"unit":"g"},{"name":"Pimiento rojo","amount":150,"unit":"g"},{"name":"Tomate maduro","amount":200,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en rodajas de 5 mm de grosor.","Cortar berenjena en rodajas de 5 mm de grosor sin pelar.","Cortar pimiento rojo en tiras anchas, retirando semillas y nervios.","Cortar tomate maduro en dados pequeños.","Picar ajo muy fino.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Freír las rodajas de patata en tandas hasta que estén doradas y tiernas.","Escurrir las rodajas de patata fritas sobre papel absorbente y reservar.","Freír las rodajas de berenjena en la misma sartén hasta que estén doradas.","Escurrir las rodajas de berenjena fritas sobre papel absorbente y reservar.","Freír las tiras de pimiento rojo en la misma sartén hasta que estén tiernas y con algo de color.","Escurrir las tiras de pimiento rojo fritas sobre papel absorbente y reservar.","Retirar el aceite sobrante de la sartén dejando solo un fondo fino.","Sofreír el ajo picado a fuego suave hasta que esté dorado.","Añadir el tomate en dados y cocer a fuego medio, removiendo de vez en cuando, hasta que la salsa espese.","Precalentar el horno a 180 °C con calor arriba y abajo.","Disponer las rodajas de patata fritas formando una capa uniforme en el fondo de una bandeja de horno.","Colocar encima las rodajas de berenjena fritas formando una segunda capa uniforme.","Añadir las tiras de pimiento rojo frito formando la tercera capa de verduras.","Cubrir todas las capas con la salsa de tomate, repartiéndola de forma homogénea.","Hornear a 180 °C durante 10 min hasta que la salsa burbujee ligeramente y el conjunto esté bien caliente.","Retirar del horno y servir el tumbet en la bandeja o en platos individuales."}', 'Capas de verduras fritas con salsa de tomate al estilo balear', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Corta las verduras y ásalas en el horno a 200°C con aceite de oliva durante unos 30-40 minutos, hasta que estén tiernas y ligeramente doradas. Luego, monta las capas de verduras con la salsa de tomate y hornea 15-20 minutos más para que los sabores se integren bien."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Prepara las verduras cortadas y cocínalas en la airfryer a 190°C en varias tandas (unos 10-15 min por tanda) hasta que estén tiernas y con un toque dorado. Haz la salsa de tomate aparte y luego monta el tumbet en capas para servir."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Patata}} y cortar en rodajas de 5 mm de grosor.","minutes":3,"kind":"prep"},{"text":"Cortar {{Berenjena}} en rodajas de 5 mm de grosor sin pelar.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pimiento rojo}} en tiras anchas, retirando semillas y nervios.","minutes":2,"kind":"prep"},{"text":"Cortar {{Tomate maduro}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Freír las rodajas de patata en tandas hasta que estén doradas y tiernas.","minutes":8,"kind":"activo"},{"text":"Escurrir las rodajas de patata fritas sobre papel absorbente y reservar.","minutes":1,"kind":"prep"},{"text":"Freír las rodajas de berenjena en la misma sartén hasta que estén doradas.","minutes":5,"kind":"activo"},{"text":"Escurrir las rodajas de berenjena fritas sobre papel absorbente y reservar.","minutes":1,"kind":"prep"},{"text":"Freír las tiras de pimiento rojo en la misma sartén hasta que estén tiernas y con algo de color.","minutes":4,"kind":"activo"},{"text":"Escurrir las tiras de pimiento rojo fritas sobre papel absorbente y reservar.","minutes":1,"kind":"prep"},{"text":"Retirar el aceite sobrante de la sartén dejando solo un fondo fino.","minutes":1,"kind":"prep"},{"text":"Sofreír el ajo picado a fuego suave hasta que esté dorado.","minutes":2,"kind":"activo"},{"text":"Añadir el tomate en dados y cocer a fuego medio, removiendo de vez en cuando, hasta que la salsa espese.","minutes":8,"kind":"activo"},{"text":"Precalentar el horno a 180 °C con calor arriba y abajo.","minutes":10,"kind":"paralelo","during":14},{"text":"Disponer las rodajas de patata fritas formando una capa uniforme en el fondo de una bandeja de horno.","minutes":1,"kind":"prep"},{"text":"Colocar encima las rodajas de berenjena fritas formando una segunda capa uniforme.","minutes":1,"kind":"prep"},{"text":"Añadir las tiras de pimiento rojo frito formando la tercera capa de verduras.","minutes":1,"kind":"prep"},{"text":"Cubrir todas las capas con la salsa de tomate, repartiéndola de forma homogénea.","minutes":1,"kind":"prep"},{"text":"Hornear a 180 °C durante 10 min hasta que la salsa burbujee ligeramente y el conjunto esté bien caliente.","minutes":10,"kind":"pasivo"},{"text":"Retirar del horno y servir el tumbet en la bandeja o en platos individuales.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_018', 'Espárragos a la plancha con ajo', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 108, 4, 4, 8, 2, true, false, '{}', '[{"name":"Espárragos trigueros","amount":300,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Sal en escamas","amount":2,"unit":"g"}]'::jsonb, '{"Lavar los espárragos, cortar la parte leñosa del tallo y picar finamente el ajo","Calentar la sartén a fuego fuerte hasta que empiece a humear","Pintar los espárragos con el aceite y cocinarlos 4 min, girándolos, hasta que estén tiernos y marcados","Repartir el ajo picado y la sal en escamas por encima y servir"}', 'Espárragos trigueros a la plancha con aceite y ajo', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Mezcla los espárragos con el aceite de oliva, ajo picado y sal. Cocina en la airfryer precalentada a 190°C durante 10-12 minutos, agitando la cesta a mitad del tiempo, hasta que estén tiernos y ligeramente dorados."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. En una bandeja, extiende los espárragos mezclados con aceite de oliva, ajo picado y sal. Asa durante 15-20 minutos, volteándolos a mitad, hasta que estén tiernos y con puntas ligeramente crujientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar los {{Espárragos trigueros}}, cortar la parte leñosa del tallo y picar finamente {{Ajo}}.","minutes":5,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que empiece a humear.","minutes":3,"kind":"activo"},{"text":"Pintar los espárragos con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"paralelo","during":1},{"text":"Cocinar los espárragos 4 min, girándolos, hasta que estén tiernos y marcados.","minutes":4,"kind":"activo"},{"text":"Repartir el ajo picado, {{Sal en escamas|gusto}} por encima y servir.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_020', 'Acelgas rehogadas', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'invierno', 138, 5, 8, 10, 2, true, true, '{}', '[{"name":"Acelgas","amount":400,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":3,"unit":"g"}]'::jsonb, '{"Lavar acelgas bajo el grifo con agua fría.","Cortar las pencas de las acelgas en trozos de 3 cm y las hojas en tiras anchas. Reservar por separado.","Pelar patata y cortar en dados de 2 cm.","Laminar ajo fino y reservar.","Llevar a ebullición agua con sal en una olla a fuego fuerte.","Añadir las pencas de acelga y la patata cuando rompa a hervir. Cocer a fuego medio durante 7 min.","Añadir las hojas de acelga a la olla y cocer 3 min más hasta que estén tiernas.","Escurrir las verduras en un colador y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo laminado a fuego medio hasta que se dore ligeramente.","Retirar la sartén del fuego y añadir pimentón. Remover rápido para que no se queme.","Añadir las verduras escurridas a la sartén y mezclar bien con el sofrito.","Saltear a fuego medio durante 2 min hasta que todo esté bien integrado.","Servir las acelgas rehogadas en plato inmediatamente."}', 'Acelgas cocidas rehogadas con ajo, patata y pimentón', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina las patatas y acelgas al vapor en el Varoma. Luego, sofríe el ajo y pimentón en el vaso con aceite, añade las verduras cocidas y mezcla a velocidad cuchara hasta integrar."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Sofríe el ajo y pimentón en la olla con aceite. Añade las patatas y acelgas con un poco de agua, cierra la olla y cocina a presión durante 3-5 minutos. Libera la presión y mezcla bien."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Lavar {{Acelgas}} bajo el grifo con agua fría.","minutes":2,"kind":"prep"},{"text":"Cortar las pencas de las acelgas en trozos de 3 cm y las hojas en tiras anchas. Reservar por separado.","minutes":3,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en dados de 2 cm.","minutes":2,"kind":"prep"},{"text":"Laminar {{Ajo}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Llevar a ebullición agua con sal en una olla a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Añadir las pencas de acelga y la patata cuando rompa a hervir. Cocer a fuego medio durante 7 min.","minutes":7,"kind":"pasivo"},{"text":"Añadir las hojas de acelga a la olla y cocer 3 min más hasta que estén tiernas.","minutes":3,"kind":"pasivo"},{"text":"Escurrir las verduras en un colador y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo laminado a fuego medio hasta que se dore ligeramente.","minutes":2,"kind":"activo"},{"text":"Retirar la sartén del fuego y añadir {{Pimentón|pizca}}. Remover rápido para que no se queme.","minutes":1,"kind":"activo"},{"text":"Añadir las verduras escurridas a la sartén y mezclar bien con el sofrito.","minutes":1,"kind":"activo"},{"text":"Saltear a fuego medio durante 2 min hasta que todo esté bien integrado.","minutes":2,"kind":"activo"},{"text":"Servir las acelgas rehogadas en plato inmediatamente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL)
