) values
  ('ensaladas_verduras_021', 'Ensalada griega', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 268, 9, 12, 20, 2, true, false, '{"lactosa","sulfitos"}', '[{"name":"Tomate","amount":300,"unit":"g"},{"name":"Pepino","amount":150,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Cebolla morada","amount":50,"unit":"g"},{"name":"Queso feta","amount":100,"unit":"g"},{"name":"Aceitunas","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Orégano","amount":2,"unit":"g"}]'::jsonb, '{"Cortar tomate en gajos medianos y disponer en una ensaladera amplia.","Cortar pepino en medias lunas de 1 cm y añadir a la ensaladera.","Cortar pimiento verde en tiras finas y añadir a la ensaladera.","Laminar cebolla morada en medias lunas finas y añadir a la ensaladera.","Cortar queso feta en dados de 2 cm y repartir por encima de las verduras.","Repartir aceitunas sobre la ensalada.","Aliñar con aceite de oliva y espolvorear orégano. Servir de inmediato."}', 'Ensalada griega con tomate, pepino, feta, aceitunas y orégano', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Tomate}} en gajos medianos y disponer en una ensaladera amplia.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pepino}} en medias lunas de 1 cm y añadir a la ensaladera.","minutes":1,"kind":"prep"},{"text":"Cortar {{Pimiento verde}} en tiras finas y añadir a la ensaladera.","minutes":1,"kind":"prep"},{"text":"Laminar {{Cebolla morada}} en medias lunas finas y añadir a la ensaladera.","minutes":1,"kind":"prep"},{"text":"Cortar {{Queso feta}} en dados de 2 cm y repartir por encima de las verduras.","minutes":1,"kind":"prep"},{"text":"Repartir {{Aceitunas}} sobre la ensalada.","minutes":1,"kind":"prep"},{"text":"Aliñar con {{Aceite de oliva|chorrito}} y espolvorear {{Orégano|pizca}}. Servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_022', 'Lombarda rehogada', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'invierno', 152, 3, 18, 8, 2, true, true, '{}', '[{"name":"Lombarda","amount":400,"unit":"g"},{"name":"Manzana","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Vinagre","amount":15,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Retirar las hojas exteriores de lombarda y laminar en tiras finas de unos 3 mm.","Pelar cebolla y picar en dados pequeños.","Pelar manzana, retirar el corazón y cortar en dados de 1 cm.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír la cebolla picada en la sartén a fuego medio hasta que esté transparente, unos 4 min.","Añadir la lombarda laminada y vinagre a la sartén y remover hasta que la lombarda se integre con la cebolla.","Tapar la sartén y cocer a fuego suave hasta que la lombarda esté tierna, unos 15 min.","Incorporar los dados de manzana, remover y cocer destapado a fuego suave 3 min más hasta que la manzana esté tierna pero no deshecha.","Servir la lombarda rehogada caliente o templada directamente en el plato."}', 'Lombarda estofada con manzana y vinagre', '[{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Trocea la cebolla y sofríe con aceite. Añade la lombarda y manzana troceadas, el vinagre y cocina a temperatura Varoma, giro inverso, velocidad cuchara durante 20-25 minutos hasta que esté tierna."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla con aceite en la olla abierta. Incorpora la lombarda, manzana y vinagre, cierra la olla y cocina a presión durante 8-10 minutos. Despresuriza y sirve."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Retirar las hojas exteriores de {{Lombarda}} y laminar en tiras finas de unos 3 mm.","minutes":5,"kind":"prep"},{"text":"Pelar {{Cebolla}} y picar en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Pelar {{Manzana}}, retirar el corazón y cortar en dados de 1 cm.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada en la sartén a fuego medio hasta que esté transparente, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Añadir la lombarda laminada y {{Vinagre}} a la sartén y remover hasta que la lombarda se integre con la cebolla.","minutes":2,"kind":"activo"},{"text":"Tapar la sartén y cocer a fuego suave hasta que la lombarda esté tierna, unos 15 min.","minutes":15,"kind":"pasivo"},{"text":"Incorporar los dados de manzana, remover y cocer destapado a fuego suave 3 min más hasta que la manzana esté tierna pero no deshecha.","minutes":3,"kind":"activo"},{"text":"Servir la lombarda rehogada caliente o templada directamente en el plato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_023', 'Coles de Bruselas salteadas', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'invierno', 162, 6, 10, 10, 2, false, true, '{}', '[{"name":"Coles de Bruselas","amount":350,"unit":"g"},{"name":"Panceta","amount":40,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Retirar las hojas exteriores dañadas de coles de bruselas y cortar la base de cada una.","Cortar cada col de Bruselas por la mitad a lo largo.","Cortar panceta en taquitos de aproximadamente 1 cm.","Laminar ajo en láminas finas.","Llevar a ebullición agua con sal en un cazo a fuego fuerte.","Cocer las coles de Bruselas en el agua hirviendo hasta que estén ligeramente tiernas pero firmes.","Escurrir las coles de Bruselas y reservar.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Añadir los taquitos de panceta y saltear a fuego fuerte hasta que estén dorados y crujientes.","Añadir el ajo laminado y saltear a fuego fuerte hasta que empiece a dorarse.","Incorporar las coles de Bruselas con la cara plana hacia abajo y dorar a fuego fuerte sin remover, hasta que caramelicen.","Remover la sartén y saltear el conjunto a fuego fuerte hasta que esté bien dorado.","Servir las coles de Bruselas salteadas de inmediato en plato caliente."}', 'Coles de Bruselas salteadas con panceta crujiente', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Mezcla las coles de Bruselas cortadas, la panceta, el ajo y el aceite. Cocina durante 15-20 minutos, agitando la cesta a mitad del tiempo para un acabado crujiente y dorado."},{"appliance":"horno","time":28,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Extiende las coles de Bruselas, la panceta y el ajo con el aceite en una bandeja de horno. Hornea durante 25-30 minutos, removiendo a mitad, hasta que estén tiernas y bien doradas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Retirar las hojas exteriores dañadas de {{Coles de Bruselas}} y cortar la base de cada una.","minutes":2,"kind":"prep"},{"text":"Cortar cada col de Bruselas por la mitad a lo largo.","minutes":2,"kind":"prep"},{"text":"Cortar {{Panceta}} en taquitos de aproximadamente 1 cm.","minutes":1,"kind":"prep"},{"text":"Laminar {{Ajo}} en láminas finas.","minutes":1,"kind":"prep"},{"text":"Llevar a ebullición agua con {{Sal|gusto}} en un cazo a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer las coles de Bruselas en el agua hirviendo hasta que estén ligeramente tiernas pero firmes.","minutes":5,"kind":"pasivo"},{"text":"Escurrir las coles de Bruselas y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte hasta que humee ligeramente.","minutes":1,"kind":"activo"},{"text":"Añadir los taquitos de panceta y saltear a fuego fuerte hasta que estén dorados y crujientes.","minutes":2,"kind":"activo"},{"text":"Añadir el ajo laminado y saltear a fuego fuerte hasta que empiece a dorarse.","minutes":1,"kind":"activo"},{"text":"Incorporar las coles de Bruselas con la cara plana hacia abajo y dorar a fuego fuerte sin remover, hasta que caramelicen.","minutes":3,"kind":"pasivo"},{"text":"Remover la sartén y saltear el conjunto a fuego fuerte hasta que esté bien dorado.","minutes":1,"kind":"activo"},{"text":"Servir las coles de Bruselas salteadas de inmediato en plato caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL),
  ('ensaladas_verduras_024', 'Ensalada César', 'ensaladas_verduras', 'pollo', NULL, ARRAY['primero','plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 328, 24, 12, 22, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Lechuga romana","amount":200,"unit":"g"},{"name":"Pechuga de pollo","amount":200,"unit":"g"},{"name":"Pan","amount":40,"unit":"g"},{"name":"Queso parmesano","amount":20,"unit":"g"},{"name":"Mayonesa","amount":30,"unit":"g"},{"name":"Ajo","amount":4,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar pan en dados de 1 cm.","Pelar y picar ajo muy fino.","Rallar queso parmesano.","Exprimir limón y reservar el zumo.","Lavar lechuga romana y trocear en hojas grandes.","Calentar plancha a fuego fuerte con aceite de oliva.","Cocinar pechuga de pollo hasta que esté dorada, 4 min por cada lado.","Retirar la pechuga de pollo de la plancha y dejar reposar.","Calentar sartén a fuego medio con el resto del aceite de oliva.","Añadir el ajo picado y los dados de pan hasta que estén dorados y crujientes.","Mezclar mayonesa con el zumo de limón y el queso parmesano rallado en un bol hasta obtener una salsa homogénea.","Cortar la pechuga de pollo reposada en tiras de 1 cm.","Disponer la lechuga romana en los platos.","Añadir las tiras de pollo y los picatostes sobre la lechuga.","Repartir la salsa por encima y servir de inmediato."}', 'Ensalada de lechuga romana con pollo, picatostes y salsa César', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Cocina el pollo cortado en tiras o dados a 180°C durante 15-18 minutos, dándole la vuelta. Luego, tuesta los dados de pan con un poco de aceite y ajo a 180°C durante 5-8 minutos hasta que estén crujientes."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Hornea el pollo a 200°C durante 20-25 minutos hasta que esté dorado y cocido. Al mismo tiempo, tuesta los dados de pan con aceite y ajo a 180°C durante 10-15 minutos hasta obtener unos picatostes crujientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pan}} en dados de 1 cm.","minutes":2,"kind":"prep"},{"text":"Pelar y picar {{Ajo}} muy fino.","minutes":1,"kind":"prep"},{"text":"Rallar {{Queso parmesano}}.","minutes":1,"kind":"prep"},{"text":"Exprimir {{Limón}} y reservar el zumo.","minutes":1,"kind":"prep"},{"text":"Lavar {{Lechuga romana}} y trocear en hojas grandes.","minutes":2,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"activo"},{"text":"Cocinar {{Pechuga de pollo}} hasta que esté dorada, 4 min por cada lado.","minutes":8,"kind":"pasivo"},{"text":"Retirar la pechuga de pollo de la plancha y dejar reposar.","minutes":2,"kind":"espera"},{"text":"Calentar {{@Sartén}} a fuego medio con el resto del aceite de oliva.","minutes":1,"kind":"activo"},{"text":"Añadir el ajo picado y los dados de pan hasta que estén dorados y crujientes.","minutes":4,"kind":"activo"},{"text":"Mezclar {{Mayonesa}} con el zumo de limón y el queso parmesano rallado en un bol hasta obtener una salsa homogénea.","minutes":1,"kind":"prep"},{"text":"Cortar la pechuga de pollo reposada en tiras de 1 cm.","minutes":1,"kind":"prep"},{"text":"Disponer la lechuga romana en los platos.","minutes":1,"kind":"emplatado"},{"text":"Añadir las tiras de pollo y los picatostes sobre la lechuga.","minutes":1,"kind":"emplatado"},{"text":"Repartir la salsa por encima y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL)
